"""E39 panel census (descriptive; NO judgment, NO prereg).

Three read-only legs over ``data/daily``, all deterministic and offline:

  stale  -- the coverage face counts 1,723 of 1,725 panels as current and
            cannot say whether the last two are dead listings or refresh
            failures. Decide it from the rows on disk.
  mtime  -- the 2026-10-17/10-21 refresh wave moved the whole panel. Size it:
            how many files were rewritten, how many bars arrived, and which
            days did the writing.
  ladder -- every wide-book spread in E34/E36/E37/E38 is quoted "vs ladder5",
            yet the denominator has only ever been ann/vol/Sharpe. Describe it
            properly: drawdown, worst month, cash-leg share. The curve comes
            from importing the E24/E27 engine, never a re-implementation.

Every face is descriptive: no gate, no verdict on a strategy, no prereg, no
trial count consumed.
"""

from __future__ import annotations

import argparse
import csv
import hashlib
import json
import os
import random
import sys
import zlib
from datetime import datetime

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "scripts"))

DAILY = os.path.join(ROOT, "data", "daily")
BULK_IMPORT_DATE = "2026-09-22"   # the one-off full-panel pull, see E30 coverage face
REFRESH_WAVE_DATE = "2026-10-17"  # first mtime of the 2026-10-21 refresh pass


def read_bars(path):
    """-> list of {date, close, volume, amount} with numeric coercion."""
    out = []
    with open(path, "r", encoding="utf-8", newline="") as fh:
        for row in csv.DictReader(fh):
            d = (row.get("date") or "").strip()
            if not d:
                continue
            def num(key):
                try:
                    return float((row.get(key) or "").strip())
                except ValueError:
                    return None
            out.append({"date": d, "close": num("close"),
                        "volume": num("volume"), "amount": num("amount")})
    out.sort(key=lambda r: r["date"])
    return out


def panel_files():
    return sorted(f for f in os.listdir(DAILY) if f.lower().endswith(".csv"))


def panel_calendar():
    import e24_ladder_weighting as base
    return base.load_panel()[0]


def _quant(seq, q):
    if not seq:
        return None
    s = sorted(seq)
    k = max(0, min(len(s) - 1, int(round(q * (len(s) - 1)))))
    return s[k]


# ---------------------------------------------------------------- leg: stale

def classify_stale(name, bars, cal, cutoff):
    """Mechanical criteria, applied to rows on disk only.

    PINNED_SLOT_COPY  -- the file carries a '_tag' suffix and its rows sit
                         inside another live panel's date range: a frozen
                         snapshot, not a universe member.
    SOURCE_SIDE_GAP   -- last bar predates the 2026-09-22 bulk import and the
                         last bars still carried normal turnover, so the source
                         never had those rows to import: a listing that stopped
                         printing, not a refresh that failed.
    REFRESH_FAILURE   -- last bar is the bulk-import date itself with normal
                         turnover: the in-chain updater skipped it afterwards.
    """
    if not bars:
        return {"class": "EMPTY_FILE", "why": "no parseable rows"}
    last = bars[-1]["date"]
    tail = bars[-20:]
    vols = [b["volume"] for b in tail if b["volume"] is not None]
    tail_vol_med = _quant(vols, 0.5)
    amts = [b["amount"] for b in tail if b["amount"] is not None]
    tail_amt_med = _quant(amts, 0.5)
    missing = [d for d in cal if d > last] if cal else []
    stem = os.path.splitext(name)[0]
    tagged = "_" in stem
    normal_turnover = bool(tail_vol_med and tail_vol_med > 0)
    if tagged:
        cls, why = "PINNED_SLOT_COPY", "filename carries a '_tag' slot suffix"
    elif last == BULK_IMPORT_DATE and normal_turnover:
        cls, why = "REFRESH_FAILURE", "stopped exactly at the bulk-import date"
    elif last < BULK_IMPORT_DATE and normal_turnover:
        cls, why = "SOURCE_SIDE_GAP", "last bars still traded, so the source never offered rows after it"
    elif not normal_turnover:
        cls, why = "DEAD_LISTING", "tail turnover is zero (no trades printed)"
    else:
        cls, why = "UNCLASSIFIED", "no criterion matched"
    return {
        "class": cls, "why": why, "rows": len(bars),
        "first_bar": bars[0]["date"], "last_bar": last,
        "calendar_days_missing_after_last_bar": len(missing),
        "tail20_volume_median": tail_vol_med, "tail20_amount_median": tail_amt_med,
        "tail5": [{"date": b["date"], "close": b["close"], "volume": b["volume"]} for b in bars[-5:]],
        "last_bar_vs_cutoff_days": (
            (datetime.fromisoformat(cutoff) - datetime.fromisoformat(last)).days if cutoff else None),
    }


def run_stale(outdir):
    cal = panel_calendar()
    cutoff = cal[-1]
    rows = []
    for f in panel_files():
        bars = read_bars(os.path.join(DAILY, f))
        if not bars:
            continue
        last = bars[-1]["date"]
        lag = len([d for d in cal if d > last])
        if lag < 1:
            continue  # on the panel cutoff: current, not a stale-panel question
        rows.append((f, bars, lag))
    faces = []
    for f, bars, lag in rows:
        rec = {"file": f, "bars_behind_calendar": lag}
        rec.update(classify_stale(f, bars, cal, cutoff))
        faces.append(rec)

    # cross-check: is a tagged copy actually a duplicate of a live panel?
    dup = None
    for rec in faces:
        if rec["class"] != "PINNED_SLOT_COPY":
            continue
        stem = os.path.splitext(rec["file"])[0]
        for live in panel_files():
            ls = os.path.splitext(live)[0]
            if ls == stem.split("_")[0] or ls == "sh" + stem.split("_")[0]:
                a = read_bars(os.path.join(DAILY, live))
                b = read_bars(os.path.join(DAILY, rec["file"]))
                am = {r["date"]: r["close"] for r in a}
                bm = {r["date"]: r["close"] for r in b}
                common = set(am) & set(bm)
                same = sum(1 for d in common if am[d] == bm[d])
                dup = {"live_panel": live, "common_dates": len(common),
                       "identical_closes": same,
                       "live_last_bar": a[-1]["date"] if a else None,
                       "copy_last_bar": b[-1]["date"] if b else None}
                break
        if dup:
            break

    face = {
        "study": "e39_stale_two_census",
        "evidence_cutoff": cutoff,
        "calendar_bars": len(cal),
        "thresholds": {"stale_if_bars_behind_calendar": ">=1 (strictly behind the panel cutoff)",
                       "bulk_import_date": BULK_IMPORT_DATE},
        "panel_files": len(panel_files()),
        "stale_panels": len(faces),
        "findings": faces,
        "pinned_copy_crosscheck": dup,
        "denominator_advice": [
            "PINNED_SLOT_COPY is not a universe member: drop it from any coverage denominator.",
            "SOURCE_SIDE_GAP is a listing that stopped printing: keep it in the universe file, "
            "but never count it as a refresh obligation.",
            "REFRESH_FAILURE is the only class that is our own defect.",
        ],
        "honest": [
            "classification reads rows on disk only; no vendor metadata, no listing notices",
            "a SOURCE_SIDE_GAP verdict is an inference from turnover, not a confirmed delisting",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }
    return face


# ---------------------------------------------------------------- leg: mtime

def run_mtime(outdir):
    files = panel_files()
    pockets = []
    day_hist = {}
    rows_total = 0
    bytes_total = 0
    advanced = unchanged = behind = 0
    reached_cutoff = None
    for f in files:
        p = os.path.join(DAILY, f)
        st = os.stat(p)
        bars = read_bars(p)
        if not bars:
            continue
        last = bars[-1]["date"]
        reached_cutoff = last if reached_cutoff is None or last > reached_cutoff else reached_cutoff
        rows_after_bulk = len([b for b in bars if b["date"] > BULK_IMPORT_DATE])
        mday = datetime.fromtimestamp(st.st_mtime).strftime("%Y-%m-%d")
        day_hist[mday] = day_hist.get(mday, 0) + 1
        rows_total += len(bars)
        bytes_total += st.st_size
        if last > BULK_IMPORT_DATE:
            advanced += 1
        elif last == BULK_IMPORT_DATE:
            unchanged += 1
        else:
            behind += 1
        pockets.append({
            "file": f, "mtime": datetime.fromtimestamp(st.st_mtime).isoformat(timespec="seconds"),
            "bytes": st.st_size, "rows": len(bars), "last_bar": last,
            "rows_after_bulk_import": rows_after_bulk,
        })
    touched = [p for p in pockets if p["mtime"][:10] >= REFRESH_WAVE_DATE]
    face = {
        "study": "e39_panel_mtime_census",
        "evidence_cutoff": reached_cutoff,
        "panel_files": len(pockets),
        "bulk_import_date": BULK_IMPORT_DATE,
        "refresh_wave_since": REFRESH_WAVE_DATE,
        "totals": {
            "rows": rows_total, "bytes": bytes_total,
            "files_advanced_past_bulk": advanced,
            "files_stopped_at_bulk": unchanged,
            "files_behind_bulk": behind,
        },
        "refresh_wave": {
            "files_touched": len(touched),
            "rows_after_bulk_import_carried": sum(p["rows_after_bulk_import"] for p in touched),
            "bytes_rewritten": sum(p["bytes"] for p in touched),
            "mtime_day_histogram": dict(sorted(day_hist.items())),
            "first_mtime": min((p["mtime"] for p in touched), default=None),
            "last_mtime": max((p["mtime"] for p in touched), default=None),
        },
        "largest_carriers": sorted(touched, key=lambda p: -p["rows_after_bulk_import"])[:10],
        "honest": [
            "mtime is a disk fact, not a provenance record: a rewrite that changed no row is invisible here",
            "rows_after_bulk_import counts bars dated after the bulk pull, so it is the bar payload of the wave",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }
    return face, pockets


# --------------------------------------------------------------- leg: ladder

def _month_ends(curve):
    out = []
    for d, v in curve:
        if out and out[-1][0][:7] == d[:7]:
            out[-1] = (d, v)
        else:
            out.append((d, v))
    return out


def risk_profile(curve, years):
    vals = [v for _, v in curve]
    peak = vals[0]
    peak_date = curve[0][0]
    max_dd = 0.0
    max_dd_span = None
    worst_dd_start = curve[0][0]
    for d, v in curve:
        if v > peak:
            peak, peak_date = v, d
        dd = v / peak - 1.0
        if dd < max_dd:
            max_dd = dd
            max_dd_span = (peak_date, d)
            worst_dd_start = peak_date
    # longest underwater run in sessions
    longest = cur = 0
    peak = vals[0]
    for _, v in curve:
        if v >= peak:
            peak = v
            cur = 0
        else:
            cur += 1
            longest = max(longest, cur)
    me = _month_ends(curve)
    mrets = [(me[k][0][:7], me[k][1] / me[k - 1][1] - 1.0) for k in range(1, len(me))]
    worst = min(mrets, key=lambda r: r[1]) if mrets else None
    best = max(mrets, key=lambda r: r[1]) if mrets else None
    neg = len([r for r in mrets if r[1] < 0])
    return {
        "years": round(years, 2),
        "ann_return_pct": round((vals[-1] / vals[0]) ** (1.0 / years) * 100 - 100, 2) if years else None,
        "max_drawdown_pct": round(max_dd * 100, 2),
        "max_drawdown_span": list(max_dd_span) if max_dd_span else None,
        "longest_underwater_sessions": longest,
        "worst_month": {"month": worst[0], "return_pct": round(worst[1] * 100, 2)} if worst else None,
        "best_month": {"month": best[0], "return_pct": round(best[1] * 100, 2)} if best else None,
        "months": len(mrets),
        "negative_months": neg,
        "monthly_win_rate_pct": round((len(mrets) - neg) / len(mrets) * 100, 1) if mrets else None,
    }


def run_ladder(outdir, starts=("2020-01-01", "2018-01-01")):
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    raw = e27.load_universe()
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]
    faces = {}
    for start in starts:
        cal = [d for d in cal_full if d >= start]
        years = len(cal) / 252.0
        prices = {}
        for s in base.LADDER:
            c = raw.get(s, ({}, {}))[0] if s in raw else {}
            if not c:
                c = base.load_panel(s)[1].get(s, {})
            prices[s] = [c.get(d) for d in cal]
        cash = base.load_cash_series(cal)
        curve, aux, holdings = e27.simulate(cal, prices, {}, base.LADDER, cash, None, 1.0, {})
        m = base.metrics(curve, years)
        prof = risk_profile(curve, years)
        # cash-leg share: bars where at least one ladder member had no close
        gaps = [d for k, d in enumerate(cal[1:]) if any(prices[s][k + 1] is None for s in base.LADDER)]
        cash_map = cash["series"] if cash else {}
        cash_rates = [cash_map[d] for d in cal if d in cash_map]
        prof.update({
            "start": start, "bars": len(cal),
            "metrics_engine": m,
            "turnover_per_year": aux["turnover_total"] / years if years else None,
            "cost_per_year_bp": aux["cost_paid_frac"] / years * 1e4 if years else None,
            "cash_leg": {
                "bars_with_a_missing_member": len(gaps),
                "missing_member_bars": {
                    s: sum(1 for k, d in enumerate(cal) if prices[s][k] is None)
                    for s in base.LADDER},
                "cash_leg_share_pct": round(len(gaps) / max(1, len(cal) - 1) * 100, 2),
                "mean_daily_cash_return_bp": round(sum(cash_rates) / len(cash_rates) * 1e4, 4) if cash_rates else None,
                "mean_annual_cash_rate_pct": round(sum(cash_rates) / len(cash_rates) * 252 * 100, 2) if cash_rates else None,
            },
            "last_holdings": holdings,
        })
        faces[start] = prof
    return {
        "study": "e39_ladder_risk_profile",
        "evidence_cutoff": cutoff,
        "baseline": base.LADDER,
        "cost_bp_per_side": base.COST_BP_SIDE,
        "windows": faces,
        "honest": [
            "the curve is the E24/E27 engine's own curve (module import), not a re-implementation",
            "drawdown is measured on the daily equity curve; months are month-end marks",
            "cash-leg share is the fraction of bars with a missing ladder member price, "
            "not a discretionary cash position",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }


# ------------------------------------------------------- leg: month attribution

def run_month(outdir, month):
    """Attribute one calendar month of the ladder from rows only.

    Decomposes the equal-weight month into per-member contributions and flags
    data anomalies (zero-volume days, single-bar jumps the panel cannot
    explain) so a bad month can be read as a market move or as a panel defect.
    """
    import e24_ladder_weighting as base

    cal = base.load_panel()[0]
    days = [d for d in cal if d.startswith(month)]
    if not days:
        return None
    prev = [d for d in cal if d < month]
    start_day = prev[-1] if prev else days[0]
    members = {}
    for s in base.LADDER:
        p = os.path.join(DAILY, s + ".csv")
        bars = read_bars(p) if os.path.exists(p) else []
        by = {b["date"]: b for b in bars}
        first = by.get(start_day) or by.get(days[0])
        last = by.get(days[-1])
        if not first or not last or not first["close"] or not last["close"]:
            members[s] = {"status": "MISSING_ROW"}
            continue
        r = last["close"] / first["close"] - 1.0
        window = [by[d] for d in days if d in by]
        jumps = []
        for k in range(1, len(window)):
            a, b = window[k - 1]["close"], window[k]["close"]
            if a and b and abs(b / a - 1.0) > 0.10:
                jumps.append({"date": window[k]["date"], "ret_pct": round((b / a - 1) * 100, 2)})
        members[s] = {
            "status": "OK",
            "month_return_pct": round(r * 100, 2),
            "bars": len(window),
            "missing_bars": len(days) - len(window),
            "zero_volume_days": len([w for w in window if not w["volume"]]),
            "first_close": first["close"], "last_close": last["close"],
            "single_bar_jumps_over_10pct": jumps,
        }
    live = {s: v for s, v in members.items() if v.get("status") == "OK"}
    eq = (sum(v["month_return_pct"] for v in live.values()) / len(live)) if live else None
    return {
        "study": "e39_month_attribution",
        "evidence_cutoff": days[-1],
        "month": month,
        "entry_mark": start_day,
        "bars_in_month": len(days),
        "members": members,
        "equal_weight_month_return_pct": round(eq, 2) if eq is not None else None,
        "anomaly_flags": sorted(
            {"%s:zero_volume" % s for s, v in live.items() if v["zero_volume_days"]}
            | {"%s:jump" % s for s, v in live.items() if v["single_bar_jumps_over_10pct"]}
            | {"%s:missing_bars" % s for s, v in live.items() if v["missing_bars"]}),
        "honest": [
            "equal weight at entry mark, no rebalance inside the month: a contribution view, not the engine curve",
            "anomaly flags are mechanical (zero volume, >10% single-bar moves), not proof of a data defect",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }


# ----------------------------------------------------- leg: pair drawdown path

def run_pair(outdir, starts=("2020-01-01", "2018-01-01"), pick_n=9999,
             exclude=("sh511",), raw=None):
    """Read the E34-E38 wide-book spread on the drawdown path, not on its mean.

    Same calendar, same cost, same spec, one shared rank cache: ladder5 and the
    wide book (top-N of the eligible universe) are simulated side by side and
    then profiled by the identical function, so max drawdown, underwater run
    and worst month are comparable line for line. A third profile is taken on
    the ratio of the two equity curves -- the spread itself, which every
    vs-ladder number quotes but never measures.

    ``raw`` lets a caller hand in an already-loaded (optionally screened) panel
    so a twin can burn both arms off ONE load (E113/E122 seam); the default path
    still loads the shipped universe.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    raw_all = raw if raw is not None else e27.load_universe()
    if exclude:
        raw_all = {s: v for s, v in raw_all.items()
                   if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]
    wide_name = "wide_top%d" % pick_n
    windows = {}
    for start in starts:
        cal = [d for d in cal_full if d >= start]
        years = len(cal) / 252.0
        all_syms = sorted(set(base.LADDER) | set(raw_all))
        prices, amounts = {}, {}
        for s in all_syms:
            c, a = raw_all.get(s, ({}, {}))
            prices[s] = [c.get(d) for d in cal]
            amounts[s] = [a.get(d) for d in cal]
        universe = [s for s in all_syms if s in raw_all]
        cash = base.load_cash_series(cal)
        rank_cache = {}
        curves = {}
        for name, univ, n in (("ladder5", base.LADDER, None),
                              (wide_name, universe, pick_n)):
            curve, _aux, _hold = e27.simulate(cal, prices, amounts, univ, cash,
                                              n, 1.0, rank_cache)
            curves[name] = curve
        lad = curves["ladder5"]
        lmap = dict(lad)
        ratio = [(d, v / lmap[d]) for d, v in curves[wide_name]
                 if d in lmap and lmap[d] > 0]
        prof = {k: risk_profile(c, years) for k, c in
                (("ladder5", lad), (wide_name, curves[wide_name]),
                 ("spread_ratio", ratio))}
        prof["ladder5"]["engine_metrics"] = base.metrics(lad, years)
        prof[wide_name]["engine_metrics"] = base.metrics(curves[wide_name], years)
        answers = {
            "ann_spread_pct": round(prof[wide_name]["ann_return_pct"]
                                    - prof["ladder5"]["ann_return_pct"], 2),
            "maxdd_delta_pct": round(prof[wide_name]["max_drawdown_pct"]
                                     - prof["ladder5"]["max_drawdown_pct"], 2),
            "underwater_delta_sessions": (
                prof[wide_name]["longest_underwater_sessions"]
                - prof["ladder5"]["longest_underwater_sessions"]),
            "worst_month_same_month": (
                (prof[wide_name]["worst_month"] or {}).get("month")
                == (prof["ladder5"]["worst_month"] or {}).get("month")),
            "spread_maxdd_pct": prof["spread_ratio"]["max_drawdown_pct"],
            "spread_longest_underwater_sessions":
                prof["spread_ratio"]["longest_underwater_sessions"],
            "spread_worst_month": prof["spread_ratio"]["worst_month"],
        }
        windows[start] = {"bars": len(cal), "years": round(years, 2),
                          "profiles": prof, "answers": answers}
    return {
        "study": "e40_pair_drawdown",
        "evidence_cutoff": cutoff,
        "spec": {"pick_n": pick_n, "exclude_prefixes": list(exclude),
                 "cost_mult": 1.0, "cost_bp_per_side": base.COST_BP_SIDE,
                 "starts": list(starts)},
        "windows": windows,
        "honest": [
            "both curves come from the E24/E27 engine (module import), one calendar, one rank cache",
            "spread_ratio is a ratio of equity curves, not a tradable sleeve: it prices the "
            "vs-ladder claim, it does not add a portfolio",
            "drawdown is measured on daily equity; months are month-end marks",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }


# ------------------------------------------------------- leg: cash-leg drag

def _scale_cash(cash, mult):
    """Scale a load_cash_series payload's daily returns. None stays None (0%)."""
    if cash is None or not mult:
        return None if cash is None else {"series": {}}
    return {"series": {d: r * mult for d, r in cash["series"].items()}}


CASH_IDENTITY_TOL_BP = 5.0


def _first_trade_index(rebal, prices, universe, elig):
    """(E128) the first month end on which THIS book's own universe can trade.

    Extracted so the per-book window is testable and so two books cannot
    accidentally share one answer: eligibility needs a per-name burn-in, and a
    1317-name universe and a 5-name universe are not eligible on the same month
    end unless their oldest bars happen to line up.
    """
    for ri in rebal:
        if any(elig(prices[s], ri) for s in universe):
            return ri
    return None


def _window_is_burn_in_driven(idx, min_bars, slack=35):
    """(E128) is the repo stretch the window's own burn-in, or a real delay?

    ``base.elig`` demands ``MIN_BARS`` of non-missing closes on the WINDOW-LOCAL
    price array, so a window that starts at 2020 is guaranteed to sit in repo
    until a month end about 250 bars later -- whatever the panel looks like.
    If the first trading rebalance lands within a month or so of that gate, the
    window is the burn-in and must not be narrated as scarce investable names.
    """
    if idx is None or min_bars is None:
        return None
    return (idx - min_bars) <= slack


def _cash_identity(rate_pct, share_pct, measured_bp, tol_bp=CASH_IDENTITY_TOL_BP):
    """(E128) rate x share vs the measured attribution, as a published residual.

    The identity is the arithmetic a reader does in their head: a repo rate of
    ``rate_pct`` per year, carried on the un-invested weight for ``share_pct``
    of the bars, is worth about ``rate_pct * share_pct`` basis points a year
    (because bp = pct/100 * share/100 * 1e4). The engine compounds the accrual
    on the equity curve instead of summing it linearly, so the measured number
    is NOT required to equal the identity -- but the gap is only allowed to be
    a valuation difference. A residual that grows with the window, or one that
    dwarfs the number it explains, is a defect in the attribution rather than a
    market fact, and the face has to say which one it is.
    """
    if rate_pct is None or share_pct is None:
        return {
            "expected_linear_bp": None, "measured_bp": measured_bp,
            "residual_bp": None, "tolerance_bp": tol_bp,
            "within_tolerance": None, "status": "inputs_missing",
            "reading": "no rate or no share on this book, so the identity is "
                       "not computable -- say so rather than printing zero",
        }
    expected = round(rate_pct * share_pct, 2)
    if measured_bp is None:
        return {
            "expected_linear_bp": expected, "measured_bp": None,
            "residual_bp": None, "tolerance_bp": tol_bp,
            "within_tolerance": None, "status": "measurement_missing",
            "reading": "the identity is computable but the book published no "
                       "measured attribution, so there is nothing to reconcile",
        }
    resid = round(measured_bp - expected, 2)
    within = abs(resid) <= tol_bp
    return {
        "expected_linear_bp": expected,
        "measured_bp": measured_bp,
        "residual_bp": resid,
        "tolerance_bp": tol_bp,
        "within_tolerance": within,
        "ratio_measured_over_expected": (round(measured_bp / expected, 3)
                                        if expected else None),
        "residual_share_of_measured_pct": (round(abs(resid) / abs(measured_bp) * 100, 1)
                                           if measured_bp else None),
        "status": "ok" if within else "residual_outside_tolerance",
        "reading": ("the linear identity closes within %.1fbp of the measured "
                    "attribution, so the gap is the compounding difference, not "
                    "a missing mechanism" % tol_bp if within else
                    "the identity misses the measured attribution by more than "
                    "%.1fbp: either the accrual is not the only cash channel or "
                    "the attribution is mis-specified" % tol_bp),
    }


def run_cashdrag(outdir, starts=("2020-01-01",), pick_n=9999, exclude=("sh511",),
                 rate_mults=(0.0, 1.0, 3.0), raw=None):
    """How much of the ladder/wide verdict is the repo leg actually paying for?

    The engine accrues cash only on the un-invested weight: it is 1.0 before the
    first monthly decision and (1 - sum(weights)) afterwards, which is zero for
    an equal-weight book that rebalanced into a non-empty live set. So this leg
    re-runs the identical spec at repo multipliers 0x / 1x / 3x and reads the
    annualised column, which bounds the cash leg's contribution to the verdict
    instead of asserting it.

    ``raw`` lets a caller hand in an already-loaded (optionally screened) panel
    so a twin can burn both arms off ONE load (E113/E125 seam); the default path
    still loads the shipped universe.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    raw_all = dict(raw) if raw is not None else e27.load_universe()
    if exclude:
        raw_all = {s: v for s, v in raw_all.items()
                   if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]
    wide_name = "wide_top%d" % pick_n
    windows = {}
    for start in starts:
        cal = [d for d in cal_full if d >= start]
        years = len(cal) / 252.0
        all_syms = sorted(set(base.LADDER) | set(raw_all))
        prices, amounts = {}, {}
        for s in all_syms:
            c, a = raw_all.get(s, ({}, {}))
            prices[s] = [c.get(d) for d in cal]
            amounts[s] = [a.get(d) for d in cal]
        universe = [s for s in all_syms if s in raw_all]
        cash_panel = base.load_cash_series(cal)
        rebal = base.month_end_indices(cal)
        # The cash weight is the un-invested weight, and the first rebalance that
        # actually trades is NOT the first month end: eligibility needs a burn-in,
        # so empty live sets keep the book in repo for far longer. Measure it --
        # PER BOOK (E128): the window belongs to the book's own universe, not to
        # the ladder's. A 1317-name universe and a 5-name universe do not become
        # eligible on the same month end, so one shared window would silently
        # answer "when does the ladder trade" for both books.
        book_universes = {"ladder5": list(base.LADDER), wide_name: universe}
        first_trade_idx = _first_trade_index(rebal, prices, base.LADDER, base.elig)
        book_windows = {}
        for name, univ in book_universes.items():
            idx = _first_trade_index(rebal, prices, univ, base.elig)
            bars = (idx + 1) if idx is not None else len(cal) - 1
            book_windows[name] = {
                "first_rebalance_index": rebal[0] if rebal else None,
                "first_trading_rebalance_index": idx,
                "first_invested_bar": (cal[idx + 1] if idx is not None else None),
                "cash_bars": bars,
                "cash_bar_share_pct": round(bars / max(1, len(cal) - 1) * 100, 2),
                "universe_size": len(univ),
                # E128: the gate that decides WHEN this book first trades is
                # base.elig, which demands MIN_BARS of non-missing closes ON THE
                # WINDOW-LOCAL array. So the repo stretch is the window's own
                # burn-in, not a scarcity of investable names -- publishing the
                # number beside the window is what stops "13 months in cash"
                # being read as a market fact.
                "burn_in_bars_required": base.MIN_BARS,
                "bars_beyond_burn_in": ((idx - base.MIN_BARS) if idx is not None else None),
                "window_is_burn_in_driven": _window_is_burn_in_driven(idx, base.MIN_BARS),
            }
        cash_bars = (first_trade_idx + 1) if first_trade_idx is not None else len(cal) - 1
        rank_cache = {}
        table = {}
        for name, univ, n in (("ladder5", base.LADDER, None),
                              (wide_name, universe, pick_n)):
            rows = {}
            for k in rate_mults:
                cash = _scale_cash(cash_panel, k)
                curve, aux, holdings = e27.simulate(
                    cal, prices, amounts, univ, cash, n, 1.0, rank_cache)
                prof = risk_profile(curve, years)
                m = base.metrics(curve, years)
                rows["x%g" % k] = {
                    "ann_return_pct": prof["ann_return_pct"],
                    "ann_vs_x0_bp": None,  # filled below
                    "vol_pct": m.get("ann_vol_pct"),
                    "sharpe": m.get("sharpe"),
                    "max_drawdown_pct": prof["max_drawdown_pct"],
                    "cost_per_year_bp": (aux["cost_paid_frac"] / years * 1e4
                                         if years else None),
                    "curve_first": curve[0][1],
                    "curve_last": curve[-1][1],
                }
            zero = rows.get("x0", {}).get("ann_return_pct")
            for key, row in rows.items():
                if zero is not None and row["ann_return_pct"] is not None:
                    row["ann_vs_x0_bp"] = round((row["ann_return_pct"] - zero) * 100, 2)
            table[name] = rows
        cash_map = (cash_panel or {}).get("series", {})
        rates = [cash_map[d] for d in cal if d in cash_map]
        mean_rate_pct = (round(sum(rates) / len(rates) * 252 * 100, 2) if rates else None)
        # E128: each book gets its OWN window, and each window carries the
        # rate x share identity beside the attribution it is supposed to explain.
        # Ladder-only bookkeeping could not say whether the 1bp ladder/wide gap
        # was a window difference or a rate difference; a reader could not say
        # either, because the wide book published no window at all.
        window_by_book = {}
        for name, bw in book_windows.items():
            measured = table[name].get("x1", {}).get("ann_vs_x0_bp")
            row = dict(bw)
            row["mean_annual_cash_rate_pct"] = mean_rate_pct
            row["measured_attribution_bp"] = measured
            row.update(_cash_identity(mean_rate_pct, bw["cash_bar_share_pct"], measured))
            window_by_book[name] = row
        same_window = (book_windows["ladder5"]["first_trading_rebalance_index"]
                       == book_windows[wide_name]["first_trading_rebalance_index"])
        exp_lad = window_by_book["ladder5"].get("expected_linear_bp")
        exp_wid = window_by_book[wide_name].get("expected_linear_bp")
        meas_lad = window_by_book["ladder5"].get("measured_attribution_bp")
        meas_wid = window_by_book[wide_name].get("measured_attribution_bp")
        gap = (round(meas_lad - meas_wid, 2)
               if (meas_lad is not None and meas_wid is not None) else None)
        gap_window = (round(exp_lad - exp_wid, 2)
                      if (exp_lad is not None and exp_wid is not None) else None)
        windows[start] = {
            "bars": len(cal),
            "years": round(years, 2),
            "schemes": table,
            "cash_window_by_book": window_by_book,
            "cash_window_note": {
                "same_window_for_both_books": same_window,
                "ladder_gap_bp": gap,
                "ladder_gap_from_window_bp": gap_window,
                "ladder_gap_unexplained_bp": (round(gap - gap_window, 2)
                                              if (gap is not None and gap_window is not None)
                                              else None),
                "tolerance_bp": CASH_IDENTITY_TOL_BP,
                "window_is_burn_in_driven": all(
                    row.get("window_is_burn_in_driven") for row in window_by_book.values()),
                "burn_in_bars_required": base.MIN_BARS,
                "reading": ("both books first trade on the same month end, so the "
                            "ladder/wide attribution gap cannot be a window difference"
                            if same_window else
                            "the two books first trade on different month ends, so part "
                            "of the attribution gap is window and only the remainder is "
                            "rate or valuation"),
            },
            "cash_mechanism": {
                "first_rebalance_index": rebal[0] if rebal else None,
                "first_trading_rebalance_index": first_trade_idx,
                "first_invested_bar": (cal[first_trade_idx + 1]
                                       if first_trade_idx is not None else None),
                "cash_bars": cash_bars,
                "cash_bar_share_pct": round(cash_bars / max(1, len(cal) - 1) * 100, 2),
                "rebalance_decisions": len(rebal),
                "panel_covered_days": (cash_panel or {}).get("covered_days"),
                "panel_ffilled_days": (cash_panel or {}).get("ffilled_days"),
                "panel_first": (cash_panel or {}).get("first"),
                "panel_last": (cash_panel or {}).get("last"),
                "mean_daily_cash_bp": round(sum(rates) / len(rates) * 1e4, 4) if rates else None,
                "mean_annual_cash_rate_pct": mean_rate_pct,
                "cash_is_discretionary": False,
                "per_book_window_published_separately": True,
                "why": ("the engine holds cash only for the un-invested weight: 1.0 until the first "
                        "rebalance whose live set is non-empty (eligibility needs a burn-in, "
                        "so that is far later than the first month end), then 0.0 after an "
                        "equal-weight rebalance, because the weight is taken over the live "
                        "names only. This block is the LADDER's window; E128 publishes every "
                        "book's own window under cash_window_by_book"),
            },
            "answers": {
                "ladder_cash_attributable_bp": table["ladder5"].get("x1", {}).get("ann_vs_x0_bp"),
                "wide_cash_attributable_bp": table[wide_name].get("x1", {}).get("ann_vs_x0_bp"),
                "ladder_x3_delta_bp": table["ladder5"].get("x3", {}).get("ann_vs_x0_bp"),
                "wide_x3_delta_bp": table[wide_name].get("x3", {}).get("ann_vs_x0_bp"),
                "cash_window_same_for_both_books": same_window,
                "ladder_identity_residual_bp":
                    window_by_book["ladder5"].get("residual_bp"),
                "wide_identity_residual_bp":
                    window_by_book[wide_name].get("residual_bp"),
                "identity_within_tolerance": {
                    name: row.get("within_tolerance")
                    for name, row in window_by_book.items()},
                "maxdd_moves_with_cash": {
                    name: round((table[name].get("x1", {}).get("max_drawdown_pct") or 0)
                                - (table[name].get("x0", {}).get("max_drawdown_pct") or 0), 2)
                    for name in table},
            },
        }
    return {
        "study": "e40_cashleg_drag",
        "evidence_cutoff": cutoff,
        "spec": {"pick_n": pick_n, "exclude_prefixes": list(exclude),
                 "rate_mults": list(rate_mults), "starts": list(starts),
                 "cost_bp_per_side": base.COST_BP_SIDE},
        "windows": windows,
        "honest": [
            "the repo leg is not a discretionary allocation: it is the un-invested weight of "
            "the same engine, so 'cash drag' here means the accrual rate on dead weight",
            "x0 reproduces the historical zero-cash convention (cash=None -> 0.0 daily return)",
            "a multiplier is a counterfactual rate, not a rate that ever existed",
            "the per-book identity residual is rate x share minus measured attribution: the "
            "engine compounds on the equity curve instead of summing linearly, so a few bp of "
            "gap is expected and a gap above the published tolerance is a defect in the "
            "attribution, not a market fact",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }


# ------------------------------------------------------- leg: size tilt (E40)

TILT_LARGE = ("sh510300", "sh510050")
TILT_SMALL = ("sh510500", "sh512100", "sh588000")
# four-member reach-back skin: sh588000 has no bars before 2020-11-13, so the
# five-member tilt cannot be measured on pre-2021 months (E43-TILT-4MEMBER-HISTORY)
TILT4_SMALL = ("sh510500", "sh512100")
# three-member reach-back skin: sh512100 has no bars before 2016-11-04, so the
# four-member tilt cannot be priced on 2013-2016 either (E43-TILT-3MEMBER-
# REACHBACK). Dropping it leaves 2 broad-cap vs sh510500 alone (first bar
# 2013-03-15), the only skin that reads the pre-2017 years -- at a composition
# cost that is published beside the wider skins rather than assumed away.
TILT3_SMALL = ("sh510500",)


def _tilt_series(mem, brk, months, large, small):
    """Monthly (small_mean - large_mean) on the months both legs can be priced.

    Returns (used_months, {month: tilt}, dropped) where a dropped month is one
    whose legs are missing a member or carry a >20% single-day corporate action
    on a member's own rows. Shared by the five-member and four-member skins so
    the two faces cannot drift apart.
    """
    used, tilt, dropped = [], {}, []
    for m in months:
        lg = [mem[s][m] for s in large if m in mem[s] and m not in brk[s]]
        sm = [mem[s][m] for s in small if m in mem[s] and m not in brk[s]]
        if not lg or not sm:
            dropped.append({
                "month": m,
                "members_with_break": [s for s in list(large) + list(small) if m in brk[s]],
                "members_missing": [s for s in list(large) + list(small) if m not in mem[s]],
            })
            continue
        used.append(m)
        tilt[m] = sum(sm) / len(sm) - sum(lg) / len(lg)
    return used, tilt, dropped


def _skin_months(lad_m, wide_m, mem, large, small):
    """Months one skin can be priced on: every member of BOTH legs is present.

    The wider skins bind on their newest member (sh588000 from 2020-11,
    sh512100 from 2016-11), so the reach-back of a skin IS this predicate. It is
    a named function rather than an inline comprehension because a selftest can
    then prove the narrow skin really extends the window instead of trusting the
    constant (E126 liveness leg).
    """
    need = list(large) + list(small)
    return [m for m in sorted(lad_m)
            if m in wide_m and all(m in mem[s] for s in need)]


def _compose_counts(live, large, small):
    """Weight shares of one equal-weight book by the ladder's own size legs."""
    n = len(live)
    if not n:
        return {"n": 0}
    ns = sum(1 for s in live if s in small)
    nl = sum(1 for s in live if s in large)
    return {
        "n": n,
        "ladder_small_names": ns,
        "ladder_large_names": nl,
        "ladder_small_weight_pct": round(ns / n * 100, 4),
        "ladder_large_weight_pct": round(nl / n * 100, 4),
        "other_weight_pct": round((n - ns - nl) / n * 100, 4),
    }


def _month_rets(curve):
    """[(YYYY-MM, return)] from month-end marks of an equity curve."""
    me = _month_ends(curve)
    return [(me[k][0][:7], me[k][1] / me[k - 1][1] - 1.0) for k in range(1, len(me))]


def _member_monthly(cal, sym, raw):
    """{YYYY-MM: return} for one member, from its own month-end closes."""
    c = raw.get(sym, ({}, {}))[0] if sym in raw else {}
    if not c:
        c = {}
    marks = []
    for i, d in enumerate(cal):
        if i == len(cal) - 1 or cal[i + 1][:7] != d[:7]:
            marks.append((d[:7], c.get(d)))
    out = {}
    for k in range(1, len(marks)):
        prev, cur = marks[k - 1][1], marks[k][1]
        if prev and cur and prev > 0:
            out[marks[k][0]] = cur / prev - 1.0
    return out


def _moments(xs):
    n = len(xs)
    if n < 2:
        return {"n": n, "mean": (xs[0] if xs else None), "sd": None}
    m = sum(xs) / n
    var = sum((x - m) ** 2 for x in xs) / (n - 1)
    return {"n": n, "mean": m, "sd": var ** 0.5}


def _member_break_months(cal, sym, raw, thresh=0.20):
    """{YYYY-MM} where the member's own rows carry a >thresh single-day jump.

    The panel is as-traded: a share split / unit conversion shows up as a one-day
    scale change (e.g. sh510500 2015-04-15 +248.6%, sh512100 2022-09-05 +176.3%).
    Those months are not a size move, so they are excluded from the spread and
    disclosed instead of being silently averaged in.
    """
    c = raw.get(sym, ({}, {}))[0] if sym in raw else {}
    out = set()
    prev = None
    for d in cal:
        v = c.get(d)
        if v and prev and prev > 0 and abs(v / prev - 1.0) > thresh:
            out.add(d[:7])
        if v:
            prev = v
    return out


def run_tilt(outdir, starts=("2020-01-01", "2018-01-01")):
    """Measure the ladder's size tilt, so a vs-ladder spread can be read net of it.

    The ladder is five equal weights across the size ladder, so it is not a
    neutral baseline: it carries 3/5 mid/small/STAR and 2/5 large-cap. This leg
    decomposes its monthly return into the size legs, measures the monthly
    large-vs-small spread as a series, and reports how much of the ladder's
    monthly variance that spread explains. The ladder curve itself is the
    E24/E27 engine's (module import), the members' monthly returns are marks
    from the panel rows.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    raw = e27.load_universe()
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]
    w_large = len(TILT_LARGE) / float(len(base.LADDER))
    w_small = len(TILT_SMALL) / float(len(base.LADDER))
    windows = {}
    for start in starts:
        cal = [d for d in cal_full if d >= start]
        years = len(cal) / 252.0
        prices = {}
        for s in base.LADDER:
            c = raw.get(s, ({}, {}))[0] if s in raw else {}
            if not c:
                c = base.load_panel(s)[1].get(s, {})
            prices[s] = [c.get(d) for d in cal]
        cash = base.load_cash_series(cal)
        curve, aux, _hold = e27.simulate(cal, prices, {}, base.LADDER, cash, None, 1.0, {})
        eng = dict(_month_rets(curve))
        mem = {s: _member_monthly(cal, s, raw) for s in base.LADDER}
        brk = {s: _member_break_months(cal, s, raw) for s in base.LADDER}
        months = sorted(m for m in eng if all(m in mem[s] for s in base.LADDER))
        used, dropped = [], []
        large_m, small_m = [], []
        for m in months:
            lg = [mem[s][m] for s in TILT_LARGE if m not in brk[s]]
            sm = [mem[s][m] for s in TILT_SMALL if m not in brk[s]]
            if lg and sm:
                used.append(m)
                large_m.append(sum(lg) / len(lg))
                small_m.append(sum(sm) / len(sm))
            else:
                dropped.append({"month": m,
                                "members_with_break": [s for s in base.LADDER if m in brk[s]]})
        months = used
        break_events = [{"member": s, "months": sorted(brk[s])}
                        for s in base.LADDER if brk[s]]
        tilt_m = [sm - lm for lm, sm in zip(large_m, small_m)]
        ladder_m = [w_large * lm + w_small * sm for lm, sm in zip(large_m, small_m)]
        eng_m = [eng[m] for m in months]
        recon = max((abs(a - b) for a, b in zip(eng_m, ladder_m)), default=None)
        tl = _moments(tilt_m)
        lv = _moments(eng_m)
        beta = None
        alpha = None
        r2 = None
        if tl["sd"] and lv["sd"] and len(months) > 2:
            cov = sum((t - tl["mean"]) * (l - lv["mean"])
                      for t, l in zip(tilt_m, eng_m)) / (len(months) - 1)
            beta = cov / (tl["sd"] ** 2)
            alpha = lv["mean"] - beta * tl["mean"]
            r2 = (cov ** 2) / (tl["sd"] ** 2 * lv["sd"] ** 2)
        worst_i = min(range(len(eng_m)), key=lambda i: eng_m[i]) if eng_m else None
        best_i = max(range(len(eng_m)), key=lambda i: eng_m[i]) if eng_m else None
        cum = 1.0
        for t in tilt_m:
            cum *= 1.0 + t
        windows[start] = {
            "bars": len(cal), "years": round(years, 2), "months": len(months),
            "size_weights": {"large": round(w_large, 4), "small": round(w_small, 4),
                             "large_legs": list(TILT_LARGE), "small_legs": list(TILT_SMALL)},
            "break_guard": {"single_day_threshold_pct": 20.0,
                            "member_break_events": break_events,
                            "excluded_months": dropped},
            "monthly": {
                "ladder_mean_pct": round(lv["mean"] * 100, 4) if lv["mean"] is not None else None,
                "ladder_sd_pct": round(lv["sd"] * 100, 4) if lv["sd"] is not None else None,
                "tilt_mean_bp": round(tl["mean"] * 1e4, 2) if tl["mean"] is not None else None,
                "tilt_sd_bp": round(tl["sd"] * 1e4, 2) if tl["sd"] is not None else None,
                "tilt_annualised_bp": round(tl["mean"] * 12 * 1e4, 2) if tl["mean"] is not None else None,
                "tilt_share_positive_pct": round(
                    sum(1 for t in tilt_m if t > 0) / len(tilt_m) * 100, 1) if tilt_m else None,
                "tilt_cumulative_pct": round((cum - 1.0) * 100, 2) if months else None,
                "tilt_best_month": ({"month": months[max(range(len(tilt_m)), key=lambda i: tilt_m[i])],
                                     "spread_pct": round(tilt_m[max(range(len(tilt_m)), key=lambda i: tilt_m[i])] * 100, 2)}
                                    if tilt_m else None),
                "tilt_worst_month": ({"month": months[min(range(len(tilt_m)), key=lambda i: tilt_m[i])],
                                      "spread_pct": round(tilt_m[min(range(len(tilt_m)), key=lambda i: tilt_m[i])] * 100, 2)}
                                     if tilt_m else None),
            },
            "exposure_regression": {
                "beta_ladder_on_tilt": round(beta, 3) if beta is not None else None,
                "alpha_monthly_bp": round(alpha * 1e4, 2) if alpha is not None else None,
                "r_squared": round(r2, 4) if r2 is not None else None,
                "tilt_explains_ladder_var_pct": round(r2 * 100, 2) if r2 is not None else None,
                "identity_reconciliation_max_abs_diff": (round(recon, 12)
                                                         if recon is not None else None),
                "reconciliation_note": ("largest gap between the engine's monthly curve and the "
                                        "marks-implied 0.4*large+0.6*small month; a non-zero gap is "
                                        "eligibility burn-in / rebalance-timing, not an identity "
                                        "failure"),
            },
            "worst_month_diagnostic": ({
                "month": months[worst_i],
                "ladder_pct": round(eng_m[worst_i] * 100, 2),
                "large_leg_pct": round(large_m[worst_i] * 100, 2),
                "small_leg_pct": round(small_m[worst_i] * 100, 2),
                "tilt_spread_pct": round(tilt_m[worst_i] * 100, 2),
                "members": {s: round(mem[s][months[worst_i]] * 100, 2) for s in base.LADDER},
            } if worst_i is not None else None),
            "best_month_diagnostic": ({
                "month": months[best_i],
                "ladder_pct": round(eng_m[best_i] * 100, 2),
                "tilt_spread_pct": round(tilt_m[best_i] * 100, 2),
            } if best_i is not None else None),
            "engine_metrics": base.metrics(curve, years),
            "turnover_per_year": aux["turnover_total"] / years if years else None,
        }
    return {
        "study": "e40_ladder_size_tilt",
        "evidence_cutoff": cutoff,
        "spec": {"ladder": base.LADDER, "large": list(TILT_LARGE), "small": list(TILT_SMALL),
                 "decomposition": "ladder_monthly = 0.4*large_mean + 0.6*small_mean",
                 "starts": list(starts), "cost_bp_per_side": base.COST_BP_SIDE},
        "windows": windows,
        "answers": {k: {
            "tilt_annualised_bp": v["monthly"]["tilt_annualised_bp"],
            "tilt_sd_bp": v["monthly"]["tilt_sd_bp"],
            "beta_ladder_on_tilt": v["exposure_regression"]["beta_ladder_on_tilt"],
            "tilt_explains_ladder_var_pct": v["exposure_regression"]["tilt_explains_ladder_var_pct"],
            "worst_month": v["worst_month_diagnostic"]["month"] if v["worst_month_diagnostic"] else None,
        } for k, v in windows.items()},
        "honest": [
            "the ladder curve is the E24/E27 engine's own (module import); members' monthly "
            "returns are month-end marks from panel rows, so the reconciliation row prices the gap",
            "large/small split is a naming choice (two broad-cap legs vs mid/small/STAR), not a "
            "factor-model exposure estimate",
            "the regression is descriptive: it says how much monthly variance moves with the "
            "spread, not that the spread causes anything",
            "corporate-action guard: a member month carrying a >20% single-day jump on its own "
            "rows is dropped from that month's leg mean (the panel is as-traded, so a share "
            "split or unit conversion reads as a 100%+ return)",
            "both start windows resolve to the same member months: the common-month set is "
            "bounded by sh588000's first bar, so the 2018 window adds engine months that carry "
            "no member marks and cannot enter the spread",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }


# ------------------------------------------------ leg: rebalance-day shift

def _shift_indices(idxs, k, n):
    """Shift rebalance indices by k sessions, clamped into [0, n-1], deduped."""
    return sorted({min(max(i + k, 0), n - 1) for i in idxs})


def _mid_month_indices(cal, day=15):
    """First trading index of each month whose day-of-month is >= day."""
    out, seen = [], set()
    for i, d in enumerate(cal):
        m = d[:7]
        if m in seen or int(d[8:10]) < day:
            continue
        seen.add(m)
        out.append(i)
    return out


def run_rebalday(outdir, starts=("2020-01-01", "2018-01-01"), pick_n=9999,
                 exclude=("sh511",), mid_day=15, raw=None):
    """Does the verdict survive moving the decision calendar by one session?

    Every number in E34-E40 rests on one decision calendar: month-end. This leg
    re-runs the identical spec (same universe, same rank cache, same cost) on
    month-end-1 / month-end / month-end+1 and on a mid-month date, for the
    ladder and the wide book alike, so a day-of-month artefact cannot hide
    inside a quoted spread. The engine's own semantics apply: it reads the
    rebalance set as "the close of index (i-1) is the decision", so a shift of
    k sessions moves decision and trade together.

    ``raw`` (E121) is the screened-twin seam: the twin hands in a repaired
    universe so both arms burn off one load.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    raw_all = raw if raw is not None else e27.load_universe()
    if exclude:
        raw_all = {s: v for s, v in raw_all.items()
                   if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]
    wide_name = "wide_top%d" % pick_n
    windows = {}
    for start in starts:
        cal = [d for d in cal_full if d >= start]
        years = len(cal) / 252.0
        all_syms = sorted(set(base.LADDER) | set(raw_all))
        prices, amounts = {}, {}
        for s in all_syms:
            c, a = raw_all.get(s, ({}, {}))
            prices[s] = [c.get(d) for d in cal]
            amounts[s] = [a.get(d) for d in cal]
        universe = [s for s in all_syms if s in raw_all]
        cash = base.load_cash_series(cal)
        rank_cache = {}
        month_ends = base.month_end_indices(cal)
        variants = [
            ("me_m1", _shift_indices(month_ends, -1, len(cal))),
            ("me", sorted(set(month_ends))),
            ("me_p1", _shift_indices(month_ends, 1, len(cal))),
            ("mid%d" % mid_day, _mid_month_indices(cal, mid_day)),
        ]
        rows = {}
        for vname, idxs in variants:
            rebal = set(idxs)
            rows[vname] = {"rebalances": len(rebal)}
            for scheme, univ, n in (("ladder5", base.LADDER, None),
                                    (wide_name, universe, pick_n)):
                curve, aux, _hold = e27.simulate(cal, prices, amounts, univ, cash,
                                                 n, 1.0, rank_cache, rebal)
                prof = risk_profile(curve, years)
                rows[vname][scheme] = {
                    "ann_return_pct": prof["ann_return_pct"],
                    "max_drawdown_pct": prof["max_drawdown_pct"],
                    "monthly_win_rate_pct": prof["monthly_win_rate_pct"],
                    "rebalances": aux["rebalances"],
                    "turnover_per_year": round(aux["turnover_total"] / years, 3) if years else None,
                }
            rows[vname]["vs_ladder_spread_bp"] = round(
                (rows[vname][wide_name]["ann_return_pct"]
                 - rows[vname]["ladder5"]["ann_return_pct"]) * 100, 1)
        lad = [r["ladder5"]["ann_return_pct"] for r in rows.values()]
        wid = [r[wide_name]["ann_return_pct"] for r in rows.values()]
        spr = [r["vs_ladder_spread_bp"] for r in rows.values()]
        windows[start] = {
            "bars": len(cal), "years": round(years, 2),
            "variants": rows,
            "answers": {
                "ladder_ann_range_bp": round((max(lad) - min(lad)) * 100, 1),
                "wide_ann_range_bp": round((max(wid) - min(wid)) * 100, 1),
                "spread_range_bp": round(max(spr) - min(spr), 1),
                "spread_all_positive": all(x > 0 for x in spr),
                "spread_min_bp": min(spr), "spread_max_bp": max(spr),
                "spread_at_month_end_bp": rows["me"]["vs_ladder_spread_bp"],
                "universe_members": len(universe),
            },
        }
    return {
        "study": "e41_rebalance_day_sensitivity",
        "evidence_cutoff": cutoff,
        "spec": {"pick_n": pick_n, "exclude_prefixes": list(exclude),
                 "cost_mult": 1.0, "cost_bp_per_side": base.COST_BP_SIDE,
                 "starts": list(starts), "mid_month_day": mid_day,
                 "variants": ["me_m1", "me", "me_p1", "mid%d" % mid_day]},
        "windows": windows,
        "answers": {k: v["answers"] for k, v in windows.items()},
        "honest": [
            "the engine reads the rebalance set as a decision at the close of index (i-1), so a "
            "one-session shift moves decision and trade together; this leg does not test a "
            "decision-only shift",
            "all four variants share one calendar, one universe and one rank cache, so the only "
            "moving part is the set of decision sessions",
            "mid-month is a single fixed date (day %d), not a sweep: it prices a wrong-calendar "
            "cost, it does not search for a better one" % mid_day,
            "spread is the annualised column difference in bp, the same convention as E34-E40; "
            "the ratio curve's path is not re-measured here",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }


# ---------------------------------------------------- leg: spread era decay

def _slice_curve(curve, lo, hi):
    return [(d, v) for d, v in curve if (lo is None or d >= lo) and (hi is None or d <= hi)]


def _rebase(curve):
    if not curve:
        return []
    base = curve[0][1]
    return [(d, v / base) for d, v in curve] if base else []


def _era_curves(raw_all, cal, pick_n, cost_mult=1.0):
    """(E41/E76/E77) the ladder5 and wide-top-N curves on one calendar.

    Factored out of run_era so the E76 screen leg can replay the identical book
    from a repaired universe: the two faces then differ only in the closes
    handed in, not in any book convention.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    all_syms = sorted(set(base.LADDER) | set(raw_all))
    prices, amounts = {}, {}
    for s in all_syms:
        c, a = raw_all.get(s, ({}, {}))
        prices[s] = [c.get(d) for d in cal]
        amounts[s] = [a.get(d) for d in cal]
    universe = [s for s in all_syms if s in raw_all]
    cash = base.load_cash_series(cal)
    rank_cache = {}
    curves = {}
    for name, univ, n in (("ladder5", base.LADDER, None),
                          ("wide_top%d" % pick_n, universe, pick_n)):
        curves[name], _aux, _hold = e27.simulate(cal, prices, amounts, univ, cash,
                                                 n, cost_mult, rank_cache)
    lad = curves["ladder5"]
    wide = curves["wide_top%d" % pick_n]
    lmap = dict(lad)
    ratio = [(d, v / lmap[d]) for d, v in wide if d in lmap and lmap[d] > 0]
    return lad, wide, ratio


def _era_rows(lad, wide, ratio, eras):
    """Era-partitioned risk profile of the ladder, the wide book and their ratio."""
    rows = {}
    for name, lo, hi in eras:
        seg_l = _rebase(_slice_curve(lad, lo, hi))
        seg_w = _rebase(_slice_curve(wide, lo, hi))
        seg_r = _rebase(_slice_curve(ratio, lo, hi))
        if len(seg_l) < 2 or len(seg_w) < 2 or len(seg_r) < 2:
            rows[name] = {"bars": len(seg_l), "skipped": "fewer than 2 bars in this era"}
            continue
        yrs = len(seg_l) / 252.0
        pl = risk_profile(seg_l, yrs)
        pw = risk_profile(seg_w, yrs)
        pr = risk_profile(seg_r, yrs)
        rows[name] = {
            "from": seg_l[0][0], "to": seg_l[-1][0], "bars": len(seg_l),
            "years": round(yrs, 2),
            "ladder_ann_pct": pl["ann_return_pct"],
            "wide_ann_pct": pw["ann_return_pct"],
            "spread_ann_bp": round((pw["ann_return_pct"] - pl["ann_return_pct"]) * 100, 1),
            "spread_positive": (pw["ann_return_pct"] - pl["ann_return_pct"]) > 0,
            "ratio_path": {
                "ann_pct": pr["ann_return_pct"],
                "max_drawdown_pct": pr["max_drawdown_pct"],
                "max_drawdown_span": pr["max_drawdown_span"],
                "longest_underwater_sessions": pr["longest_underwater_sessions"],
                "worst_month": pr["worst_month"],
                "monthly_win_rate_pct": pr["monthly_win_rate_pct"],
                "months": pr["months"],
            },
            "ladder_max_drawdown_pct": pl["max_drawdown_pct"],
            "wide_max_drawdown_pct": pw["max_drawdown_pct"],
        }
    return rows


def run_era(outdir, pick_n=9999, exclude=("sh511",),
            eras=(("pre2017", None, "2016-12-31"),
                  ("2017_2020", "2017-01-01", "2020-12-31"),
                  ("2021_2023", "2021-01-01", "2023-12-31"),
                  ("2024_now", "2024-01-01", None))):
    """Is the vs-ladder spread a regime or a constant?

    The 2020+ pair leg measured the spread's own -13.04% drawdown, which already
    says it is not a constant. This leg splits the same ratio curve by era and
    profiles each slice on its own (re-based at the era's first bar), so a
    single full-sample number cannot stand in for a path.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    raw_all = e27.load_universe()
    if exclude:
        raw_all = {s: v for s, v in raw_all.items()
                   if not s.startswith(tuple(exclude))}
    cal = base.load_panel()[0]
    cutoff = cal[-1]
    lad, wide, ratio = _era_curves(raw_all, cal, pick_n)
    rows = _era_rows(lad, wide, ratio, eras)
    spreads = [r["spread_ann_bp"] for r in rows.values() if "spread_ann_bp" in r]
    return {
        "study": "e41_spread_era_decay",
        "evidence_cutoff": cutoff,
        "spec": {"pick_n": pick_n, "exclude_prefixes": list(exclude),
                 "cost_mult": 1.0, "cost_bp_per_side": base.COST_BP_SIDE,
                 "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
                 "calendar_from": cal[0]},
        "eras": rows,
        "answers": {
            "spread_positive_eras": sum(1 for r in rows.values() if r.get("spread_positive")),
            "eras_with_data": len(spreads),
            "spread_range_bp": (round(max(spreads) - min(spreads), 1) if spreads else None),
            "spread_min_bp": min(spreads) if spreads else None,
            "spread_max_bp": max(spreads) if spreads else None,
            "era_of_worst_ratio_drawdown": min(
                (r for r in rows.values() if "ratio_path" in r),
                key=lambda r: r["ratio_path"]["max_drawdown_pct"])["from"]
            if any("ratio_path" in r for r in rows.values()) else None,
        },
        "honest": [
            "eras are calendar partitions of one continuous curve; each slice is re-based at its "
            "own first bar, so era ann% are not additive and do not compound to the full-sample number",
            "the last era is open-ended (2024-01-01 to the cutoff) and is therefore the shortest "
            "and the least stable",
            "the ratio curve is a ratio of equity curves, not a tradable sleeve",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }


# ------------------------------------ leg: E42 spread net of the size tilt
#
# E40 measured the ladder's own size tilt (beta 0.62 on the small-minus-large
# month, +612bp/yr) and E41 measured a spread that is 4.7x thinner in the newest
# era than at its 2017-2020 peak. Both are quoted against the same ladder
# denominator, so neither can be read alone: this leg decomposes the spread and
# reports the intercept, which is what the wide book pays when the size leg is
# flat. Then it splits the tilt itself by the same four eras, so one full-sample
# exposure number cannot stand in for a regime. Monthly additive convention
# throughout, so every bp column is directly comparable.

ERAS = (("pre2017", None, "2016-12-31"),
        ("2017_2020", "2017-01-01", "2020-12-31"),
        ("2021_2023", "2021-01-01", "2023-12-31"),
        ("2024_now", "2024-01-01", None))

# E74: the panel carries some names unadjusted, so a share split prints as a
# -90% "return". Any single-session move beyond any A-share/ETF daily limit is
# treated as a corporate-action artefact and excluded from the priced tail.
ARTEFACT_JUMP = 0.30


def _in_era(month, lo, hi):
    """Month (YYYY-MM) inside an era whose bounds are dates (YYYY-MM-DD) or None."""
    if lo and month < lo[:7]:
        return False
    if hi and month > hi[:7]:
        return False
    return True


def _ols(y, x):
    """OLS y = alpha + beta*x -> (beta, alpha, r2); None when under-determined."""
    if len(y) < 3:
        return None, None, None
    my, mx = _moments(y), _moments(x)
    # a constant series has sd ~1e-17 from float rounding, not 0.0 -- compare to a tolerance
    if my["sd"] is None or mx["sd"] is None or my["sd"] <= 1e-15 or mx["sd"] <= 1e-15:
        return None, None, None
    cov = sum((a - my["mean"]) * (b - mx["mean"]) for a, b in zip(y, x)) / (len(y) - 1)
    beta = cov / (mx["sd"] ** 2)
    alpha = my["mean"] - beta * mx["mean"]
    r2 = (cov ** 2) / (mx["sd"] ** 2 * my["sd"] ** 2)
    return beta, alpha, r2


def _monthly_core(pick_n=9999, exclude=("sh511",), raw_all=None, contrib=False,
                  cost_mult=1.0):
    """One shared build: both engine curves plus the member tilt series.

    The two E42 product legs read this object so their faces cannot drift apart
    and the expensive panel pass happens once per process.

    ``raw_all`` lets a screen leg hand in a repaired universe (E81). With the
    default ``None`` this calls ``e27.load_universe()`` exactly as before, so
    every published face keeps reading the untouched loader.

    ``contrib=True`` (E174) additionally keeps each book's per-(month, name)
    arithmetic contribution in ``core["contrib"]``, so a leg can say which name
    carried an engine month. Off by default: the recorder costs a dict write per
    name-day and no existing face should pay for it.

    ``cost_mult`` (E185) is the fee seam: the sink records only the ``w*r``
    growth term, so a decomposition read off the sink is GROSS of the turnover
    fee while one read off the curve is NET of it. Passing 0.0 rebuilds the same
    two books with the fee switched off, which is how that one term is measured.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    if raw_all is None:
        raw_all = e27.load_universe()
    if exclude:
        raw_all = {s: v for s, v in raw_all.items()
                   if not s.startswith(tuple(exclude))}
    cal = base.load_panel()[0]
    cutoff = cal[-1]
    all_syms = sorted(set(base.LADDER) | set(raw_all))
    prices, amounts = {}, {}
    for s in all_syms:
        c, a = raw_all.get(s, ({}, {}))
        prices[s] = [c.get(d) for d in cal]
        amounts[s] = [a.get(d) for d in cal]
    universe = [s for s in all_syms if s in raw_all]
    cash = base.load_cash_series(cal)
    rank_cache = {}
    wide_name = "wide_top%d" % pick_n
    curves = {}
    sinks = {}
    for name, univ, n in (("ladder5", base.LADDER, None), (wide_name, universe, pick_n)):
        sinks[name] = {} if contrib else None
        curves[name], _aux, _hold = e27.simulate(cal, prices, amounts, univ, cash,
                                                 n, cost_mult, rank_cache,
                                                 contrib=sinks[name])
    lad_m = dict(_month_rets(curves["ladder5"]))
    wide_m = dict(_month_rets(curves[wide_name]))
    mem = {s: _member_monthly(cal, s, raw_all) for s in base.LADDER}
    brk = {s: _member_break_months(cal, s, raw_all) for s in base.LADDER}
    five_ok = _skin_months(lad_m, wide_m, mem, TILT_LARGE, TILT_SMALL)
    months, tilt, dropped = _tilt_series(mem, brk, five_ok, TILT_LARGE, TILT_SMALL)
    four_ok = _skin_months(lad_m, wide_m, mem, TILT_LARGE, TILT4_SMALL)
    months4, tilt4, dropped4 = _tilt_series(mem, brk, four_ok, TILT_LARGE, TILT4_SMALL)
    three_ok = _skin_months(lad_m, wide_m, mem, TILT_LARGE, TILT3_SMALL)
    months3, tilt3, dropped3 = _tilt_series(mem, brk, three_ok, TILT_LARGE, TILT3_SMALL)
    return {"cutoff": cutoff, "cal": cal, "curves": curves, "wide_name": wide_name,
            "lad_m": lad_m, "wide_m": wide_m, "months": months, "tilt": tilt,
            "months4": months4, "tilt4": tilt4, "dropped4": dropped4,
            "months3": months3, "tilt3": tilt3, "dropped3": dropped3,
            "dropped": dropped, "universe": len(universe),
            # E174: the per-name arithmetic behind both engine curves, off unless asked
            "contrib": ({"wide": sinks[wide_name], "lad": sinks["ladder5"]}
                        if contrib else None),
            # per-member monthly returns + break months, so a leg can rebuild any
            # sub-skin without a second panel pass (E44 leave-one-out)
            "mem": mem, "brk": brk,
            "years": len(cal) / 252.0}


def run_spreadsize(outdir, core=None, eras=ERAS):
    """Restate the vs-ladder spread net of the size tilt, per era."""
    core = core or _monthly_core()
    rows = {}
    for name, lo, hi in list(eras) + [("full", None, None)]:
        ms = [m for m in core["months"] if _in_era(m, lo, hi)]
        if len(ms) < 3:
            rows[name] = {"months": len(ms), "skipped": "fewer than 3 usable months"}
            continue
        spread = [core["wide_m"][m] - core["lad_m"][m] for m in ms]
        tilt = [core["tilt"][m] for m in ms]
        raw_ann = sum(spread) / len(spread) * 12.0 * 1e4
        beta, alpha, r2 = _ols(spread, tilt)
        tilt_ann = sum(tilt) / len(tilt) * 12.0 * 1e4
        size_part = beta * tilt_ann if beta is not None else None
        # reconciliation against the E41 era leg: the geometric ann% difference on the
        # same era slice. The additive monthly mean and the compounded difference are
        # two conventions of one quantity, so the gap is disclosed, never averaged away.
        seg_l = _rebase(_slice_curve(core["curves"]["ladder5"], lo, hi))
        seg_w = _rebase(_slice_curve(core["curves"][core["wide_name"]], lo, hi))
        eng_diff = None
        if len(seg_l) > 1 and len(seg_w) > 1:
            yrs = len(seg_l) / 252.0
            eng_diff = round((risk_profile(seg_w, yrs)["ann_return_pct"]
                              - risk_profile(seg_l, yrs)["ann_return_pct"]) * 100, 1)
        rows[name] = {
            "months": len(ms), "from": ms[0], "to": ms[-1],
            "raw_spread_ann_bp": round(raw_ann, 1),
            "size_neutral_ann_bp": round(alpha * 12.0 * 1e4, 1) if alpha is not None else None,
            "size_component_ann_bp": round(size_part, 1) if size_part is not None else None,
            "beta_spread_on_tilt": round(beta, 3) if beta is not None else None,
            "alpha_monthly_bp": round(alpha * 1e4, 2) if alpha is not None else None,
            "r_squared": round(r2, 4) if r2 is not None else None,
            "tilt_explains_spread_var_pct": round(r2 * 100, 2) if r2 is not None else None,
            "tilt_ann_bp_in_era": round(tilt_ann, 1),
            "share_of_spread_from_size_pct": (
                round(size_part / raw_ann * 100, 1) if size_part is not None and raw_ann else None),
            "engine_ann_diff_bp": eng_diff,
            "arithmetic_vs_geometric_gap_bp": (
                round(raw_ann - eng_diff, 1) if eng_diff is not None else None),
        }
    per_era = {k: v for k, v in rows.items() if k != "full" and "raw_spread_ann_bp" in v}
    neutral = [v["size_neutral_ann_bp"] for v in per_era.values() if v.get("size_neutral_ann_bp") is not None]
    return {
        "study": "e42_spread_size_neutral",
        "evidence_cutoff": core["cutoff"],
        "spec": {"pick_n": 9999, "exclude_prefixes": ["sh511"], "cost_mult": 1.0,
                 "calendar": "month-end decision, the E24/E27 default",
                 "decomposition": "spread_m = alpha + beta * tilt_m; "
                                  "size_neutral = alpha*12*1e4 bp, size = beta*tilt_mean*12*1e4 bp",
                 "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
                 "universe_members": core["universe"]},
        "eras": rows,
        "answers": {
            "size_neutral_range_bp": (round(max(neutral) - min(neutral), 1) if neutral else None),
            "size_neutral_min_bp": min(neutral) if neutral else None,
            "size_neutral_max_bp": max(neutral) if neutral else None,
            "eras_positive_size_neutral": sum(1 for x in neutral if x > 0),
            "eras_with_data": len(neutral),
            "max_arithmetic_vs_geometric_gap_bp": max(
                (abs(v["arithmetic_vs_geometric_gap_bp"]) for v in per_era.values()
                 if v.get("arithmetic_vs_geometric_gap_bp") is not None), default=None),
            "alpha_equals_raw_minus_size_row_check": all(
                abs((v["raw_spread_ann_bp"] or 0) - (v["size_neutral_ann_bp"] or 0)
                    - (v["size_component_ann_bp"] or 0)) <= 0.25
                for v in per_era.values() if "raw_spread_ann_bp" in v),
        },
        "honest": [
            "the tilt is a naming split (2 broad-cap legs vs 3 mid/small/STAR legs), not a "
            "factor-model exposure; beta is descriptive, it does not claim the size spread causes "
            "the ladder/wide gap",
            "the two engine curves are the E24/E27 engine's own (module import); the tilt series is "
            "month-end marks from the panel rows",
            "monthly convention: raw = size_neutral + size component holds on the arithmetic mean, "
            "so the columns do not compound to the era-leg's geometric ann% difference",
            "member months carrying a >20% single-day corporate-action jump are dropped from the "
            "tilt mean (as-traded panel), and the dropped set is disclosed below",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
        "dropped_months": core["dropped"],
    }


SPREAD_COLUMNS = ("raw_spread_ann_bp", "size_neutral_ann_bp",
                  "size_component_ann_bp", "beta_spread_on_tilt", "r_squared")


def _spread_delta_rows(base_label, faces, modes, eras):
    """Column-by-column unscreened vs screened table for the E42 spread face.

    Pure function of the built faces, so the selftest can pin the arithmetic
    without touching the panel.
    """
    rows = []
    base_face = faces[base_label]["eras"]
    order = [n for n, _lo, _hi in list(eras) + [("full", None, None)]]
    for era in order:
        era_row = base_face.get(era) or {}
        for col in SPREAD_COLUMNS:
            u = era_row.get(col)
            row = {"era": era, "column": col, "unscreened": u}
            for mode in modes:
                v = (faces[mode]["eras"].get(era) or {}).get(col)
                row[mode] = v
                # one delta column per arm, not per cell column: a single
                # ``delta_<column>`` key would keep only the last arm's figure
                row["delta_" + mode] = (round(v - u, 4)
                                        if isinstance(v, (int, float))
                                        and isinstance(u, (int, float)) else None)
            rows.append(row)
    return rows


def run_screenspread(outdir, pick_n=9999, exclude=("sh511",),
                     modes=("neutralise_int", "neutralise", "neutralise_persist"),
                     eras=ERAS):
    """E81 leg 2: replay the size-neutral spread from the repaired universe.

    E42's newest-era size-neutral spread is the number the chain quotes as its
    surviving claim, and it is an equal-weight figure read from the as-traded
    panel -- so a share-split print inside the wide book is charged at weight
    1/n, exactly the defect E81 screened out of the calendar face. This leg
    rebuilds the whole monthly core per arm (engine curves *and* the member tilt
    series, so the regression and its regressor move together) and publishes the
    screened column beside the unscreened one. No published face is rewritten.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    if exclude:
        raw = {s: v for s, v in raw.items() if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]

    arms = {"unscreened": raw}
    reports = {}
    for mode in modes:
        repaired, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)
        reports[mode] = report
        arms[mode] = repaired

    faces = {}
    for label, univ in arms.items():
        core = _monthly_core(pick_n=pick_n, exclude=(), raw_all=univ)
        face = run_spreadsize(None, core=core, eras=eras)
        faces[label] = {"universe_size": len(univ),
                        "months": len(core["months"]),
                        "eras": face["eras"],
                        "answers": face["answers"]}

    delta = _spread_delta_rows("unscreened", faces, modes, eras)
    order = [n for n, _lo, _hi in list(eras) + [("full", None, None)]]

    def _neutral(arm, era):
        return (faces[arm]["eras"].get(era) or {}).get("size_neutral_ann_bp")

    levels = {arm: {era: _neutral(arm, era) for era in order} for arm in faces}
    per_era = [n for n, _lo, _hi in eras]

    def _band(arm):
        xs = [levels[arm][e] for e in per_era if levels[arm][e] is not None]
        return (round(max(xs) - min(xs), 1) if len(xs) >= 2 else None)

    def _level(arm):
        xs = [levels[arm][e] for e in per_era if levels[arm][e] is not None]
        return round(sum(xs) / len(xs), 1) if xs else None

    def _all_positive(arm):
        xs = [levels[arm][e] for e in per_era if levels[arm][e] is not None]
        return all(x > 0 for x in xs) if xs else None

    # E82: a moved cell must be nameable. Count the repaired prints by era and
    # carry the newest-era names, so the reader can check the dates themselves.
    def _era_event_census(mode):
        counts = {n: 0 for n, _lo, _hi in list(eras) + [("full", None, None)]}
        named = []
        for entry in reports[mode].get("names") or []:
            if entry.get("action") != "neutralise":
                continue
            for pr in entry.get("prints") or []:
                if pr.get("factor_applied") is None:
                    continue
                era = _era_of(pr.get("date"), eras) or "full"
                counts[era] = counts.get(era, 0) + 1
                counts["full"] = counts.get("full", 0) + 1
                if era == "2024_now" and len(named) < 8:
                    named.append({"name": entry["name"], "date": pr.get("date"),
                                  "ret_pct": pr.get("ret_pct"),
                                  "ratio": round(pr.get("ratio") or 0.0, 4),
                                  "nearest_int": pr.get("nearest_int")})
        return {"events_by_era": counts, "newest_era_names_sample": named}

    flips = {}
    for mode in modes:
        flips[mode] = [e for e in per_era
                       if levels["unscreened"][e] is not None
                       and levels[mode][e] is not None
                       and (levels["unscreened"][e] > 0) != (levels[mode][e] > 0)]
    moves = []
    for mode in modes:
        for r in delta:
            if r["column"] == "size_neutral_ann_bp" and r.get("delta_" + mode):
                x = dict(r)
                x["arm"] = mode
                x["delta_bp"] = r["delta_" + mode]
                moves.append(x)
    widest = max(moves, key=lambda r: abs(r["delta_bp"])) if moves else None
    return {
        "study": "e42_spread_size_neutral_screened",
        "evidence_cutoff": cutoff,
        "spec": {"pick_n": pick_n, "exclude_prefixes": list(exclude), "cost_mult": 1.0,
                 "modes": list(modes),
                 "calendar": "month-end decision, the E24/E27 default",
                 "decomposition": "spread_m = alpha + beta * tilt_m; "
                                  "size_neutral = alpha*12*1e4 bp, size = beta*tilt_mean*12*1e4 bp",
                 "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
                 "screen": {m: reports[m] for m in modes}},
        "arms": faces,
        "delta": delta,
        "answers": {
            "size_neutral_by_arm_era_bp": levels,
            "level_mean_over_eras_bp": {arm: _level(arm) for arm in faces},
            "band_max_minus_min_bp": {arm: _band(arm) for arm in faces},
            "all_eras_positive": {arm: _all_positive(arm) for arm in faces},
            "sign_flips_vs_unscreened": flips,
            "era_event_census": {m: _era_event_census(m) for m in modes},
            "full_sample_size_neutral_bp": {arm: levels[arm].get("full") for arm in faces},
            "widest_correction": widest,
            "delta_cells": len(delta),
            "non_zero_delta_cells": sum(
                1 for r in delta
                if any(r.get("delta_" + m) not in (None, 0, 0.0) for m in modes)),
            "arm_alpha_identity_holds": {
                arm: faces[arm]["answers"]["alpha_equals_raw_minus_size_row_check"]
                for arm in faces},
        },
        "honest": [
            "repairing an integer-ratio print is a sensitivity, not a correction: an ETF whose "
            "daily limit differs from the 10%/20% stock band can print >30% for real",
            "the screen repairs both the wide book and the tilt members, so a moved alpha is net "
            "of both legs and is not attributable to one of them",
            "the unscreened arm is rebuilt here rather than copied from the published face: it is "
            "the same code path on the same panel, and the published COST/NEUTRAL files stay "
            "untouched",
            "level and band are published together: max-min over eras is blind to a common shift, "
            "which is exactly how the E81 calendar leg first hid a tripled level",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }


def run_tilt_era(outdir, core=None, eras=ERAS):
    """Split the ladder's size tilt and its beta/R2 by the same four eras."""
    core = core or _monthly_core()
    rows = {}
    for name, lo, hi in list(eras) + [("full", None, None)]:
        ms = [m for m in core["months"] if _in_era(m, lo, hi)]
        if len(ms) < 3:
            rows[name] = {"months": len(ms), "skipped": "fewer than 3 usable months"}
            continue
        tilt = [core["tilt"][m] for m in ms]
        lad = [core["lad_m"][m] for m in ms]
        tm = _moments(tilt)
        beta, alpha, r2 = _ols(lad, tilt)
        cum = 1.0
        for t in tilt:
            cum *= 1.0 + t
        pos = sum(1 for t in tilt if t > 0)
        i_max = max(range(len(tilt)), key=lambda i: tilt[i])
        i_min = min(range(len(tilt)), key=lambda i: tilt[i])
        rows[name] = {
            "months": len(ms), "from": ms[0], "to": ms[-1],
            "tilt_annualised_bp": round(tm["mean"] * 12 * 1e4, 1) if tm["mean"] is not None else None,
            "tilt_sd_bp": round(tm["sd"] * 1e4, 1) if tm["sd"] is not None else None,
            "tilt_positive_share_pct": round(pos / len(tilt) * 100, 1),
            "tilt_cumulative_pct": round((cum - 1.0) * 100, 2),
            "tilt_best_month": {"month": ms[i_max], "spread_pct": round(tilt[i_max] * 100, 2)},
            "tilt_worst_month": {"month": ms[i_min], "spread_pct": round(tilt[i_min] * 100, 2)},
            "beta_ladder_on_tilt": round(beta, 3) if beta is not None else None,
            "alpha_monthly_bp": round(alpha * 1e4, 2) if alpha is not None else None,
            "r_squared": round(r2, 4) if r2 is not None else None,
            "tilt_explains_ladder_var_pct": round(r2 * 100, 2) if r2 is not None else None,
            "ladder_mean_month_pct": round(_moments(lad)["mean"] * 100, 4),
        }
    per_era = {k: v for k, v in rows.items() if k != "full" and "tilt_annualised_bp" in v}
    tilts = [v["tilt_annualised_bp"] for v in per_era.values()]
    return {
        "study": "e42_ladder_tilt_by_era",
        "evidence_cutoff": core["cutoff"],
        "spec": {"ladder": ["sh510300", "sh510050", "sh510500", "sh512100", "sh588000"],
                 "large": list(TILT_LARGE), "small": list(TILT_SMALL),
                 "decomposition": "ladder_monthly ~ alpha + beta*(small_mean - large_mean)",
                 "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras]},
        "eras": rows,
        "answers": {
            "tilt_range_bp": (round(max(tilts) - min(tilts), 1) if tilts else None),
            "tilt_min_bp": min(tilts) if tilts else None,
            "tilt_max_bp": max(tilts) if tilts else None,
            "eras_positive_tilt": sum(1 for t in tilts if t > 0),
            "eras_with_data": len(tilts),
            "peak_era": (max(per_era, key=lambda k: per_era[k]["tilt_annualised_bp"])
                         if per_era else None),
            "newest_era_tilt_vs_peak_pct": (
                round(per_era["2024_now"]["tilt_annualised_bp"]
                      / max(v["tilt_annualised_bp"] for v in per_era.values()) * 100, 1)
                if "2024_now" in per_era and tilts else None),
        },
        "honest": [
            "eras are calendar partitions of one continuous monthly series; each row is measured "
            "on its own months, so the era tilt bp do not add up to the full-sample number",
            "the decomposition is the E40 identity (2/5 large + 3/5 small) applied per era; the "
            "regression is descriptive, not a factor-model estimate",
            "the newest era is open-ended and the shortest, so its beta carries the widest error",
            "corporate-action guard as in E40: months with a >20% single-day member jump are dropped",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
        "dropped_months": core["dropped"],
    }


# ------------------------------------ leg: E95 newest-era cell stability

NEWEST_ERA = ("2024_now", "2024-01-01", None)


def _tilt_stats(core, months):
    """The E42 tilt cell measured on an explicit list of months.

    Factored out so the stability leg and the published face cannot disagree
    about what the cell *is*: run_tilt_era keeps its own body (its published
    output must stay bit-identical), and the selftest pins this helper to the
    same number on the same month list.
    """
    if len(months) < 3:
        return {"months": len(months), "skipped": "fewer than 3 usable months"}
    tilt = [core["tilt"][m] for m in months]
    lad = [core["lad_m"][m] for m in months]
    tm = _moments(tilt)
    beta, alpha, r2 = _ols(lad, tilt)
    pos = sum(1 for t in tilt if t > 0)
    return {
        "months": len(months), "from": months[0], "to": months[-1],
        "tilt_annualised_bp": round(tm["mean"] * 12 * 1e4, 1),
        "tilt_sd_bp": round(tm["sd"] * 1e4, 1) if tm["sd"] is not None else None,
        "tilt_positive_share_pct": round(pos / len(tilt) * 100, 1),
        "beta_ladder_on_tilt": round(beta, 3) if beta is not None else None,
        "alpha_monthly_bp": round(alpha * 1e4, 2) if alpha is not None else None,
        "r_squared": round(r2, 4) if r2 is not None else None,
    }


def _published_tilt_readings(outdir):
    """Every newest-era tilt reading this repo has already published, read back
    off the faces themselves (no transcription, no memory)."""
    out = []
    if not os.path.isdir(outdir):
        return out
    for name in sorted(os.listdir(outdir)):
        if not (name.startswith("TILT-ERA-") and name.endswith(".json")):
            continue
        try:
            with open(os.path.join(outdir, name), encoding="utf-8") as fh:
                face = json.load(fh)
        except (OSError, ValueError):
            continue
        row = (face.get("eras") or {}).get("2024_now") or {}
        val = row.get("tilt_annualised_bp")
        if val is None:
            continue
        out.append({"file": name, "cutoff": face.get("evidence_cutoff"),
                    "months": row.get("months"), "tilt_annualised_bp": val})
    return out


def _stability_verdict(observed_bp, span_bp):
    """Is the spread of published readings inside what moving the end alone does?"""
    if observed_bp is None or span_bp is None:
        return None
    return "inside_end_choice_span" if observed_bp <= span_bp else "beyond_end_choice_span"


def run_tilt_stable(outdir, core=None, ends=12, era=NEWEST_ERA):
    """Rolling-window stability of the newest-era tilt cell (E95).

    Same panel, same code path, only the *evaluation end* moves. If the whole
    spread of already-published readings fits inside the spread this grid
    produces, the cell is being re-derived, not re-measured.
    """
    core = core or _monthly_core()
    name, lo, hi = era
    era_months = [m for m in core["months"] if _in_era(m, lo, hi)]
    full = _tilt_stats(core, era_months)
    end_months = era_months[-int(ends):] if era_months else []
    rows = []
    for end in end_months:
        ms = [m for m in era_months if m <= end]
        row = _tilt_stats(core, ms)
        row["window_end"] = end
        rows.append(row)
    vals = [r["tilt_annualised_bp"] for r in rows
            if r.get("tilt_annualised_bp") is not None]
    span = round(max(vals) - min(vals), 1) if len(vals) >= 2 else None
    published = _published_tilt_readings(outdir or os.path.join(ROOT, "results", "e42_tilt_era"))
    readings = [p["tilt_annualised_bp"] for p in published
                if p.get("tilt_annualised_bp") is not None]
    if full.get("tilt_annualised_bp") is not None:
        readings.append(full["tilt_annualised_bp"])
    observed = (round(max(readings) - min(readings), 1) if len(readings) >= 2 else None)
    verdict = _stability_verdict(observed, span)
    return {
        "study": "e95_newest_era_cell_stability",
        "evidence_cutoff": core["cutoff"],
        "spec": {"era": name, "era_from": lo, "era_to": hi,
                 "cell": "ladder monthly size tilt, annualised bp",
                 "end_grid": "the last %d era month-ends, same panel, same loader"
                             % len(end_months),
                 "panel_months": len(core["months"])},
        "cell_now": full,
        "end_choice_series": rows,
        "end_choice_answers": {
            "ends": len(rows), "span_bp": span,
            "min_bp": min(vals) if vals else None,
            "max_bp": max(vals) if vals else None,
            "sd_bp": (round(_moments(vals)["sd"], 1) if len(vals) >= 2 else None),
            "latest_end_bp": vals[-1] if vals else None,
        },
        "published_readings": published,
        "stability_answers": {
            "published_n": len(readings),
            "observed_spread_bp": observed,
            "end_choice_span_bp": span,
            "verdict": verdict,
            "reads_as": (
                "the spread of published readings is no larger than what moving the "
                "evaluation end alone produces -- read the cell as re-derived, not re-measured"
                if verdict == "inside_end_choice_span" else
                "published readings spread wider than the end-choice grid -- at least part "
                "of the move is not an end-choice artefact"
                if verdict == "beyond_end_choice_span" else None),
        },
        "honest": [
            "one panel, one loader, one cutoff: the grid moves the evaluation end only, so it "
            "cannot see panel-arrival effects (E-register r1110) or a changed universe",
            "the newest era is open-ended and the shortest, so its beta carries the widest error "
            "and its own early months are the ones each truncated window drops first",
            "published readings are read back from the faces verbatim; a face that was never "
            "written is absent here rather than guessed",
            "descriptive census only: no gate, no verdict on the strategy, no prereg, no trial",
        ],
        "dropped_months": core["dropped"],
    }


# ------------------------------------ leg: E98 end-choice slack on every era

def _published_era_readings(outdir, era):
    """Every already-published cell for one era, read back off the faces.

    Two schemas share this directory: the plain E42 face keeps its ``eras`` at
    the top level, the E81 screened face keeps one full copy per screening arm
    under ``faces``. Both are read here, because a reader that only knows the
    flat shape reports zero published readings for the whole screened family --
    and "nothing was published" is the one answer a stability question must
    never invent.
    """
    out = []
    if not os.path.isdir(outdir):
        return out
    for name in sorted(os.listdir(outdir)):
        if not (name.startswith("TILT-ERA-") and name.endswith(".json")):
            continue
        try:
            with open(os.path.join(outdir, name), encoding="utf-8") as fh:
                face = json.load(fh)
        except (OSError, ValueError):
            continue
        containers = []
        if isinstance(face.get("eras"), dict):
            containers.append((None, face["eras"]))
        for arm, sub in sorted((face.get("faces") or {}).items()):
            if isinstance(sub, dict) and isinstance(sub.get("eras"), dict):
                containers.append((arm, sub["eras"]))
        for arm, eras in containers:
            row = eras.get(era) or {}
            val = row.get("tilt_annualised_bp")
            if val is None:
                continue
            out.append({"file": name, "arm": arm,
                        "cutoff": face.get("evidence_cutoff"),
                        "months": row.get("months"),
                        "tilt_annualised_bp": val})
    return out


def _endchoice_era_row(core, era, ends, outdir):
    """One era's end-choice grid: same panel, same loader, only the end moves.

    An era the panel does not reach is reported as structurally empty rather
    than measured on borrowed months -- the E42 panel opens in 2020-12, so two
    of the four era names carry no months at all and cannot be swept.
    """
    name, lo, hi = era
    era_months = [m for m in core["months"] if _in_era(m, lo, hi)]
    row = {"era": name, "era_from": lo, "era_to": hi,
           "panel_months": len(era_months)}
    if len(era_months) < 3:
        row.update({"skipped": "the panel carries fewer than 3 months in this era",
                    "grid_ends": 0, "span_bp": None, "verdict": None,
                    "end_choice_series": [], "published": [],
                    "observed_spread_bp": None, "span_over_monthly_sd": None})
        return row
    full = _tilt_stats(core, era_months)
    grid = era_months[-int(ends):]
    series = []
    for end in grid:
        ms = [m for m in era_months if m <= end]
        r = _tilt_stats(core, ms)
        r["window_end"] = end
        series.append(r)
    vals = [r["tilt_annualised_bp"] for r in series
            if r.get("tilt_annualised_bp") is not None]
    span = round(max(vals) - min(vals), 1) if len(vals) >= 2 else None
    # how much of the era each truncated run throws away at most
    dropped = (len(era_months) - min(r["months"] for r in series
                                     if r.get("months"))) if series else None
    monthly_sd = None
    tm = _moments([core["tilt"][m] for m in era_months])
    if tm["sd"] is not None:
        monthly_sd = round(tm["sd"] * 1e4, 1)
    published = _published_era_readings(outdir, name)
    readings = [p["tilt_annualised_bp"] for p in published]
    observed = round(max(readings) - min(readings), 1) if len(readings) >= 2 else None
    row.update({
        "cell_now": full,
        "grid_ends": len(series),
        "months_dropped_max": dropped,
        "span_bp": span,
        "min_bp": min(vals) if vals else None,
        "max_bp": max(vals) if vals else None,
        "sd_bp": round(_moments(vals)["sd"], 1) if len(vals) >= 2 else None,
        "latest_end_bp": vals[-1] if vals else None,
        "monthly_sd_bp": monthly_sd,
        # E95's own denominator, now per era: a span can only be called wide
        # relative to how much this era actually moves month to month.
        "span_over_monthly_sd": (round(span / monthly_sd, 2)
                                 if span is not None and monthly_sd else None),
        "published": published,
        "published_n": len(readings),
        "observed_spread_bp": observed,
        "verdict": _stability_verdict(observed, span),
        "end_choice_series": series,
    })
    return row


def run_endchoice_all_eras(outdir, core=None, ends=12):
    """E98: run the E95 end-choice grid on every era, not just the newest one.

    The question E95 could not answer: is "the cell is re-derived, not
    re-measured" a property of the newest era or of the instrument? Same panel,
    same loader, same end grid width; only the era window changes.
    """
    core = core or _monthly_core()
    rows = [_endchoice_era_row(core, era, ends, outdir) for era in ERAS]
    measured = [r for r in rows if r.get("span_bp") is not None]
    empty = [r["era"] for r in rows if r.get("skipped")]
    widest = (max(measured, key=lambda r: r["span_bp"]) if measured else None)
    # a span is only comparable to another span once both are stated against
    # the month-to-month movement of their own era
    ratios = {r["era"]: r["span_over_monthly_sd"] for r in measured}
    verdicts = {r["era"]: r["verdict"] for r in measured}
    return {
        "study": "e98_end_choice_slack_by_era",
        "evidence_cutoff": core["cutoff"],
        "spec": {"grid": "the last %d month-ends of each era, same panel, same loader"
                         % int(ends),
                 "eras": [e[0] for e in ERAS],
                 "cell": "ladder monthly size tilt, annualised bp",
                 "identity": "the grid moves the evaluation end only; the era window "
                             "is the only thing that differs between rows"},
        "eras": rows,
        "answers": {
            "measured_eras": [r["era"] for r in measured],
            "structurally_empty_eras": empty,
            "spans_bp": {r["era"]: r["span_bp"] for r in measured},
            "span_over_monthly_sd": ratios,
            "verdicts": verdicts,
            "widest_era": widest["era"] if widest else None,
            "widest_span_bp": widest["span_bp"] if widest else None,
            "any_era_quotable_by_level": (
                any(r["verdict"] == "beyond_end_choice_span" for r in measured)
                if measured else None),
            "reads_as": (
                "every era the panel reaches re-derives under its own end grid -- the "
                "E95 caveat is a property of the instrument, not of the newest years, so "
                "no era level may be quoted as a measurement"
                if measured and not any(r["verdict"] == "beyond_end_choice_span"
                                        for r in measured) else
                "at least one era survives its own end grid, so the caveat is local to "
                "the eras that do not and must be cited per era"
                if measured else None),
        },
        "honest": [
            "one panel, one loader, one cutoff: this cannot see panel-arrival effects "
            "or a changed universe, only the choice of end",
            "two of the four era names carry no months on the E42 panel (it opens in "
            "2020-12), so they are reported structurally empty rather than swept",
            "short eras lose a larger share of themselves to the same 12-end grid, so "
            "the span is also stated against the era's own monthly sd",
            "published readings are read back from the faces verbatim, both schemas; a "
            "reading never written is absent here rather than guessed",
            "descriptive census only: no gate, no verdict on the strategy, no prereg, "
            "no trial, no ledger booking",
        ],
        "dropped_months": core["dropped"],
    }


# ------------------------------------ leg: E42 calendar band at cost x3

def _calcost_face(raw_all, cal_full, start="2020-01-01", pick_n=9999,
                  exclude=("sh511",), mid_day=15, cost_mults=(1.0, 3.0)):
    """The E42 calendar-cost face from an already loaded universe.

    Split out of ``run_calcost`` so the E81 screened twins can replay the exact
    same face from a repaired universe without a second copy of the body.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    cutoff = cal_full[-1]
    cal = [d for d in cal_full if d >= start]
    years = len(cal) / 252.0
    all_syms = sorted(set(base.LADDER) | set(raw_all))
    prices, amounts = {}, {}
    for s in all_syms:
        c, a = raw_all.get(s, ({}, {}))
        prices[s] = [c.get(d) for d in cal]
        amounts[s] = [a.get(d) for d in cal]
    universe = [s for s in all_syms if s in raw_all]
    wide_name = "wide_top%d" % pick_n
    cash = base.load_cash_series(cal)
    rank_cache = {}
    month_ends = base.month_end_indices(cal)
    variants = [("me_m1", _shift_indices(month_ends, -1, len(cal))),
                ("me", sorted(set(month_ends))),
                ("me_p1", _shift_indices(month_ends, 1, len(cal))),
                ("mid%d" % mid_day, _mid_month_indices(cal, mid_day))]
    rows = {}
    for mult in cost_mults:
        tag = "cost_x%g" % mult
        rows[tag] = {}
        for vname, idxs in variants:
            rebal = set(idxs)
            cell = {"rebalances": len(rebal)}
            for scheme, univ, n in (("ladder5", base.LADDER, None),
                                    (wide_name, universe, pick_n)):
                curve, aux, _hold = e27.simulate(cal, prices, amounts, univ, cash,
                                                 n, mult, rank_cache, rebal)
                prof = risk_profile(curve, years)
                cell[scheme] = {
                    "ann_return_pct": prof["ann_return_pct"],
                    "max_drawdown_pct": prof["max_drawdown_pct"],
                    "rebalances": aux["rebalances"],
                    "turnover_per_year": round(aux["turnover_total"] / years, 3) if years else None,
                    "cost_per_year_bp": round(aux["cost_paid_frac"] / years * 1e4, 1) if years else None,
                }
            cell["vs_ladder_spread_bp"] = round(
                (cell[wide_name]["ann_return_pct"] - cell["ladder5"]["ann_return_pct"]) * 100, 1)
            rows[tag][vname] = cell
    summary = {}
    for tag, table in rows.items():
        spr = [c["vs_ladder_spread_bp"] for c in table.values()]
        ladder = [c["ladder5"]["ann_return_pct"] for c in table.values()]
        summary[tag] = {
            "spread_range_bp": round(max(spr) - min(spr), 1),
            "spread_all_positive": all(x > 0 for x in spr),
            "spread_min_bp": min(spr), "spread_max_bp": max(spr),
            "spread_at_me_bp": table["me"]["vs_ladder_spread_bp"],
            "ladder_ann_range_bp": round((max(ladder) - min(ladder)) * 100, 1),
            "cost_per_year_bp": {
                "ladder5": table["me"]["ladder5"]["cost_per_year_bp"],
                wide_name: table["me"][wide_name]["cost_per_year_bp"]},
            "turnover_per_year": {
                "ladder5": table["me"]["ladder5"]["turnover_per_year"],
                wide_name: table["me"][wide_name]["turnover_per_year"]},
        }
    tags = sorted(summary)
    return {
        "study": "e42_calendar_band_cost",
        "evidence_cutoff": cutoff,
        "spec": {"start": start, "bars": len(cal), "years": round(years, 2),
                 "pick_n": pick_n, "exclude_prefixes": list(exclude),
                 "cost_bp_per_side": base.COST_BP_SIDE, "cost_mults": list(cost_mults),
                 "mid_month_day": mid_day,
                 "variants": [v for v, _ in variants],
                 "universe_members": len(universe)},
        "calendars": rows,
        "answers": {
            "band_by_cost": {t: summary[t]["spread_range_bp"] for t in tags},
            "band_delta_top_vs_base_bp": (
                round(summary[tags[-1]]["spread_range_bp"]
                      - summary[tags[0]]["spread_range_bp"], 1) if len(tags) > 1 else None),
            "spread_all_positive": {t: summary[t]["spread_all_positive"] for t in tags},
            "level_shift_bp": {t: summary[t]["spread_at_me_bp"] for t in tags},
            "cost_per_year_bp": {t: summary[t]["cost_per_year_bp"] for t in tags},
            "summary": summary,
        },
        "honest": [
            "the engine reads a rebalance index as a decision at the close of that index, so the "
            "variants differ in session choice only -- universe, ranks and calendar are shared",
            "cost x3 scales the engine's own 13.041bp/side constant; it is a stress multiplier, "
            "not a measured fee schedule",
            "a wider band at x3 is consistent with turnover explaining it, but the two readings "
            "are not exclusive and nothing here selects a calendar",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }


def run_calcost(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",),
                mid_day=15, cost_mults=(1.0, 3.0)):
    """Is the calendar band in the spread a fee artefact? Re-run it at cost x3.

    E41 moved the decision calendar by one session and the spread band moved
    26bp while the ladder level moved 52bp on one shift. If the band is pricing
    (different sessions hold different names) the fee tripling leaves the band
    roughly where it is; if it is turnover-driven the band widens with the fee.
    Both readings are descriptive -- nothing here decides which calendar to use.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    raw_all = e27.load_universe()
    if exclude:
        raw_all = {s: v for s, v in raw_all.items()
                   if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    return _calcost_face(raw_all, cal_full, start=start, pick_n=pick_n,
                         exclude=exclude, mid_day=mid_day,
                         cost_mults=cost_mults)


CALCOST_CELL_COLUMNS = ("ann_return_pct", "max_drawdown_pct",
                        "turnover_per_year", "cost_per_year_bp")


def _calcost_cell(faces, arm, tag, variant, scheme, col):
    """One published cell of one arm; scheme None reads the calendar cell."""
    table = (faces.get(arm) or {}).get("calendars") or {}
    cell = (table.get(tag) or {}).get(variant) or {}
    if scheme is None:
        return cell.get(col)
    return (cell.get(scheme) or {}).get(col)


def _calcost_delta_rows(faces, base="unscreened"):
    """(E81) unscreened vs each screened arm, one row per published cell.

    The spread cell and every per-scheme column are read through the same
    accessor, so a renamed scheme shows up as a missing cell instead of a
    silently dropped row.
    """
    rows = []
    others = sorted(k for k in faces if k != base)
    for tag in sorted((faces[base].get("calendars") or {})):
        for variant in sorted(faces[base]["calendars"][tag]):
            cell = faces[base]["calendars"][tag][variant]
            pairs = [(None, "vs_ladder_spread_bp")]
            for scheme in sorted(cell):
                if isinstance(cell[scheme], dict):
                    pairs.extend((scheme, c) for c in CALCOST_CELL_COLUMNS)
            for scheme, col in pairs:
                u = _calcost_cell(faces, base, tag, variant, scheme, col)
                row = {"cost_tag": tag, "calendar": variant,
                       "scheme": scheme or "spread", "column": col,
                       "unscreened": u}
                for arm in others:
                    v = _calcost_cell(faces, arm, tag, variant, scheme, col)
                    row[arm] = v
                    row["delta_" + arm] = (
                        round(v - u, 4)
                        if isinstance(v, (int, float))
                        and isinstance(u, (int, float)) else None)
                rows.append(row)
    return rows


def run_calcost_screenreg(outdir, start="2020-01-01", pick_n=9999,
                          exclude=("sh511",), mid_day=15,
                          cost_mults=(1.0, 3.0),
                          modes=("neutralise_int", "neutralise")):
    """(E81) replay the E42 calendar-cost face from a screened universe.

    E79's matrix found 33 census modes reading the per-name loader with no raw
    hook, so the fee-channel reading of the calendar band was still charged by
    unadjusted prints. The E76 twin (``run_screenreg``) covers the era spread;
    this leg covers the calendar band. Each screened arm is published BESIDE
    the untouched column and the published COST-<cutoff>.json is never
    rewritten in place.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw_all = e27.load_universe()
    if exclude:
        raw_all = {s: v for s, v in raw_all.items()
                   if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]

    faces = {"unscreened": _calcost_face(raw_all, cal_full, start=start,
                                         pick_n=pick_n, exclude=exclude,
                                         mid_day=mid_day, cost_mults=cost_mults)}
    reports = {}
    for mode in modes:
        repaired, report = panel_screen.screen_universe(raw_all, mode=mode,
                                                        cal=cal_full)
        reports[mode] = report
        faces[mode] = _calcost_face(repaired, cal_full, start=start,
                                    pick_n=pick_n, exclude=exclude,
                                    mid_day=mid_day, cost_mults=cost_mults)

    delta = _calcost_delta_rows(faces)
    arms = ["unscreened"] + list(modes)
    widest = None
    for row in delta:
        mag = max([abs(row["delta_" + m]) for m in modes
                   if isinstance(row.get("delta_" + m), (int, float))] or [0])
        if mag and (widest is None or mag > widest["abs_delta_bp"]):
            widest = {"calendar": row["calendar"], "cost_tag": row["cost_tag"],
                      "scheme": row["scheme"], "column": row["column"],
                      "unscreened": row["unscreened"],
                      "abs_delta_bp": round(mag, 4),
                      "arms": {m: row.get(m) for m in modes}}

    bands = {arm: (faces[arm]["answers"]["band_by_cost"]) for arm in arms}
    widening = {arm: faces[arm]["answers"]["band_delta_top_vs_base_bp"]
                for arm in arms}
    return {
        "study": "e81_calcost_screenreg",
        "evidence_cutoff": cutoff,
        "spec": {
            "start": start, "pick_n": pick_n, "mid_day": mid_day,
            "exclude_prefixes": list(exclude), "modes": list(modes),
            "cost_bp_per_side": base.COST_BP_SIDE,
            "cost_mults": list(cost_mults),
            "loader": "scripts/panel_screen.py (opt-in; the published COST face "
                      "still reads e27.load_universe() unmodified)",
            "faces": "E42 calendar band: ladder5 vs wide_topN at every cost "
                     "multiple and calendar variant",
        },
        "screen_reports": reports,
        "faces": faces,
        "delta": delta,
        "answers": {
            "band_by_cost": bands,
            "band_widening_x1_to_x3_bp": widening,
            "spread_all_positive": {arm: faces[arm]["answers"]["spread_all_positive"]
                                    for arm in arms},
            "level_shift_bp": {arm: faces[arm]["answers"]["level_shift_bp"]
                               for arm in arms},
            "fee_channel_reading": {arm: (widening.get(arm) > 0
                                          if widening.get(arm) is not None else None)
                                    for arm in arms},
            "widest_correction": widest,
            "delta_cells": len(delta),
            "non_zero_delta_cells": len([
                r for r in delta
                if any(r.get("delta_" + m) not in (None, 0) for m in modes)]),
        },
        "honest": [
            "the screen repairs arithmetic impossibility only: a flagged ETF print "
            "may be genuine (ETF daily limits differ from the 10%/20% stock band), "
            "so every arm is a sensitivity face, not a corrected truth",
            "neutralise_int repairs only prints whose price ratio lands on an "
            "integer; neutralise repairs every adjacent print -- the range between "
            "them bounds the correction",
            "the screened book is not a pre-registration and books no trial: it is "
            "the same descriptive face replayed from a different input",
            "the band is a max-minus-min over four calendars, so a correction that "
            "moves every calendar alike leaves the band untouched -- read the "
            "level_shift_bp columns beside it",
            "a fee-channel verdict flips only if band_widening_x1_to_x3_bp changes "
            "sign; a smaller widening is not a refutation of the turnover reading",
            "descriptive census only: no gate, no verdict, no ledger booking, trial 0",
        ],
    }


def _tiltdelta_rows(faces, base="unscreened",
                    columns=("tilt_annualised_bp", "beta_ladder_on_tilt",
                             "alpha_monthly_bp", "r_squared")):
    """(E81) unscreened vs each screened arm, one row per era-and-column cell.

    Every cell keeps the unscreened value beside the arm values, so a reader can
    see whether the screen moved a level without re-deriving the face.
    """
    rows = []
    eras = list(faces[base]["eras"])
    arms = [a for a in faces if a != base]
    for era in eras:
        u_row = faces[base]["eras"].get(era) or {}
        for col in columns:
            u = u_row.get(col)
            row = {"era": era, "column": col, "unscreened": u}
            for arm in arms:
                v = (faces[arm]["eras"].get(era) or {}).get(col)
                row[arm] = v
                row["delta_" + arm] = (round(v - u, 4)
                                       if isinstance(u, (int, float))
                                       and isinstance(v, (int, float)) else None)
            rows.append(row)
    return rows


def run_screentilt(outdir, pick_n=9999, exclude=("sh511",),
                   modes=("neutralise_int", "neutralise"), eras=ERAS):
    """(E81) replay the E42 tilt-era face from a screened universe.

    E79's matrix left ``era``/``calcost``/``neutralrob`` exposed; the calendar
    band and the robustness grid now have screened twins, and this leg covers the
    remaining member-tilt decomposer -- the face that reads "how much of the
    ladder's monthly return is a size tilt, and what is left over". It rebuilds
    the whole monthly core per arm (engine curves *and* the member tilt series
    move together), publishes each arm BESIDE the untouched column, and never
    rewrites the published ``TILT-ERA-<cutoff>.json`` in place.
    """
    import e27_universe_expansion as e27
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw_all = e27.load_universe()
    cal_full = base.load_panel()[0]
    faces = {"unscreened": run_tilt_era(None, core=_monthly_core(
        pick_n, exclude, raw_all), eras=eras)}
    reports = {}
    for mode in modes:
        repaired, report = panel_screen.screen_universe(raw_all, mode=mode,
                                                        cal=cal_full)
        reports[mode] = report
        faces[mode] = run_tilt_era(None, core=_monthly_core(
            pick_n, exclude, repaired), eras=eras)

    delta = _tiltdelta_rows(faces)
    arms = ["unscreened"] + list(modes)
    per_era = [e[0] for e in eras]

    tilt_by_arm = {arm: {era: (faces[arm]["eras"].get(era) or {}).get(
        "tilt_annualised_bp") for era in per_era} for arm in arms}
    beta_by_arm = {arm: {era: (faces[arm]["eras"].get(era) or {}).get(
        "beta_ladder_on_tilt") for era in per_era} for arm in arms}
    r2_by_arm = {arm: {era: (faces[arm]["eras"].get(era) or {}).get(
        "r_squared") for era in per_era} for arm in arms}

    def _range(vals):
        nums = [v for v in vals if isinstance(v, (int, float))]
        return round(max(nums) - min(nums), 1) if len(nums) > 1 else None

    flips = []
    for era in per_era:
        u = tilt_by_arm["unscreened"].get(era)
        for arm in modes:
            v = tilt_by_arm[arm].get(era)
            if isinstance(u, (int, float)) and isinstance(v, (int, float)) \
                    and (u > 0) != (v > 0):
                flips.append({"era": era, "arm": arm,
                              "unscreened_bp": u, "screened_bp": v})

    widest = None
    for row in delta:
        mag = max([abs(row["delta_" + m]) for m in modes
                   if isinstance(row.get("delta_" + m), (int, float))] or [0])
        if mag and (widest is None or mag > widest["abs_delta"]):
            widest = {"era": row["era"], "column": row["column"],
                      "unscreened": row["unscreened"],
                      "abs_delta": round(mag, 4),
                      "arms": {m: row.get(m) for m in modes}}

    return {
        "study": "e81_tilt_era_screened",
        "evidence_cutoff": faces["unscreened"]["evidence_cutoff"],
        "spec": {
            "pick_n": pick_n, "exclude_prefixes": list(exclude),
            "modes": list(modes), "eras": [e[0] for e in eras],
            "decomposition": "ladder_monthly ~ alpha + beta*(small_mean - large_mean)",
            "loader": "scripts/panel_screen.py (opt-in; the published TILT-ERA "
                      "face still reads e27.load_universe() unmodified)",
            "faces": "E42 ladder tilt by era, rebuilt per arm from the same "
                     "monthly core builder the published twin uses",
        },
        "screen_reports": reports,
        "faces": faces,
        "delta": delta,
        "answers": {
            "tilt_by_arm_era_bp": tilt_by_arm,
            "tilt_range_by_arm_bp": {arm: _range(list(tilt_by_arm[arm].values()))
                                     for arm in arms},
            "beta_by_arm_era": beta_by_arm,
            "r_squared_by_arm_era": r2_by_arm,
            "sign_flips_vs_unscreened": flips,
            "widest_correction": widest,
            "delta_cells": len(delta),
            "non_zero_delta_cells": len([
                r for r in delta
                if any(r.get("delta_" + m) not in (None, 0) for m in modes)]),
        },
        "honest": [
            "the screen repairs arithmetic impossibility only: a flagged ETF print "
            "may be genuine (ETF daily limits differ from the 10%/20% stock band), "
            "so every arm is a sensitivity face, not a corrected truth",
            "neutralise_int repairs only prints whose price ratio lands on an "
            "integer; neutralise repairs every adjacent print -- the range between "
            "them bounds the correction",
            "eras are calendar partitions of one continuous monthly series; each "
            "row is measured on its own months, so era bp do not add up to the "
            "full-sample number",
            "the tilt regression is descriptive, not a factor-model estimate, and "
            "the newest era is the shortest so its beta carries the widest error",
            "the screened tilt is not a pre-registration and books no trial: it is "
            "the same descriptive face replayed from a different input",
            "descriptive census only: no gate, no verdict, no ledger booking, trial 0",
        ],
    }


# ------------------- leg: E43 four-member reach-back (tilt + neutral spread)

def run_tilt4(outdir, core=None, eras=ERAS, raw=None):
    """Rebuild the tilt and the size-neutral spread on the four-member sub-ladder.

    E42 measured the era band on two of four eras: the five-member tilt needs
    sh588000, whose first bar is 2020-11-13, so pre2017 had 0 usable months and
    2017-2020 had 1. Dropping the STAR leg (2 broad-cap vs 2 mid/small) reaches
    back to 2017-01 while keeping the same identity, so the 2017-2020 leg is
    measured (48 months) instead of skipped. The binding member is now sh512100
    (first bar 2016-11-04), not the STAR leg -- pre2017 stays unmeasurable (1
    month) on BOTH skins, and the reach-back is 2017-01, not 2013. The
    five-member rows are reported beside it wherever both skins can price the
    same era.

    ``raw`` lets a caller hand in an already-loaded (optionally screened) panel
    so a twin can burn both arms off ONE load (E113/E124 seam); the default path
    still reads the shipped universe through ``_monthly_core``.
    """
    core = core if core is not None else _monthly_core(raw_all=raw)
    rows = {}
    for name, lo, hi in list(eras) + [("full", None, None)]:
        ms = [m for m in core["months4"] if _in_era(m, lo, hi)]
        if len(ms) < 3:
            rows[name] = {"months": len(ms), "skipped": "fewer than 3 usable months"}
            continue
        tilt = [core["tilt4"][m] for m in ms]
        lad = [core["lad_m"][m] for m in ms]
        spread = [core["wide_m"][m] - core["lad_m"][m] for m in ms]
        tm = _moments(tilt)
        beta_l, alpha_l, r2_l = _ols(lad, tilt)
        beta_s, alpha_s, r2_s = _ols(spread, tilt)
        tilt_ann = tm["mean"] * 12.0 * 1e4 if tm["mean"] is not None else None
        raw_ann = sum(spread) / len(spread) * 12.0 * 1e4
        seg_l = _rebase(_slice_curve(core["curves"]["ladder5"], lo, hi))
        seg_w = _rebase(_slice_curve(core["curves"][core["wide_name"]], lo, hi))
        eng_diff = None
        if len(seg_l) > 1 and len(seg_w) > 1:
            yrs = len(seg_l) / 252.0
            eng_diff = round((risk_profile(seg_w, yrs)["ann_return_pct"]
                              - risk_profile(seg_l, yrs)["ann_return_pct"]) * 100, 1)
        pos = sum(1 for t in tilt if t > 0)
        i_max = max(range(len(tilt)), key=lambda i: tilt[i])
        i_min = min(range(len(tilt)), key=lambda i: tilt[i])
        rows[name] = {
            "months": len(ms), "from": ms[0], "to": ms[-1],
            "skin": "4-member (2 broad vs 510500/512100)",
            "tilt_annualised_bp": round(tilt_ann, 1) if tilt_ann is not None else None,
            "tilt_sd_bp": round(tm["sd"] * 1e4, 1) if tm["sd"] is not None else None,
            "tilt_positive_share_pct": round(pos / len(tilt) * 100, 1),
            "tilt_best_month": {"month": ms[i_max], "spread_pct": round(tilt[i_max] * 100, 2)},
            "tilt_worst_month": {"month": ms[i_min], "spread_pct": round(tilt[i_min] * 100, 2)},
            "beta_ladder_on_tilt": round(beta_l, 3) if beta_l is not None else None,
            "alpha_monthly_bp": round(alpha_l * 1e4, 2) if alpha_l is not None else None,
            "r_squared": round(r2_l, 4) if r2_l is not None else None,
            "tilt_explains_ladder_var_pct": round(r2_l * 100, 2) if r2_l is not None else None,
            "ladder_mean_month_pct": round(_moments(lad)["mean"] * 100, 4),
            "spread_raw_ann_bp": round(raw_ann, 1),
            "spread_size_neutral_ann_bp": (round(alpha_s * 12.0 * 1e4, 1)
                                           if alpha_s is not None else None),
            "spread_size_component_ann_bp": (round(beta_s * tilt_ann, 1)
                                             if beta_s is not None and tilt_ann is not None else None),
            "beta_spread_on_tilt": round(beta_s, 3) if beta_s is not None else None,
            "r_squared_spread": round(r2_s, 4) if r2_s is not None else None,
            "engine_ann_diff_bp": eng_diff,
            "arithmetic_vs_geometric_gap_bp": (
                round(raw_ann - eng_diff, 1) if eng_diff is not None else None),
        }
    # the same eras read on the five-member skin where it can be priced at all
    compare = {}
    for name, lo, hi in list(eras) + [("full", None, None)]:
        ms5 = [m for m in core["months"] if _in_era(m, lo, hi)]
        if len(ms5) < 3:
            compare[name] = {"months_5member": len(ms5), "note": "not measurable on 5-member skin"}
            continue
        t5 = [core["tilt"][m] for m in ms5]
        compare[name] = {
            "months_5member": len(ms5),
            "tilt_5member_ann_bp": round(_moments(t5)["mean"] * 12 * 1e4, 1),
            "tilt_4member_ann_bp_same_months": round(
                _moments([core["tilt4"][m] for m in ms5])["mean"] * 12 * 1e4, 1),
            "note": "same months, two skins -- the gap is the STAR leg, not a window effect",
        }
    measured = {k: v for k, v in rows.items() if k != "full" and "tilt_annualised_bp" in v}
    neutral4 = [v["spread_size_neutral_ann_bp"] for v in measured.values()
                if v.get("spread_size_neutral_ann_bp") is not None]
    return {
        "study": "e43_tilt_4member_history",
        "evidence_cutoff": core["cutoff"],
        "spec": {"large": list(TILT_LARGE), "small": list(TILT4_SMALL),
                 "five_member_small": list(TILT_SMALL),
                 "decomposition": "ladder_monthly ~ alpha + beta*(small_mean - large_mean), "
                                  "equal weight 0.5/0.5 on the four-member skin",
                 "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
                 "pick_n": 9999, "exclude_prefixes": ["sh511"], "cost_mult": 1.0},
        "eras": rows,
        "skin_comparison": compare,
        "answers": {
            "eras_measured_4member": len(measured),
            "eras_measured_5member": sum(
                1 for v in compare.values() if v.get("months_5member", 0) >= 3),
            "era_names_measured_4member": sorted(measured),
            "eras_positive_tilt": sum(1 for v in measured.values() if v["tilt_annualised_bp"] > 0),
            "eras_positive_size_neutral": sum(1 for x in neutral4 if x > 0),
            "size_neutral_range_bp": (round(max(neutral4) - min(neutral4), 1) if neutral4 else None),
            "pre2021_eras_newly_measured": [
                k for k, v in measured.items() if v["to"] < "2021-01"][:8],
        },
        "honest": [
            "the four-member skin drops the STAR leg, so its tilt is a broad-vs-mid/small read, "
            "not the E40 five-member identity; the skin_comparison rows price that difference on "
            "the months both skins can see",
            "the ladder and wide curves are the E24/E27 engine's own (module import), unchanged by "
            "the skin choice -- only the tilt regressor changes, so any movement in the neutral "
            "column is the size adjustment, not a different book",
            "eras remain calendar partitions of one continuous monthly series and do not add up",
            "corporate-action guard as in E40 (drops >20% single-day member months)",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
        "dropped_months_4member": core["dropped4"],
    }


def _skin_small_weights(small):
    """Equal-weight share of each member inside one size leg, in percent."""
    return {s: round(100.0 / len(small), 4) for s in small}


def run_tilt3(outdir, core=None, eras=ERAS, raw=None):
    """E43-TILT-3MEMBER-REACHBACK: read the tilt in the years no wider skin can price.

    E43's four-member skin reaches 2017-01 and its docstring claimed a 2013
    reach-back, but the binding member there is sh512100 (first bar 2016-11-04),
    so pre2017 carries 1 usable month on BOTH the four- and five-member skins.
    Dropping to three members (the same 2 broad-cap leg vs sh510500 alone, first
    bar 2013-03-15) makes 2013-04..2016-12 measurable for the first time.

    The three skins are NOT interchangeable readings of one identity: the small
    leg goes from 1 name (510500) to 2 (+512100) to 3 (+STAR 588000), so part of
    any difference is composition. Every era therefore publishes the three-member
    number BESIDE the four- and five-member number on the months they share, with
    the denominator of each side, and the deltas are only printed where both
    sides cover the same months -- a delta across different month sets is an
    artefact, not a skin price (E126 denominator rule).

    ``raw`` mirrors run_tilt4's seam so a twin can burn both arms off one load.
    """
    core = core if core is not None else _monthly_core(raw_all=raw)
    rows = {}
    for name, lo, hi in list(eras) + [("full", None, None)]:
        ms = [m for m in core["months3"] if _in_era(m, lo, hi)]
        if len(ms) < 3:
            rows[name] = {"months": len(ms), "skipped": "fewer than 3 usable months"}
            continue
        tilt = [core["tilt3"][m] for m in ms]
        lad = [core["lad_m"][m] for m in ms]
        spread = [core["wide_m"][m] - core["lad_m"][m] for m in ms]
        tm = _moments(tilt)
        beta_l, alpha_l, r2_l = _ols(lad, tilt)
        beta_s, alpha_s, r2_s = _ols(spread, tilt)
        tilt_ann = tm["mean"] * 12.0 * 1e4 if tm["mean"] is not None else None
        raw_ann = sum(spread) / len(spread) * 12.0 * 1e4
        seg_l = _rebase(_slice_curve(core["curves"]["ladder5"], lo, hi))
        seg_w = _rebase(_slice_curve(core["curves"][core["wide_name"]], lo, hi))
        eng_diff = None
        if len(seg_l) > 1 and len(seg_w) > 1:
            yrs = len(seg_l) / 252.0
            eng_diff = round((risk_profile(seg_w, yrs)["ann_return_pct"]
                              - risk_profile(seg_l, yrs)["ann_return_pct"]) * 100, 1)
        pos = sum(1 for t in tilt if t > 0)
        i_max = max(range(len(tilt)), key=lambda i: tilt[i])
        i_min = min(range(len(tilt)), key=lambda i: tilt[i])
        rows[name] = {
            "months": len(ms), "from": ms[0], "to": ms[-1],
            "skin": "3-member (2 broad vs 510500)",
            "tilt_annualised_bp": round(tilt_ann, 1) if tilt_ann is not None else None,
            "tilt_sd_bp": round(tm["sd"] * 1e4, 1) if tm["sd"] is not None else None,
            "tilt_positive_share_pct": round(pos / len(tilt) * 100, 1),
            "tilt_best_month": {"month": ms[i_max], "spread_pct": round(tilt[i_max] * 100, 2)},
            "tilt_worst_month": {"month": ms[i_min], "spread_pct": round(tilt[i_min] * 100, 2)},
            "beta_ladder_on_tilt": round(beta_l, 3) if beta_l is not None else None,
            "alpha_monthly_bp": round(alpha_l * 1e4, 2) if alpha_l is not None else None,
            "r_squared": round(r2_l, 4) if r2_l is not None else None,
            "tilt_explains_ladder_var_pct": round(r2_l * 100, 2) if r2_l is not None else None,
            "ladder_mean_month_pct": round(_moments(lad)["mean"] * 100, 4),
            "spread_raw_ann_bp": round(raw_ann, 1),
            "spread_size_neutral_ann_bp": (round(alpha_s * 12.0 * 1e4, 1)
                                           if alpha_s is not None else None),
            "spread_size_component_ann_bp": (round(beta_s * tilt_ann, 1)
                                             if beta_s is not None and tilt_ann is not None else None),
            "beta_spread_on_tilt": round(beta_s, 3) if beta_s is not None else None,
            "r_squared_spread": round(r2_s, 4) if r2_s is not None else None,
            "engine_ann_diff_bp": eng_diff,
            "arithmetic_vs_geometric_gap_bp": (
                round(raw_ann - eng_diff, 1) if eng_diff is not None else None),
        }
    # the same months read on the wider skins (never presented as the identity)
    compare = {}
    for name, lo, hi in list(eras) + [("full", None, None)]:
        ms3 = [m for m in core["months3"] if _in_era(m, lo, hi)]
        shared4 = [m for m in ms3 if m in core["tilt4"]]
        shared5 = [m for m in ms3 if m in core["tilt"]]
        t3 = _moments([core["tilt3"][m] for m in ms3])["mean"] if ms3 else None
        t4 = _moments([core["tilt4"][m] for m in shared4])["mean"] if shared4 else None
        t5 = _moments([core["tilt"][m] for m in shared5])["mean"] if shared5 else None
        row = {
            "months_3member": len(ms3),
            "months_4member_shared": len(shared4),
            "months_5member_shared": len(shared5),
            "tilt_3member_ann_bp": round(t3 * 12 * 1e4, 1) if t3 is not None else None,
            "tilt_4member_ann_bp_shared_months":
                round(t4 * 12 * 1e4, 1) if t4 is not None else None,
            "tilt_5member_ann_bp_shared_months":
                round(t5 * 12 * 1e4, 1) if t5 is not None else None,
        }
        # a delta is only a skin price when both sides price the SAME months
        if t3 is not None and t4 is not None and len(shared4) == len(ms3):
            row["delta_4member_minus_3member_bp"] = round((t4 - t3) * 12 * 1e4, 1)
        else:
            row["delta_4member_minus_3member_bp"] = None
            row["delta_4member_minus_3member_reason"] = (
                "denominators differ (%d vs %d months)" % (len(shared4), len(ms3)))
        if t3 is not None and t5 is not None and len(shared5) == len(ms3):
            row["delta_5member_minus_3member_bp"] = round((t5 - t3) * 12 * 1e4, 1)
        else:
            row["delta_5member_minus_3member_bp"] = None
            row["delta_5member_minus_3member_reason"] = (
                "denominators differ (%d vs %d months)" % (len(shared5), len(ms3)))
        row["note"] = ("three skins weight the small leg differently; the delta is the "
                       "composition price, not the identity")
        compare[name] = row
    measured = {k: v for k, v in rows.items() if k != "full" and "tilt_annualised_bp" in v}
    neutral3 = [v["spread_size_neutral_ann_bp"] for v in measured.values()
                if v.get("spread_size_neutral_ann_bp") is not None]
    pre = rows.get("pre2017") or {}
    return {
        "study": "e43_tilt_3member_reachback",
        "evidence_cutoff": core["cutoff"],
        "spec": {"large": list(TILT_LARGE), "small": list(TILT3_SMALL),
                 "four_member_small": list(TILT4_SMALL),
                 "five_member_small": list(TILT_SMALL),
                 "small_leg_member_weight_pct": {
                     "3member": _skin_small_weights(TILT3_SMALL),
                     "4member": _skin_small_weights(TILT4_SMALL),
                     "5member": _skin_small_weights(TILT_SMALL)},
                 "decomposition": "ladder_monthly ~ alpha + beta*(small_mean - large_mean), "
                                  "equal weight within each leg on the three-member skin",
                 "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
                 "pick_n": 9999, "exclude_prefixes": ["sh511"], "cost_mult": 1.0},
        "eras": rows,
        "skin_comparison": compare,
        "answers": {
            "eras_measured_3member": len(measured),
            "eras_measured_4member": sum(
                1 for v in rows.values() if v.get("months") and v.get("months") >= 3),
            "era_names_measured_3member": sorted(measured),
            "pre2017_months_3member": pre.get("months"),
            "pre2017_tilt_3member_ann_bp": pre.get("tilt_annualised_bp"),
            "pre2017_measurable_at_all": bool(pre.get("months", 0) >= 3),
            "eras_positive_tilt": sum(1 for v in measured.values()
                                      if v["tilt_annualised_bp"] > 0),
            "eras_positive_size_neutral": sum(1 for x in neutral3 if x > 0),
            "size_neutral_range_bp": (round(max(neutral3) - min(neutral3), 1)
                                      if neutral3 else None),
            "skin_cells_compared": len(compare),
            "skin_deltas_published": sum(
                1 for v in compare.values()
                if v.get("delta_4member_minus_3member_bp") is not None),
        },
        "honest": [
            "the three-member skin is the NARROWEST reading in this family: its small leg is one "
            "name (sh510500), so its tilt is a broad-vs-mid read with no STAR or 512100 content -- "
            "it is published beside the four- and five-member rows, never as the identity",
            "the three skins differ in composition, not only in window: the small-leg member "
            "weights are stated in spec.small_leg_member_weight_pct so a reader can see what the "
            "delta is priced against",
            "deltas are printed only where both sides price the same months; where the wider skin "
            "covers fewer months the delta is null with the two denominators published",
            "the ladder and wide curves are the E24/E27 engine's own (module import), unchanged by "
            "the skin choice -- only the tilt regressor changes",
            "eras remain calendar partitions of one continuous monthly series and do not add up",
            "corporate-action guard as in E40 (drops >20% single-day member months)",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
        "dropped_months_3member": core["dropped3"],
    }


# ---------------------- leg: E168 pre-2017 leg split + leave-one-month-out
#
# E126 made 2013-04..2016-12 measurable for the first time and published
# +1186.4bp/yr of tilt beside a +134.4bp size-neutral leg. That pair says most
# of the era's headline is the size leg, but it does not say whether the size
# leg is itself 44 months or two of them, and the three-member skin's small leg
# is ONE name. So the era is split into its two legs on their own and each mean
# is re-derived with every month removed once (LOMO).
TILT3_HALF_SHARE = 0.5          # declared before the burn (E168)
TILT3_LOMO_TOP = 5              # months published per era beside the sweep


def _leg_monthly(mem, brk, months, names):
    """Equal-weight monthly return of ONE size leg on the months it can price.

    A leg is priced only on months where EVERY member of that leg has a clean
    month: a partial roster would silently change the leg's weights, which is
    the composition trap the three skins already publish (E126).
    """
    names = tuple(names)
    if not names:
        return {}
    out = {}
    for m in months:
        if any(m not in mem.get(s, {}) or m in brk.get(s, {}) for s in names):
            continue
        out[m] = sum(mem[s][m] for s in names) / len(names)
    return out


def _lomo_sweep(months, values):
    """Leave-one-month-out on an era mean, plus how many months carry it.

    Two different questions, published side by side because one number answers
    neither alone: ``span_bp`` is the range of the era mean when each month is
    dropped once (a reading carried by one month has a wide span), and
    ``months_to_half`` orders months by their own contribution in the sign of
    the mean and counts how many are needed to reach half the total.
    """
    pairs = [(m, v) for m, v in zip(months, values) if v is not None]
    n = len(pairs)
    if n < 2:
        return {"months": n, "skipped": "fewer than 2 usable months"}
    full = sum(v for _m, v in pairs) / n * 12.0 * 1e4
    drops = []
    for i, (m, _v) in enumerate(pairs):
        rest = [v for j, (_mm, v) in enumerate(pairs) if j != i]
        drops.append((m, sum(rest) / len(rest) * 12.0 * 1e4))
    anns = [a for _m, a in drops]
    worst = max(drops, key=lambda p: abs(p[1] - full))
    total = sum(v for _m, v in pairs)
    ordered = sorted(pairs, key=lambda p: abs(p[1]), reverse=True)
    top = [{"month": m, "tilt_bp": round(v * 1e4, 1),
            "share_of_mean_pct": (round(v / total * 100, 1) if total else None)}
           for m, v in ordered[:TILT3_LOMO_TOP]]
    months_to_half, running = None, 0.0
    if total:
        sign = 1.0 if total > 0 else -1.0
        same_sign = sorted((v for _m, v in pairs if v * sign > 0), reverse=True)
        for v in same_sign:
            running += v
            months_to_half = (months_to_half or 0) + 1
            if abs(running) >= abs(total) * TILT3_HALF_SHARE:
                break
    return {
        "months": n,
        "full_mean_ann_bp": round(full, 1),
        "drop_min_ann_bp": round(min(anns), 1),
        "drop_max_ann_bp": round(max(anns), 1),
        "span_bp": round(max(anns) - min(anns), 1),
        "biggest_abs_shift": {"month": worst[0],
                              "ann_bp_after_drop": round(worst[1], 1),
                              "delta_bp": round(worst[1] - full, 1)},
        "months_to_half": months_to_half,
        "months_to_half_share": TILT3_HALF_SHARE,
        "top_months": top,
        "sign_flips_under_a_single_drop": min(anns) < 0.0 < max(anns),
        "sum_of_months_bp": round(total * 1e4, 1),
    }


def run_tilt3legs(outdir, core=None, eras=ERAS, raw=None):
    """E43-TILT3-PRE2017-LEG-SPLIT: price the era's two legs on their own.

    The three-member skin's tilt is ``mean(sh510500) - mean(the two broad-cap
    members)``, so every era reading is the difference of two leg returns, and
    the small leg is a single name. This face publishes each leg's annualised
    return beside the tilt, the arithmetic identity (small - large) against the
    published ``tilt3`` series, and a leave-one-month-out sweep of each era mean
    so a 44-month reading carried by a handful of months is quantified rather
    than described.

    ``raw`` mirrors run_tilt3's seam so a screened twin can burn both arms off
    one load without a second panel pass.
    """
    core = core if core is not None else _monthly_core(raw_all=raw)
    rows = {}
    for name, lo, hi in list(eras) + [("full", None, None)]:
        ms = [m for m in core["months3"] if _in_era(m, lo, hi)]
        if len(ms) < 3:
            rows[name] = {"months": len(ms), "skipped": "fewer than 3 usable months"}
            continue
        big = _leg_monthly(core["mem"], core["brk"], ms, TILT_LARGE)
        sml = _leg_monthly(core["mem"], core["brk"], ms, TILT3_SMALL)
        paired = [m for m in ms if m in big and m in sml and m in core["tilt3"]]
        if len(paired) < 3:
            rows[name] = {"months": len(paired),
                          "skipped": "fewer than 3 months priced on both legs"}
            continue
        tilt = [core["tilt3"][m] for m in paired]
        big_ann = sum(big[m] for m in paired) / len(paired) * 12.0 * 1e4
        sml_ann = sum(sml[m] for m in paired) / len(paired) * 12.0 * 1e4
        tilt_ann = sum(tilt) / len(tilt) * 12.0 * 1e4
        residual = max(abs((sml[m] - big[m]) - core["tilt3"][m]) for m in paired)
        pos = sum(1 for t in tilt if t > 0)
        rows[name] = {
            "months": len(paired), "from": paired[0], "to": paired[-1],
            "months_dropped_from_era": len(ms) - len(paired),
            "large_leg": {
                "members": list(TILT_LARGE),
                "ann_bp": round(big_ann, 1),
                "best_month": round(max(big.values()) * 100, 2),
                "worst_month": round(min(big.values()) * 100, 2),
                "positive_share_pct": round(
                    sum(1 for m in paired if big[m] > 0) / len(paired) * 100, 1),
            },
            "small_leg": {
                "members": list(TILT3_SMALL),
                "ann_bp": round(sml_ann, 1),
                "best_month": round(max(sml.values()) * 100, 2),
                "worst_month": round(min(sml.values()) * 100, 2),
                "positive_share_pct": round(
                    sum(1 for m in paired if sml[m] > 0) / len(paired) * 100, 1),
                "note": ("the small leg of this skin is a single name, so this "
                         "number is that name's own return, not a bucket"),
            },
            "tilt_ann_bp": round(tilt_ann, 1),
            "tilt_from_legs_bp": round(sml_ann - big_ann, 1),
            "identity_residual_bp": round(residual * 12.0 * 1e4, 6),
            "tilt_positive_share_pct": round(pos / len(tilt) * 100, 1),
            "legs_differ_in_sign": (big_ann > 0) != (sml_ann > 0),
            "legs_sum_bp": round(big_ann + sml_ann, 1),
            "lomo": _lomo_sweep(paired, tilt),
        }
        if name == "pre2017":
            rows[name]["months_detail"] = [
                {"month": m, "large_pct": round(big[m] * 100, 2),
                 "small_pct": round(sml[m] * 100, 2),
                 "tilt_pct": round(core["tilt3"][m] * 100, 2)} for m in paired]
    measured = {k: v for k, v in rows.items()
                if k != "full" and "lomo" in v}
    pre = rows.get("pre2017") or {}
    gaps = [(k, v["large_leg"]["ann_bp"] - v["small_leg"]["ann_bp"])
            for k, v in measured.items()]
    return {
        "study": "e43_tilt3_pre2017_leg_split",
        "evidence_cutoff": core["cutoff"],
        "spec": {
            "large": list(TILT_LARGE), "small": list(TILT3_SMALL),
            "leg_rule": "equal weight within each leg; both legs priced only on "
                        "months where every member of that leg is present and clean",
            "lomo": "each era mean re-derived with every month removed once; "
                    "months_to_half orders months by their own contribution in the "
                    "sign of the mean and counts to a declared %.2f share"
                    % TILT3_HALF_SHARE,
            "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
            "pick_n": 9999, "exclude_prefixes": ["sh511"], "cost_mult": 1.0,
        },
        "eras": rows,
        "answers": {
            "eras_measured": len(measured),
            "era_names_measured": sorted(measured),
            "pre2017_months": pre.get("months"),
            "pre2017_large_leg_ann_bp": (pre.get("large_leg") or {}).get("ann_bp"),
            "pre2017_small_leg_ann_bp": (pre.get("small_leg") or {}).get("ann_bp"),
            "pre2017_tilt_ann_bp": pre.get("tilt_ann_bp"),
            "pre2017_lomo_span_bp": (pre.get("lomo") or {}).get("span_bp"),
            "pre2017_lomo_min_bp": (pre.get("lomo") or {}).get("drop_min_ann_bp"),
            "pre2017_lomo_max_bp": (pre.get("lomo") or {}).get("drop_max_ann_bp"),
            "pre2017_months_to_half": (pre.get("lomo") or {}).get("months_to_half"),
            "pre2017_biggest_shift_month":
                ((pre.get("lomo") or {}).get("biggest_abs_shift") or {}).get("month"),
            "eras_with_sign_flip_under_one_drop": sorted(
                k for k, v in measured.items()
                if v["lomo"].get("sign_flips_under_a_single_drop")),
            "largest_leg_gap_bp": (round(min(gaps, key=lambda p: p[1])[1], 1)
                                   if gaps else None),
            "largest_leg_gap_era": (min(gaps, key=lambda p: p[1])[0]
                                    if gaps else None),
            "identity_residual_max_bp": (round(max(v["identity_residual_bp"]
                                                   for v in measured.values()), 6)
                                         if measured else None),
        },
        "honest": [
            "the small leg of the three-member skin is ONE name (sh510500): the "
            "era reading inherits that name's own drawdowns and cannot be read "
            "as a small-cap bucket return",
            "eras remain calendar partitions of one continuous monthly series and "
            "do not add up to the full row",
            "leave-one-month-out prices the mean's dependence on single months; "
            "it is not a confidence interval and no p-value is claimed",
            "months_to_half counts contribution in the sign of the mean, so a "
            "mean that is only large because a few months are large is named as "
            "such rather than being called robust",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
        "dropped_months_3member": core["dropped3"],
    }


# ---------------------- leg: E43 wide-book size composition

def run_widecomp(outdir, core=None, pick_n=9999, exclude=("sh511",), eras=ERAS):
    """Explain the sign of the wide book's tilt beta from its own holdings.

    E42's regression says the wide book loses ground when small caps lead
    (beta -0.216 full, -0.289 in 2024-now). This leg measures the composition
    instead of inferring it: at every decision point, the holdings' weight share
    falling in the ladder's own small-cap legs, its two broad legs, and the rest
    of the book; then the same monthly regression run on the residual bucket
    (universe minus the five ladder members) so the sign is attributable.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    core = core or _monthly_core()
    raw_all = e27.load_universe()
    if exclude:
        raw_all = {s: v for s, v in raw_all.items()
                   if not s.startswith(tuple(exclude))}
    cal = base.load_panel()[0]
    cutoff = cal[-1]
    all_syms = sorted(set(base.LADDER) | set(raw_all))
    prices, amounts = {}, {}
    for s in all_syms:
        c, a = raw_all.get(s, ({}, {}))
        prices[s] = [c.get(d) for d in cal]
        amounts[s] = [a.get(d) for d in cal]
    universe = [s for s in all_syms if s in raw_all]
    cash = base.load_cash_series(cal)
    rank_cache = {}
    wide_name = "wide_top%d" % pick_n
    curve, aux, _hold = e27.simulate(cal, prices, amounts, universe, cash,
                                     pick_n, 1.0, rank_cache)
    resid_univ = [s for s in universe if s not in base.LADDER]
    rcurve, raux, _rhold = e27.simulate(cal, prices, amounts, resid_univ, cash,
                                        None, 1.0, rank_cache)
    comp = []
    for idx in sorted(set(base.month_end_indices(cal))):
        live = e27._rank(idx, universe, prices, amounts, rank_cache)[:pick_n]
        row = {"date": cal[idx]}
        row.update(_compose_counts(live, TILT_LARGE, TILT_SMALL))
        comp.append(row)
    wide_m = dict(_month_rets(curve))
    resid_m = dict(_month_rets(rcurve))
    lad_m = core["lad_m"]

    def _reg(series, name):
        rows = {}
        for era, lo, hi in list(eras) + [("full", None, None)]:
            ms = [m for m in core["months4"] if _in_era(m, lo, hi) and m in series]
            if len(ms) < 3:
                rows[era] = {"months": len(ms), "skipped": "fewer than 3 usable months"}
                continue
            y = [series[m] for m in ms]
            x = [core["tilt4"][m] for m in ms]
            b, a, r2 = _ols(y, x)
            rows[era] = {
                "months": len(ms), "from": ms[0], "to": ms[-1],
                "mean_month_pct": round(_moments(y)["mean"] * 100, 4),
                "beta_on_tilt": round(b, 3) if b is not None else None,
                "r_squared": round(r2, 4) if r2 is not None else None,
                "ann_bp": round(_moments(y)["mean"] * 12 * 1e4, 1),
            }
        return rows

    spread_m = {m: wide_m[m] - lad_m[m] for m in wide_m if m in lad_m}
    shares = [c for c in comp if c.get("n")]
    avg = (lambda k: round(sum(c[k] for c in shares) / len(shares), 4)) if shares else (lambda k: None)
    return {
        "study": "e43_wide_size_composition",
        "evidence_cutoff": cutoff,
        "spec": {"pick_n": pick_n, "exclude_prefixes": list(exclude),
                 "ladder_large_legs": list(TILT_LARGE),
                 "ladder_small_legs": list(TILT_SMALL),
                 "residual_bucket": "universe minus the five ladder members, equal weight",
                 "rebalances": len(shares), "holdings": wide_name},
        "composition": comp,
        "composition_summary": {
            "mean_holdings": avg("n"),
            "mean_ladder_small_weight_pct": avg("ladder_small_weight_pct"),
            "mean_ladder_large_weight_pct": avg("ladder_large_weight_pct"),
            "mean_other_weight_pct": avg("other_weight_pct"),
            "min_ladder_all_weight_pct": round(min(
                c["ladder_small_weight_pct"] + c["ladder_large_weight_pct"]
                for c in shares), 4) if shares else None,
            "max_ladder_all_weight_pct": round(max(
                c["ladder_small_weight_pct"] + c["ladder_large_weight_pct"]
                for c in shares), 4) if shares else None,
        },
        "regressions": {"wide_book": _reg(wide_m, "wide"),
                        "residual_bucket": _reg(resid_m, "resid"),
                        "spread_vs_ladder": _reg(spread_m, "spread")},
        "engine": {"wide": {"rebalances": aux["rebalances"],
                            "turnover_per_year": round(aux["turnover_total"] / core["years"], 3),
                            "cost_per_year_bp": round(aux["cost_paid_frac"] / core["years"] * 1e4, 1)},
                   "residual": {"rebalances": raux["rebalances"],
                                "turnover_per_year": round(raux["turnover_total"] / core["years"], 3)}},
        "answers": {
            "mean_ladder_all_weight_pct": (round(avg("ladder_small_weight_pct")
                                                 + avg("ladder_large_weight_pct"), 4)
                                           if shares else None),
            "beta_wide_full": _reg(wide_m, "wide")["full"].get("beta_on_tilt"),
            "beta_residual_full": _reg(resid_m, "resid")["full"].get("beta_on_tilt"),
            "beta_wide_2024_now": _reg(wide_m, "wide").get("2024_now", {}).get("beta_on_tilt"),
            "beta_residual_2024_now": _reg(resid_m, "resid").get("2024_now", {}).get("beta_on_tilt"),
            "sign_explained_by_residual": (
                abs((_reg(wide_m, "wide")["full"].get("beta_on_tilt") or 0)
                    - (_reg(resid_m, "resid")["full"].get("beta_on_tilt") or 0)) < 0.05),
        },
        "honest": [
            "the wide book is every eligible member at equal weight, so the ladder's five legs are "
            "a rounding error in it by construction; the beta therefore cannot come from holding "
            "them, and the residual-bucket regression is the direct measurement of where it does",
            "holdings are read with the engine's own ranking function on the engine's own rank "
            "cache at each decision index, so the composition rows and the simulated curve cannot "
            "disagree about which names were eligible",
            "the residual bucket re-ranks in its own universe, so it is a clean equal-weight "
            "read of non-ladder members, not a subtraction of two curves",
            "the tilt regressor is the four-member skin (E43 reach-back) wherever the five-member "
            "skin cannot be priced; both are reported in the E43 history face",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }


# ---------------------- leg: E43 size-neutral robustness (calendar x cost)

def run_neutralrobust(outdir, core=None, start="2020-01-01", pick_n=9999,
                      exclude=("sh511",), mid_day=15, cost_mults=(1.0, 3.0),
                      raw_all=None):
    """Re-run the size-neutral spread on all four decision calendars at cost x3.

    E42's +181bp newest-era figure has survived neither a fee stress nor a
    calendar shift: E41 moved the calendar and the spread band moved 26bp, and
    E42's cost x3 moved the fee 3x. This leg crosses both axes and reports the
    size-neutral number per cell, so the only surviving claim is the one that
    clears both at once.

    ``raw_all`` lets a screen leg hand in a repaired universe (E81 leg 3). With
    the default ``None`` this calls ``e27.load_universe()`` exactly as before,
    so the published ROBUST face keeps reading the untouched loader.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    core = core or _monthly_core()
    if raw_all is None:
        raw_all = e27.load_universe()
    if exclude:
        raw_all = {s: v for s, v in raw_all.items()
                   if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]
    cal = [d for d in cal_full if d >= start]
    years = len(cal) / 252.0
    all_syms = sorted(set(base.LADDER) | set(raw_all))
    prices, amounts = {}, {}
    for s in all_syms:
        c, a = raw_all.get(s, ({}, {}))
        prices[s] = [c.get(d) for d in cal]
        amounts[s] = [a.get(d) for d in cal]
    universe = [s for s in all_syms if s in raw_all]
    cash = base.load_cash_series(cal)
    rank_cache = {}
    wide_name = "wide_top%d" % pick_n
    month_ends = base.month_end_indices(cal)
    variants = [("me_m1", _shift_indices(month_ends, -1, len(cal))),
                ("me", sorted(set(month_ends))),
                ("me_p1", _shift_indices(month_ends, 1, len(cal))),
                ("mid%d" % mid_day, _mid_month_indices(cal, mid_day))]
    cells = {}
    for mult in cost_mults:
        for vname, idxs in variants:
            rebal = set(idxs)
            curves = {}
            for scheme, univ, n in (("ladder5", base.LADDER, None),
                                    (wide_name, universe, pick_n)):
                curves[scheme], _aux, _h = e27.simulate(cal, prices, amounts, univ, cash,
                                                        n, mult, rank_cache, rebal)
            lm = dict(_month_rets(curves["ladder5"]))
            wm = dict(_month_rets(curves[wide_name]))
            cell = {"rebalances": len(rebal), "era": {}}
            for era, lo, hi in list(ERAS) + [("full", None, None)]:
                ms = [m for m in core["months4"]
                      if _in_era(m, lo, hi) and m in lm and m in wm]
                if len(ms) < 3:
                    cell["era"][era] = {"months": len(ms),
                                        "skipped": "fewer than 3 usable months"}
                    continue
                spread = [wm[m] - lm[m] for m in ms]
                tilt = [core["tilt4"][m] for m in ms]
                b, a, r2 = _ols(spread, tilt)
                raw_ann = sum(spread) / len(spread) * 12 * 1e4
                cell["era"][era] = {
                    "months": len(ms), "from": ms[0], "to": ms[-1],
                    "raw_spread_ann_bp": round(raw_ann, 1),
                    "size_neutral_ann_bp": (round(a * 12 * 1e4, 1) if a is not None else None),
                    "size_component_ann_bp": (round(b * _moments(tilt)["mean"] * 12 * 1e4, 1)
                                              if b is not None else None),
                    "beta_spread_on_tilt": round(b, 3) if b is not None else None,
                    "r_squared": round(r2, 4) if r2 is not None else None,
                }
            cells["cost_x%g|%s" % (mult, vname)] = cell
    newest = {k: v["era"].get("2024_now", {}).get("size_neutral_ann_bp")
              for k, v in cells.items()}
    newest_ok = {k: x for k, x in newest.items() if x is not None}
    full = {k: v["era"].get("full", {}).get("size_neutral_ann_bp") for k, v in cells.items()}
    full_ok = {k: x for k, x in full.items() if x is not None}
    return {
        "study": "e43_size_neutral_robustness",
        "evidence_cutoff": cutoff,
        "spec": {"start": start, "bars": len(cal), "years": round(years, 2),
                 "pick_n": pick_n, "exclude_prefixes": list(exclude),
                 "cost_bp_per_side": base.COST_BP_SIDE, "cost_mults": list(cost_mults),
                 "calendars": [v for v, _ in variants], "mid_month_day": mid_day,
                 "tilt_skin": "4-member (2 broad vs 510500/512100)",
                 "universe_members": len(universe)},
        "cells": cells,
        "answers": {
            "newest_era_size_neutral_by_cell_bp": newest,
            "newest_era_all_positive": (all(x > 0 for x in newest_ok.values())
                                        if newest_ok else None),
            "newest_era_min_bp": min(newest_ok.values()) if newest_ok else None,
            "newest_era_max_bp": max(newest_ok.values()) if newest_ok else None,
            "newest_era_range_bp": (round(max(newest_ok.values()) - min(newest_ok.values()), 1)
                                    if newest_ok else None),
            "full_size_neutral_all_positive": (all(x > 0 for x in full_ok.values())
                                               if full_ok else None),
            "full_min_bp": min(full_ok.values()) if full_ok else None,
            "at_cost_x3_all_positive": (
                all(x > 0 for k, x in newest_ok.items() if k.startswith("cost_x3"))
                if newest_ok else None),
            "cells_measured": len(newest_ok),
        },
        "honest": [
            "cost x3 scales the engine's own 13.041bp/side constant; it is a stress multiplier, "
            "not a measured fee schedule",
            "the calendars differ in session choice only -- universe, ranking and cost model are "
            "shared, so a surviving number is robust to decision timing, not to a different book",
            "the newest era is the shortest and open-ended, so its per-cell regression rests on "
            "the fewest months and carries the widest error",
            "the tilt regressor is the four-member skin; the five-member skin cannot price the "
            "pre-2021 months (E43 reach-back face)",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }


def _robdelta_rows(base_label, faces, modes, eras):
    """Cell-by-cell unscreened vs screened table for the E43 robustness face.

    Same contract as ``_spread_delta_rows``: one delta column per arm (a single
    ``delta_<column>`` key would silently keep only the last arm), and a cell
    whose either side is unmeasured stays None rather than being priced as 0.
    """
    rows = []
    order = [n for n, _lo, _hi in list(eras) + [("full", None, None)]]
    base_cells = faces[base_label]["cells"]
    for cell in sorted(base_cells):
        for era in order:
            era_row = (((base_cells.get(cell) or {}).get("era") or {}).get(era)) or {}
            for col in SPREAD_COLUMNS:
                u = era_row.get(col)
                row = {"cell": cell, "era": era, "column": col, "unscreened": u}
                for mode in modes:
                    v = ((((faces[mode]["cells"].get(cell) or {}).get("era") or {})
                          .get(era)) or {}).get(col)
                    row[mode] = v
                    row["delta_" + mode] = (round(v - u, 4)
                                            if isinstance(v, (int, float))
                                            and isinstance(u, (int, float)) else None)
                rows.append(row)
    return rows


def run_screenrob(outdir, pick_n=9999, exclude=("sh511",),
                  modes=("neutralise_int", "neutralise"), eras=ERAS):
    """E81 leg 3: replay the E43 robustness face from the repaired universe.

    E43 is the face that decides whether the size-neutral spread survives
    twelve cells (four calendars x two fee levels), and it is read off the
    as-traded panel, so the same split-print defect E81 screened out of the
    calendar and spread faces lives inside every one of its cells. This leg
    rebuilds the whole cell grid per arm -- engine curves and the member tilt
    regressor together -- and publishes the screened grid beside the untouched
    one. No published face is rewritten.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    if exclude:
        raw = {s: v for s, v in raw.items() if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]

    arms = {"unscreened": raw}
    reports = {}
    for mode in modes:
        repaired, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)
        reports[mode] = report
        arms[mode] = repaired

    faces = {}
    for label, univ in arms.items():
        core = _monthly_core(pick_n=pick_n, exclude=(), raw_all=univ)
        face = run_neutralrobust(None, core=core, pick_n=pick_n, exclude=(),
                                 raw_all=univ)
        faces[label] = {"universe_size": len(univ), "cells": face["cells"],
                        "answers": face["answers"]}

    delta = _robdelta_rows("unscreened", faces, modes, eras)

    def _cell_bp(arm, cell, era):
        return ((((faces[arm]["cells"].get(cell) or {}).get("era") or {})
                 .get(era)) or {}).get("size_neutral_ann_bp")

    cells = sorted(faces["unscreened"]["cells"])
    levels = {arm: {c: _cell_bp(arm, c, "2024_now") for c in cells} for arm in faces}

    def _positive(arm):
        xs = [x for x in levels[arm].values() if x is not None]
        return all(x > 0 for x in xs) if xs else None

    def _spread(arm):
        xs = [x for x in levels[arm].values() if x is not None]
        return (round(max(xs) - min(xs), 1) if len(xs) >= 2 else None)

    flips = {}
    for mode in modes:
        flips[mode] = [c for c in cells
                       if levels["unscreened"][c] is not None
                       and levels[mode][c] is not None
                       and (levels["unscreened"][c] > 0) != (levels[mode][c] > 0)]

    moves = []
    for mode in modes:
        best = None
        for c in cells:
            u, v = levels["unscreened"][c], levels[mode][c]
            if u is None or v is None:
                continue
            if best is None or abs(v - u) > abs(best["delta_bp"]):
                best = {"cell": c, "unscreened_bp": u, "screened_bp": v,
                        "delta_bp": round(v - u, 1)}
        moves.append({"arm": mode, "widest_cell_move": best,
                      "no_delta_cells": sum(
                          1 for r in delta
                          if r["column"] == "size_neutral_ann_bp"
                          and r["delta_" + mode] == 0.0)})

    def _era_event_census(mode):
        counts = {n: 0 for n, _lo, _hi in list(eras) + [("full", None, None)]}
        for entry in reports[mode].get("names") or []:
            if entry.get("action") != "neutralise":
                continue
            for pr in entry.get("prints") or []:
                if pr.get("factor_applied") is None:
                    continue
                era = _era_of(pr.get("date"), eras) or "full"
                counts[era] = counts.get(era, 0) + 1
                counts["full"] = counts.get("full", 0) + 1
        return counts

    return {
        "study": "e81_leg3_size_neutral_robustness_screened",
        "evidence_cutoff": cutoff,
        "spec": {"pick_n": pick_n, "exclude_prefixes": list(exclude),
                 "cells": cells, "arms": list(faces), "screen_modes": list(modes),
                 "cost_mults": [1.0, 3.0], "calendars": ["me_m1", "me", "me_p1", "mid15"]},
        "arms": {arm: {"universe_size": faces[arm]["universe_size"],
                       "newest_era_all_positive_by_cell": _positive(arm),
                       "newest_era_range_bp": _spread(arm),
                       "newest_era_by_cell_bp": levels[arm],
                       "delta_cells": 0 if arm == "unscreened" else 1,
                       "repair_events_by_era": (_era_event_census(arm)
                                                if arm in reports else {})}
                 for arm in faces},
        "answers": {
            "newest_era_by_arm_cell_bp": levels,
            "all_positive": {arm: _positive(arm) for arm in faces},
            "range_bp": {arm: _spread(arm) for arm in faces},
            "sign_flips_vs_unscreened": flips,
            "widest_moves": moves,
            "newest_era_unscreened_min_bp": min(
                [x for x in levels["unscreened"].values() if x is not None] or [None]),
            "newest_era_unscreened_max_bp": max(
                [x for x in levels["unscreened"].values() if x is not None] or [None]),
        },
        "delta_table": delta,
        "honest": [
            "screened arms repair integer-ratio prints inside the wide book; the ladder "
            "leg is untouched because its five members are never the repaired names",
            "cost x3 is the engine's own 13.041bp/side constant scaled, not a measured schedule",
            "the screen cannot recover a print that the source never published -- it only "
            "removes the ones the panel shows as integer-ratio jumps",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }


# ------------------------------------- leg: E44 leave-one-out skin decomposition

def _skin_sets(drop=None):
    """(large, small) member legs after dropping one member (None = full skin)."""
    large = tuple(s for s in TILT_LARGE if s != drop)
    small = tuple(s for s in TILT_SMALL if s != drop)
    return large, small


def run_skinloo(outdir, core=None, eras=ERAS, members=None):
    """Price the size-neutral spread on every leave-one-out skin, per era.

    E43's four-member reach-back is itself one leave-one-out skin (STAR dropped),
    and it moved the newest-era size-neutral spread from +181.2bp to +38.5bp. A
    number that moves 4.7x on a naming decision cannot be quoted without the
    skin being disclosed, so every one-member drop is priced here on the same
    engine curves and the same months. The delta column is the answer to "which
    member carries the sign flip", not a new spread estimate.
    """
    core = core or _monthly_core()
    mem, brk = core["mem"], core["brk"]
    lad_m, wide_m = core["lad_m"], core["wide_m"]
    months_all = [m for m in sorted(lad_m) if m in wide_m]
    members = list(members or (TILT_LARGE + TILT_SMALL))

    def read_skin(large, small):
        used, tilt, dropped = _tilt_series(mem, brk, months_all, large, small)
        rows = {}
        for name, lo, hi in list(eras) + [("full", None, None)]:
            ms = [m for m in used if _in_era(m, lo, hi)]
            if len(ms) < 3:
                rows[name] = {"months": len(ms), "skipped": "fewer than 3 usable months"}
                continue
            t = [tilt[m] for m in ms]
            spread = [wide_m[m] - lad_m[m] for m in ms]
            tm = _moments(t)
            beta, alpha, r2 = _ols(spread, t)
            tilt_ann = tm["mean"] * 12.0 * 1e4
            rows[name] = {
                "months": len(ms), "from": ms[0], "to": ms[-1],
                "tilt_annualised_bp": round(tilt_ann, 1),
                "tilt_sd_bp": round(tm["sd"] * 1e4, 1) if tm["sd"] is not None else None,
                "spread_raw_ann_bp": round(sum(spread) / len(spread) * 12.0 * 1e4, 1),
                "spread_size_neutral_ann_bp": (round(alpha * 12.0 * 1e4, 1)
                                               if alpha is not None else None),
                "beta_spread_on_tilt": round(beta, 3) if beta is not None else None,
                "r_squared_spread": round(r2, 4) if r2 is not None else None,
            }
        return rows, dropped

    base_rows, base_dropped = read_skin(TILT_LARGE, TILT_SMALL)
    skins = {"full_5": {"drop": None, "skin": "5-member", "members": list(TILT_LARGE + TILT_SMALL),
                        "eras": base_rows}}
    for drop in members:
        large, small = _skin_sets(drop)
        if not large or not small:
            continue
        rows, dropped = read_skin(large, small)
        skins["drop_" + drop] = {
            "drop": drop,
            "skin": "%d-member" % (len(large) + len(small)),
            "members": list(large + small),
            "eras": rows,
            "dropped_months": len(dropped),
        }

    # per-era delta against the full skin: which member moves the number, and by how much
    delta = {}
    for name in skins:
        if name == "full_5":
            continue
        d = {}
        for era in ("2017_2020", "2021_2023", "2024_now", "full"):
            a = skins[name]["eras"].get(era, {}).get("spread_size_neutral_ann_bp")
            b = base_rows.get(era, {}).get("spread_size_neutral_ann_bp")
            d[era] = round(a - b, 1) if (a is not None and b is not None) else None
        delta[skins[name]["drop"]] = d

    def sign(x):
        if x is None:
            return None
        return 1 if x > 0 else (-1 if x < 0 else 0)

    flips = {}
    for era in ("2021_2023", "2024_now"):
        b = base_rows.get(era, {}).get("spread_size_neutral_ann_bp")
        flips[era] = {
            "full_skin_bp": b,
            "members_whose_removal_flips_sign": [
                m for m, d in delta.items()
                if d.get(era) is not None and sign(d[era] + (b or 0)) != sign(b)
            ],
            "largest_removal_effect": (
                sorted(((abs(d[era]), m) for m, d in delta.items() if d.get(era) is not None),
                       reverse=True) or [(None, None)])[0][1],
        }

    return {
        "leg": "e44_skin_loo",
        "evidence_cutoff": core["cutoff"],
        "engine": {"wide_book": core["wide_name"], "ladder": "ladder5",
                   "cost_bp_per_side": 13.041, "convention": "monthly additive bp"},
        "eras": [{"name": n, "lo": lo, "hi": hi} for n, lo, hi in eras],
        "skins": skins,
        "delta_vs_full_skin_bp": delta,
        "sign_flip_attribution": flips,
        "answers": {
            "which_member_carries_the_2021_2023_vs_2024_now_flip":
                flips["2024_now"]["largest_removal_effect"],
            "spread_range_across_skins_2024_now_bp": [
                min(r["eras"]["2024_now"]["spread_size_neutral_ann_bp"]
                    for r in skins.values()
                    if r["eras"].get("2024_now", {}).get("spread_size_neutral_ann_bp") is not None),
                max(r["eras"]["2024_now"]["spread_size_neutral_ann_bp"]
                    for r in skins.values()
                    if r["eras"].get("2024_now", {}).get("spread_size_neutral_ann_bp") is not None),
            ],
            "four_member_row_matches_e43": (
                "drop_sh588000 is exactly the E43 four-member skin; its 2024_now "
                "size-neutral number is the one E43 headlines"),
        },
        "honest": [
            "every skin is priced on the same engine curves, the same months and the same "
            "13.041bp/side constant -- only the tilt regressor changes",
            "a leave-one-out skin is not an alternative portfolio: it is the same wide book "
            "measured against a narrower size reference, so the spread levels are not tradeable "
            "alternatives to each other",
            "the sign-flip attribution is a decomposition, not a forecast; the newest era is the "
            "shortest and carries the widest error",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }


# -------------------------------- leg: E44 eligibility burn-in / missing years

def _first_eligible_idx(series, min_bars):
    """First index whose trailing ``min_bars`` window is fully priced.

    Mirrors ``e24_ladder_weighting.elig`` exactly: eligibility needs MIN_BARS of
    *consecutive, non-missing, in-window* closes, so it is window-relative -- the
    first ~250 sessions of any start window are structurally un-investable no
    matter how long the symbol's own history is.
    """
    run = 0
    for i, v in enumerate(series):
        run = run + 1 if v is not None else 0
        if run >= min_bars:
            return i
    return None


def _annual_rets(marks):
    """{year: pct} from month-end marks, each year chained off the prior year-end."""
    by_year = {}
    for m, v in marks:
        by_year[m[:4]] = v
    out = {}
    prev = None
    for y in sorted(by_year):
        if prev:
            out[y] = round((by_year[y] / prev - 1.0) * 100, 2)
        prev = by_year[y]
    return out


def run_burnin(outdir, starts=("2013-01-01", "2016-01-01", "2018-01-01", "2020-01-01"),
               pick_n=9999, exclude=("sh511",), min_bars=None, raw=None):
    """Attribute the missing pre-2017 years to the eligibility gate, not to mystery.

    E40 measured that the book sits in repo for 263 of its first 1,645 bars and
    that the first invested bar is 2021-02-01 on a 2020 start. This leg measures
    the gate itself: how many sessions each start window spends un-invested, when
    the first eligible set actually arrives (and how many names it holds), how
    much of that is the 250-bar rule being window-relative versus the panel's own
    symbol start dates, and what 2013-2016 is worth on the same spec once the
    burn-in is paid outside the measured window (a warm run on the full calendar,
    sliced afterwards).
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    min_bars = int(min_bars or base.MIN_BARS)
    prev_min_bars = base.MIN_BARS
    base.MIN_BARS = min_bars   # e27.load_universe and base.elig both read this global
    # ``raw`` lets a caller burn a screened twin of the same panel (E112) without
    # re-loading it here; the default path is untouched for every existing face.
    raw_all = raw if raw is not None else e27.load_universe()
    if exclude:
        raw_all = {s: v for s, v in raw_all.items()
                   if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]
    all_syms = sorted(set(base.LADDER) | set(raw_all))
    universe = [s for s in all_syms if s in raw_all]

    def build(cal):
        prices, amounts = {}, {}
        for s in all_syms:
            c, a = raw_all.get(s, ({}, {}))
            prices[s] = [c.get(d) for d in cal]
            amounts[s] = [a.get(d) for d in cal]
        return prices, amounts

    # one warm pair of curves on the whole calendar: the burn-in is paid before
    # the measured slice begins, so the slice prices the spec, not the gate.
    warm_prices, warm_amounts = build(cal_full)
    warm = {}
    for name, univ, n in (("ladder5", base.LADDER, None), ("wide", universe, pick_n)):
        curve, aux, _ = e27.simulate(cal_full, warm_prices, warm_amounts, univ,
                                     None, n, 1.0, {})
        warm[name] = curve

    def slice_faces(curve, lo, hi=None):
        part = [pt for pt in curve if pt[0] >= lo and (hi is None or pt[0] <= hi)]
        if len(part) < 3:
            return None
        me = _month_ends(part)
        if len(me) < 2:
            return None
        yrs = len(part) / 252.0
        return {
            "bars": len(part),
            "from": part[0][0], "to": part[-1][0],
            "ann_return_pct": round((part[-1][1] / part[0][1]) ** (1.0 / yrs) * 100 - 100, 2),
            "max_drawdown_pct": risk_profile(part, yrs)["max_drawdown_pct"],
            "annual_returns_pct": _annual_rets(me),
            "monthly_marks": len(me),
        }

    # calendar-year returns on the warm curve itself: a year's return chains off
    # the prior year-end mark, which a slice starting inside the year cannot see.
    warm_annual = {name: _annual_rets(_month_ends(warm[name])) for name in warm}

    windows = {}
    for start in starts:
        cal = [d for d in cal_full if d >= start]
        years = len(cal) / 252.0
        prices, amounts = build(cal)
        rebal = base.month_end_indices(cal)
        elig_series = []
        for ri in rebal:
            elig_series.append({
                "date": cal[ri], "idx": ri,
                "n_priced": sum(1 for s in universe if prices[s][ri] is not None),
                "n_eligible": sum(1 for s in universe if base.elig(prices[s], ri)),
            })
        first_trade_idx = next((ri for ri in rebal
                                if any(base.elig(prices[s], ri) for s in universe)), None)
        first_ladder_idx = next((ri for ri in rebal
                                 if any(base.elig(prices[s], ri) for s in base.LADDER)), None)
        # earliest decision the 250-bar rule can possibly allow in this window
        allowed = [ri for ri in rebal if ri >= min_bars]
        # per-symbol arrival of eligibility inside the window
        arrival = {}
        for s in universe:
            i = _first_eligible_idx(prices[s], min_bars)
            if i is not None:
                arrival[s] = cal[i]
        hist = {}
        for d in arrival.values():
            hist[d[:4]] = hist.get(d[:4], 0) + 1
        first_invested = (cal[first_trade_idx + 1] if first_trade_idx is not None else None)
        uninv = (first_trade_idx + 1) if first_trade_idx is not None else len(cal) - 1

        naive = {}
        for name, univ, n in (("ladder5", base.LADDER, None), ("wide", universe, pick_n)):
            curve, aux, _ = e27.simulate(cal, prices, amounts, univ, None, n, 1.0, {})
            naive[name] = {
                "ann_return_pct": risk_profile(curve, years)["ann_return_pct"],
                "first_curve_bar": curve[0][0],
            }
        windows[start] = {
            "bars": len(cal),
            "years": round(years, 2),
            "min_bars_gate": min_bars,
            "rebalance_decisions": len(rebal),
            "first_rebalance": cal[rebal[0]] if rebal else None,
            "earliest_possible_trading_decision": cal[allowed[0]] if allowed else None,
            "earliest_possible_gate_date": cal[min_bars] if len(cal) > min_bars else None,
            "first_trading_rebalance": cal[first_trade_idx] if first_trade_idx is not None else None,
            "first_invested_bar": first_invested,
            "sessions_uninvested": uninv,
            "sessions_uninvested_share_pct": round(uninv / max(1, len(cal) - 1) * 100, 2),
            "months_uninvested": round(uninv / 21.0, 1),
            "first_trading_rebalance_ladder5": (cal[first_ladder_idx]
                                                if first_ladder_idx is not None else None),
            "eligible_at_first_invested": next(
                (r["n_eligible"] for r in elig_series
                 if first_trade_idx is not None and r["idx"] == first_trade_idx), None),
            "first_rebalance_with_elig_ge_5": next(
                (r["date"] for r in elig_series if r["n_eligible"] >= 5), None),
            "first_rebalance_with_elig_ge_20": next(
                (r["date"] for r in elig_series if r["n_eligible"] >= 20), None),
            "eligibility_at_rebalances": elig_series,
            "symbol_first_eligible_hist_by_year": dict(sorted(hist.items())),
            "symbols_eligible": len(arrival),
            "symbols_in_universe": len(universe),
            "naive_start_curves": naive,
            "warm_slice": {name: slice_faces(warm[name], start) for name in warm},
        }

    # the question the E43/E44 line actually leaves open: is 2013-2016 worth
    # anything on the same spec, and how much of it does the gate eat?
    span = {}
    for lo, hi in (("2013-01-01", "2016-12-31"), ("2017-01-01", "2020-12-31"),
                   ("2021-01-01", None)):
        block = {"%s..%s" % (lo, hi or "now"): {}}
        for name in warm:
            face = slice_faces(warm[name], lo, hi)
            if face is not None:
                y0, y1 = lo[:4], (hi or "9999")[:4]
                face["calendar_year_returns_pct"] = {
                    y: v for y, v in warm_annual[name].items() if y0 <= y <= y1}
            block["%s..%s" % (lo, hi or "now")][name] = face
        span.update(block)

    base.MIN_BARS = prev_min_bars
    return {
        "study": "e44_eligibility_burnin",
        "evidence_cutoff": cutoff,
        "spec": {"pick_n": pick_n, "exclude_prefixes": list(exclude),
                 "starts": list(starts), "min_bars": min_bars,
                 "cost_bp_per_side": base.COST_BP_SIDE,
                 "calendar_first": cal_full[0], "calendar_last": cal_full[-1]},
        "windows": windows,
        "era_spans_warm": span,
        "answers": {
            "gate_is_window_relative": True,
            "why_first_set_is_late": (
                "elig() needs %d consecutive non-missing closes measured inside the start "
                "window, so no decision before index %d can hold anything: the first "
                "possible invested bar is the session after the first month end at or "
                "past index %d" % (min_bars, min_bars, min_bars)),
            "sessions_uninvested_by_start": {
                s: windows[s]["sessions_uninvested"] for s in windows},
            "first_invested_bar_by_start": {
                s: windows[s]["first_invested_bar"] for s in windows},
            "warm_2013_2016_wide_ann_pct": (
                span["2013-01-01..2016-12-31"].get("wide") or {}).get("ann_return_pct"),
            "warm_2013_2016_ladder_ann_pct": (
                span["2013-01-01..2016-12-31"].get("ladder5") or {}).get("ann_return_pct"),
            "naive_2013_start_wide_ann_pct":
                windows["2013-01-01"]["naive_start_curves"]["wide"]["ann_return_pct"],
        },
        "honest": [
            "the burn-in is a property of the engine's membership rule, not a data defect: "
            "the same %d-bar rule gates every scheme" % min_bars,
            "warm slices pay the burn-in on bars outside the measured span; the naive "
            "columns are the same spec started cold, and the difference is the gate",
            "symbols_in_universe counts de-duplicated panels; eligibility arrival is per "
            "window because the rule is window-relative",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }


_BURNSCREEN_DELTA_FLOOR_PP = 0.005


def _burnin_arm_cells(face, starts):
    """-> {(start, cell): value} for every number a burn-in face publishes.

    Only the columns that carry a burn-in reading are harvested: the gate dates
    and the session counts must be comparable across arms, and so must the
    return columns the warmth argument is built on.
    """
    out = {}
    for start in starts:
        w = (face.get("windows") or {}).get(start) or {}
        out[(start, "sessions_uninvested")] = w.get("sessions_uninvested")
        out[(start, "sessions_uninvested_share_pct")] = w.get(
            "sessions_uninvested_share_pct")
        out[(start, "months_uninvested")] = w.get("months_uninvested")
        out[(start, "eligible_at_first_invested")] = w.get("eligible_at_first_invested")
        out[(start, "symbols_eligible")] = w.get("symbols_eligible")
        for book in ("ladder5", "wide"):
            out[(start, "naive_" + book + "_ann_pct")] = (
                ((w.get("naive_start_curves") or {}).get(book) or {}).get("ann_return_pct"))
            sl = (w.get("warm_slice") or {}).get(book) or {}
            out[(start, "warm_" + book + "_ann_pct")] = sl.get("ann_return_pct")
            out[(start, "warm_" + book + "_maxdd_pct")] = sl.get("max_drawdown_pct")
    for span, block in (face.get("era_spans_warm") or {}).items():
        for book, sl in (block or {}).items():
            sl = sl or {}
            out[(span, "span_" + book + "_ann_pct")] = sl.get("ann_return_pct")
            out[(span, "span_" + book + "_maxdd_pct")] = sl.get("max_drawdown_pct")
    return out


def _burnin_gate_dates(face, starts):
    """Gate *dates* of a burn-in face: strings, so they either move or they do not."""
    out = {}
    for start in starts:
        w = (face.get("windows") or {}).get(start) or {}
        out[start] = {col: w.get(col) for col in (
            "first_invested_bar", "first_trading_rebalance",
            "earliest_possible_trading_decision",
            "first_rebalance_with_elig_ge_5")}
    return out


def _burnin_pair_rows(raw_arm, screened_arm, starts, cells_fn=None, dates_fn=None):
    """(E112, generalised E113) Join two faces cell by cell and publish the deltas.

    A "screened twin" is only a twin if the join covers the same cells: anything
    present on one side and missing on the other is reported, not skipped, and a
    cell that moved is reported with its pointer (start or era span, column).

    ``cells_fn(face, starts) -> {(key, column): value}`` and
    ``dates_fn(face, starts) -> {key: {column: value}}`` keep the join generic
    over face shapes: E112 harvests burn-in columns, E113 harvests the cut
    curve, and both are joined by this one function rather than two.
    """
    cells_fn = cells_fn or _burnin_arm_cells
    dates_fn = dates_fn or _burnin_gate_dates
    a = cells_fn(raw_arm, starts)
    b = cells_fn(screened_arm, starts)
    shared = [k for k in a if k in b and a[k] is not None and b[k] is not None]
    only_a = sorted(k for k in a if k not in b)
    only_b = sorted(k for k in b if k not in a)
    missing = sorted(k for k in a if k in b and (a[k] is None or b[k] is None))
    rows, moved = [], []
    for k in shared:
        d = b[k] - a[k]
        row = {"start": k[0], "column": k[1],
               "raw": round(a[k], 4), "screened": round(b[k], 4),
               "delta": round(d, 4)}
        rows.append(row)
        if abs(d) > _BURNSCREEN_DELTA_FLOOR_PP:
            moved.append(row)
    # gate dates are strings: they either move or they do not
    da = dates_fn(raw_arm, starts)
    db = dates_fn(screened_arm, starts)
    date_cols = {}
    for start in sorted(set(da) | set(db)):
        ca = da.get(start) or {}
        cb = db.get(start) or {}
        cols = {}
        for col in sorted(set(ca) | set(cb)):
            va, vb = ca.get(col), cb.get(col)
            cols[col] = {"raw": va, "screened": vb, "moved": va != vb}
        date_cols[start] = cols
    dates_moved = [{"start": s, "column": c, "raw": v["raw"], "screened": v["screened"]}
                   for s, cols in date_cols.items() for c, v in cols.items()
                   if v["moved"]]
    worst = max(moved, key=lambda r: abs(r["delta"])) if moved else None
    return {
        "rows": rows,
        "moved": moved,
        "only_in_raw": [{"start": k[0], "column": k[1]} for k in only_a],
        "only_in_screened": [{"start": k[0], "column": k[1]} for k in only_b],
        "null_on_either_side": [{"start": k[0], "column": k[1]} for k in missing],
        "gate_dates": date_cols,
        "gate_dates_moved": dates_moved,
        "summary": {
            "cells_compared": len(shared),
            "cells_moved": len(moved),
            "max_abs_delta_pp": (abs(worst["delta"]) if worst else 0.0),
            "worst": worst,
            "only_in_raw": len(only_a),
            "only_in_screened": len(only_b),
            "null_on_either_side": len(missing),
            "gate_dates_moved": len(dates_moved),
        },
    }


def _twin_survives(summary, control):
    """(E116) "survives" means the NUMBERS did not move, not that the join worked.

    E112-E115 folded both questions into one boolean: a complete join with a
    silent control returned True even when dozens of cells had moved, and E116
    caught it live (55 of 93 cells moved while the face still said the ladder
    survived the repair). A join's completeness and its verdict are two facts.
    """
    return (summary["only_in_raw"] == 0 and summary["only_in_screened"] == 0
            and summary["cells_moved"] == 0
            and control["cells_moved"] == 0
            and control["max_abs_delta_pp"] == 0.0)


def run_burninscreen(outdir, starts=("2013-01-01", "2016-01-01", "2018-01-01", "2020-01-01"),
                     pick_n=9999, exclude=("sh511",), mode="neutralise_int",
                     resume=True):
    """E112: re-derive the burn-in face on the screened arm, beside the raw one.

    E97's routing table leaves 21 of 25 charged modes with no screened twin, and
    the largest single burn is this one: ``run_burnin`` feeds four published
    modes and carries 1,727 numbers. E77 moved the wide book by ~216bp/yr when
    the split repair was switched on, so the open question is not whether the
    numbers move but whether the *burn-in conclusion* survives them -- the gate
    dates and the un-invested session counts are the load-bearing columns, the
    return columns are the ones expected to move.

    Both arms are burned off ONE load of the panel (the screen takes the same
    ``raw`` mapping ``run_burnin`` would have loaded), each arm checkpoints to
    its own file so a killed pass resumes instead of restarting, and the pair is
    joined by ``_burnin_pair_rows``. A same-arm control (raw vs raw) is computed
    in-round: if it does not read zero on every cell, the join machinery moved
    the numbers and the face must not be read.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]
    tag = cutoff.replace("-", "")

    def cached(label, thunk):
        p = os.path.join(outdir or ".", "BURNSCREEN-arm-%s-%s.json" % (label, tag))
        if resume and os.path.isfile(p):
            try:
                with open(p, "r", encoding="utf-8") as fh:
                    return json.load(fh)
            except Exception:
                pass
        face = thunk()
        if outdir:
            write_json(outdir, "BURNSCREEN-arm-%s-%s.json" % (label, tag), face)
        return face

    raw_excl = {s: v for s, v in raw.items()
                if not s.startswith(tuple(exclude))} if exclude else dict(raw)
    screened, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)
    screened_excl = {s: v for s, v in screened.items()
                     if not s.startswith(tuple(exclude))} if exclude else dict(screened)

    raw_arm = cached("raw", lambda: run_burnin(None, starts=starts, pick_n=pick_n,
                                               exclude=exclude, raw=raw_excl))
    scr_arm = cached(mode, lambda: run_burnin(None, starts=starts, pick_n=pick_n,
                                              exclude=exclude, raw=screened_excl))

    pair = _burnin_pair_rows(raw_arm, scr_arm, starts)
    # identity control: the same arm joined against itself must read zero
    control = _burnin_pair_rows(raw_arm, raw_arm, starts)["summary"]

    # cutoff control: the newest *previously published* raw burn-in face against
    # today's raw arm. Two arms at one cutoff isolate the repair; two cutoffs on
    # one arm isolate the panel refresh. Without both, a moved cell cannot be
    # attributed to either.
    cutoff_control = None
    if outdir and os.path.isdir(outdir):
        olds = sorted(p for p in os.listdir(outdir)
                      if p.startswith("BURNIN-") and p.endswith(".json"))
        for p in reversed(olds):
            if p[len("BURNIN-"):-len(".json")] == tag:
                continue
            try:
                with open(os.path.join(outdir, p), "r", encoding="utf-8") as fh:
                    old_face = json.load(fh)
            except Exception:
                continue
            old_pair = _burnin_pair_rows(old_face, raw_arm, starts)
            cutoff_control = {
                "old_face": p,
                "old_cutoff": old_face.get("evidence_cutoff"),
                "comparison": "old raw arm vs today raw arm (arm held fixed)",
                "summary": old_pair["summary"],
                "moved": old_pair["moved"],
            }
            break

    s = pair["summary"]
    survives = (s["gate_dates_moved"] == 0
                and s["only_in_raw"] == 0 and s["only_in_screened"] == 0
                and control["cells_moved"] == 0 and control["max_abs_delta_pp"] == 0.0)
    gate_cols = ("sessions_uninvested", "sessions_uninvested_share_pct",
                 "months_uninvested", "eligible_at_first_invested", "symbols_eligible")
    gate_moved = [r for r in pair["moved"] if r["column"] in gate_cols]
    return_moved = [r for r in pair["moved"] if r["column"] not in gate_cols]
    return {
        "study": "e112_burnin_screened_twin",
        "evidence_cutoff": cutoff,
        "spec": {
            "starts": list(starts), "pick_n": pick_n,
            "exclude_prefixes": list(exclude), "screen_mode": mode,
            "arms": {"raw": "e27.load_universe() as shipped",
                     "screened": "panel_screen.screen_universe(mode=%s)" % mode},
            "join": ("_burnin_arm_cells harvests every numeric column a burn-in "
                     "face publishes; a cell present on one side only is reported, "
                     "and a cell moved is reported with its pointer"),
            "control": ("the same arm joined against itself; every cell must read "
                        "delta 0.0 or the join machinery moved the numbers"),
        },
        "screen_report": report,
        "pair": pair,
        "control": control,
        "cutoff_control": cutoff_control,
        "arms": {
            "raw": {"cutoff": raw_arm.get("evidence_cutoff"),
                    "symbols_in_universe": {
                        st: ((raw_arm["windows"].get(st) or {}).get("symbols_in_universe"))
                        for st in starts}},
            "screened": {"cutoff": scr_arm.get("evidence_cutoff"),
                         "symbols_in_universe": {
                             st: ((scr_arm["windows"].get(st) or {}).get("symbols_in_universe"))
                             for st in starts}},
        },
        "answers": {
            "conclusion_survives_the_repair": bool(survives),
            "cells_compared": s["cells_compared"],
            "cells_moved": s["cells_moved"],
            "max_abs_delta_pp": s["max_abs_delta_pp"],
            "worst_cell": s["worst"],
            "gate_columns_moved": len(gate_moved),
            "return_columns_moved": len(return_moved),
            "gate_dates_moved": s["gate_dates_moved"],
            "control_cells_moved": control["cells_moved"],
            "cutoff_control": ({"old_face": cutoff_control["old_face"],
                                "cells_moved": cutoff_control["summary"]["cells_moved"],
                                "max_abs_delta_pp":
                                    cutoff_control["summary"]["max_abs_delta_pp"]}
                               if cutoff_control else None),
            "reading": (
                ("the burn-in conclusion survives the repair: all %d gate columns "
                 "and every gate date are unchanged; %d of %d return cells move, "
                 "worst %.2f pp"
                 % (len([r for r in pair["rows"] if r["column"] in gate_cols]),
                    len(return_moved), len(pair["rows"]) - len(
                        [r for r in pair["rows"] if r["column"] in gate_cols]),
                    s["max_abs_delta_pp"]))
                if survives else
                ("the repair reaches the burn-in reading: %d gate columns and %d "
                 "gate dates move between the arms, so the warm-up numbers are not "
                 "arm-free" % (len(gate_moved), s["gate_dates_moved"]))),
        },
        "honest": [
            "descriptive census only: no gate, no verdict on the strategy, no "
            "prereg, no trial count, no ledger booking",
            "the screened arm repairs prints *inside* the panel it is handed; it "
            "does not change which bars are missing, so an unchanged eligibility "
            "count is a property of the repair, not evidence the data is clean",
            "a same-arm control is run in-round and published; a non-zero control "
            "invalidates the pair regardless of how the deltas read",
            "one burn per runner: burnin/e44/knife/skinloo share run_burnin, so "
            "this ticket re-derives the burn-in face only; knife and skinloo keep "
            "their own tickets",
        ],
    }


def run_knife(outdir, starts=("2013-01-01", "2016-01-01", "2018-01-01", "2020-01-01"),
              knives=(60, 120, 250), pick_n=9999, exclude=("sh511",), resume=True):
    """E45: price the knife edge of the MIN_BARS eligibility rule.

    The 250-bar gate is a deliberate no-thin-history-listing rule, but nobody has
    measured what it buys against what it costs. Rerun the identical spec at
    MIN_BARS 60/120/250 and read two things per window: the annualised return the
    book earns once it is finally allowed to trade, and the size of the eligible
    set on that first trade. A cheaper gate that buys most of the return back
    without flooding the book with one-month-old listings means the 250 is a
    six-month tax; early bars that read as junk at 60 mean it is earning its keep.

    Per-knife checkpoints land as ``KNIFE-<cutoff>-mb<n>.json`` so a killed pass
    resumes instead of restarting; the assembled face is written once all knives
    are on disk. Descriptive only: no gate, no verdict, no prereg, no trials.
    """
    per_knife = {}
    for mb in knives:
        cached = None
        if resume:
            hit = [p for p in sorted(os.listdir(outdir) or [])
                   if p.startswith("KNIFE-") and p.endswith("-mb%d.json" % mb)] \
                if os.path.isdir(outdir) else []
            if hit:
                try:
                    with open(os.path.join(outdir, hit[-1]), encoding="utf-8") as fh:
                        cached = json.load(fh)
                except Exception:
                    cached = None
        if cached is None:
            cached = run_burnin(None, starts=starts, pick_n=pick_n,
                                exclude=exclude, min_bars=mb)
            write_json(outdir, "KNIFE-%s-mb%d.json"
                       % (cached["evidence_cutoff"].replace("-", ""), mb), cached)
        per_knife[mb] = cached

    cutoff = per_knife[knives[0]]["evidence_cutoff"]
    rows = {}
    for start in starts:
        rows[start] = {}
        for mb in knives:
            w = per_knife[mb]["windows"].get(start)
            if not w:
                continue
            rows[start][mb] = {
                "min_bars": mb,
                "sessions_uninvested": w["sessions_uninvested"],
                "sessions_uninvested_share_pct": w["sessions_uninvested_share_pct"],
                "first_invested_bar": w["first_invested_bar"],
                "eligible_at_first_invested": w["eligible_at_first_invested"],
                "symbols_in_universe": w["symbols_in_universe"],
                "wide_ann_return_pct": (w["naive_start_curves"]["wide"] or {}).get(
                    "ann_return_pct"),
                "ladder_ann_return_pct": (w["naive_start_curves"]["ladder5"] or {}).get(
                    "ann_return_pct"),
                "eligible_set_at_first_trade": w["eligible_at_first_invested"],
            }

    # the two questions the batch asks, answered off the same grid
    answers = {}
    for start, by_mb in rows.items():
        base_face = by_mb.get(250) or {}
        cheap = by_mb.get(120) or by_mb.get(60) or {}
        if not base_face or not cheap:
            continue
        answers[start] = {
            "return_gap_120_vs_250_pp": (
                round(cheap["wide_ann_return_pct"] - base_face["wide_ann_return_pct"], 2)
                if (cheap.get("wide_ann_return_pct") is not None
                    and base_face.get("wide_ann_return_pct") is not None) else None),
            "eligible_gap_120_vs_250": (
                cheap["eligible_at_first_invested"] - base_face["eligible_at_first_invested"]
                if (cheap.get("eligible_at_first_invested") is not None
                    and base_face.get("eligible_at_first_invested") is not None) else None),
        }

    return {
        "study": "e45_burnin_knife",
        "evidence_cutoff": cutoff,
        "spec": {"pick_n": pick_n, "exclude_prefixes": list(exclude),
                 "starts": list(starts), "knives": list(knives),
                 "cost_bp_per_side": per_knife[knives[0]]["spec"]["cost_bp_per_side"]},
        "grid": rows,
        "answers": answers,
        "honest": [
            "the same spec runs at each knife; only the membership rule moves, so any "
            "return difference is the gate's price, not a different strategy",
            "a bigger eligible set at a cheaper gate is not automatically good: the "
            "question is whether the extra names are tradeable or one-month-old listings",
            "descriptive census only: no gate, no verdict, no prereg, no trials consumed",
        ],
    }


# ---------------------------- leg: E45 warm slices vs cold-start windows
#
# Every era spread since E41 is quoted off the E24/E27 engine, and r1120 measured
# that the 250-bar rule deletes 259-265 sessions (12.3 months) from the front of
# ANY start window. Both books share that dead block, so the spread itself should
# be immune -- but the block is not free: while the book holds nothing the engine
# carries cash at weight 1.0, so the dead block accrues at the repo rate for both
# books and it is a very different share of a 2024 window than of a 2013 one.
# This leg puts the two quotes side by side per era -- the warm slice (one curve
# on the full calendar, sliced afterwards, so the burn-in is paid outside the
# measured span) against the cold start (a fresh curve from the era's own start)
# -- and reports the dead block's size and what it accrued in each case.

def _bars_before(curve, date):
    """Bars in ``curve`` strictly before ``date``; 0 when ``date`` is unknown."""
    if not date:
        return 0
    return sum(1 for d, _v in curve if d < date)


def _curve_faces(curve):
    """Rebased annualised face of one slice; None when the slice is too short."""
    seg = _rebase(curve)
    if len(seg) < 3:
        return None
    prof = risk_profile(seg, len(seg) / 252.0)
    return {"from": seg[0][0], "to": seg[-1][0], "bars": len(seg),
            "ann_return_pct": prof["ann_return_pct"],
            "max_drawdown_pct": prof["max_drawdown_pct"]}


def _spread_bp(ladder_face, wide_face):
    """wide minus ladder in bp on the annualised column; None if either is missing."""
    if not ladder_face or not wide_face:
        return None
    return round((wide_face["ann_return_pct"] - ladder_face["ann_return_pct"]) * 100, 1)


def _cash_accrual_pct(cash, cal_x, upto_date):
    """Compounded cash return over the bars before ``upto_date``, in pct."""
    if not cash or not upto_date:
        return 0.0
    tot = 1.0
    for d in cal_x:
        if d >= upto_date:
            break
        tot *= (1.0 + cash["series"].get(d, 0.0))
    return round((tot - 1.0) * 100.0, 3)


def run_warmspread(outdir, eras=ERAS, pick_n=9999, exclude=("sh511",), raw=None):
    """E45: does the era ordering survive once the dead block is outside the window?

    ``raw`` (E122) lets the screened twin hand in an already repaired universe so
    both arms are burned off one load; passing it skips the loader entirely.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    raw_all = raw if raw is not None else e27.load_universe()
    if exclude:
        raw_all = {s: v for s, v in raw_all.items()
                   if not s.startswith(tuple(exclude))}
    cal = base.load_panel()[0]
    cutoff = cal[-1]
    all_syms = sorted(set(base.LADDER) | set(raw_all))
    prices, amounts = {}, {}
    for s in all_syms:
        c, a = raw_all.get(s, ({}, {}))
        prices[s] = [c.get(d) for d in cal]
        amounts[s] = [a.get(d) for d in cal]
    universe = [s for s in all_syms if s in raw_all]
    wide_name = "wide_top%d" % pick_n
    books = (("ladder5", list(base.LADDER), None), (wide_name, universe, pick_n))

    def build(cal_x):
        px, ax = {}, {}
        for s in all_syms:
            c, a = raw_all.get(s, ({}, {}))
            px[s] = [c.get(d) for d in cal_x]
            ax[s] = [a.get(d) for d in cal_x]
        return px, ax

    def first_invested(cal_x, px, book_univ):
        """First bar the book can actually hold something on this calendar."""
        rebal = base.month_end_indices(cal_x)
        idx = next((ri for ri in rebal
                    if any(base.elig(px[s], ri) for s in book_univ)), None)
        if idx is None:
            return None
        return cal_x[idx + 1] if idx + 1 < len(cal_x) else None

    # warm: one pair of curves on the whole calendar, sliced per era afterwards
    warm, warm_first = {}, {}
    for name, univ, n in books:
        curve, _aux, _hold = e27.simulate(cal, prices, amounts, univ,
                                          base.load_cash_series(cal), n, 1.0, {})
        warm[name] = curve
        warm_first[name] = first_invested(cal, prices, univ)

    rows = {}
    for era_name, lo, hi in eras:
        cold_cal = [d for d in cal if lo is None or d >= lo]
        cpx, cax = build(cold_cal)
        ccash = base.load_cash_series(cold_cal)
        cold, cold_first = {}, {}
        for name, univ, n in books:
            curve, _aux, _hold = e27.simulate(cold_cal, cpx, cax, univ, ccash, n, 1.0, {})
            cold[name] = [pt for pt in curve if hi is None or pt[0] <= hi]
            cold_first[name] = first_invested(cold_cal, cpx, univ)
        warm_slice = {name: [pt for pt in warm[name]
                             if (lo is None or pt[0] >= lo) and (hi is None or pt[0] <= hi)]
                      for name, _u, _n in books}
        wl = _curve_faces(warm_slice["ladder5"])
        ww = _curve_faces(warm_slice[wide_name])
        cl = _curve_faces(cold["ladder5"])
        cw = _curve_faces(cold[wide_name])
        bars = max(len(warm_slice["ladder5"]), 1)
        warm_dead = _bars_before(warm_slice["ladder5"], warm_first["ladder5"])
        cold_dead = _bars_before(cold["ladder5"], cold_first["ladder5"])
        rows[era_name] = {
            "from": (wl or cl or {}).get("from"), "to": (wl or cl or {}).get("to"),
            "bars": bars,
            "warm": {"ladder": wl, "wide": ww, "spread_bp": _spread_bp(wl, ww),
                     "first_invested_bar": warm_first["ladder5"],
                     "dead_block_bars": warm_dead,
                     "dead_block_share_pct": round(warm_dead / max(1, bars - 1) * 100, 2)},
            "cold": {"ladder": cl, "wide": cw, "spread_bp": _spread_bp(cl, cw),
                     "first_invested_bar": cold_first["ladder5"],
                     "dead_block_bars": cold_dead,
                     "dead_block_share_pct": round(cold_dead / max(1, bars - 1) * 100, 2),
                     "cash_accrued_in_dead_block_pct": _cash_accrual_pct(
                         ccash, cold_cal, cold_first["ladder5"])},
        }
        if rows[era_name]["warm"]["spread_bp"] is not None \
                and rows[era_name]["cold"]["spread_bp"] is not None:
            rows[era_name]["warm_minus_cold_bp"] = round(
                rows[era_name]["warm"]["spread_bp"] - rows[era_name]["cold"]["spread_bp"], 1)

    # the cold newest-era number is the same market as a warm forward slice: from the
    # first allowed decision onward both books hold identical weights, so a warm slice
    # started at that bar must reproduce the cold reading -- if it does, the gap is the
    # skipped bars and nothing else.
    newest = eras[-1][0] if eras else None
    live_from = (rows.get(newest) or {}).get("cold", {}).get("first_invested_bar")
    live = {}
    if live_from:
        ls = [pt for pt in warm["ladder5"] if pt[0] >= live_from]
        ws = [pt for pt in warm[wide_name] if pt[0] >= live_from]
        lf, wf = _curve_faces(ls), _curve_faces(ws)
        live = {"from": live_from, "to": (lf or {}).get("to"), "bars": len(ls),
                "ladder": lf, "wide": wf, "spread_bp": _spread_bp(lf, wf)}
        if newest and "warm_live_window" not in rows[newest]:
            rows[newest]["warm_live_window"] = live

    warm_order = [(k, v["warm"]["spread_bp"]) for k, v in rows.items()
                  if v["warm"]["spread_bp"] is not None]
    cold_order = [(k, v["cold"]["spread_bp"]) for k, v in rows.items()
                  if v["cold"]["spread_bp"] is not None]
    warm_sorted = sorted(warm_order, key=lambda kv: kv[1])
    cold_sorted = sorted(cold_order, key=lambda kv: kv[1])
    return {
        "study": "e45_warm_spread",
        "evidence_cutoff": cutoff,
        "spec": {"pick_n": pick_n, "exclude_prefixes": list(exclude),
                 "cost_mult": 1.0, "cost_bp_per_side": base.COST_BP_SIDE,
                 "calendar_from": cal[0], "min_bars": base.MIN_BARS,
                 "warm": "one pair of curves on the full calendar, sliced per era",
                 "cold": "a fresh pair started at the era's own first bar, "
                         "measured over the same era span",
                 "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
                 "universe_members": len(universe)},
        "eras": rows,
        "answers": {
            "warm_order_thinnest_to_widest": warm_sorted,
            "cold_order_thinnest_to_widest": cold_sorted,
            "newest_era_is_thinnest_warm": bool(warm_sorted) and warm_sorted[0][0] == "2024_now",
            "newest_era_is_thinnest_cold": bool(cold_sorted) and cold_sorted[0][0] == "2024_now",
            "ordering_preserved": [k for k, _v in warm_sorted] == [k for k, _v in cold_sorted],
            "newest_era_live_window": live,
            "cold_minus_live_bp": (
                round(rows[newest]["cold"]["spread_bp"] - live["spread_bp"], 1)
                if newest and live.get("spread_bp") is not None
                and rows[newest]["cold"]["spread_bp"] is not None else None),
            "max_warm_minus_cold_bp": max(
                (abs(v["warm_minus_cold_bp"]) for v in rows.values()
                 if "warm_minus_cold_bp" in v), default=None),
            "cold_dead_block_share_pct_by_era": {
                k: v["cold"]["dead_block_share_pct"] for k, v in rows.items()},
            "cold_cash_accrued_in_dead_block_pct_by_era": {
                k: v["cold"]["cash_accrued_in_dead_block_pct"] for k, v in rows.items()},
        },
        "honest": [
            "the warm slice pays the burn-in on bars before the measured span, so it prices the "
            "spec; the cold window is the same spec started at the era's own first bar, and the "
            "gap is the gate plus whatever the dead block accrued at the repo rate",
            "the pre2017 era starts where the panel starts, so its warm and cold quotes are the "
            "same curve by construction -- that is a disclosure, not a measurement",
            "the dead block is identified by the first decision the 250-bar rule allows, not by "
            "inspecting weights; no rebalance before it can hold a name",
            "the ratio of two rebased ann% is not a tradable sleeve, and era slices are not "
            "additive across eras",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }


def _warmspread_arm_cells(face, starts=None):
    """(E122) -> {(key, column): value} for every cell the warm-spread leg publishes.

    E45 publishes a PAIR per era -- the warm (full-calendar, sliced) spread and the
    cold (era-restarted) spread -- plus their difference. A repair that changes
    which name the wide book holds on a monthly decision can move one side of that
    pair and not the other, so all three are harvested per era. The width book is
    the only book a print repair can reach: the five-name ladder is a fixed list,
    so a moved ``ladder`` cell means something other than a repair effect.
    """
    out = {}
    for era, row in (face.get("eras") or {}).items():
        row = row or {}
        key = "era/" + era
        out[(key, "bars")] = row.get("bars")
        for arm in ("warm", "cold"):
            a = row.get(arm) or {}
            out[(key + "/" + arm, "spread_bp")] = a.get("spread_bp")
            out[(key + "/" + arm, "dead_block_bars")] = a.get("dead_block_bars")
            out[(key + "/" + arm, "dead_block_share_pct")] = (
                a.get("dead_block_share_pct"))
            for leg in ("ladder", "wide"):
                f = a.get(leg) or {}
                out[(key + "/" + arm + "/" + leg, "ann_return_pct")] = (
                    f.get("ann_return_pct"))
                out[(key + "/" + arm + "/" + leg, "max_drawdown_pct")] = (
                    f.get("max_drawdown_pct"))
        out[(key, "warm_minus_cold_bp")] = row.get("warm_minus_cold_bp")
        live = row.get("warm_live_window") or {}
        out[(key, "warm_live_spread_bp")] = live.get("spread_bp")
    ans = face.get("answers") or {}
    for col in ("cold_minus_live_bp", "max_warm_minus_cold_bp"):
        out[("answers", col)] = ans.get(col)
    out[("spec", "universe_members")] = (face.get("spec") or {}).get("universe_members")
    return out


def _warmspread_ordering(face):
    """(E122) the published claim of E45: two orders and their booleans."""
    ans = face.get("answers") or {}
    warm = list(ans.get("warm_order_thinnest_to_widest") or [])
    cold = list(ans.get("cold_order_thinnest_to_widest") or [])
    return {
        "warm_order": [k for k, _v in warm],
        "cold_order": [k for k, _v in cold],
        "newest_era_is_thinnest_warm": bool(ans.get("newest_era_is_thinnest_warm")),
        "newest_era_is_thinnest_cold": bool(ans.get("newest_era_is_thinnest_cold")),
        "ordering_preserved": bool(ans.get("ordering_preserved")),
        "spreads_warm": {k: v for k, v in warm},
        "spreads_cold": {k: v for k, v in cold},
    }


def _warmspread_arm_dates(face, starts=None):
    """(E122) the ordering claims travel as strings/booleans, not as numbers.

    An ordering can flip while every spread in it moves by less than a basis
    point, so the join needs a second layer that reports the claim itself. Without
    it a twin could publish "0 cells moved" while the leg's headline answer became
    the opposite one.
    """
    o = _warmspread_ordering(face)
    return {"ordering": {
        "warm_order": ">".join(o["warm_order"]),
        "cold_order": ">".join(o["cold_order"]),
        "newest_era_is_thinnest_warm": o["newest_era_is_thinnest_warm"],
        "newest_era_is_thinnest_cold": o["newest_era_is_thinnest_cold"],
        "ordering_preserved": o["ordering_preserved"],
    }}


def run_warmspreadscreened(outdir, eras=ERAS, pick_n=9999, exclude=("sh511",),
                           mode="neutralise_int", resume=True):
    """E122: re-derive the WARM-SPREAD ordering on the screened arm, beside the raw.

    E97 row 8 after the burnin/cutcurve/livespan/chase/early/split/stale/entrydelay
    twins. E45's published reading is an ORDERING of eras by warm spread plus a
    warm-vs-cold difference per era -- not a set of cells -- so the twin publishes
    the two orders on each arm beside the moved-cell count. A repair that changes
    which name the wide book holds on one monthly decision can flip the order of
    two adjacent eras while moving every spread by under a basis point, and a
    delta-only reading would call that "nothing happened".

    Same machinery as E112-E119 otherwise: one load, both arms burned off it,
    per-arm checkpoints, the shared ``_burnin_pair_rows`` join, a same-arm control
    that must read zero, and a cutoff control against the newest previously
    published raw face.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]
    tag = cutoff.replace("-", "")

    def cached(label, thunk):
        p = os.path.join(outdir or ".", "WARMSPREAD-arm-%s-%s.json" % (label, tag))
        if resume and os.path.isfile(p):
            try:
                with open(p, "r", encoding="utf-8") as fh:
                    return json.load(fh)
            except Exception:
                pass
        face = thunk()
        if outdir:
            write_json(outdir, "WARMSPREAD-arm-%s-%s.json" % (label, tag), face)
        return face

    screened, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)

    kw = dict(eras=eras, pick_n=pick_n, exclude=exclude)
    raw_arm = cached("raw", lambda: run_warmspread(None, raw=raw, **kw))
    scr_arm = cached(mode, lambda: run_warmspread(None, raw=screened, **kw))

    keys = sorted({k[0] for k in _warmspread_arm_cells(raw_arm)})
    pair = _burnin_pair_rows(raw_arm, scr_arm, keys,
                             cells_fn=_warmspread_arm_cells,
                             dates_fn=_warmspread_arm_dates)
    control = _burnin_pair_rows(raw_arm, raw_arm, keys,
                                cells_fn=_warmspread_arm_cells,
                                dates_fn=_warmspread_arm_dates)["summary"]

    # cutoff control: newest previously published raw face vs today's raw arm --
    # same arm, two cutoffs, so it isolates the panel refresh. This leg's own raw
    # face is published by the e45 CLI into results/e45_warm_spread, so the search
    # must start there: looking only in the twin's own directory would return
    # null, and null reads as "no older face exists" (E159 pit).
    cutoff_control = None
    search_dirs = [d for d in (os.path.join(ROOT, "results", "e45_warm_spread"),
                               outdir,
                               os.path.join(ROOT, "results", "e44_midmonth"))
                   if d and os.path.isdir(d)]
    olds = []
    for d in search_dirs:
        olds.extend(os.path.join(d, p) for p in os.listdir(d)
                    if p.startswith("WARMSPREAD-") and p.endswith(".json")
                    and not p.startswith("WARMSPREADSCREEN-")
                    and not p.startswith("WARMSPREAD-arm-"))
    for path in sorted(olds, key=os.path.basename, reverse=True):
        p = os.path.basename(path)
        if p[len("WARMSPREAD-"):-len(".json")] == tag:
            continue
        try:
            with open(path, "r", encoding="utf-8") as fh:
                old_face = json.load(fh)
        except Exception:
            continue
        old_keys = sorted({k[0] for k in _warmspread_arm_cells(old_face)})
        old_pair = _burnin_pair_rows(old_face, raw_arm, old_keys,
                                     cells_fn=_warmspread_arm_cells,
                                     dates_fn=_warmspread_arm_dates)
        cutoff_control = {
            "old_face": p,
            "old_cutoff": old_face.get("evidence_cutoff"),
            "comparison": "old raw arm vs today raw arm (arm held fixed)",
            "summary": old_pair["summary"],
            "moved": old_pair["moved"],
        }
        break

    s = pair["summary"]
    survives = _twin_survives(s, control)
    orders = {"raw": _warmspread_ordering(raw_arm),
              "screened": _warmspread_ordering(scr_arm)}
    order_survives = (orders["raw"]["warm_order"] == orders["screened"]["warm_order"]
                      and orders["raw"]["cold_order"] == orders["screened"]["cold_order"])
    # the ladder book is a fixed five-name list: a moved ladder cell cannot be a
    # repair effect and must be named separately from a moved wide book. Keys end
    # WITH the leg name (".../warm/wide"), so the test must be endswith: an
    # "/wide/" test matches nothing and silently reports zero wide moves while
    # the OTHER bucket absorbs them (E94 family, third recurrence).
    wide_moved = [r for r in pair["moved"] if r["start"].endswith("/wide")]
    ladder_moved = [r for r in pair["moved"] if r["start"].endswith("/ladder")]
    spread_moved = [r for r in pair["moved"] if r["column"] == "spread_bp"]
    other_moved = [r for r in pair["moved"]
                   if r not in wide_moved and r not in ladder_moved
                   and r not in spread_moved]
    return {
        "study": "e122_warmspread_screened_twin",
        "evidence_cutoff": cutoff,
        "spec": {
            "pick_n": pick_n, "exclude_prefixes": list(exclude),
            "screen_mode": mode,
            "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
            "arms": {"raw": "e27.load_universe() as shipped",
                     "screened": "panel_screen.screen_universe(mode=%s)" % mode},
            "seam": ("run_warmspread grew a raw= parameter this round: before it "
                     "loaded the universe itself, so a twin could not burn both "
                     "arms off one load"),
            "join": ("_warmspread_arm_cells harvests per-era warm/cold spreads, "
                     "dead-block bars, both curve faces and the answers scalars; "
                     "_warmspread_arm_dates harvests the ORDERS themselves, because "
                     "an ordering can flip without any spread moving past the "
                     "delta floor"),
        },
        "screen_report": report,
        "orders": orders,
        "pair": pair,
        "control": control,
        "cutoff_control": cutoff_control,
        "answers": {
            "counts_survive_the_repair": bool(survives),
            "ordering_survives_the_repair": bool(order_survives),
            "cells_compared": s["cells_compared"],
            "cells_moved": s["cells_moved"],
            "max_abs_delta": s["max_abs_delta_pp"],
            "delta_units": ("each delta is in the units of its column: bp for "
                            "spreads, percent per year for ann_return_pct, bars for "
                            "dead_block_bars -- the summary max is a max over mixed "
                            "units and is a screen, not a quantity"),
            "worst_cell": s["worst"],
            "wide_cells_moved": len(wide_moved),
            "ladder_cells_moved": len(ladder_moved),
            "spread_cells_moved": len(spread_moved),
            "other_cells_moved": len(other_moved),
            "ordering_cells_moved": len(pair["gate_dates_moved"]),
            "moved_attribution_complete": (
                len(wide_moved) + len(ladder_moved) + len(spread_moved)
                + len(other_moved) == s["cells_moved"]),
            "control_cells_moved": control["cells_moved"],
            "control_ordering_moved": control["gate_dates_moved"],
            "cutoff_control": ({"old_face": cutoff_control["old_face"],
                                "cells_moved":
                                    cutoff_control["summary"]["cells_moved"],
                                "max_abs_delta":
                                    cutoff_control["summary"]["max_abs_delta_pp"]}
                               if cutoff_control else None),
            "reading": (
                ("the warm-spread ordering survives the repair: %d of %d cells "
                 "move (%d wide / %d spread / %d ladder) and both orders are "
                 "unchanged" %
                 (s["cells_moved"], s["cells_compared"], len(wide_moved),
                  len(spread_moved), len(ladder_moved)))
                if (survives and order_survives) else
                ("the repair reaches the warm-spread face: %d of %d cells move "
                 "(%d wide, %d spread, %d ladder, %d other), %d ordering claim(s) "
                 "move, and %d cell(s) exist on one arm only" %
                 (s["cells_moved"], s["cells_compared"], len(wide_moved),
                  len(spread_moved), len(ladder_moved), len(other_moved),
                  len(pair["gate_dates_moved"]),
                  s["only_in_raw"] + s["only_in_screened"]))),
        },
        "honest": [
            "descriptive census only: no gate, no verdict on the strategy, no "
            "prereg, no trial count, no ledger booking",
            "the screened arm repairs prints inside the panel it is handed; it does "
            "not add or remove bars, so an unchanged universe_members count is a "
            "property of the repair, not evidence the panel is clean",
            "the warm curve pays the burn-in before the measured span by "
            "construction, so a spread move on the warm arm can be a slightly "
            "different weight path rather than a different decision",
            "the five-name ladder is a constant list: a moved ladder cell names a "
            "defect in the join or the cache, not a repair effect",
            "orderings are read off the published face verbatim; a tie in spread "
            "would make the order arbitrary and is disclosed by the raw spread map "
            "rather than smoothed away",
        ],
    }


_PAIR_PROFILE_SCALARS = ("years", "ann_return_pct", "max_drawdown_pct",
                         "longest_underwater_sessions", "months",
                         "negative_months", "monthly_win_rate_pct")


def _pair_sign(v):
    """(E123) -1/0/1, or None when the cell is absent: a missing answer is not zero."""
    if v is None:
        return None
    return (v > 0) - (v < 0)


def _pair_arm_cells(face, starts=None):
    """(E123) -> {(key, column): value} for every cell the pair leg publishes.

    E40 publishes three PROFILES per window -- the five-name ladder, the wide
    book and the ratio of their curves -- plus the scalar answers derived from
    them. Only the wide book can be reached by a print repair, so the buckets
    have to be separable: a moved ``ladder5`` cell names a defect in the join or
    the cache, a moved ``spread_ratio`` cell is derived, and the compare-to-order
    claims (worst month identity) live in the dates layer because they are
    booleans and a delta over a boolean is meaningless.
    """
    out = {}
    for start, win in (face.get("windows") or {}).items():
        key = "win/" + str(start)
        out[(key, "bars")] = (win or {}).get("bars")
        for name, prof in ((win or {}).get("profiles") or {}).items():
            p = prof or {}
            k = key + "/" + name
            for col in _PAIR_PROFILE_SCALARS:
                out[(k, col)] = p.get(col)
            out[(k, "worst_month_return_pct")] = (p.get("worst_month") or {}).get("return_pct")
            out[(k, "best_month_return_pct")] = (p.get("best_month") or {}).get("return_pct")
            em = p.get("engine_metrics") or {}
            out[(k, "engine_ann_vol_pct")] = em.get("ann_vol_pct")
            out[(k, "engine_sharpe")] = em.get("sharpe")
        ans = (win or {}).get("answers") or {}
        for col in ("ann_spread_pct", "maxdd_delta_pct",
                    "underwater_delta_sessions", "spread_maxdd_pct",
                    "spread_longest_underwater_sessions"):
            out[(key + "/answers", col)] = ans.get(col)
    out[("spec", "pick_n")] = (face.get("spec") or {}).get("pick_n")
    return out


def _pair_arm_dates(face, starts=None):
    """(E123) the pair leg's claim layer: month identities and booleans.

    E40's answers include ``worst_month_same_month`` -- "both books lost their
    worst month in the same month" -- which is a claim, not a quantity. A twin
    that only diffs numbers would report that claim as unchanged even when it
    flipped, so the same layer that carries gate dates carries these.
    """
    out = {}
    for start, win in (face.get("windows") or {}).items():
        win = win or {}
        cols = {"worst_month_same_month": (win.get("answers") or {}).get(
            "worst_month_same_month")}
        for name, prof in (win.get("profiles") or {}).items():
            prof = prof or {}
            for which in ("worst_month", "best_month"):
                cols["%s_%s" % (name, which)] = (prof.get(which) or {}).get("month")
        out["win/" + str(start)] = cols
    return out


_PAIR_ARROW_COLUMNS = ("ann_spread_sign", "maxdd_delta_sign",
                       "underwater_delta_sign", "worst_month_same_month")


def _pair_arrows(face):
    """(E123) the published ARROWS per window: signs plus the month identity.

    A spread that is +40bp on both arms is the same reading as +20bp on both; a
    spread that changes sign is not, however small the cell delta. The first cut
    of this leg listed only the spread and drawdown signs and missed the
    underwater-delta sign flipping (+48 -> -92 sessions on a 0.4pp cell move) --
    the arrow list must cover every answer that is read as a direction, or the
    twin reports "arrows hold" while the face says the opposite (E94 family).
    """
    out = {}
    for start, win in (face.get("windows") or {}).items():
        ans = (win or {}).get("answers") or {}
        out[str(start)] = {
            "ann_spread_sign": _pair_sign(ans.get("ann_spread_pct")),
            "maxdd_delta_sign": _pair_sign(ans.get("maxdd_delta_pct")),
            "underwater_delta_sign": _pair_sign(
                ans.get("underwater_delta_sessions")),
            "worst_month_same_month": ans.get("worst_month_same_month"),
        }
    return out


def run_pairscreened(outdir, starts=("2020-01-01", "2018-01-01"), pick_n=9999,
                     exclude=("sh511",), mode="neutralise_int", resume=True):
    """E123: re-derive the E40 ladder-vs-wide drawdown face on the screened arm.

    E97 row 9 after the burnin/cutcurve/livespan/chase/early/split/stale/entrydelay/
    warmspread twins. E40 publishes drawdown SHAPE -- max drawdown, longest
    underwater run, worst month and the ratio curve's own drawdown -- so a twin
    must publish whether each window's ARROWS survive, not only whether cells
    moved: a repair that reorders two adjacent drawdowns by 3bp changes the
    reading while every level stays inside a plausible band.

    Same machinery as E112-E122: one load, both arms burned off it, per-arm
    checkpoints, the shared ``_burnin_pair_rows`` join, a same-arm control that
    must read zero, and a cutoff control against the newest published raw face.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]
    tag = cutoff.replace("-", "")

    def cached(label, thunk):
        p = os.path.join(outdir or ".", "PAIR-arm-%s-%s.json" % (label, tag))
        if resume and os.path.isfile(p):
            try:
                with open(p, "r", encoding="utf-8") as fh:
                    return json.load(fh)
            except Exception:
                pass
        face = thunk()
        if outdir:
            write_json(outdir, "PAIR-arm-%s-%s.json" % (label, tag), face)
        return face

    screened, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)

    kw = dict(starts=starts, pick_n=pick_n, exclude=exclude)
    raw_arm = cached("raw", lambda: run_pair(None, raw=raw, **kw))
    scr_arm = cached(mode, lambda: run_pair(None, raw=screened, **kw))

    keys = sorted({k[0] for k in _pair_arm_cells(raw_arm)})
    pair = _burnin_pair_rows(raw_arm, scr_arm, keys,
                             cells_fn=_pair_arm_cells,
                             dates_fn=_pair_arm_dates)
    control = _burnin_pair_rows(raw_arm, raw_arm, keys,
                                cells_fn=_pair_arm_cells,
                                dates_fn=_pair_arm_dates)["summary"]

    # cutoff control: newest previously published raw face vs today's raw arm,
    # arm held fixed. E40's own raw face is published by the pair CLI into
    # results/e40_pair_drawdown, so the search starts there (E159 pit: a twin
    # that looks only in its own directory returns null, and null reads as
    # "no older face exists").
    cutoff_control = None
    search_dirs = [d for d in (os.path.join(ROOT, "results", "e40_pair_drawdown"),
                               outdir) if d and os.path.isdir(d)]
    olds = []
    for d in search_dirs:
        olds.extend(os.path.join(d, p) for p in os.listdir(d)
                    if p.startswith("PAIR-") and p.endswith(".json")
                    and not p.startswith("PAIRSCREEN-")
                    and not p.startswith("PAIR-arm-"))
    for path in sorted(olds, key=os.path.basename, reverse=True):
        p = os.path.basename(path)
        if p[len("PAIR-"):-len(".json")] == tag:
            continue
        try:
            with open(path, "r", encoding="utf-8") as fh:
                old_face = json.load(fh)
        except Exception:
            continue
        old_keys = sorted({k[0] for k in _pair_arm_cells(old_face)})
        old_pair = _burnin_pair_rows(old_face, raw_arm, old_keys,
                                     cells_fn=_pair_arm_cells,
                                     dates_fn=_pair_arm_dates)
        cutoff_control = {
            "old_face": p,
            "old_cutoff": old_face.get("evidence_cutoff"),
            "comparison": "old raw arm vs today raw arm (arm held fixed)",
            "summary": old_pair["summary"],
            "moved": old_pair["moved"],
        }
        break

    s = pair["summary"]
    survives = _twin_survives(s, control)
    wide_name = "wide_top%d" % pick_n

    # arrows: per window, the sign of every answer that is read as a direction.
    # A spread that is +40bp on both arms and +20bp on both arms is the same
    # reading; one that flips is not, however small the cell delta.
    arr_raw, arr_scr = _pair_arrows(raw_arm), _pair_arrows(scr_arm)
    arrow_moved = [{"start": k, "column": c, "raw": arr_raw[k][c],
                    "screened": (arr_scr.get(k) or {}).get(c)}
                   for k in sorted(arr_raw)
                   for c in _PAIR_ARROW_COLUMNS
                   if arr_scr.get(k, {}).get(c) != arr_raw[k][c]]
    survives_arrows = not arrow_moved

    # attribution: keys end WITH the leg name (".../wide_top9999"), so the test
    # must be a suffix test on the dynamic wide name. An infixed test matches
    # nothing and the "other" bucket absorbs the moves silently (E94 family).
    wide_moved = [r for r in pair["moved"] if r["start"].endswith("/" + wide_name)]
    ladder_moved = [r for r in pair["moved"] if r["start"].endswith("/ladder5")]
    ratio_moved = [r for r in pair["moved"] if r["start"].endswith("/spread_ratio")]
    answer_moved = [r for r in pair["moved"] if r["start"].endswith("/answers")]
    other_moved = [r for r in pair["moved"]
                   if r not in wide_moved and r not in ladder_moved
                   and r not in ratio_moved and r not in answer_moved]
    return {
        "study": "e123_pair_screened_twin",
        "evidence_cutoff": cutoff,
        "spec": {
            "pick_n": pick_n, "exclude_prefixes": list(exclude),
            "screen_mode": mode, "starts": list(starts),
            "wide_name": wide_name,
            "arms": {"raw": "e27.load_universe() as shipped",
                     "screened": "panel_screen.screen_universe(mode=%s)" % mode},
            "seam": ("run_pair grew a raw= parameter this round: before it loaded "
                     "the universe itself, so a twin could not burn both arms off "
                     "one load"),
            "join": ("_pair_arm_cells harvests every scalar in the three profiles "
                     "and the derived answers; _pair_arm_dates harvests the month "
                     "identities and the worst_month_same_month claim, because a "
                     "boolean compared by subtraction is not a measurement"),
        },
        "screen_report": report,
        "arrows": {"raw": arr_raw, "screened": arr_scr},
        "pair": pair,
        "control": control,
        "cutoff_control": cutoff_control,
        "answers": {
            "counts_survive_the_repair": bool(survives),
            "arrows_survive_the_repair": bool(survives_arrows),
            "cells_compared": s["cells_compared"],
            "cells_moved": s["cells_moved"],
            "max_abs_delta": s["max_abs_delta_pp"],
            "delta_units": ("each delta is in the units of its column: percent for "
                            "returns and drawdowns, sessions for underwater runs, "
                            "count for months/negative_months -- the summary max is "
                            "a max over mixed units and is a screen, not a quantity"),
            "worst_cell": s["worst"],
            "wide_cells_moved": len(wide_moved),
            "ladder_cells_moved": len(ladder_moved),
            "spread_ratio_cells_moved": len(ratio_moved),
            "answer_cells_moved": len(answer_moved),
            "other_cells_moved": len(other_moved),
            "arrow_claims_moved": len(arrow_moved),
            "moved_attribution_complete": (
                len(wide_moved) + len(ladder_moved) + len(ratio_moved)
                + len(answer_moved) + len(other_moved) == s["cells_moved"]),
            "control_cells_moved": control["cells_moved"],
            "control_ordering_moved": control["gate_dates_moved"],
            "cutoff_control": ({"old_face": cutoff_control["old_face"],
                                "cells_moved":
                                    cutoff_control["summary"]["cells_moved"],
                                "max_abs_delta":
                                    cutoff_control["summary"]["max_abs_delta_pp"]}
                               if cutoff_control else None),
            "reading": (
                ("the drawdown face survives the repair: %d of %d cells move "
                 "(%d wide / %d ratio / %d answer / %d ladder), every window's "
                 "arrows hold and the worst-month identity is unchanged" %
                 (s["cells_moved"], s["cells_compared"], len(wide_moved),
                  len(ratio_moved), len(answer_moved), len(ladder_moved)))
                if (survives and survives_arrows) else
                ("the repair reaches the drawdown face: %d of %d cells move "
                 "(%d wide, %d ratio, %d answer, %d ladder, %d other) and %d of "
                 "%d arrow claims move; %d cell(s) exist on one arm only" %
                 (s["cells_moved"], s["cells_compared"], len(wide_moved),
                  len(ratio_moved), len(answer_moved), len(ladder_moved),
                  len(other_moved), len(arrow_moved), len(arr_raw) * 4,
                  s["only_in_raw"] + s["only_in_screened"]))),
        },
        "honest": [
            "descriptive census only: no gate, no verdict on the strategy, no "
            "prereg, no trial count, no ledger booking",
            "the screened arm repairs prints inside the panel it is handed; it does "
            "not add or remove bars, so an unchanged ``bars`` cell is a property of "
            "the repair, not evidence the panel is clean",
            "the five-name ladder is a constant list: a moved ladder cell names a "
            "defect in the join or the cache, not a repair effect",
            "spread_ratio is a ratio of equity curves, not a tradable sleeve, so a "
            "move there is derived from the two books rather than independent",
            "worst_month_same_month is a claim about two curves landing in the same "
            "month; it is carried in the dates layer because a boolean has no delta",
        ],
    }


# ------------------- leg: E124 four-member tilt, screened twin
#
# E97 left run_tilt4 uncovered: 91 numbers across e43/tilt4/widecomp. This face
# is a PER-ERA attribution, not a total -- each era carries its own four-member
# tilt (2 broad vs 510500/512100), and the spread is decomposed into a
# size-neutral alpha plus a size beta*tilt. A repair that moves one era's
# neutral component while the others hold says the panel work sits in one
# sleeve; every era moving together says something else. So the twin must
# publish the per-era split, and the decomposition has to sum or the attribution
# is silent.

_TILT4_ERA_SCALARS = (
    "months", "tilt_annualised_bp", "tilt_sd_bp", "tilt_positive_share_pct",
    "beta_ladder_on_tilt", "alpha_monthly_bp", "r_squared",
    "tilt_explains_ladder_var_pct", "ladder_mean_month_pct",
    "spread_raw_ann_bp", "spread_size_neutral_ann_bp",
    "spread_size_component_ann_bp", "beta_spread_on_tilt", "r_squared_spread",
    "engine_ann_diff_bp", "arithmetic_vs_geometric_gap_bp",
)
_TILT4_COMPARE_SCALARS = ("months_5member", "tilt_5member_ann_bp",
                          "tilt_4member_ann_bp_same_months")
_TILT4_ANSWER_SCALARS = ("eras_measured_4member", "eras_measured_5member",
                         "eras_positive_tilt", "eras_positive_size_neutral",
                         "size_neutral_range_bp")


def _tilt4_decomposition_gap(row):
    """(E124) raw spread minus (size-neutral + size component), or None.

    E43 publishes the decomposition as three numbers that are supposed to add
    up. If they stop adding up, the per-era attribution stops meaning anything
    -- so the gap is published per era instead of being trusted.
    """
    raw_ = (row or {}).get("spread_raw_ann_bp")
    neu = (row or {}).get("spread_size_neutral_ann_bp")
    siz = (row or {}).get("spread_size_component_ann_bp")
    if raw_ is None or neu is None or siz is None:
        return None
    return round(raw_ - (neu + siz), 3)


def _tilt4_arm_cells(face, keys=None):
    """(E124) -> {(key, column): value} for every cell the tilt4 leg publishes.

    Three buckets, because they fail differently: ``era/`` cells are the per-era
    tilt and its decomposition (what the reader consumes as the attribution),
    ``skin/`` cells price the STAR-leg difference on shared months (a skin
    effect, not a repair effect), and ``answers`` are aggregates over eras. A
    moved ``skin/`` cell beside an untouched ``era/`` set says the repair reached
    a leg the attribution does not use.
    """
    out = {}
    for era, row in (face.get("eras") or {}).items():
        row = row or {}
        for col in _TILT4_ERA_SCALARS:
            out[("era/" + era, col)] = row.get(col)
        out[("era/" + era, "best_month_spread_pct")] = (
            (row.get("tilt_best_month") or {}).get("spread_pct"))
        out[("era/" + era, "worst_month_spread_pct")] = (
            (row.get("tilt_worst_month") or {}).get("spread_pct"))
        out[("era/" + era, "decomposition_gap_bp")] = _tilt4_decomposition_gap(row)
    for era, row in (face.get("skin_comparison") or {}).items():
        for col in _TILT4_COMPARE_SCALARS:
            out[("skin/" + era, col)] = (row or {}).get(col)
    for col in _TILT4_ANSWER_SCALARS:
        out[("answers", col)] = (face.get("answers") or {}).get(col)
    return out


def _tilt4_arm_dates(face, keys=None):
    """(E124) the claim layer: era boundaries, month identities, skin notes.

    An era's ``from``/``to`` is a claim about which months it covers, and the
    best/worst month is an identity -- neither has a delta, so they ride in the
    dates layer (a repair that silently shortens an era is otherwise invisible).
    """
    out = {}
    for era, row in (face.get("eras") or {}).items():
        row = row or {}
        out["era/" + era] = {
            "from": row.get("from"), "to": row.get("to"),
            "best_month": (row.get("tilt_best_month") or {}).get("month"),
            "worst_month": (row.get("tilt_worst_month") or {}).get("month"),
        }
    for era, row in (face.get("skin_comparison") or {}).items():
        out.setdefault("skin/" + era, {})["note"] = (row or {}).get("note")
    return out


_TILT4_ARROW_COLUMNS = ("tilt_sign", "spread_raw_sign",
                        "spread_size_neutral_sign", "beta_ladder_sign")


def _tilt4_arrows(face):
    """(E124) the published ARROWS per era: the signs a reader consumes.

    The tilt's sign is the headline ("small caps led or lagged"); the raw spread
    sign says which book won the era; the size-neutral sign says whether the win
    survives removing the size tilt; the beta sign says which way the ladder
    leans on the tilt. A component can change sign while the era's tilt does
    not, so all four are carried -- a list narrower than the reading is the E94
    family this repo keeps re-learning.
    """
    out = {}
    for era, row in (face.get("eras") or {}).items():
        row = row or {}
        out[str(era)] = {
            "tilt_sign": _pair_sign(row.get("tilt_annualised_bp")),
            "spread_raw_sign": _pair_sign(row.get("spread_raw_ann_bp")),
            "spread_size_neutral_sign": _pair_sign(
                row.get("spread_size_neutral_ann_bp")),
            "beta_ladder_sign": _pair_sign(row.get("beta_ladder_on_tilt")),
        }
    return out


_TILT3_COMPARE_SCALARS = (
    "months_3member", "months_4member_shared", "months_5member_shared",
    "tilt_3member_ann_bp", "tilt_4member_ann_bp_shared_months",
    "tilt_5member_ann_bp_shared_months",
    "delta_4member_minus_3member_bp", "delta_5member_minus_3member_bp",
)
_TILT3_ANSWER_SCALARS = (
    "eras_measured_3member", "pre2017_months_3member",
    "pre2017_tilt_3member_ann_bp", "eras_positive_tilt",
    "eras_positive_size_neutral", "size_neutral_range_bp",
    "skin_cells_compared", "skin_deltas_published",
)


def _tilt3_arm_cells(face, keys=None):
    """(E126) -> {(key, column): value} for every cell the tilt3 leg publishes.

    Same three-bucket shape as ``_tilt4_arm_cells`` so the family's join can be
    reused. The ``skin/`` bucket names BOTH arms inside the column name
    (``delta_4member_minus_3member_bp``): a delta keyed only by "the compared
    column" silently overwrites the first arm when a second arm is added
    (r1280 family), and this face carries two such deltas.
    """
    out = {}
    for era, row in (face.get("eras") or {}).items():
        row = row or {}
        for col in _TILT4_ERA_SCALARS:
            out[("era/" + era, col)] = row.get(col)
        out[("era/" + era, "best_month_spread_pct")] = (
            (row.get("tilt_best_month") or {}).get("spread_pct"))
        out[("era/" + era, "worst_month_spread_pct")] = (
            (row.get("tilt_worst_month") or {}).get("spread_pct"))
        out[("era/" + era, "decomposition_gap_bp")] = _tilt4_decomposition_gap(row)
    for era, row in (face.get("skin_comparison") or {}).items():
        for col in _TILT3_COMPARE_SCALARS:
            out[("skin/" + era, col)] = (row or {}).get(col)
    for col in _TILT3_ANSWER_SCALARS:
        out[("answers", col)] = (face.get("answers") or {}).get(col)
    return out


def _tilt3_arm_dates(face, keys=None):
    """(E126) the claim layer: era boundaries, month identities, skin notes.

    A delta set to null because the two skins cover different month counts is a
    claim, not a missing number -- the reason string rides here so a reader can
    tell "not measured" from "measured and equal".
    """
    out = {}
    for era, row in (face.get("eras") or {}).items():
        row = row or {}
        out["era/" + era] = {
            "from": row.get("from"), "to": row.get("to"),
            "best_month": (row.get("tilt_best_month") or {}).get("month"),
            "worst_month": (row.get("tilt_worst_month") or {}).get("month"),
        }
    for era, row in (face.get("skin_comparison") or {}).items():
        row = row or {}
        out.setdefault("skin/" + era, {})["note"] = row.get("note")
        out["skin/" + era]["delta_4member_reason"] = row.get(
            "delta_4member_minus_3member_reason")
        out["skin/" + era]["delta_5member_reason"] = row.get(
            "delta_5member_minus_3member_reason")
    return out


# ---------------------- leg: E169 does the engine earn the tilt's sign
#
# E126 measured the REGRESSOR: the three-member tilt reads +1186bp pre-2017,
# -924bp 2017-2020, +610bp 2021-2023. What no face in this family asks is
# whether the engine's own wide-vs-ladder spread earns the same sign in the same
# months. The tilt is a property of the members; the spread is what a book is
# actually paid. An era-level comparison alone cannot separate a level story
# from a month-by-month one, so both are published with their denominators.
TILT3SIGN_DEADBAND_BP = 10.0    # monthly bp; declared before the burn (E169)
TILT3SIGN_DISAGREE_TOP = 5      # months named per era beside the counts

# E171: the numeric cells of the E169 face, split so a reader can ask WHICH
# column the repair reached (tilt_* is claimed arm-invariant, engine_* is not).
# Booleans and month names are NOT here -- they ride _tilt3sign_arm_dates,
# because a delta on a boolean is not the claim a reader consumes.
TILT3SIGN_ERA_SCALARS = (
    "months", "months_dropped_from_era",
    "tilt_mean_ann_bp", "engine_mean_ann_bp",
    "months_tilt_up", "months_tilt_down", "months_engine_up",
    "months_agree", "months_disagree", "month_agreement_pct",
    "agreement_when_tilt_up_pct", "agreement_when_tilt_down_pct",
    "months_outside_deadband", "month_agreement_outside_deadband_pct",
)
TILT3SIGN_ANSWER_SCALARS = (
    "eras_measured", "eras_where_signs_differ", "eras_where_signs_agree",
    "month_agreement_min_pct", "month_agreement_max_pct",
    "month_agreement_outside_deadband_min_pct",
    "month_agreement_outside_deadband_max_pct",
    "full_window_month_agreement_pct",
)


def _tilt3sign_arm_cells(face, keys=None):
    """(E171) -> {(key, column): value} for every numeric cell E169 publishes."""
    out = {}
    for era, row in (face.get("eras") or {}).items():
        row = row or {}
        for col in TILT3SIGN_ERA_SCALARS:
            out[("era/" + era, col)] = row.get(col)
    for col in TILT3SIGN_ANSWER_SCALARS:
        out[("answers", col)] = (face.get("answers") or {}).get(col)
    return out


def _tilt3sign_arm_dates(face, keys=None):
    """(E171) the claim layer of E169: era boundaries, sign verdicts, names.

    ``signs_agree`` is a verdict a reader consumes, so a flip must be visible
    even when no adjacent number moves; the disagreeing era list is the same
    kind of claim.
    """
    out = {}
    for era, row in (face.get("eras") or {}).items():
        row = row or {}
        out["era/" + era] = {
            "from": row.get("from"), "to": row.get("to"),
            "signs_agree": row.get("signs_agree"),
            "tilt_sign": row.get("tilt_sign"),
            "engine_sign": row.get("engine_sign"),
        }
    out["answers"] = {
        "era_names_where_signs_differ":
            list((face.get("answers") or {}).get("era_names_where_signs_differ")
                 or []),
    }
    return out


def _sign3(x):
    """Sign with an explicit zero (None stays None; a 0.0 is not a claim)."""
    if x is None:
        return None
    if x > 0:
        return 1
    if x < 0:
        return -1
    return 0


def run_tilt3sign(outdir, core=None, eras=ERAS, raw=None, deadband_bp=None):
    """E43-TILT3-SIGN-VS-ENGINE (E169): does the traded spread earn the tilt?

    The family publishes the tilt's sign per era and the engine's own
    wide-vs-ladder difference per era on separate rows, and nothing has ever
    put the two arrows side by side and said whether they point the same way.
    They do not everywhere: 2017_2020 reads -924bp of tilt beside +419bp of
    engine difference, so "the wide book lost that era" is true of the
    regressor and false of the book.

    Two rates, because they answer different questions:

    * ``signs_agree`` -- the era's two LEVELS point the same way (what a reader
      quoting the headline consumes);
    * ``month_agreement_pct`` -- how often the two MONTHLY series share a sign.
      A tilt that agrees at the era level but coin-flips month to month carries
      no month-scale information, and no era table can show that.

    ``deadband_bp`` is declared before the burn: months where either series is
    under it are excluded from the deadband rate, because a sign there is not a
    claim. Both rates are published -- suppressing the raw rate would be
    hiding the deadband's effect rather than naming it.

    ``raw`` mirrors run_tilt3's seam so a screened twin can burn both arms off
    one load without a second panel pass.
    """
    db = TILT3SIGN_DEADBAND_BP if deadband_bp is None else float(deadband_bp)
    core = core if core is not None else _monthly_core(raw_all=raw)
    tilt3 = core.get("tilt3") or {}
    wide_m = core.get("wide_m") or {}
    lad_m = core.get("lad_m") or {}
    rows = {}
    for name, lo, hi in list(eras) + [("full", None, None)]:
        ms = [m for m in core["months3"] if _in_era(m, lo, hi)]
        paired = [m for m in ms
                  if m in tilt3 and m in wide_m and m in lad_m]
        if len(paired) < 3:
            rows[name] = {"months": len(paired),
                          "skipped": "fewer than 3 months priced on both faces"}
            continue
        tilt = [tilt3[m] for m in paired]
        eng = [wide_m[m] - lad_m[m] for m in paired]
        tilt_ann = sum(tilt) / len(tilt) * 12.0 * 1e4
        eng_ann = sum(eng) / len(eng) * 12.0 * 1e4
        agree = [t * e > 0 for t, e in zip(tilt, eng)]
        up = [i for i, t in enumerate(tilt) if t > 0]
        down = [i for i, t in enumerate(tilt) if t < 0]
        outside = [i for i, (t, e) in enumerate(zip(tilt, eng))
                   if abs(t) * 1e4 >= db and abs(e) * 1e4 >= db]
        dis = sorted(((m, t, e) for m, t, e, ok in zip(paired, tilt, eng, agree)
                      if not ok), key=lambda r: abs(r[1]), reverse=True)

        def _rate(idx):
            if not idx:
                return None
            return round(sum(1 for i in idx if agree[i]) / len(idx) * 100, 1)

        rows[name] = {
            "months": len(paired), "from": paired[0], "to": paired[-1],
            "months_dropped_from_era": len(ms) - len(paired),
            "tilt_mean_ann_bp": round(tilt_ann, 1),
            "engine_mean_ann_bp": round(eng_ann, 1),
            "tilt_sign": _sign3(round(tilt_ann, 6)),
            "engine_sign": _sign3(round(eng_ann, 6)),
            "signs_agree": _sign3(round(tilt_ann, 6)) == _sign3(round(eng_ann, 6)),
            "months_tilt_up": len(up),
            "months_tilt_down": len(down),
            "months_engine_up": sum(1 for e in eng if e > 0),
            "months_agree": sum(1 for a in agree if a),
            "months_disagree": sum(1 for a in agree if not a),
            "month_agreement_pct": round(sum(1 for a in agree if a) / len(agree) * 100, 1),
            "agreement_when_tilt_up_pct": _rate(up),
            "agreement_when_tilt_down_pct": _rate(down),
            "deadband_bp": db,
            "months_outside_deadband": len(outside),
            "month_agreement_outside_deadband_pct": _rate(outside),
            "top_disagreement_months": [
                {"month": m, "tilt_bp": round(t * 1e4, 1),
                 "engine_bp": round(e * 1e4, 1)}
                for m, t, e in dis[:TILT3SIGN_DISAGREE_TOP]],
        }
    measured = {k: v for k, v in rows.items()
                if k != "full" and "month_agreement_pct" in v}
    differ = sorted(k for k, v in measured.items() if not v["signs_agree"])
    raw_rates = [v["month_agreement_pct"] for v in measured.values()]
    dead_rates = [v["month_agreement_outside_deadband_pct"]
                  for v in measured.values()
                  if v["month_agreement_outside_deadband_pct"] is not None]
    return {
        "study": "e169_tilt3_sign_vs_engine",
        "evidence_cutoff": core["cutoff"],
        "spec": {
            "large": list(TILT_LARGE), "small": list(TILT3_SMALL),
            "tilt": "three-member: mean(small leg) - mean(large leg), equal weight in-leg",
            "engine_series": "wide monthly return minus ladder monthly return "
                             "(the same curves the paid book is measured on)",
            "month_agreement": "share of months where sign(tilt) == sign(engine), "
                               "ties counted as disagreement",
            "deadband_bp": db,
            "disagreement_named_per_era": TILT3SIGN_DISAGREE_TOP,
            "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
            "pick_n": 9999, "exclude_prefixes": ["sh511"], "cost_mult": 1.0,
        },
        "eras": rows,
        "answers": {
            "eras_measured": len(measured),
            "eras_where_signs_differ": len(differ),
            "era_names_where_signs_differ": differ,
            "eras_where_signs_agree": len(measured) - len(differ),
            "month_agreement_min_pct": min(raw_rates) if raw_rates else None,
            "month_agreement_max_pct": max(raw_rates) if raw_rates else None,
            "month_agreement_outside_deadband_min_pct":
                min(dead_rates) if dead_rates else None,
            "month_agreement_outside_deadband_max_pct":
                max(dead_rates) if dead_rates else None,
            "full_window_month_agreement_pct":
                (rows.get("full") or {}).get("month_agreement_pct"),
            "full_window_signs_agree": (rows.get("full") or {}).get("signs_agree"),
            "deadband_bp": db,
        },
        "honest": [
            "an era sign comparison is a statement about two LEVELS; the month-level rate "
            "beneath it is the one that says whether the tilt tracks the traded spread at all",
            "a month-level rate near 50% is a result, not a defect: it means the era agreement "
            "is carried by the level, and quoting the tilt as a timing signal is not supported",
            "the deadband is declared before the burn (%gbp monthly): months where either "
            "series is inside it are excluded from the deadband rate, and the raw rate is "
            "printed beside it rather than replaced" % db,
            "the engine series is the engine's own wide-vs-ladder monthly difference, so this "
            "compares a member ratio against a traded quantity, not two regressions",
            "eras remain calendar partitions of one continuous monthly series and do not add up",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
        "dropped_months_3member": core.get("dropped3"),
    }


# ---------------------- leg: E172 the deadband is a sweep, not a constant
#
# E169 published ONE deadband (10bp) and on 2024_now the deadband rate came out
# WORSE than the raw rate. One constant cannot tell a reader whether that era is
# anti-correlated or merely noisy -- dropping months can remove evidence as
# easily as it removes noise. So the deadband is swept and, at every step, the
# number of months that survived it is published beside the rate.
TILT3SIGNBAND_BP = (0.0, 10.0, 25.0, 50.0)   # declared before the burn (E172)
TILT3SIGNBAND_MIN_MONTHS = 6                 # retention floor for a rate to be quoted
TILT3SIGNBAND_HALF = 50.0                    # the coin-flip line


def _band_verdict(rate, months, floor=TILT3SIGNBAND_MIN_MONTHS):
    """What a single band's reading is allowed to claim.

    A rate under half is only a verdict when enough months survived the band;
    below the floor the band has removed the evidence, not the noise, and the
    honest label is ``thin`` rather than either side of the coin.
    """
    if rate is None or months is None or months < floor:
        return "thin"
    if rate < TILT3SIGNBAND_HALF:
        return "anti_correlated"
    if rate > TILT3SIGNBAND_HALF:
        return "aligned"
    return "coin_flip"


def run_tilt3signband(outdir, core=None, eras=ERAS, raw=None, bands=None):
    """E172: sweep E169's deadband and publish the support each rate stands on.

    The deadband cannot reach an era's LEVEL (it filters months, never edits a
    return), so ``tilt_sign``/``engine_sign``/``signs_agree`` are constant across
    the sweep BY CONSTRUCTION and are published once, beside a line saying so --
    a reader who sees identical signs at four bands is not looking at four
    findings. What the sweep does move is the month rate, and the only honest
    way to read that movement is next to ``months_outside_deadband``: a rate
    that falls while the denominator collapses is the band choosing its sample.
    """
    bands = [float(b) for b in (bands if bands is not None else TILT3SIGNBAND_BP)]
    core = core if core is not None else _monthly_core(raw_all=raw)
    arms = {b: run_tilt3sign(None, core=core, eras=eras, deadband_bp=b)
            for b in bands}
    names = list(arms[bands[0]]["eras"].keys())
    rows = {}
    for name in names:
        sweep = []
        base = None
        for b in bands:
            row = (arms[b]["eras"] or {}).get(name) or {}
            if base is None and "month_agreement_outside_deadband_pct" in row:
                base = row
            if "month_agreement_outside_deadband_pct" not in row:
                sweep.append({"deadband_bp": b, "skipped": row.get("skipped")})
                continue
            sweep.append({
                "deadband_bp": b,
                "months_outside_deadband": row.get("months_outside_deadband"),
                "month_agreement_outside_deadband_pct":
                    row.get("month_agreement_outside_deadband_pct"),
                "verdict": _band_verdict(
                    row.get("month_agreement_outside_deadband_pct"),
                    row.get("months_outside_deadband")),
            })
        if base is None:
            rows[name] = {"months": ((arms[bands[0]]["eras"] or {}).get(name) or {}).get("months"),
                          "skipped": "no band priced this era", "sweep": sweep}
            continue
        quoted = [s for s in sweep if s.get("verdict") != "thin"]
        all_rates = [s["month_agreement_outside_deadband_pct"] for s in sweep
                     if s.get("month_agreement_outside_deadband_pct") is not None]
        quoted_rates = [s["month_agreement_outside_deadband_pct"] for s in quoted]
        verdicts = [s["verdict"] for s in sweep if "verdict" in s]
        quoted_verdicts = [s["verdict"] for s in quoted]
        rows[name] = {
            "months": base.get("months"),
            "from": base.get("from"), "to": base.get("to"),
            "months_dropped_from_era": base.get("months_dropped_from_era"),
            "tilt_mean_ann_bp": base.get("tilt_mean_ann_bp"),
            "engine_mean_ann_bp": base.get("engine_mean_ann_bp"),
            "tilt_sign": base.get("tilt_sign"),
            "engine_sign": base.get("engine_sign"),
            "signs_agree": base.get("signs_agree"),
            "signs_band_invariant": all(
                (arms[b]["eras"] or {}).get(name, {}).get("signs_agree")
                == base.get("signs_agree") for b in bands
                if "month_agreement_pct" in ((arms[b]["eras"] or {}).get(name) or {})),
            "rate_at_zero_band_pct": (sweep[0] or {}).get("month_agreement_outside_deadband_pct"),
            "rate_span_quoted_pct": round(max(quoted_rates) - min(quoted_rates), 1)
            if len(quoted_rates) >= 2 else None,
            "rate_span_all_pct": round(max(all_rates) - min(all_rates), 1)
            if len(all_rates) >= 2 else None,
            "quoted_bands": [s["deadband_bp"] for s in quoted],
            "thin_bands": [s["deadband_bp"] for s in sweep
                           if s.get("verdict") == "thin"],
            "verdicts": verdicts,
            "quoted_verdicts": quoted_verdicts,
            "verdict_stable": (len(set(quoted_verdicts)) == 1
                               if quoted_verdicts else None),
            "sweep": sweep,
        }
    measured = {k: v for k, v in rows.items()
                if k != "full" and v.get("sweep") and v.get("verdicts") is not None}

    def _names(pred):
        return sorted(k for k, v in measured.items() if pred(v))

    unstable = _names(lambda v: not v["verdict_stable"])
    anti_all = _names(lambda v: v["verdicts"] and
                      set(v["verdicts"]) == {"anti_correlated"})
    thin_all = _names(lambda v: v["verdicts"] and
                      set(v["verdicts"]) == {"thin"})
    spans = [(k, v["rate_span_quoted_pct"]) for k, v in measured.items()
             if v.get("rate_span_quoted_pct") is not None]
    widest = max(spans, key=lambda r: r[1]) if spans else (None, None)
    first_thin = None
    for b in bands:
        if any(b in (v.get("thin_bands") or []) for v in measured.values()):
            first_thin = b
            break
    return {
        "study": "e172_tilt3sign_deadband_sweep",
        "evidence_cutoff": core["cutoff"],
        "spec": {
            "bands_bp": bands,
            "min_months_floor": TILT3SIGNBAND_MIN_MONTHS,
            "half_line_pct": TILT3SIGNBAND_HALF,
            "rate_definition": "share of surviving months where sign(tilt) == "
                               "sign(engine); zero band equals the raw rate by "
                               "construction (abs(x) >= 0 always holds)",
            "era_signs": "constant across bands by construction: the deadband "
                         "filters months and never edits a return",
            "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
            "pick_n": 9999, "exclude_prefixes": ["sh511"], "cost_mult": 1.0,
        },
        "eras": rows,
        "answers": {
            "eras_measured": len(measured),
            "bands": bands,
            "era_names_verdict_stable": _names(lambda v: v["verdict_stable"]),
            "era_names_verdict_unstable": unstable,
            "era_names_anti_correlated_at_every_band": anti_all,
            "era_names_thin_at_every_band": thin_all,
            "max_rate_span_quoted_pct": widest[1],
            "max_rate_span_era": widest[0],
            "first_band_with_any_thin_era": first_thin,
            "full_window_rates_pct": {str((s or {}).get("deadband_bp")): (s or {}).get("month_agreement_outside_deadband_pct")
                                      for s in (rows.get("full") or {}).get("sweep", [])},
        },
        "honest": [
            "the era signs are identical at every band because a deadband cannot "
            "reach a level -- four rows of the same sign are one finding, not four",
            "a rate that moves while months_outside_deadband collapses is the band "
            "choosing its sample; a rate quoted with fewer than %d months is labelled "
            "thin and kept out of the span" % TILT3SIGNBAND_MIN_MONTHS,
            "the zero band reproduces the raw rate exactly, so E169's published "
            "figures remain readable inside this face",
            "sweeping a constant that was declared before the burn is a sensitivity "
            "table on a published reading, not a re-fit: nothing here selects a band",
            "descriptive census only: no gate, no verdict on the book, no prereg, "
            "no trial count",
        ],
    }


def run_tilt3screened(outdir, mode="neutralise_int", eras=ERAS, resume=True):
    """E170: re-derive the E126 three-member tilt face on the screened arm.

    E126 reached back to 2013-04 for the first time, but published it on the RAW
    panel -- while every other skin in this family (E112-E127) was re-read on the
    split-event-repaired arm. So "the pre-2017 era reads +1186bp" and "this
    family has been repaired" had never been in the same sentence.

    Same machinery as E124: one load, both arms burnt off it, per-arm
    checkpoints, the shared ``_burnin_pair_rows`` join, a same-arm control that
    must read zero and a cutoff control against the newest published raw face.

    The question is per-era, not "did the numbers move": "the repair moved the
    pre-2017 era" has to be separable from "the repair moved everything", so the
    per-era table publishes raw vs screened beside each other, era bucket moves
    are counted separately from the skin bucket and the answers, and a sign flip
    on the era's tilt is called out on its own line.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]
    tag = cutoff.replace("-", "")

    def cached(label, thunk):
        p = os.path.join(outdir or ".", "TILT3-arm-%s-%s.json" % (label, tag))
        if resume and os.path.isfile(p):
            try:
                with open(p, "r", encoding="utf-8") as fh:
                    return json.load(fh)
            except Exception:
                pass
        face = thunk()
        if outdir:
            write_json(outdir, "TILT3-arm-%s-%s.json" % (label, tag), face)
        return face

    screened, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)

    raw_arm = cached("raw", lambda: run_tilt3(None, raw=raw, eras=eras))
    scr_arm = cached(mode, lambda: run_tilt3(None, raw=screened, eras=eras))

    keys = sorted({k[0] for k in _tilt3_arm_cells(raw_arm)})
    pair = _burnin_pair_rows(raw_arm, scr_arm, keys,
                             cells_fn=_tilt3_arm_cells,
                             dates_fn=_tilt3_arm_dates)
    control = _burnin_pair_rows(raw_arm, raw_arm, keys,
                                cells_fn=_tilt3_arm_cells,
                                dates_fn=_tilt3_arm_dates)["summary"]

    # cutoff control: newest previously published RAW tilt3 face vs today's raw
    # arm. The raw face lives in results/e43_tilt_4member, so that directory is
    # searched first as well as our own (E159 pit).
    cutoff_control = None
    search_dirs = [d for d in (os.path.join(ROOT, "results", "e43_tilt_4member"),
                               outdir) if d and os.path.isdir(d)]
    olds = []
    for d in search_dirs:
        olds.extend(os.path.join(d, p) for p in os.listdir(d)
                    if p.startswith("TILT3REACH-") and p.endswith(".json"))
    for path in sorted(olds, key=os.path.basename, reverse=True):
        p = os.path.basename(path)
        if p[len("TILT3REACH-"):-len(".json")] == tag:
            continue
        try:
            with open(path, "r", encoding="utf-8") as fh:
                old_face = json.load(fh)
        except Exception:
            continue
        old_keys = sorted({k[0] for k in _tilt3_arm_cells(old_face)})
        old_pair = _burnin_pair_rows(old_face, raw_arm, old_keys,
                                     cells_fn=_tilt3_arm_cells,
                                     dates_fn=_tilt3_arm_dates)
        cutoff_control = {
            "old_face": p,
            "old_cutoff": old_face.get("evidence_cutoff"),
            "comparison": "old raw arm vs today raw arm (arm held fixed)",
            "summary": old_pair["summary"],
            "moved": old_pair["moved"],
        }
        break

    def _delta(a, b):
        if isinstance(a, (int, float)) and isinstance(b, (int, float)):
            return round(b - a, 3)
        return None

    raw_eras = raw_arm.get("eras") or {}
    scr_eras = scr_arm.get("eras") or {}
    per_era = {}
    for era in sorted(set(raw_eras) | set(scr_eras)):
        r = raw_eras.get(era) or {}
        q = scr_eras.get(era) or {}
        per_era[era] = {
            "months_raw": r.get("months"), "months_screened": q.get("months"),
            "tilt_bp_raw": r.get("tilt_annualised_bp"),
            "tilt_bp_screened": q.get("tilt_annualised_bp"),
            "tilt_bp_delta": _delta(r.get("tilt_annualised_bp"),
                                    q.get("tilt_annualised_bp")),
            "spread_raw_bp_raw": r.get("spread_raw_ann_bp"),
            "spread_raw_bp_screened": q.get("spread_raw_ann_bp"),
            "spread_raw_bp_delta": _delta(r.get("spread_raw_ann_bp"),
                                          q.get("spread_raw_ann_bp")),
            "neutral_bp_raw": r.get("spread_size_neutral_ann_bp"),
            "neutral_bp_screened": q.get("spread_size_neutral_ann_bp"),
            "neutral_bp_delta": _delta(r.get("spread_size_neutral_ann_bp"),
                                       q.get("spread_size_neutral_ann_bp")),
            "engine_diff_bp_raw": r.get("engine_ann_diff_bp"),
            "engine_diff_bp_screened": q.get("engine_ann_diff_bp"),
            "tilt_sign_raw": _pair_sign(r.get("tilt_annualised_bp")),
            "tilt_sign_screened": _pair_sign(q.get("tilt_annualised_bp")),
        }
        per_era[era]["tilt_sign_flipped"] = (
            per_era[era]["tilt_sign_raw"] != per_era[era]["tilt_sign_screened"])

    s = pair["summary"]
    survives = _twin_survives(s, control)

    arr_raw, arr_scr = _tilt4_arrows(raw_arm), _tilt4_arrows(scr_arm)
    arrow_moved = [{"era": k, "column": c, "raw": arr_raw[k][c],
                    "screened": (arr_scr.get(k) or {}).get(c)}
                   for k in sorted(arr_raw)
                   for c in _TILT4_ARROW_COLUMNS
                   if arr_scr.get(k, {}).get(c) != arr_raw[k][c]]
    survives_arrows = not arrow_moved

    era_moved = [r for r in pair["moved"] if r["start"].startswith("era/")]
    skin_moved = [r for r in pair["moved"] if r["start"].startswith("skin/")]
    answer_moved = [r for r in pair["moved"] if r["start"] == "answers"]
    other_moved = [r for r in pair["moved"]
                   if r not in era_moved and r not in skin_moved
                   and r not in answer_moved]
    eras_moved = sorted({r["start"][len("era/"):] for r in era_moved})
    signs_flipped = sorted(k for k, v in per_era.items() if v["tilt_sign_flipped"])

    gaps = {era: _tilt4_decomposition_gap(row)
            for era, row in (scr_arm.get("eras") or {}).items()}
    gap_bad = {k: v for k, v in gaps.items() if v is not None and abs(v) > 0.2}
    raw_gaps = {era: _tilt4_decomposition_gap(row)
                for era, row in (raw_arm.get("eras") or {}).items()}

    return {
        "study": "e170_tilt3_screened_twin",
        "evidence_cutoff": cutoff,
        "spec": {
            "screen_mode": mode,
            "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
            "large": list(TILT_LARGE), "small": list(TILT3_SMALL),
            "four_member_small": list(TILT4_SMALL),
            "five_member_small": list(TILT_SMALL),
            "arms": {"raw": "e27.load_universe() as shipped",
                     "screened": "panel_screen.screen_universe(mode=%s)" % mode},
            "join": ("_tilt3_arm_cells harvests the per-era tilt and its "
                     "decomposition, the 3-vs-4-vs-5-member skin rows and the "
                     "aggregates; _tilt3_arm_dates carries era boundaries, the "
                     "best/worst month identities and the delta reasons, because "
                     "a date or a month name has no delta"),
            "units": ("deltas are in the units of their column: bp for the "
                      "annualised columns, percent for the share/squared columns, "
                      "count for months and beta"),
        },
        "screen_report": report,
        "arrows": {"raw": arr_raw, "screened": arr_scr},
        "per_era": per_era,
        "pair": pair,
        "control": control,
        "cutoff_control": cutoff_control,
        "decomposition": {"screened_gaps_bp": gaps, "raw_gaps_bp": raw_gaps,
                          "tolerance_bp": 0.2,
                          "incomplete_eras": sorted(gap_bad)},
        "answers": {
            "counts_survive_the_repair": bool(survives),
            "arrows_survive_the_repair": bool(survives_arrows),
            "cells_compared": s["cells_compared"],
            "cells_moved": s["cells_moved"],
            "max_abs_delta": s["max_abs_delta_pp"],
            "worst_cell": s["worst"],
            "era_cells_moved": len(era_moved),
            "skin_cells_moved": len(skin_moved),
            "answer_cells_moved": len(answer_moved),
            "other_cells_moved": len(other_moved),
            "eras_with_any_moved_cell": eras_moved,
            "eras_with_a_flipped_tilt_sign": signs_flipped,
            "n_eras": len([k for k in keys if k.startswith("era/")]),
            "arrow_claims_moved": len(arrow_moved),
            "moved_attribution_complete": (
                len(era_moved) + len(skin_moved) + len(answer_moved)
                + len(other_moved) == s["cells_moved"]),
            "decomposition_complete": not gap_bad,
            "control_cells_moved": control["cells_moved"],
            "control_ordering_moved": control["gate_dates_moved"],
            "cutoff_control": ({"old_face": cutoff_control["old_face"],
                                "cells_moved":
                                    cutoff_control["summary"]["cells_moved"],
                                "max_abs_delta":
                                    cutoff_control["summary"]["max_abs_delta_pp"]}
                               if cutoff_control else None),
            "cutoff_control_reason": (
                None if cutoff_control else
                "no older TILT3REACH-* raw face on disk: the only published face "
                "carries this same cutoff, so a stale-face control has nothing to "
                "compare against yet (null means 'not measurable', not 'clean')"),
            "era_tilt_bp_cells_moved": len(
                [k for k, v in per_era.items() if v["tilt_bp_delta"] not in (None, 0)]),
            "reading": (
                ("the three-member tilt attribution survives the repair: %d of %d "
                 "cells move, no era flips its tilt sign, every arrow holds and "
                 "each era still decomposes"
                 % (s["cells_moved"], s["cells_compared"]))
                if (survives and survives_arrows and not gap_bad
                    and not signs_flipped) else
                ("the repair reaches the three-member attribution: %d of %d cells "
                 "move (%d era / %d skin / %d answer / %d other), eras touched=%s, "
                 "tilt-sign flips=%s, %d of %d arrow claims move and %d era(s) no "
                 "longer decompose; %d cell(s) exist on one arm only"
                 % (s["cells_moved"], s["cells_compared"], len(era_moved),
                    len(skin_moved), len(answer_moved), len(other_moved),
                    eras_moved, signs_flipped, len(arrow_moved),
                    len(arr_raw) * len(_TILT4_ARROW_COLUMNS), len(gap_bad),
                    s["only_in_raw"] + s["only_in_screened"]))),
        },
        "honest": [
            "both arms are burnt off ONE load of the panel so the twin differs in "
            "the repair, not in what was read",
            "the per-era table is the answer face: a constant shift across eras "
            "leaves the attribution intact while a single-era shift rewrites it",
            "a tilt-sign flip is published as its own list because a sign is the "
            "headline a reader consumes ('small caps led') and a magnitude delta "
            "cannot express it",
            "skin rows compare 3-, 4- and 5-member readings on shared months only; "
            "the delta is the composition price, not the identity",
            "the cutoff control holds the arm fixed (raw vs raw) so a stale face is "
            "separated from a repair effect",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }


def _agreement_change(raw_pct, scr_pct):
    """(E171) three-state change of a rate: equal is NOT a deterioration.

    The first cut derived a boolean ``recovered = screened > raw`` and published
    ``worsens`` as its negation, which printed "worsens in all five eras" while
    every era's rate was bit-identical on both arms (23.5 vs 23.5, 45.8 vs 45.8).
    A two-state label on a three-state fact is the E94 family this repo keeps
    re-learning, so equality gets its own name and "not measurable" does too.
    """
    if raw_pct is None or scr_pct is None:
        return "not_measurable"
    if scr_pct > raw_pct:
        return "recovered"
    if scr_pct < raw_pct:
        return "worsened"
    return "unchanged"


def run_tilt3screensign(outdir, mode="neutralise_int", eras=ERAS, resume=True):
    """E171: re-derive the E169 tilt-vs-engine sign face on the screened arm.

    E169 compared the tilt's sign against the engine's own wide-minus-ladder
    monthly difference, and found two eras (2017_2020, 2024_now) where the
    arrows disagree while no era clears 57% month-level agreement. That face
    was burnt on the RAW panel, so the one era whose published arrow flips under
    the repair (2024_now) was also the one whose sign verdict had never been
    screened.

    E170 already proved the tilt SERIES is arm-insensitive (tilt_bp_delta = 0.0
    on every era), so this twin can only move the engine column -- and saying
    that up front is the point: a column-by-column join tells a reader which
    half of the face the repair reaches, which a single "cells moved" count
    cannot.

    Same machinery as E170: one load, both arms burnt off it, per-arm
    checkpoints, the shared ``_burnin_pair_rows`` join, a same-arm control that
    must read zero and a cutoff control against the newest published raw face.

    Per-era table carries raw and screened BESIDE each other and names its
    denominators (months priced on each arm), because "the agreement recovered"
    on a different month count is not the same experiment.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]
    tag = cutoff.replace("-", "")

    def cached(label, thunk):
        p = os.path.join(outdir or ".", "TILT3SIGN-arm-%s-%s.json" % (label, tag))
        if resume and os.path.isfile(p):
            try:
                with open(p, "r", encoding="utf-8") as fh:
                    return json.load(fh)
            except Exception:
                pass
        face = thunk()
        if outdir:
            write_json(outdir, "TILT3SIGN-arm-%s-%s.json" % (label, tag), face)
        return face

    screened, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)

    raw_arm = cached("raw", lambda: run_tilt3sign(None, raw=raw, eras=eras))
    scr_arm = cached(mode, lambda: run_tilt3sign(None, raw=screened, eras=eras))

    keys = sorted({k[0] for k in _tilt3sign_arm_cells(raw_arm)})
    pair = _burnin_pair_rows(raw_arm, scr_arm, keys,
                             cells_fn=_tilt3sign_arm_cells,
                             dates_fn=_tilt3sign_arm_dates)
    control = _burnin_pair_rows(raw_arm, raw_arm, keys,
                                cells_fn=_tilt3sign_arm_cells,
                                dates_fn=_tilt3sign_arm_dates)["summary"]

    # cutoff control: newest previously published RAW tilt3sign face vs today's
    # raw arm. Arm held fixed, so a stale face is separated from a repair effect.
    cutoff_control = None
    search_dirs = [d for d in (os.path.join(ROOT, "results", "e43_tilt_4member"),
                               outdir) if d and os.path.isdir(d)]
    olds = []
    for d in search_dirs:
        olds.extend(os.path.join(d, p) for p in os.listdir(d)
                    if p.startswith("TILT3SIGN-") and p.endswith(".json"))
    for path in sorted(olds, key=os.path.basename, reverse=True):
        p = os.path.basename(path)
        if p[len("TILT3SIGN-"):-len(".json")] == tag:
            continue
        try:
            with open(path, "r", encoding="utf-8") as fh:
                old_face = json.load(fh)
        except Exception:
            continue
        old_keys = sorted({k[0] for k in _tilt3sign_arm_cells(old_face)})
        old_pair = _burnin_pair_rows(old_face, raw_arm, old_keys,
                                     cells_fn=_tilt3sign_arm_cells,
                                     dates_fn=_tilt3sign_arm_dates)
        cutoff_control = {
            "old_face": p,
            "old_cutoff": old_face.get("evidence_cutoff"),
            "comparison": "old raw arm vs today raw arm (arm held fixed)",
            "summary": old_pair["summary"],
            "moved": old_pair["moved"],
        }
        break

    def _delta(a, b):
        if isinstance(a, (int, float)) and isinstance(b, (int, float)):
            return round(b - a, 3)
        return None

    raw_eras = raw_arm.get("eras") or {}
    scr_eras = scr_arm.get("eras") or {}
    per_era = {}
    for era in sorted(set(raw_eras) | set(scr_eras)):
        r = raw_eras.get(era) or {}
        q = scr_eras.get(era) or {}
        agree_r = r.get("signs_agree")
        agree_q = q.get("signs_agree")
        per_era[era] = {
            "months_raw": r.get("months"), "months_screened": q.get("months"),
            "months_same": (r.get("months") is not None
                            and r.get("months") == q.get("months")),
            "tilt_bp_raw": r.get("tilt_mean_ann_bp"),
            "tilt_bp_screened": q.get("tilt_mean_ann_bp"),
            "tilt_bp_delta": _delta(r.get("tilt_mean_ann_bp"),
                                    q.get("tilt_mean_ann_bp")),
            "engine_bp_raw": r.get("engine_mean_ann_bp"),
            "engine_bp_screened": q.get("engine_mean_ann_bp"),
            "engine_bp_delta": _delta(r.get("engine_mean_ann_bp"),
                                      q.get("engine_mean_ann_bp")),
            "tilt_sign_raw": _pair_sign(r.get("tilt_mean_ann_bp")),
            "tilt_sign_screened": _pair_sign(q.get("tilt_mean_ann_bp")),
            "engine_sign_raw": _pair_sign(r.get("engine_mean_ann_bp")),
            "engine_sign_screened": _pair_sign(q.get("engine_mean_ann_bp")),
            "signs_agree_raw": agree_r,
            "signs_agree_screened": agree_q,
            "era_verdict_flipped": (None if agree_r is None or agree_q is None
                                    else bool(agree_r) != bool(agree_q)),
            "month_agreement_pct_raw": r.get("month_agreement_pct"),
            "month_agreement_pct_screened": q.get("month_agreement_pct"),
            "month_agreement_delta": _delta(r.get("month_agreement_pct"),
                                            q.get("month_agreement_pct")),
            "outside_deadband_pct_raw": r.get("month_agreement_outside_deadband_pct"),
            "outside_deadband_pct_screened": q.get("month_agreement_outside_deadband_pct"),
            "outside_deadband_delta": _delta(
                r.get("month_agreement_outside_deadband_pct"),
                q.get("month_agreement_outside_deadband_pct")),
            "months_disagree_raw": r.get("months_disagree"),
            "months_disagree_screened": q.get("months_disagree"),
        }
        pr = per_era[era]["month_agreement_pct_raw"]
        ps = per_era[era]["month_agreement_pct_screened"]
        per_era[era]["agreement_change"] = _agreement_change(pr, ps)
        per_era[era]["agreement_recovered"] = (
            None if per_era[era]["agreement_change"] == "not_measurable"
            else per_era[era]["agreement_change"] == "recovered")
        per_era[era]["engine_sign_flipped"] = (
            per_era[era]["engine_sign_raw"] != per_era[era]["engine_sign_screened"])

    s = pair["summary"]
    survives = _twin_survives(s, control)

    era_moved = [r for r in pair["moved"] if r["start"].startswith("era/")]
    answer_moved = [r for r in pair["moved"] if r["start"] == "answers"]
    other_moved = [r for r in pair["moved"]
                   if r not in era_moved and r not in answer_moved]
    eras_moved = sorted({r["start"][len("era/"):] for r in era_moved})
    verdict_flips = sorted(k for k, v in per_era.items()
                           if v["era_verdict_flipped"])
    engine_sign_flips = sorted(k for k, v in per_era.items()
                               if v["engine_sign_flipped"])
    tilt_cells_moved = [r for r in era_moved if r["column"].startswith("tilt_")]
    engine_cells_moved = [r for r in era_moved if r["column"].startswith("engine_")]
    recovered = sorted(k for k, v in per_era.items()
                       if v["agreement_change"] == "recovered")
    worsened = sorted(k for k, v in per_era.items()
                      if v["agreement_change"] == "worsened")
    unchanged = sorted(k for k, v in per_era.items()
                       if v["agreement_change"] == "unchanged")

    raw_differ = sorted(k for k, v in per_era.items()
                        if v["signs_agree_raw"] is False)
    scr_differ = sorted(k for k, v in per_era.items()
                        if v["signs_agree_screened"] is False)
    same_months = all(v["months_same"] for v in per_era.values() if v["months_raw"])

    return {
        "study": "e171_tilt3_screened_sign",
        "evidence_cutoff": cutoff,
        "spec": {
            "screen_mode": mode,
            "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
            "large": list(TILT_LARGE), "small": list(TILT3_SMALL),
            "arms": {"raw": "e27.load_universe() as shipped",
                     "screened": "panel_screen.screen_universe(mode=%s)" % mode},
            "columns_moved_by_construction": (
                "the tilt series is arm-invariant (E170 measured 0.0bp on every "
                "era), so this twin is read as a per-column question: tilt_* "
                "cells move only if that claim fails today"),
            "units": ("bp for the annualised tilt/engine columns, percent for "
                      "the agreement rates, months for the denominators"),
            "join": ("_tilt3sign_arm_cells harvests the per-era numeric columns "
                     "and the answer scalars; _tilt3sign_arm_dates carries era "
                     "boundaries, the signs_agree verdict and the differ-names "
                     "list, because a boolean or a month name has no delta"),
        },
        "screen_report": report,
        "per_era": per_era,
        "pair": pair,
        "control": control,
        "cutoff_control": cutoff_control,
        "answers": {
            "counts_survive_the_repair": bool(survives),
            "cells_compared": s["cells_compared"],
            "cells_moved": s["cells_moved"],
            "max_abs_delta": s["max_abs_delta_pp"],
            "worst_cell": s["worst"],
            "era_cells_moved": len(era_moved),
            "answer_cells_moved": len(answer_moved),
            "other_cells_moved": len(other_moved),
            "eras_with_any_moved_cell": eras_moved,
            "tilt_cells_moved": len(tilt_cells_moved),
            "engine_cells_moved": len(engine_cells_moved),
            "tilt_series_arm_invariant_today": (len(tilt_cells_moved) == 0),
            "eras_where_signs_differ_raw": raw_differ,
            "eras_where_signs_differ_screened": scr_differ,
            "era_verdict_flips": verdict_flips,
            "engine_sign_flips": engine_sign_flips,
            "eras_whose_month_agreement_recovers": recovered,
            "eras_whose_month_agreement_worsens": worsened,
            "eras_whose_month_agreement_unchanged": unchanged,
            "all_eras_priced_on_the_same_month_count": bool(same_months),
            "control_cells_moved": control["cells_moved"],
            "control_ordering_moved": control["gate_dates_moved"],
            "cutoff_control": ({"old_face": cutoff_control["old_face"],
                                "cells_moved":
                                    cutoff_control["summary"]["cells_moved"],
                                "max_abs_delta":
                                    cutoff_control["summary"]["max_abs_delta_pp"]}
                               if cutoff_control else None),
            "cutoff_control_reason": (
                None if cutoff_control else
                "no older TILT3SIGN-* raw face on disk: the only published face "
                "carries this same cutoff, so a stale-face control has nothing to "
                "compare against yet (null means 'not measurable', not 'clean')"),
            "reading": (
                ("the engine column is repair-insensitive too: %d of %d cells move, "
                 "no era changes its sign verdict and the two disagreeing eras are "
                 "the same on both arms"
                 % (s["cells_moved"], s["cells_compared"]))
                if (survives and not verdict_flips) else
                ("the repair reaches the sign face: %d of %d cells move (%d era / "
                 "%d answer / %d other; tilt %d, engine %d), disagreeing eras raw=%s "
                 "screened=%s, era verdict flips=%s, engine sign flips=%s, agreement "
                 "recovers in %s, worsens in %s and is unchanged in %s; "
                 "%d cell(s) exist on one arm only"
                 % (s["cells_moved"], s["cells_compared"], len(era_moved),
                    len(answer_moved), len(other_moved), len(tilt_cells_moved),
                    len(engine_cells_moved), raw_differ, scr_differ, verdict_flips,
                    engine_sign_flips, recovered, worsened, unchanged,
                    s["only_in_raw"] + s["only_in_screened"]))),
        },
        "honest": [
            "both arms are burnt off ONE load of the panel so the twin differs in "
            "the repair, not in what was read",
            "the tilt column moving at all would refute E170's 0.0bp invariance; it "
            "is re-measured here rather than trusted, and reported separately from "
            "the engine column",
            "month-agreement is a rate over priced months, so the denominators are "
            "published per arm; an era read on a different month count is disclosed "
            "in months_same rather than silently compared",
            "the cutoff control holds the arm fixed (raw vs raw) so a stale face is "
            "separated from a repair effect",
            "a null agreement_recovered means the era is missing on one arm -- "
            "'not measurable' is not 'no change'",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }


# ---------------------- leg: E174 who carries the engine column's repair move
#
# E171 published that the split-event repair moves the ENGINE column in three
# eras and moves the tilt column nowhere, and that 2024_now's era verdict flips
# as a result. An era-level delta on a 4-of-17-month reading is not something a
# reader can audit: the engine column is wide-minus-ladder, i.e. a difference of
# two held books, so the move can in principle come from ONE name-month on
# either side. This leg decomposes it name by name and asks whether the flipped
# verdict survives dropping the biggest carrier.
TILT3SIGNNAMES_TOP = 5              # carriers named per era
TILT3SIGNNAMES_MONTHS_PER_NAME = 3  # worst months named per carrier
TILT3SIGNNAMES_CASH = "__cash__"    # un-invested residual, booked not dropped
TILT3SIGNNAMES_COVERS = (50.0, 80.0)


def _engine_net_contrib(contrib):
    """(E174) wide minus ladder per (month, name): the engine series decomposed.

    A name held by both books nets out, a name held by only one book carries its
    whole weight, and the cash residual keeps its own pseudo-name -- dropping it
    would make the attribution read complete while being short.
    """
    out = {}
    if not contrib:
        return out
    for side, sign in (("wide", 1.0), ("lad", -1.0)):
        for key, v in (contrib.get(side) or {}).items():
            out[key] = out.get(key, 0.0) + sign * v
    return out


def _era_engine_months(core, lo, hi):
    """The era's months that carry BOTH engine curves (run_tilt3sign's own set)."""
    tilt3 = core.get("tilt3") or {}
    wide_m = core.get("wide_m") or {}
    lad_m = core.get("lad_m") or {}
    return [m for m in core["months3"]
            if _in_era(m, lo, hi) and m in tilt3 and m in wide_m and m in lad_m]


def _era_side_bp(net, months):
    """Per-name annualised bp contribution to ONE arm's era engine level."""
    n = len(months)
    if not n:
        return {}
    scale = 12.0 / n * 1e4
    mset = set(months)
    out = {}
    for (m, s), v in net.items():
        if m in mset:
            out[s] = out.get(s, 0.0) + v * scale
    return out


def _era_name_split(net_raw, net_scr, months):
    """Per-name bp contribution to the era's engine DELTA (screened - raw)."""
    raw_bp = _era_side_bp(net_raw, months)
    scr_bp = _era_side_bp(net_scr, months)
    out = {}
    for s in set(raw_bp) | set(scr_bp):
        out[s] = scr_bp.get(s, 0.0) - raw_bp.get(s, 0.0)
    return out, raw_bp, scr_bp


def _carrier_coverage(rows, delta_bp):
    """How many names it takes to explain 50%/80% of a delta (E143 family)."""
    total = abs(delta_bp)
    if not rows or total <= 0:
        return {("cover_%g_pct" % c): {"names": None, "share_pct": None}
                for c in TILT3SIGNNAMES_COVERS}
    out, run = {}, 0.0
    for i, (_s, v) in enumerate(rows):
        run += abs(v)
        for c in TILT3SIGNNAMES_COVERS:
            key = "cover_%g_pct" % c
            if key not in out and run >= total * c / 100.0:
                out[key] = {"names": i + 1,
                            "share_pct": round(run / total * 100.0, 1)}
    for c in TILT3SIGNNAMES_COVERS:
        out.setdefault("cover_%g_pct" % c, {"names": None, "share_pct": None})
    return out


# ---------------------------------------------------------------- E175
TILT3SIGNDROPSWEEP_NAME_LIST = 8   # names reprinted on each ladder row
TILT3SIGNDROPSWEEP_MAX_ROWS = 25   # individual rows printed; the bands cover the rest


def _tilt3signname_burn(mode, eras):
    """(E175) the one load path the two name-level legs share.

    E174 and E175 read the same two arms over the same months. Loading twice
    would let the sweep describe a panel the published carrier table cannot be
    joined back to, so both legs take their inputs from here.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    cal_full = base.load_panel()[0]
    screened, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)
    core_raw = _monthly_core(raw_all=raw, contrib=True)
    core_scr = _monthly_core(raw_all=screened, contrib=True)
    return {
        "cutoff": cal_full[-1],
        "report": report,
        "core_raw": core_raw,
        "core_scr": core_scr,
        "net_raw": _engine_net_contrib(core_raw.get("contrib")),
        "net_scr": _engine_net_contrib(core_scr.get("contrib")),
        "arm_raw": run_tilt3sign(None, core=core_raw, eras=eras),
        "arm_scr": run_tilt3sign(None, core=core_scr, eras=eras),
    }


def _drop_bands(rows):
    """(E175) collapse the ladder into runs that share one verdict."""
    bands = []
    for r in rows:
        if bands and bands[-1]["verdict"] == r["verdict"]:
            bands[-1]["to_k"] = r["k"]
            bands[-1]["rows"] += 1
        else:
            bands.append({"from_k": r["k"], "to_k": r["k"], "rows": 1,
                          "verdict": r["verdict"]})
    return bands


def _drop_ladder(raw_bp, scr_bp, ranked, delta, base_raw=None, base_scr=None):
    """(E175) the era's sign verdict at every carrier count k = 0..n.

    k=0 reproduces the headline. Each further step removes the next name in
    |contribution| order from BOTH arms, because the engine column is a
    difference of two held books and a carrier exists on both sides of it.

    E174 published k=1 and k=5 as two points and they answered differently,
    which is the signature of a non-monotone curve sampled twice. Every k is
    printed here with how much of the delta has been consumed, so a reader can
    see both where the verdict settles and where the reading stops being about
    the books at all.

    ``base_raw``/``base_scr`` anchor the ladder on the PUBLISHED era levels and
    the fallback sums the decomposition instead. The distinction is not
    cosmetic: the per-name terms are sums of daily w*r while the published
    level is a compounded monthly mean, so the two bases can be tens of bp
    apart -- on 2024_now the offset is larger than the delta being attributed,
    and a ladder read off the unanchored base would flip a sign by arithmetic
    the carriers did not cause. Callers that publish a verdict about the
    repair must anchor and publish the offset beside it.
    """
    sum_raw = sum(raw_bp.values())
    sum_scr = sum(scr_bp.values())
    anchored = base_raw is not None and base_scr is not None
    base_raw = sum_raw if base_raw is None else float(base_raw)
    base_scr = sum_scr if base_scr is None else float(base_scr)
    total = abs(delta or 0.0)
    contrib = dict(ranked)
    # a name whose contribution did not move cannot move the verdict, so it is
    # not a rung of this ladder -- including it would print steps that change
    # nothing and read as evidence of stability
    names = [s for s, v in ranked if abs(v) > 1e-12]
    rows, cum = [], 0.0
    for k in range(len(names) + 1):
        dropped = names[:k]
        if k:
            cum += abs(contrib[dropped[-1]])
        r = base_raw - sum(raw_bp.get(s, 0.0) for s in dropped)
        s_ = base_scr - sum(scr_bp.get(s, 0.0) for s in dropped)
        sr, ss = _pair_sign(round(r, 9)), _pair_sign(round(s_, 9))
        # a level of exactly zero has no sign: 'undefined' is not 'agrees'
        verdict = ("undefined" if not sr or not ss
                   else ("agree" if sr == ss else "disagree"))
        rows.append({
            "k": k,
            "name_dropped": (dropped[-1] if k else None),
            "names_dropped": dropped[:TILT3SIGNDROPSWEEP_NAME_LIST],
            "raw_engine_bp": round(r, 2),
            "screened_engine_bp": round(s_, 2),
            "delta_bp": round(s_ - r, 2),
            "verdict": verdict,
            "share_of_delta_removed_pct": (round(cum / total * 100.0, 1)
                                           if total > 1e-9 else None),
            "beyond_delta_span": bool(total > 1e-9 and cum > total * 1.000001),
        })
    return {"rows": rows,
            "base_raw_bp": round(base_raw, 2),
            "base_screened_bp": round(base_scr, 2),
            "base_from": "published_level" if anchored else "decomposition",
            "decomposition_raw_bp": round(sum_raw, 2),
            "decomposition_screened_bp": round(sum_scr, 2),
            "n_names": len(names),
            "bands": _drop_bands(rows)}


def run_tilt3signdropsweep(outdir, mode="neutralise_int", eras=ERAS):
    """E175: sweep the carrier-drop ladder and say where the verdict settles.

    E174 answered "does the flip survive dropping a carrier" at two drop sizes
    and got two answers -- gone at k=1, back at k=5 -- so the honest object is
    the curve both points were sampled from. This leg prints the era's sign
    verdict at k = 0..n and the same ladder on an era whose engine level never
    moved: a ladder that is not flat there is broken before it says anything
    about 2024_now.

    Dropping a carrier is a counterfactual on the two arms' levels, not a
    repair: the published engine levels are untouched by this leg.
    """
    burn = _tilt3signname_burn(mode, eras)
    core_raw, core_scr = burn["core_raw"], burn["core_scr"]
    net_raw, net_scr = burn["net_raw"], burn["net_scr"]
    arm_raw, arm_scr = burn["arm_raw"], burn["arm_scr"]

    rows = {}
    honesty = []
    for name, lo, hi in list(eras) + [("full", None, None)]:
        ms = _era_engine_months(core_raw, lo, hi)
        ms_scr = _era_engine_months(core_scr, lo, hi)
        a = (arm_raw.get("eras") or {}).get(name) or {}
        b = (arm_scr.get("eras") or {}).get(name) or {}
        eng_raw = a.get("engine_mean_ann_bp")
        eng_scr = b.get("engine_mean_ann_bp")
        if not ms or eng_raw is None or eng_scr is None:
            rows[name] = {"months": len(ms),
                          "skipped": "no engine level on one arm for this era"}
            continue
        split, raw_bp, scr_bp = _era_name_split(net_raw, net_scr, ms)
        ranked = sorted(split.items(), key=lambda kv: -abs(kv[1]))
        delta = round(eng_scr - eng_raw, 3)
        # anchored on the published levels: the carriers are a DELTA quantity
        # (they reproduce the arm difference to 2.9bp at worst), while the
        # decomposition's own levels carry a compounding gap that is larger than
        # the delta on 2024_now. An unanchored ladder would let that gap flip a
        # sign no carrier caused -- E174's own drop test read both its points
        # off the unanchored base and must be read with this in mind.
        ladder = _drop_ladder(raw_bp, scr_bp, ranked, delta,
                              base_raw=eng_raw, base_scr=eng_scr)
        unanchored = _drop_ladder(raw_bp, scr_bp, ranked, delta)
        anchor = {
            "raw_offset_bp": round(eng_raw - unanchored["base_raw_bp"], 2),
            "screened_offset_bp": round(eng_scr - unanchored["base_screened_bp"], 2),
            "unanchored_base_raw_bp": unanchored["base_raw_bp"],
            "unanchored_base_screened_bp": unanchored["base_screened_bp"],
            "unanchored_k0_verdict": unanchored["rows"][0]["verdict"],
            "offset_alone_flips_raw_sign": (_pair_sign(eng_raw)
                                            != _pair_sign(unanchored["base_raw_bp"])),
            "offset_alone_flips_screened_sign": (
                _pair_sign(eng_scr)
                != _pair_sign(unanchored["base_screened_bp"])),
            "note": ("the per-name terms are sums of daily w*r while the "
                     "published level is a compounded monthly mean, so the two "
                     "bases differ by the compounding gap; the ladder is "
                     "anchored on the published level and this block says how "
                     "far the unanchored reading would have moved it"),
        }
        full = ladder["rows"]
        shown = [x for x in full
                 if x["k"] <= TILT3SIGNDROPSWEEP_MAX_ROWS or x["k"] == full[-1]["k"]]
        headline = ("agree" if _pair_sign(eng_raw) == _pair_sign(eng_scr)
                    else "disagree")
        measured_bands = [x for x in ladder["bands"] if x["verdict"] != "undefined"]
        verdicts = [x["verdict"] for x in measured_bands]
        first_change = None
        for x in ladder["bands"][1:]:
            if x["verdict"] != ladder["bands"][0]["verdict"]:
                first_change = x["from_k"]
                break
        rows[name] = {
            "months": len(ms),
            "months_screened": len(ms_scr),
            "engine_bp_raw": eng_raw,
            "engine_bp_screened": eng_scr,
            "engine_bp_delta": delta,
            "engine_sign_flipped": _pair_sign(eng_raw) != _pair_sign(eng_scr),
            # the tilt column cannot move here: this leg drops names from the
            # engine difference only, so any tilt statement is imported verbatim
            "tilt_mean_ann_bp": a.get("tilt_mean_ann_bp"),
            "tilt_sign": a.get("tilt_sign"),
            "tilt_column_note": ("imported from the arm face; a drop on the "
                                 "engine difference cannot move the tilt"),
            "headline_verdict": headline,
            "ladder_k0_verdict": full[0]["verdict"],
            "ladder_k0_matches_headline": full[0]["verdict"] == headline,
            "ladder_base": ladder["base_from"],
            "level_reconstruction": anchor,
            "names_swept": ladder["n_names"],
            "ladder_rows_total": len(full),
            "ladder_rows_omitted": len(full) - len(shown),
            "ladder_omitted_note": (None if len(full) == len(shown) else
                                    ("individual rows are printed to k=%d and at "
                                     "k=n; verdict_bands covers every k in between"
                                     % TILT3SIGNDROPSWEEP_MAX_ROWS)),
            "verdict_bands": ladder["bands"],
            "verdict_set": sorted(set(verdicts)),
            "first_k_with_a_different_verdict": first_change,
            "agrees_at_some_k": "agree" in verdicts,
            "disagrees_at_some_k": "disagree" in verdicts,
            "ladder_is_flat": len(set(verdicts)) <= 1,
            "ladder": shown,
        }
        if full[0]["verdict"] != headline:
            honesty.append("%s: the anchored ladder's k=0 verdict (%s) disagrees "
                           "with the published headline (%s), which cannot happen "
                           "unless the anchor itself was misread -- treat this "
                           "era as unusable"
                           % (name, full[0]["verdict"], headline))
        elif anchor["unanchored_k0_verdict"] != headline:
            honesty.append("%s: read off its own decomposition the era would "
                           "print '%s' instead of '%s', so the carrier ladder is "
                           "only meaningful anchored (offset %.1fbp raw / %.1fbp "
                           "screened)"
                           % (name, anchor["unanchored_k0_verdict"], headline,
                              anchor["raw_offset_bp"],
                              anchor["screened_offset_bp"]))

    measured = {k: v for k, v in rows.items() if "verdict_bands" in v}
    flipped = sorted(k for k, v in measured.items() if v["engine_sign_flipped"])
    flat = sorted(k for k, v in measured.items()
                  if abs(v["engine_bp_delta"] or 0.0) <= 0.05)
    gaps = [abs(v["level_reconstruction"]["raw_offset_bp"])
            for v in measured.values()]
    gaps += [abs(v["level_reconstruction"]["screened_offset_bp"])
             for v in measured.values()]
    offset_flips = sorted(
        k for k, v in measured.items()
        if v["level_reconstruction"]["offset_alone_flips_raw_sign"]
        or v["level_reconstruction"]["offset_alone_flips_screened_sign"])
    return {
        "study": "e175_tilt3sign_drop_ladder",
        "evidence_cutoff": burn["cutoff"],
        "spec": {
            "screen_mode": mode,
            "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
            "engine_series": "wide monthly return minus ladder monthly return",
            "ladder": ("k = 0..n carries removed in |delta contribution| order, "
                       "each removed from BOTH arms' era levels"),
            "ladder_base": ("anchored on the PUBLISHED era levels, because the "
                            "decomposition's own levels carry a compounding "
                            "offset that can exceed the delta"),
            "verdict": ("agree when the two eroded engine levels share a sign, "
                        "disagree otherwise, undefined when either level is "
                        "exactly zero"),
            "delta_span": ("share_of_delta_removed_pct is cumulative |dropped "
                           "contribution| over |delta|; beyond 100% the rung has "
                           "removed more than the delta is made of and is "
                           "flagged beyond_delta_span"),
        },
        "eras": rows,
        "answers": {
            "eras_measured": len(measured),
            "eras_where_engine_sign_flipped": flipped,
            "eras_where_engine_level_did_not_move": flat,
            "flat_eras_ladder_is_flat": {k: measured[k]["ladder_is_flat"]
                                         for k in flat},
            "first_k_with_a_different_verdict":
                {k: v["first_k_with_a_different_verdict"]
                 for k, v in measured.items()},
            "eras_agreeing_at_some_k": sorted(k for k, v in measured.items()
                                              if v["agrees_at_some_k"]),
            "eras_disagreeing_at_some_k": sorted(k for k, v in measured.items()
                                                 if v["disagrees_at_some_k"]),
            "eras_with_more_than_two_verdict_runs": sorted(
                k for k, v in measured.items()
                if len([x for x in v["verdict_bands"]
                        if x["verdict"] != "undefined"]) > 2),
            "eras_where_the_base_offset_alone_flips_a_sign": offset_flips,
            "unanchored_k0_verdict": {k: v["level_reconstruction"]
                                      ["unanchored_k0_verdict"]
                                      for k, v in measured.items()},
            "k0_matches_headline_everywhere": all(
                v["ladder_k0_matches_headline"] for v in measured.values()),
            "max_base_offset_bp": (max(gaps) if gaps else None),
        },
        "screen_report": burn["report"],
        "corrections": [
            {
                "face": "results/e43_tilt_4member/TILT3SIGNNAMES-20261027.json",
                "field": "eras.*.flip_survival",
                "issue": ("E174 read both of its drop points off the "
                          "decomposition's own era levels, whose offset from the "
                          "published levels is up to %.1fbp -- larger than the "
                          "delta being attributed. Its 'gone at top1, back at "
                          "top5' pair is therefore a property of that base, not "
                          "of the carriers."
                          % (max(gaps) if gaps else 0.0)),
                "corrected_reading": (
                    "anchored on the published levels, 2024_now's disagreement "
                    "survives every rung inside its own delta span and only "
                    "breaks once more than the delta has been removed; the "
                    "published TILT3SIGNNAMES face is frozen as-is and this face "
                    "is the reading to quote"),
                "discovered_by": "this leg's k=0 verdict disagreeing with the "
                                 "headline on the first cut",
            },
        ],
        "honest": honesty + [
            "the ladder is anchored on the published era levels and every rung "
            "removes one carrier's contribution from both arms, so k=0 IS the "
            "headline and every later rung is auditable arithmetic",
            "the unanchored decomposition base is published beside it because "
            "the gap between the two bases is larger than the delta on some "
            "eras; where that gap alone flips a sign, a verdict read off the "
            "unanchored base says nothing about the carriers",
            "a returning verdict is not a defect: it says the two arms' signs "
            "were separated by a small set of name-months, which is exactly what "
            "a two-point sample could not show",
            "the ladder is published with its delta coverage because past 100% "
            "it is eroding more than the delta, and a verdict read there is "
            "about the eroded books, not about the repair",
            "eras whose engine level did not move are the built-in control: a "
            "ladder that is not flat there is broken before it reads anything",
        ],
    }


def run_tilt3signnames(outdir, mode="neutralise_int", eras=ERAS):
    """E174: attribute E171's engine-column move to names, and test the flip.

    Three things are published per era, because one number cannot answer them:
    the era delta itself (from the two arms' published engine levels), the
    per-name carriers of that delta with their shares, and -- for the eras whose
    engine SIGN flipped -- whether dropping the biggest carrier leaves the flip
    standing. An era whose flip depends on one name-month is a data-repair
    story; an era that keeps its flip without it is a property of the books.
    """
    burn = _tilt3signname_burn(mode, eras)
    cutoff, report = burn["cutoff"], burn["report"]
    core_raw, core_scr = burn["core_raw"], burn["core_scr"]
    net_raw, net_scr = burn["net_raw"], burn["net_scr"]
    arm_raw, arm_scr = burn["arm_raw"], burn["arm_scr"]

    rows = {}
    honesty = []
    for name, lo, hi in list(eras) + [("full", None, None)]:
        ms = _era_engine_months(core_raw, lo, hi)
        ms_scr = _era_engine_months(core_scr, lo, hi)
        a = (arm_raw.get("eras") or {}).get(name) or {}
        b = (arm_scr.get("eras") or {}).get(name) or {}
        eng_raw = a.get("engine_mean_ann_bp")
        eng_scr = b.get("engine_mean_ann_bp")
        if not ms or eng_raw is None or eng_scr is None:
            rows[name] = {"months": len(ms),
                          "skipped": "no engine level on one arm for this era"}
            continue
        split, raw_bp, scr_bp = _era_name_split(net_raw, net_scr, ms)
        ranked = sorted(split.items(), key=lambda kv: -abs(kv[1]))
        delta = round(eng_scr - eng_raw, 3)
        explained = round(sum(v for _, v in ranked), 6)
        top = []
        for s, v in ranked[:TILT3SIGNNAMES_TOP]:
            months_hit = []
            for (m, nm), val in net_scr.items():
                if nm == s and m in set(ms):
                    d = val - net_raw.get((m, nm), 0.0)
                    if d:
                        months_hit.append({"month": m, "delta_bp": round(
                            d * 12.0 / len(ms) * 1e4, 2)})
            months_hit.sort(key=lambda r: -abs(r["delta_bp"]))
            top.append({
                "name": s,
                "delta_bp": round(v, 2),
                "share_of_era_delta_pct": (round(v / delta * 100.0, 1)
                                           if abs(delta) > 1e-9 else None),
                "raw_heap_bp": round(raw_bp.get(s, 0.0), 2),
                "screened_heap_bp": round(scr_bp.get(s, 0.0), 2),
                "worst_months": months_hit[:TILT3SIGNNAMES_MONTHS_PER_NAME],
            })
        sign_raw = _pair_sign(eng_raw)
        sign_scr = _pair_sign(eng_scr)
        flipped = sign_raw != sign_scr
        # an era whose level did not move has no delta to attribute: naming a
        # "top carrier" there would print a name beside a zero and read as a
        # finding, so the carrier list is emptied and the reason is published
        moved_era = abs(delta) > 0.05
        if not moved_era:
            top = []
        drop = {}
        if flipped:
            raw_lvl = sum(raw_bp.values())
            scr_lvl = sum(scr_bp.values())
            for label, names in (("top1", [ranked[0][0]] if ranked else []),
                                 ("top%d" % TILT3SIGNNAMES_TOP,
                                  [s for s, _ in ranked[:TILT3SIGNNAMES_TOP]])):
                if not names:
                    continue
                r_after = raw_lvl - sum(raw_bp.get(s, 0.0) for s in names)
                s_after = scr_lvl - sum(scr_bp.get(s, 0.0) for s in names)
                drop[label] = {
                    "names_dropped": names,
                    "raw_engine_bp_after": round(r_after, 2),
                    "screened_engine_bp_after": round(s_after, 2),
                    "verdict_flip_survives": _pair_sign(r_after) != _pair_sign(s_after),
                }
        rows[name] = {
            "months": len(ms),
            "months_screened": len(ms_scr),
            "months_same": len(ms) == len(ms_scr),
            "engine_bp_raw": eng_raw,
            "engine_bp_screened": eng_scr,
            "engine_bp_delta": delta,
            "engine_sign_raw": sign_raw,
            "engine_sign_screened": sign_scr,
            "engine_sign_flipped": flipped,
            "names_carrying_delta": len([1 for _, v in ranked if abs(v) >= 0.05]),
            "delta_from_names_bp": explained,
            "attribution_residual_bp": round(delta - explained, 6),
            "carriers": top,
            "carriers_note": (None if moved_era else
                              "the engine level is identical on both arms for this "
                              "era, so there is no delta to attribute"),
            "coverage": _carrier_coverage(ranked, delta),
            "flip_survival": drop or None,
        }
        if abs(delta - explained) > 1.0:
            honesty.append("%s: the named carriers add to %.1fbp against a %.1fbp "
                           "delta, so the residual is quoted, not zeroed"
                           % (name, explained, delta))

    measured = {k: v for k, v in rows.items() if "engine_bp_delta" in v}
    moved = sorted(k for k, v in measured.items() if abs(v["engine_bp_delta"] or 0) > 0.05)
    flips = sorted(k for k, v in measured.items() if v["engine_sign_flipped"])
    single_name = sorted(k for k, v in measured.items()
                         if v["carriers"] and (v["carriers"][0]["share_of_era_delta_pct"]
                                               or 0) >= 50.0)
    survives = {k: (v["flip_survival"] or {}).get("top1", {}).get(
        "verdict_flip_survives") for k, v in measured.items() if v["engine_sign_flipped"]}
    return {
        "study": "e174_tilt3sign_engine_move_names",
        "evidence_cutoff": cutoff,
        "spec": {
            "screen_mode": mode,
            "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
            "engine_series": "wide monthly return minus ladder monthly return",
            "decomposition": (
                "every day's w*r is booked per (month, symbol) inside e27.simulate "
                "(contrib seam) for BOTH books, then net = wide - ladder; a name "
                "held by both books nets out, the cash residual keeps __cash__"),
            "units": "annualised bp of the era (mean monthly x 12 x 1e4)",
            "carriers_named_per_era": TILT3SIGNNAMES_TOP,
            "covers_pct": list(TILT3SIGNNAMES_COVERS),
            "flip_test": ("drop the biggest carrier (and the top set) from BOTH "
                          "arms' engine levels and re-read the era sign verdict"),
        },
        "eras": rows,
        "answers": {
            "eras_measured": len(measured),
            "eras_where_engine_moved": len(moved),
            "era_names_where_engine_moved": moved,
            "eras_where_engine_sign_flipped": flips,
            "eras_where_delta_is_one_name": single_name,
            "flips_surviving_dropping_top_carrier": survives,
            "all_flips_survive_top1": (all(bool(v) for v in survives.values())
                                      if survives else None),
            "max_top_carrier_share_pct": max(
                [v["carriers"][0]["share_of_era_delta_pct"]
                 for v in measured.values() if v["carriers"]
                 and v["carriers"][0]["share_of_era_delta_pct"] is not None]
                or [None]),
            "max_abs_attribution_residual_bp": max(
                [abs(v["attribution_residual_bp"]) for v in measured.values()
                 if v["attribution_residual_bp"] is not None] or [None]),
        },
        "screen_report": report,
        "honest": [
            "the decomposition is arithmetic, not a story: contributions are the "
            "same w*r terms the engine curve compounds, so the named carriers plus "
            "the residual reconstruct the published delta",
            "the residual is quoted per era because daily compounding inside a "
            "month is not additive; a residual near zero is expected and a large "
            "one means the attribution is broken",
            "a single-name share above 50% is a disclosure, not a defect: it says "
            "the era's move is one name-month, which a reader must know before "
            "quoting the era",
            "dropping a carrier is a counterfactual, not a repair: the published "
            "engine levels are untouched",
            "the ladder leg is a fixed 5-name book, so a name that appears in both "
            "books contributes only the difference of its two weights",
        ] + honesty,
    }


# ---------------------------------------------------------------- E176
TILT3BOOKSPLIT_TOP = 3       # names reprinted per book
TILT3BOOKSPLIT_MOVED_BP = 0.05   # below this a book did not move (same tol as E174)


def _era_book_split(sides_raw, sides_scr, months):
    """(E176) per-name annualised bp for EACH book, raw and screened.

    ``sides_raw``/``sides_scr`` are ``core["contrib"]`` dicts (keys "wide" and
    "lad"). E174 nets the two books before naming carriers, which is why its
    table cannot say which book moved; nothing here is a second engine pass --
    the same w*r records are read once per side and kept apart.
    """
    out = {}
    for side in ("wide", "lad"):
        raw_bp = _era_side_bp((sides_raw or {}).get(side) or {}, months)
        scr_bp = _era_side_bp((sides_scr or {}).get(side) or {}, months)
        delta = {s: scr_bp.get(s, 0.0) - raw_bp.get(s, 0.0)
                 for s in set(raw_bp) | set(scr_bp)}
        out[side] = {
            "raw_level_bp": sum(raw_bp.values()),
            "screened_level_bp": sum(scr_bp.values()),
            "delta_bp": sum(delta.values()),
            "names_moved": sorted((s for s, v in delta.items()
                                   if abs(v) > TILT3BOOKSPLIT_MOVED_BP),
                                  key=lambda s: -abs(delta[s])),
            "per_name_delta_bp": delta,
        }
    return out


def _book_move_verdict(wide_delta_bp, ladder_delta_bp, tol=None):
    """(E176) which of the two held books the repair actually moved.

    The engine column is ``wide - ladder``, so a reader who sees "the wide book
    moved" cannot tell whether the fixed ladder leg moved instead and the sign
    of the difference carried the story. Both deltas are published and the
    verdict is a word, because "0.4bp on the ladder side" beside a 47bp engine
    delta is a disclosure, not a cause.
    """
    t = TILT3BOOKSPLIT_MOVED_BP if tol is None else float(tol)
    wide_moved = abs(wide_delta_bp or 0.0) > t
    lad_moved = abs(ladder_delta_bp or 0.0) > t
    if wide_moved and lad_moved:
        return "both"
    if wide_moved:
        return "wide_only"
    if lad_moved:
        return "ladder_only"
    return "neither"


def run_tilt3booksplit(outdir, mode="neutralise_int", eras=ERAS):
    """E176: split the engine column's repair delta BY BOOK, not by name.

    E174 named the carriers of the era delta, but every carrier there is a net
    of two held books. The question a reader of E171/E174 cannot answer is
    which book moved: if the fixed five-name ladder leg is what the repair
    re-priced, then "the wide book won 2024_now" is the wrong sentence even
    though every number in it is right.

    The decomposition levels are published beside the compounded published
    levels and their offset, because E175 measured that offset at 52.9bp on
    2024_now -- larger than the 46.7bp delta this table attributes. The offset
    is disclosed here and left unexplained (E177 owns that); what this leg
    asserts is that the two books' deltas reconstruct the DELTA, which is the
    quantity every verdict in this family quotes.
    """
    burn = _tilt3signname_burn(mode, eras)
    cutoff, report = burn["cutoff"], burn["report"]
    core_raw, core_scr = burn["core_raw"], burn["core_scr"]
    arm_raw, arm_scr = burn["arm_raw"], burn["arm_scr"]
    sides_raw = (core_raw.get("contrib") or {})
    sides_scr = (core_scr.get("contrib") or {})
    # why the fixed leg does or does not move: derived from the screen report, not
    # asserted, so 'the ladder is untouched' is a cause and not a lucky zero
    import e24_ladder_weighting as base
    _neutralised = sorted({d.get("name") for d in (report.get("names") or [])
                           if d.get("action") == "neutralise"
                           or (d.get("events") or 0) > 0})
    ladder_neutralised = [s for s in _neutralised if s in set(base.LADDER)]

    rows = {}
    for name, lo, hi in list(eras) + [("full", None, None)]:
        ms = _era_engine_months(core_raw, lo, hi)
        a = (arm_raw.get("eras") or {}).get(name) or {}
        b = (arm_scr.get("eras") or {}).get(name) or {}
        eng_raw, eng_scr = a.get("engine_mean_ann_bp"), b.get("engine_mean_ann_bp")
        if not ms or eng_raw is None or eng_scr is None:
            rows[name] = {"months": len(ms),
                          "skipped": "no engine level on one arm for this era"}
            continue
        books = _era_book_split(sides_raw, sides_scr, ms)
        wide, lad = books["wide"], books["lad"]
        dec_raw = wide["raw_level_bp"] - lad["raw_level_bp"]
        dec_scr = wide["screened_level_bp"] - lad["screened_level_bp"]
        wide_delta, lad_delta = wide["delta_bp"], lad["delta_bp"]
        delta_dec = dec_scr - dec_raw
        delta_pub = round(eng_scr - eng_raw, 6)
        moved = abs(delta_pub) > TILT3BOOKSPLIT_MOVED_BP
        top = {}
        for side in ("wide", "lad"):
            pk = books[side]["per_name_delta_bp"]
            top[side] = [{
                "name": s,
                "delta_bp": round(pk[s], 2),
                "share_of_own_book_delta_pct": (
                    round(pk[s] / books[side]["delta_bp"] * 100.0, 1)
                    if abs(books[side]["delta_bp"]) > 1e-9 else None),
            } for s in books[side]["names_moved"][:TILT3BOOKSPLIT_TOP]]
        rows[name] = {
            "months": len(ms),
            "published_engine_bp_raw": eng_raw,
            "published_engine_bp_screened": eng_scr,
            "engine_bp_delta": delta_pub,
            "wide_book_bp_raw": round(wide["raw_level_bp"], 2),
            "wide_book_bp_screened": round(wide["screened_level_bp"], 2),
            "wide_book_delta_bp": round(wide_delta, 3),
            "ladder_book_bp_raw": round(lad["raw_level_bp"], 2),
            "ladder_book_bp_screened": round(lad["screened_level_bp"], 2),
            "ladder_book_delta_bp": round(lad_delta, 3),
            "wide_share_of_engine_delta_pct": (
                round(wide_delta / delta_dec * 100.0, 1)
                if abs(delta_dec) > 1e-9 else None),
            "ladder_share_of_engine_delta_pct": (
                round(-lad_delta / delta_dec * 100.0, 1)
                if abs(delta_dec) > 1e-9 else None),
            "decomposition_engine_bp_raw": round(dec_raw, 2),
            "decomposition_engine_bp_screened": round(dec_scr, 2),
            "decomposition_level_offset_bp": {
                "raw": round(dec_raw - eng_raw, 2),
                "screened": round(dec_scr - eng_scr, 2),
            },
            "engine_delta_from_books_bp": round(delta_dec, 3),
            "engine_delta_residual_bp": round(delta_pub - delta_dec, 3),
            "which_book_moved": _book_move_verdict(wide_delta, lad_delta),
            "wide_names_moved": len(wide["names_moved"]),
            "ladder_names_moved": len(lad["names_moved"]),
            "top_names_by_book": top,
            "drivers_note": (None if moved else
                             "the engine level is identical on both arms for this "
                             "era, so there is no delta to split"),
        }

    measured = {k: v for k, v in rows.items() if "engine_bp_delta" in v}
    moved = sorted(k for k, v in measured.items()
                   if abs(v["engine_bp_delta"] or 0) > TILT3BOOKSPLIT_MOVED_BP)
    verds = {k: v["which_book_moved"] for k, v in measured.items()}
    lad_only = sorted(k for k, w in verds.items() if w == "ladder_only")
    wide_only = sorted(k for k, w in verds.items() if w == "wide_only")
    flat = sorted(k for k in measured if k not in moved)
    flat_ok = all(abs(measured[k]["wide_book_delta_bp"]) <= TILT3BOOKSPLIT_MOVED_BP
                  and abs(measured[k]["ladder_book_delta_bp"]) <= TILT3BOOKSPLIT_MOVED_BP
                  for k in flat)
    offsets = [abs(v["decomposition_level_offset_bp"]["raw"])
               for v in measured.values()] + \
              [abs(v["decomposition_level_offset_bp"]["screened"])
               for v in measured.values()]
    residuals = [abs(v["engine_delta_residual_bp"]) for v in measured.values()]
    return {
        "study": "e176_tilt3_engine_move_book_split",
        "evidence_cutoff": cutoff,
        "spec": {
            "screen_mode": mode,
            "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
            "engine_series": "wide monthly return minus ladder monthly return",
            "book_split": (
                "each book's own contrib sink is annualised per era SEPARATELY "
                "(wide and ladder), so the engine delta is rebuilt as "
                "wide_delta - ladder_delta instead of netting the two books "
                "before any attribution"),
            "units": "annualised bp of the era (mean monthly x 12 x 1e4)",
            "moved_tolerance_bp": TILT3BOOKSPLIT_MOVED_BP,
            "names_named_per_book": TILT3BOOKSPLIT_TOP,
            "offset_disclosure": (
                "the decomposition level (sum of daily w*r) is published beside "
                "the compounded published level and their difference is quoted; "
                "only the DELTA is asserted to reconstruct"),
        },
        "eras": rows,
        "answers": {
            "eras_measured": len(measured),
            "eras_where_engine_moved": moved,
            "which_book_moved": verds,
            "eras_moved_by_ladder_only": lad_only,
            "eras_moved_by_wide_only": wide_only,
            "eras_moved_by_both_books": sorted(k for k, w in verds.items()
                                               if w == "both"),
            "eras_where_neither_book_moved": flat,
            "zero_delta_eras_flat_on_both_books": flat_ok,
            "ladder_members_neutralised": ladder_neutralised,
            "ladder_book_untouched_is_structural": not ladder_neutralised,
            "neutralised_names_in_panel": len(_neutralised),
            "max_abs_decomposition_level_offset_bp": (max(offsets) if offsets else None),
            "max_abs_engine_delta_residual_bp": (max(residuals) if residuals else None),
        },
        "screen_report": report,
        "honest": [
            "the split is arithmetic on the same w*r records E174 nets: a name "
            "held by both books appears in both lists and neither list alone "
            "reconstructs the engine delta",
            "the ladder leg is a fixed five-name book, so a ladder-side delta is "
            "the repair re-pricing those five members, not the wide book's "
            "selection changing; whether any of them was neutralised is derived "
            "from the screen report and published beside the zeros",
            "the DELTA is what reproduces here; the LEVELS sit apart by the "
            "compounding offset quoted per era and are not used for any verdict",
            "an era whose engine level did not move is the built-in control: a "
            "book that moved there would mean the split is reading noise",
        ],
    }


# ---------------------------------------------------------------- E179
TILT3LADDERSPLIT_MOVED_BP = TILT3BOOKSPLIT_MOVED_BP   # same 0.05bp tolerance
TILT3LADDERSPLIT_CASH = "__cash__"


def _ladder_side_split(sides_raw, sides_scr, months, members):
    """(E179) the ladder side's LEVELS per holding, raw and screened.

    E176 annualised the ladder side as ONE sum, so its ``ladder_book_delta_bp =
    0.0`` is a net over five members plus the ``__cash__`` residual the leg
    books. This keeps every holding apart and labels it, so a zero can be read
    as five zeros instead of a total. Anything the sink turns up that is neither
    a declared member nor the cash residual is published as ``unlisted`` -- it is
    neither dropped nor allowed to impersonate a security.
    """
    raw_bp = _era_side_bp((sides_raw or {}).get("lad") or {}, months)
    scr_bp = _era_side_bp((sides_scr or {}).get("lad") or {}, months)
    member_set = set(members)
    out = {}
    for s in sorted(set(raw_bp) | set(scr_bp)):
        r, c = raw_bp.get(s, 0.0), scr_bp.get(s, 0.0)
        if s in member_set:
            kind = "member"
        elif s == TILT3LADDERSPLIT_CASH:
            kind = "cash_residual"
        else:
            kind = "unlisted"
        out[s] = {"name": s, "kind": kind, "is_security": kind == "member",
                  "raw_level_bp": r, "screened_level_bp": c, "delta_bp": c - r}
    return out


def _ladder_split_verdict(holdings, tol=None):
    """(E179) net vs gross: a zero SUM and a zero on every holding are two claims.

    A net of zero can be five flips that cancel, and a reader who sees only the
    net cannot tell which happened. The classification is published as a word so
    "the fixed leg did not move" is an auditable per-holding statement.
    """
    t = TILT3LADDERSPLIT_MOVED_BP if tol is None else float(tol)
    deltas = {s: h["delta_bp"] for s, h in holdings.items()}
    net = sum(deltas.values())
    gross = sum(abs(v) for v in deltas.values())
    moved = sorted((s for s, v in deltas.items() if abs(v) > t),
                   key=lambda s: -abs(deltas[s]))
    if not moved:
        cls = "flat_per_holding"
    elif abs(net) <= t:
        cls = "cancelling"
    else:
        cls = "moving"
    return {"net_delta_bp": net, "gross_abs_delta_bp": gross,
            "net_over_gross": (net / gross if gross > 1e-12 else None),
            "names_moved": moved, "classification": cls}


def _ladder_split_join(row, sib, era):
    """(E179) join this split's net side against the E176 ladder book, per era."""
    out = {"era": era, "e176_face": None, "max_abs_diff_bp": None, "checks": {}}
    e176 = ((sib or {}).get("eras") or {}).get(era) or {}
    if not e176:
        out["note"] = "no E176 row for this era on disk; the net side is unjoined"
        return out
    out["e176_face"] = "TILT3SIGNBOOKSPLIT"
    diffs = []
    for key in ("ladder_book_bp_raw", "ladder_book_bp_screened",
                "ladder_book_delta_bp"):
        mine, theirs = row.get(key), e176.get(key)
        if mine is None or theirs is None:
            continue
        d = abs(float(mine) - float(theirs))
        out["checks"][key] = {"this_split": mine, "e176": theirs,
                              "abs_diff_bp": round(d, 6)}
        diffs.append(d)
    out["max_abs_diff_bp"] = round(max(diffs), 6) if diffs else None
    return out


def run_tilt3laddersplit(outdir, mode="neutralise_int", eras=ERAS):
    """E179: split the ladder side into its five members and the cash residual.

    E176 published "the fixed leg never moves" as ``ladder_book_delta_bp = 0.0``
    in every era. That number is a SUM over five members plus a ``__cash__``
    residual which is not a security, so it cannot tell a reader whether each
    holding stayed put or whether two members moved in opposite directions and
    cancelled. Nothing here is a new engine pass: the same w*r records E176
    annualises as one number are kept per holding and published raw+screened.
    """
    burn = _tilt3signname_burn(mode, eras)
    cutoff, report = burn["cutoff"], burn["report"]
    core_raw, core_scr = burn["core_raw"], burn["core_scr"]
    sides_raw = (core_raw.get("contrib") or {})
    sides_scr = (core_scr.get("contrib") or {})
    import e24_ladder_weighting as base
    members = list(base.LADDER)
    _neutralised = sorted({d.get("name") for d in (report.get("names") or [])
                           if d.get("action") == "neutralise"
                           or (d.get("events") or 0) > 0})
    ladder_neutralised = [s for s in _neutralised if s in set(members)]

    # every month the ladder leg booked cash at all: the residual exists only
    # where the fixed book could not be fully held, so the span is the audit trail
    all_cash_months = sorted({m for (m, s) in ((sides_raw or {}).get("lad") or {})
                              if s == TILT3LADDERSPLIT_CASH})
    _lad_all = (sides_raw or {}).get("lad") or {}
    all_full_hold_months = sorted({m for (m, _s) in _lad_all
                                   if all((m, mb) in _lad_all for mb in members)})

    sib = None
    try:
        cand = sorted(f for f in os.listdir(outdir)
                      if f.startswith("TILT3SIGNBOOKSPLIT-") and f.endswith(".json"))
        if cand:
            with open(os.path.join(outdir, cand[-1]), "r", encoding="utf-8") as fh:
                sib = json.load(fh)
    except Exception:
        sib = None

    rows = {}
    for name, lo, hi in list(eras) + [("full", None, None)]:
        ms = _era_engine_months(core_raw, lo, hi)
        if not ms:
            rows[name] = {"months": 0, "skipped": "no months in this era"}
            continue
        hold = _ladder_side_split(sides_raw, sides_scr, ms, members)
        v = _ladder_split_verdict(hold)
        # why the cash residual exists at all: the leg books cash in a month it
        # cannot hold a declared member, so the count is derived, not asserted
        _lad_raw = (sides_raw or {}).get("lad") or {}
        gap_months = sorted({m for m in ms
                             if any((m, mb) not in _lad_raw for mb in members)})
        era_cash_months = sorted({m for (m, s) in _lad_raw
                                  if s == TILT3LADDERSPLIT_CASH and m in set(ms)})
        total_raw = sum(h["raw_level_bp"] for h in hold.values())
        total_scr = sum(h["screened_level_bp"] for h in hold.values())
        total_delta = sum(h["delta_bp"] for h in hold.values())
        cash = hold.get(TILT3LADDERSPLIT_CASH)
        published = []
        for s, h in hold.items():
            published.append({
                "name": s,
                "kind": h["kind"],
                "is_security": h["is_security"],
                "raw_level_bp": round(h["raw_level_bp"], 3),
                "screened_level_bp": round(h["screened_level_bp"], 3),
                "delta_bp": round(h["delta_bp"], 3),
                "share_of_ladder_level_pct": (
                    round(h["raw_level_bp"] / total_raw * 100.0, 2)
                    if abs(total_raw) > 1e-9 else None),
                "moved": abs(h["delta_bp"]) > TILT3LADDERSPLIT_MOVED_BP,
            })
        rows[name] = {
            "months": len(ms),
            "members_declared": members,
            "members_present": sorted(s for s, h in hold.items()
                                      if h["kind"] == "member"),
            "members_missing": sorted(set(members) - set(hold)),
            "months_with_missing_member_bars": len(gap_months),
            "cash_months": len(era_cash_months),
            "cash_month_span": ([era_cash_months[0], era_cash_months[-1]]
                                if era_cash_months else None),
            "unlisted_holdings": sorted(s for s, h in hold.items()
                                        if h["kind"] == "unlisted"),
            "holdings": published,
            "ladder_book_bp_raw": round(total_raw, 3),
            "ladder_book_bp_screened": round(total_scr, 3),
            "ladder_book_delta_bp": round(total_delta, 3),
            "net_delta_bp": round(v["net_delta_bp"], 3),
            "gross_abs_delta_bp": round(v["gross_abs_delta_bp"], 3),
            "net_over_gross": (None if v["net_over_gross"] is None else
                               round(v["net_over_gross"], 4)),
            "ladder_classification": v["classification"],
            "holdings_moved": v["names_moved"],
            "zero_is_flat_not_cancelling": (v["classification"] == "flat_per_holding"),
            "cash_residual_bp_raw": (None if cash is None else
                                     round(cash["raw_level_bp"], 3)),
            "cash_residual_share_of_ladder_level_pct": (
                round(cash["raw_level_bp"] / total_raw * 100.0, 2)
                if cash is not None and abs(total_raw) > 1e-9 else None),
        }
        rows[name]["e176_join"] = _ladder_split_join(rows[name], sib, name)

    measured = {k: v for k, v in rows.items() if "ladder_classification" in v}
    flat = sorted(k for k, v in measured.items()
                  if v["ladder_classification"] == "flat_per_holding")
    cancelling = sorted(k for k, v in measured.items()
                        if v["ladder_classification"] == "cancelling")
    moving = sorted(k for k, v in measured.items()
                    if v["ladder_classification"] == "moving")
    gross_max = max((v["gross_abs_delta_bp"] for v in measured.values()),
                    default=None)
    cash_shares = [abs(v["cash_residual_share_of_ladder_level_pct"])
                   for v in measured.values()
                   if v["cash_residual_share_of_ladder_level_pct"] is not None]
    joins = [v["e176_join"]["max_abs_diff_bp"] for v in measured.values()
             if v["e176_join"] and v["e176_join"]["max_abs_diff_bp"] is not None]
    cash_eras = sorted(k for k, v in measured.items()
                       if v["cash_residual_bp_raw"] is not None)
    missing_eras = sorted(k for k, v in measured.items() if v["members_missing"])
    return {
        "study": "e179_tilt3_ladder_side_per_holding",
        "evidence_cutoff": cutoff,
        "spec": {
            "screen_mode": mode,
            "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
            "side": "ladder (the fixed five-name book) contrib sink, kept per name",
            "units": "annualised bp of the era (mean monthly x 12 x 1e4)",
            "moved_tolerance_bp": TILT3LADDERSPLIT_MOVED_BP,
            "cash_pseudo_name": TILT3LADDERSPLIT_CASH,
            "classification": (
                "flat_per_holding = no holding moved; cancelling = some moved "
                "but the net is under tolerance; moving = the net moved"),
        },
        "eras": rows,
        "answers": {
            "eras_measured": len(measured),
            "eras_flat_per_holding": flat,
            "eras_cancelling": cancelling,
            "eras_moving": moving,
            "all_eras_flat_per_holding": len(flat) == len(measured),
            "max_gross_abs_delta_bp": (None if gross_max is None else round(gross_max, 3)),
            "cash_share_of_ladder_level_pct_range": (
                None if not cash_shares else
                [round(min(cash_shares), 2), round(max(cash_shares), 2)]),
            "ladder_members_neutralised": ladder_neutralised,
            "neutralised_names_in_panel": len(_neutralised),
            "members_present_every_era": all(
                set(v["members_present"]) == set(members) for v in measured.values()),
            "eras_with_missing_members": missing_eras,
            "members_missing_by_era": {k: v["members_missing"]
                                       for k, v in measured.items()
                                       if v["members_missing"]},
            "eras_carrying_cash_residual": cash_eras,
            "first_month_the_whole_fixed_book_could_be_held":
                (all_full_hold_months[0] if all_full_hold_months else None),
            "cash_residual_is_warmup_artifact": (
                bool(all_cash_months) and bool(all_full_hold_months)
                and max(all_cash_months) < min(all_full_hold_months)),
            "cash_months_by_era": {k: v["cash_months"] for k, v in measured.items()},
            "cash_months_total": len(all_cash_months),
            "cash_month_span": ([all_cash_months[0], all_cash_months[-1]]
                                if all_cash_months else None),
            "months_with_missing_member_bars_by_era": {
                k: v["months_with_missing_member_bars"] for k, v in measured.items()},
            "e176_join_max_abs_diff_bp": (None if not joins else round(max(joins), 6)),
        },
        "screen_report": report,
        "honest": [
            "the cash residual is not a security: it is the leg's own leftover, "
            "so its share is published but it is never counted as a member",
            "a zero net with a non-zero gross is a cancellation, not a "
            "measurement of stillness, which is exactly what a single side-level "
            "number could not say",
            "the holdings list is exhaustive for the era: an unlisted key is "
            "published as unlisted rather than folded into the members",
            "levels are annualised sums of the same w*r records E176 nets; the "
            "net side is joined against the E176 face on disk when it is present",
            "a member absent from an era means it had no bar on that arm, which "
            "is disclosed as members_missing and never silently weighted to zero",
        ],
    }


# ---------------------------------------------------------------- E177
TILT3DECOMOFFSET_RESIDUAL_BP = 1.0   # a residual under this is arithmetic noise
TILT3DECOMOFFSET_CLOSED_PCT = 80.0   # (b) explains this much of the offset -> closed
# the published arm face prints engine levels to one decimal, so a rebuild from
# the daily walk can differ from it by up to half that quantum (0.05bp) before
# anything is wrong -- this is the wiring tolerance, not a result tolerance
TILT3DECOMOFFSET_PUB_QUANTUM_BP = 0.051
TILT3DECOMOFFSET_BOOK_ROUND_BP = 0.01  # the book offsets are printed to 2dp


def _daily_rets(curve):
    """[(YYYY-MM-DD, return)] from an equity curve's own day-over-day marks."""
    out = []
    for i in range(1, len(curve)):
        prev, cur = curve[i - 1][1], curve[i][1]
        if prev:
            out.append((curve[i][0], cur / prev - 1.0))
    return out


def _month_daily_rets(daily):
    """{YYYY-MM: [daily return, ...]} -- the days behind each monthly return."""
    out = {}
    for d, r in daily:
        out.setdefault(d[:7], []).append(r)
    return out


def _compound(xs):
    p = 1.0
    for r in xs:
        p *= (1.0 + r)
    return p - 1.0


def _tilt3decom_blocks(daily_wide, daily_lad, months):
    """(E177) three readings of one month, for each book and for the engine column.

    (a) is the arithmetic sum of the daily terms -- what the per-name
    decomposition publishes. (b) compounds those same daily terms inside the
    month. (c) is the published object: each book compounded on its own and the
    engine column taken as the difference of the two compounded month returns.

    At BOOK level (b) and (c) coincide by construction, so a book's level offset
    is compounding and nothing else. At ENGINE level they do not -- compounding a
    difference is not the difference of two compoundings -- and the gap between
    them is the cross term this leg publishes.
    """
    dw = _month_daily_rets(daily_wide)
    dl = _month_daily_rets(daily_lad)
    out = {"wide": [], "lad": [], "engine": [], "months_skipped": []}
    for m in months:
        w = dw.get(m) or []
        l = dl.get(m) or []
        # the two books share one calendar, so a length mismatch means a month
        # edge was cut differently -- skipped and counted, never silently paired
        if not w or not l or len(w) != len(l):
            out["months_skipped"].append(m)
            continue
        d = [a - b for a, b in zip(w, l)]
        out["wide"].append({"month": m, "a": sum(w), "b": _compound(w)})
        out["lad"].append({"month": m, "a": sum(l), "b": _compound(l)})
        out["engine"].append({"month": m, "a": sum(d), "b": _compound(d),
                              "c": _compound(w) - _compound(l)})
    return out


def _ann_bp(xs):
    """Annualised bp of a monthly-return series, or None when empty."""
    xs = [x for x in xs if x is not None]
    if not xs:
        return None
    return round(sum(xs) / len(xs) * 12.0 * 1e4, 4)


def run_tilt3decompoffset(outdir, mode="neutralise_int", eras=ERAS):
    """E177: quantify and explain the decomposition's era-level offset.

    E175 measured the offset (decomposition level minus published level) at up
    to 55.8bp -- larger than the 46.7bp delta it was used to attribute -- and
    called it "the compounding gap" on the strength of the note, not on a
    measurement. E176 quoted the same offset and explicitly left it unexplained.
    This leg measures it three ways per era and per book, so the sentence in
    E174/E175/E176 can either keep using these levels with a stated tolerance or
    must anchor every name-level leg.
    """
    burn = _tilt3signname_burn(mode, eras)
    cutoff = burn["cutoff"]
    core_raw, core_scr = burn["core_raw"], burn["core_scr"]
    arm_raw, arm_scr = burn["arm_raw"], burn["arm_scr"]
    curves = {"raw": core_raw["curves"], "screened": core_scr["curves"]}
    wide_name = core_raw["wide_name"]

    rows = {}
    for arm, core, armmap in (("raw", core_raw, arm_raw),
                              ("screened", core_scr, arm_scr)):
        dw = _daily_rets(curves[arm][wide_name])
        dl = _daily_rets(curves[arm]["ladder5"])
        for name, lo, hi in list(eras) + [("full", None, None)]:
            ms = _era_engine_months(core, lo, hi)
            a_face = (armmap.get("eras") or {}).get(name) or {}
            pub = a_face.get("engine_mean_ann_bp")
            row = rows.setdefault("%s|%s" % (arm, name), {"arm": arm, "era": name})
            row["months"] = len(ms)
            if not ms or pub is None:
                row["skipped"] = "no engine level on this arm for this era"
                continue
            blk = _tilt3decom_blocks(dw, dl, ms)
            eng = blk["engine"]
            a_bp = _ann_bp([x["a"] for x in eng])
            b_bp = _ann_bp([x["b"] for x in eng])
            c_bp = _ann_bp([x["c"] for x in eng])
            wa = _ann_bp([x["a"] for x in blk["wide"]])
            wb = _ann_bp([x["b"] for x in blk["wide"]])
            la = _ann_bp([x["a"] for x in blk["lad"]])
            lb = _ann_bp([x["b"] for x in blk["lad"]])
            offset = None if None in (c_bp, a_bp) else round(c_bp - a_bp, 2)
            step = None if None in (b_bp, a_bp) else round(b_bp - a_bp, 2)
            resid = None if None in (c_bp, b_bp) else round(c_bp - b_bp, 2)
            explained = (round(step / offset * 100.0, 1)
                         if offset and abs(offset) > 1e-9 and step is not None
                         else None)
            if offset is None:
                verdict = "undefined"
            elif abs(resid) <= TILT3DECOMOFFSET_RESIDUAL_BP:
                verdict = "compounding_closes_it"
            elif explained is not None and explained >= TILT3DECOMOFFSET_CLOSED_PCT:
                verdict = "compounding_explains_most"
            else:
                verdict = "cross_term_remains"
            row.update({
                "published_engine_bp": pub,
                "decomposition_engine_bp": a_bp,
                "compounded_difference_engine_bp": b_bp,
                "published_rebuilt_from_days_bp": c_bp,
                "published_rebuild_residual_bp": (
                    None if c_bp is None else round(c_bp - pub, 4)),
                "level_offset_bp": offset,
                "offset_added_by_compounding_the_difference_bp": step,
                "offset_left_as_cross_term_bp": resid,
                "offset_explained_by_compounding_pct": explained,
                "verdict": verdict,
                "wide_book_arithmetic_bp": wa,
                "wide_book_compounded_bp": wb,
                "wide_book_level_offset_bp": (
                    None if None in (wb, wa) else round(wb - wa, 2)),
                "ladder_book_arithmetic_bp": la,
                "ladder_book_compounded_bp": lb,
                "ladder_book_level_offset_bp": (
                    None if None in (lb, la) else round(lb - la, 2)),
                "book_level_offset_is_compounding_only": True,
                "months_with_unpaired_days": blk["months_skipped"],
            })

    measured = {k: v for k, v in rows.items() if "level_offset_bp" in v}
    offsets = {k: v["level_offset_bp"] for k, v in measured.items()}
    resid = {k: v["offset_left_as_cross_term_bp"] for k, v in measured.items()
             if v["offset_left_as_cross_term_bp"] is not None}
    verdicts = {}
    for k, v in measured.items():
        verdicts.setdefault(v["verdict"], []).append(k)
    rebuild = [abs(v["published_rebuild_residual_bp"]) for v in measured.values()
               if v["published_rebuild_residual_bp"] is not None]
    # the discriminating check: at book level (b) and (c) are the same number by
    # construction, so any book offset that is NOT compounding means the daily
    # walk and the month walk disagree about the calendar
    book_gap = []
    for v in measured.values():
        for side in ("wide", "ladder"):
            a_ = v.get("%s_book_arithmetic_bp" % side)
            b_ = v.get("%s_book_compounded_bp" % side)
            o_ = v.get("%s_book_level_offset_bp" % side)
            if None not in (a_, b_, o_) and abs((b_ - a_) - o_) > TILT3DECOMOFFSET_BOOK_ROUND_BP:
                book_gap.append("%s|%s|%s" % (v["arm"], v["era"], side))
    return {
        "study": "e177_tilt3_decomposition_level_offset",
        "evidence_cutoff": cutoff,
        "spec": {
            "screen_mode": mode,
            "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
            "arms": ["raw", "screened"],
            "readings": {
                "a_decomposition": "sum over months of sum of daily w*r terms",
                "b_compounded_difference": ("sum over months of the daily "
                                            "difference compounded inside the month"),
                "c_published": ("sum over months of (wide monthly return - "
                                "ladder monthly return), each compounded on its own"),
            },
            "units": "annualised bp of the era (mean monthly x 12 x 1e4)",
            "residual_tolerance_bp": TILT3DECOMOFFSET_RESIDUAL_BP,
            "closed_threshold_pct": TILT3DECOMOFFSET_CLOSED_PCT,
            "published_face_quantum_bp": TILT3DECOMOFFSET_PUB_QUANTUM_BP,
        },
        "eras": rows,
        "answers": {
            "offsets_bp": offsets,
            "max_abs_offset_bp": (max(abs(x) for x in offsets.values())
                                  if offsets else None),
            "max_abs_offset_row": (max(offsets, key=lambda k: abs(offsets[k]))
                                   if offsets else None),
            "residuals_bp": resid,
            "max_abs_residual_bp": (max(abs(x) for x in resid.values())
                                    if resid else None),
            "verdict_counts": {k: len(v) for k, v in sorted(verdicts.items())},
            "verdicts": verdicts,
            "compounding_closes_it_everywhere": (
                bool(verdicts) and set(verdicts) == {"compounding_closes_it"}),
            "published_level_rebuilt_from_days": (bool(rebuild)
                                                  and max(rebuild)
                                                  <= TILT3DECOMOFFSET_PUB_QUANTUM_BP),
            "max_abs_published_rebuild_residual_bp": (max(rebuild) if rebuild
                                                      else None),
            "book_level_offsets_are_compounding_only": not book_gap,
            "book_level_mismatches": book_gap,
        },
        "honest": [
            "at BOOK level (b) and (c) are the same computation, so 'the book "
            "offset is compounding' is an identity, not a finding; the finding "
            "is what is left at ENGINE level once that identity is subtracted",
            "a book whose daily walk and month walk disagree is reported in "
            "book_level_mismatches instead of being netted into the engine "
            "residual -- a calendar edge must not look like a cross term",
            "(c) is rebuilt from the same curves the published arm face reads, "
            "so published_level_rebuilt_from_days is a wiring check, not a "
            "second opinion on the level",
            "this leg changes no published level: it says whether the "
            "decomposition may be quoted for levels, and at what tolerance",
        ],
    }


# ---------------------------------------------------------------- E178
# a pinned leg either carries a repaired member or it cannot move at all; the
# two branches are NAMED rather than left to a zero reading
TILT3LEGFAMILY_MOVED_BP = TILT3BOOKSPLIT_MOVED_BP
TILT3LEGFAMILY_SKINS = (
    ("tilt5", TILT_LARGE, TILT_SMALL, "the published five-member tilt"),
    ("tilt4", TILT_LARGE, TILT4_SMALL, "reach-back to 2021: drops sh588000"),
    ("tilt3", TILT_LARGE, TILT3_SMALL,
     "reach-back to 2013: sh510500 alone on the small leg"),
)


def _member_era_delta_bp(mem_raw, mem_scr, months):
    """(E178) per-member annualised bp of (screened - raw) monthly return.

    A month is used only when BOTH arms price it. Reading a missing screened
    month as a zero return would manufacture a large negative delta on a name
    the repair never touched, and that is exactly the quantity this leg reports.
    """
    n = len(months)
    if not n:
        return {}
    scale = 12.0 * 1e4    # mean monthly difference -> annualised bp
    out = {}
    for s in sorted(set(mem_raw) | set(mem_scr)):
        r = mem_raw.get(s) or {}
        c = mem_scr.get(s) or {}
        vals = [(c[m] - r[m]) for m in months if m in r and m in c]
        out[s] = (sum(vals) / len(vals) * scale) if vals else None
    return out


def _leg_delta_bp(deltas, members):
    """(E178) one leg's average member delta; None when no member is priced."""
    vals = [deltas.get(s) for s in members]
    vals = [v for v in vals if v is not None]
    return (sum(vals) / len(vals)) if vals else None


def _pinned_leg_verdict(members_neutralised, max_abs_member_delta_bp, tol=None):
    """(E178) WHY a pinned leg is flat: no event, or an event that did not show.

    'the fixed leg never moves' is a mechanism only when the membership set is
    disjoint from the repaired names. A leg that holds a repaired member and
    still prints zero is a different, and more suspicious, statement.
    """
    t = TILT3LEGFAMILY_MOVED_BP if tol is None else float(tol)
    if members_neutralised:
        moved = (max_abs_member_delta_bp is not None
                 and max_abs_member_delta_bp > t)
        return "carries_repair_event_moved" if moved else \
            "carries_repair_event_flat"
    return "pinned_no_repair_event"


def run_tilt3legfamily(outdir, mode="neutralise_int", eras=ERAS):
    """E178: is 'the fixed leg never moves' a family law or one 5-name book?

    E176 split the engine column's repair delta by book and found the ladder leg
    at exactly 0.0 in every era, because none of its five members appears in the
    screen report. That is a property of a MEMBERSHIP SET, not of the family:
    every pinned skin built from the same names reads zero for the same reason,
    and a book that rotates its members is not covered by the claim at all.
    This leg prices each pinned skin's two legs member by member and puts the
    rotating wide book beside them, so the scope of the invariant is published
    instead of inherited from a single 5-name reading.
    """
    burn = _tilt3signname_burn(mode, eras)
    cutoff, report = burn["cutoff"], burn["report"]
    core_raw, core_scr = burn["core_raw"], burn["core_scr"]
    sides_raw = (core_raw.get("contrib") or {})
    sides_scr = (core_scr.get("contrib") or {})
    neutralised = sorted({d.get("name") for d in (report.get("names") or [])
                          if d.get("action") == "neutralise"
                          or (d.get("events") or 0) > 0})
    nset = set(neutralised)
    mem_raw = core_raw.get("mem") or {}
    mem_scr = core_scr.get("mem") or {}
    skin_months = {
        "tilt5": core_raw.get("months") or [],
        "tilt4": core_raw.get("months4") or [],
        "tilt3": core_raw.get("months3") or [],
    }

    rows = {}
    for name, lo, hi in list(eras) + [("full", None, None)]:
        ms = _era_engine_months(core_raw, lo, hi)
        a = (burn["arm_raw"].get("eras") or {}).get(name) or {}
        b = (burn["arm_scr"].get("eras") or {}).get(name) or {}
        eng_raw, eng_scr = a.get("engine_mean_ann_bp"), b.get("engine_mean_ann_bp")
        skins = {}
        for skin, large, small, note in TILT3LEGFAMILY_SKINS:
            sm = [m for m in skin_months[skin] if _in_era(m, lo, hi)]
            deltas = _member_era_delta_bp(mem_raw, mem_scr, sm)
            members = list(large) + list(small)
            lg = _leg_delta_bp(deltas, large)
            sg = _leg_delta_bp(deltas, small)
            per = {s: (None if deltas.get(s) is None
                       else round(deltas[s], 6)) for s in members}
            vals = [abs(v) for v in per.values() if v is not None]
            absmax = max(vals) if vals else None
            hit = [s for s in members if s in nset]
            skins[skin] = {
                "note": note,
                "months": len(sm),
                "large_leg": list(large),
                "small_leg": list(small),
                "members_neutralised": hit,
                "per_member_delta_bp": per,
                "large_leg_avg_delta_bp": (None if lg is None
                                           else round(lg, 6)),
                "small_leg_avg_delta_bp": (None if sg is None
                                           else round(sg, 6)),
                "spread_avg_delta_bp": (None if lg is None or sg is None
                                        else round(sg - lg, 6)),
                "max_abs_member_delta_bp": absmax,
                "verdict": _pinned_leg_verdict(hit, absmax),
            }
        wide = _era_book_split(sides_raw, sides_scr, ms)["wide"] if ms else {}
        rows[name] = {
            "months": len(ms),
            "published_engine_bp_delta": (
                None if eng_raw is None or eng_scr is None
                else round(eng_scr - eng_raw, 6)),
            "skins": skins,
            "rotating_wide_book_delta_bp": (
                round(wide.get("delta_bp"), 3) if wide else None),
            "rotating_wide_names_moved": len(wide.get("names_moved") or []),
        }

    measured = {k: v for k, v in rows.items() if v["months"]}
    pinned_universe = sorted({s for _n, lg, sm, _note in TILT3LEGFAMILY_SKINS
                              for s in list(lg) + list(sm)})
    pinned_hit = sorted(s for s in pinned_universe if s in nset)
    stuck = {k: sorted(sk for sk, s in v["skins"].items()
                       if s["verdict"] == "pinned_no_repair_event")
             for k, v in measured.items()}
    pinned_moved = {k: sorted(sk for sk, s in v["skins"].items()
                              if s["verdict"].startswith("carries_repair_event_moved"))
                    for k, v in measured.items()}
    pinned_moved = {k: v for k, v in pinned_moved.items() if v}
    all_zero = sorted(k for k, v in measured.items()
                      if all(s["verdict"] == "pinned_no_repair_event"
                             for s in v["skins"].values()))
    rotating_moved = sorted(k for k, v in measured.items()
                            if abs(v.get("rotating_wide_book_delta_bp") or 0.0)
                            > TILT3LEGFAMILY_MOVED_BP)
    absmax = [s["max_abs_member_delta_bp"] for v in measured.values()
              for s in v["skins"].values()
              if s["max_abs_member_delta_bp"] is not None]
    scope = ("pinned_membership_only"
             if rotating_moved and not pinned_moved
             else ("family_wide" if not rotating_moved and not pinned_moved
                   else "pinned_leg_moved_too"))
    return {
        "study": "e178_tilt3_fixed_leg_family_scope",
        "evidence_cutoff": cutoff,
        "spec": {
            "screen_mode": mode,
            "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
            "skins": [{"skin": s, "large": list(lg), "small": list(sm),
                       "note": note} for s, lg, sm, note in TILT3LEGFAMILY_SKINS],
            "units": "annualised bp (mean monthly x 12 x 1e4)",
            "member_delta": (
                "per-member annualised mean of (screened monthly return - raw "
                "monthly return) on the months BOTH arms price"),
            "leg_delta": "the equal-weight average of that leg's member deltas",
            "rotating_book": (
                "the wide book's own contribution sink (E176 path) is published "
                "beside the pinned skins: it is the one book in this family whose "
                "membership turns over, so it is the control for whether the "
                "invariant can be read as a family law"),
            "moved_tolerance_bp": TILT3LEGFAMILY_MOVED_BP,
        },
        "eras": rows,
        "answers": {
            "eras_measured": len(measured),
            "pinned_universe": pinned_universe,
            "pinned_universe_neutralised": pinned_hit,
            "pinned_membership_disjoint_from_repaired": not pinned_hit,
            "neutralised_names_in_panel": len(neutralised),
            "eras_all_pinned_skins_flat": all_zero,
            "eras_where_a_pinned_skin_moved": pinned_moved,
            "eras_where_rotating_wide_book_moved": rotating_moved,
            "skins_flat_per_era": stuck,
            "max_abs_pinned_member_delta_bp": (max(absmax) if absmax else None),
            "invariant_scope": scope,
        },
        "screen_report": report,
        "honest": [
            "the invariant is a statement about MEMBERSHIP: a leg cannot move if "
            "none of its names carries a repair event, and every pinned skin here "
            "is built from the same five ladder names, so their zeros are one "
            "fact reported three times, not three independent confirmations",
            "the rotating wide book is the control, not a rival reading: it holds "
            "names the repair does touch, and it is the only book in this family "
            "whose delta can be nonzero",
            "the mid-month and pair books re-subset the same ladder leg for their "
            "fixed side, so they inherit this scope rather than extend it",
            "a pinned skin that printed zero WHILE holding a repaired member would "
            "be a wiring defect (verdict carries_repair_event_flat) and is named "
            "rather than folded into the invariant",
            "per-member deltas are price-return differences on member months; a "
            "month priced on one arm only is dropped, never treated as a zero "
            "return",
        ],
    }


def run_tilt4screened(outdir, mode="neutralise_int", eras=ERAS, resume=True):
    """E124: re-derive the E43 four-member tilt face on the screened arm.

    Same machinery as E112-E123: one load, both arms burned off it, per-arm
    checkpoints, the shared ``_burnin_pair_rows`` join, a same-arm control that
    must read zero, and a cutoff control against the newest published raw face.

    The question this leg answers is narrower than "did the numbers move": it is
    WHICH ERA moved. Tilt4's whole content is a per-era attribution, so a repair
    that shifts every era by a constant leaves the ranking intact while a repair
    that shifts one era rewrites the attribution -- and the summary max delta
    cannot tell those apart.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]
    tag = cutoff.replace("-", "")

    def cached(label, thunk):
        p = os.path.join(outdir or ".", "TILT4-arm-%s-%s.json" % (label, tag))
        if resume and os.path.isfile(p):
            try:
                with open(p, "r", encoding="utf-8") as fh:
                    return json.load(fh)
            except Exception:
                pass
        face = thunk()
        if outdir:
            write_json(outdir, "TILT4-arm-%s-%s.json" % (label, tag), face)
        return face

    screened, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)

    raw_arm = cached("raw", lambda: run_tilt4(None, raw=raw, eras=eras))
    scr_arm = cached(mode, lambda: run_tilt4(None, raw=screened, eras=eras))

    keys = sorted({k[0] for k in _tilt4_arm_cells(raw_arm)})
    pair = _burnin_pair_rows(raw_arm, scr_arm, keys,
                             cells_fn=_tilt4_arm_cells,
                             dates_fn=_tilt4_arm_dates)
    control = _burnin_pair_rows(raw_arm, raw_arm, keys,
                                cells_fn=_tilt4_arm_cells,
                                dates_fn=_tilt4_arm_dates)["summary"]

    # cutoff control: newest previously published raw tilt4 face vs today's raw
    # arm. The raw face publishes into results/e43_tilt_4member, so the search
    # starts there (E159 pit: looking only in the twin's own directory returns
    # null, and null reads as "no older face exists").
    cutoff_control = None
    search_dirs = [d for d in (os.path.join(ROOT, "results", "e43_tilt_4member"),
                               outdir) if d and os.path.isdir(d)]
    olds = []
    for d in search_dirs:
        olds.extend(os.path.join(d, p) for p in os.listdir(d)
                    if p.startswith("HIST-") and p.endswith(".json"))
    for path in sorted(olds, key=os.path.basename, reverse=True):
        p = os.path.basename(path)
        if p[len("HIST-"):-len(".json")] == tag:
            continue
        try:
            with open(path, "r", encoding="utf-8") as fh:
                old_face = json.load(fh)
        except Exception:
            continue
        old_keys = sorted({k[0] for k in _tilt4_arm_cells(old_face)})
        old_pair = _burnin_pair_rows(old_face, raw_arm, old_keys,
                                     cells_fn=_tilt4_arm_cells,
                                     dates_fn=_tilt4_arm_dates)
        cutoff_control = {
            "old_face": p,
            "old_cutoff": old_face.get("evidence_cutoff"),
            "comparison": "old raw arm vs today raw arm (arm held fixed)",
            "summary": old_pair["summary"],
            "moved": old_pair["moved"],
        }
        break

    s = pair["summary"]
    survives = _twin_survives(s, control)

    arr_raw, arr_scr = _tilt4_arrows(raw_arm), _tilt4_arrows(scr_arm)
    arrow_moved = [{"era": k, "column": c, "raw": arr_raw[k][c],
                    "screened": (arr_scr.get(k) or {}).get(c)}
                   for k in sorted(arr_raw)
                   for c in _TILT4_ARROW_COLUMNS
                   if arr_scr.get(k, {}).get(c) != arr_raw[k][c]]
    survives_arrows = not arrow_moved

    era_moved = [r for r in pair["moved"] if r["start"].startswith("era/")]
    skin_moved = [r for r in pair["moved"] if r["start"].startswith("skin/")]
    answer_moved = [r for r in pair["moved"] if r["start"] == "answers"]
    other_moved = [r for r in pair["moved"]
                   if r not in era_moved and r not in skin_moved
                   and r not in answer_moved]
    eras_moved = sorted({r["start"][len("era/"):] for r in era_moved})

    # decomposition: does the published split still add up, per era?
    gaps = {era: _tilt4_decomposition_gap(row)
            for era, row in (scr_arm.get("eras") or {}).items()}
    gap_bad = {k: v for k, v in gaps.items() if v is not None and abs(v) > 0.2}
    raw_gaps = {era: _tilt4_decomposition_gap(row)
                for era, row in (raw_arm.get("eras") or {}).items()}

    return {
        "study": "e124_tilt4_screened_twin",
        "evidence_cutoff": cutoff,
        "spec": {
            "screen_mode": mode,
            "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
            "large": list(TILT_LARGE), "small": list(TILT4_SMALL),
            "five_member_small": list(TILT_SMALL),
            "arms": {"raw": "e27.load_universe() as shipped",
                     "screened": "panel_screen.screen_universe(mode=%s)" % mode},
            "seam": ("run_tilt4 grew a raw= parameter this round: before it built "
                     "its own core, so a twin could not burn both arms off one load"),
            "join": ("_tilt4_arm_cells harvests the per-era tilt and its "
                     "decomposition, the 4-vs-5-member skin rows and the "
                     "aggregates; _tilt4_arm_dates carries the era boundaries and "
                     "the best/worst month identities, because a date or a month "
                     "name has no delta"),
        },
        "screen_report": report,
        "arrows": {"raw": arr_raw, "screened": arr_scr},
        "pair": pair,
        "control": control,
        "cutoff_control": cutoff_control,
        "decomposition": {"screened_gaps_bp": gaps, "raw_gaps_bp": raw_gaps,
                          "tolerance_bp": 0.2,
                          "incomplete_eras": sorted(gap_bad)},
        "answers": {
            "counts_survive_the_repair": bool(survives),
            "arrows_survive_the_repair": bool(survives_arrows),
            "cells_compared": s["cells_compared"],
            "cells_moved": s["cells_moved"],
            "max_abs_delta": s["max_abs_delta_pp"],
            "delta_units": ("each delta is in the units of its column: bp for the "
                            "annualised columns, percent for the share/squared "
                            "columns, count for months and beta -- the summary max "
                            "is a max over mixed units and is a screen, not a "
                            "quantity"),
            "worst_cell": s["worst"],
            "era_cells_moved": len(era_moved),
            "skin_cells_moved": len(skin_moved),
            "answer_cells_moved": len(answer_moved),
            "other_cells_moved": len(other_moved),
            "eras_with_any_moved_cell": eras_moved,
            "n_eras": len([k for k in keys if k.startswith("era/")]),
            "arrow_claims_moved": len(arrow_moved),
            "moved_attribution_complete": (
                len(era_moved) + len(skin_moved) + len(answer_moved)
                + len(other_moved) == s["cells_moved"]),
            "decomposition_complete": not gap_bad,
            "control_cells_moved": control["cells_moved"],
            "control_ordering_moved": control["gate_dates_moved"],
            "cutoff_control": ({"old_face": cutoff_control["old_face"],
                                "cells_moved":
                                    cutoff_control["summary"]["cells_moved"],
                                "max_abs_delta":
                                    cutoff_control["summary"]["max_abs_delta_pp"]}
                               if cutoff_control else None),
            "reading": (
                ("the per-era tilt attribution survives the repair: %d of %d "
                 "cells move, %d of %d eras carry any move, every era's arrows "
                 "hold and the decomposition still sums"
                 % (s["cells_moved"], s["cells_compared"], len(eras_moved),
                    len([k for k in keys if k.startswith("era/")])))
                if (survives and survives_arrows and not gap_bad) else
                ("the repair reaches the tilt attribution: %d of %d cells move "
                 "(%d era / %d skin / %d answer / %d other), %d of %d eras carry "
                 "a move, %d of %d arrow claims move and %d era(s) no longer "
                 "decompose; %d cell(s) exist on one arm only"
                 % (s["cells_moved"], s["cells_compared"], len(era_moved),
                    len(skin_moved), len(answer_moved), len(other_moved),
                    len(eras_moved), len([k for k in keys if k.startswith("era/")]),
                    len(arrow_moved), len(arr_raw) * len(_TILT4_ARROW_COLUMNS),
                    len(gap_bad), s["only_in_raw"] + s["only_in_screened"]))),
        },
        "honest": [
            "descriptive census only: no gate, no verdict on the strategy, no "
            "prereg, no trial count, no ledger booking",
            "the four-member skin drops the STAR leg, so the tilt is a "
            "broad-vs-mid/small read, not the five-member identity; the skin rows "
            "price that difference on the months both skins can see",
            "the screened arm repairs prints inside the panel it is handed; it "
            "does not add or remove bars, so an unchanged ``months`` cell is a "
            "property of the repair, not evidence the panel is clean",
            "eras are calendar partitions of one continuous monthly series and do "
            "not add up, so ``eras_with_any_moved_cell`` counts eras, not weight",
            "the decomposition gap is published per era rather than trusted: a "
            "split that stops summing makes the attribution unreadable even when "
            "every individual number looks plausible",
        ],
    }


# ------------------------------------- leg: E125 cash-leg drag, screened twin

_CASH_SCHEME_SCALARS = (
    "ann_return_pct", "ann_vs_x0_bp", "vol_pct", "sharpe",
    "max_drawdown_pct", "cost_per_year_bp", "curve_first", "curve_last",
)
_CASH_MECH_SCALARS = (
    "first_rebalance_index", "first_trading_rebalance_index", "cash_bars",
    "cash_bar_share_pct", "rebalance_decisions", "panel_covered_days",
    "panel_ffilled_days", "mean_daily_cash_bp", "mean_annual_cash_rate_pct",
)
_CASH_ANSWER_SCALARS = (
    "ladder_cash_attributable_bp", "wide_cash_attributable_bp",
    "ladder_x3_delta_bp", "wide_x3_delta_bp",
)
_CASH_ARROW_COLUMNS = ("ladder_cash_sign", "wide_cash_sign",
                       "cash_gap_sign", "ladder_maxdd_sign")


def _cash_arm_cells(face, keys=None):
    """(E125) -> {(key, column): value} for every cell the cashdrag leg publishes.

    Three buckets, because they fail differently. ``scheme/`` cells are the
    per-book per-multiplier measurements (the levels a reader quotes),
    ``cash/`` cells are the mechanism (when the book first trades, how many
    bars it sat in repo, what rate it earned there) and ``answers/`` are the
    derived attributions plus the per-book maxdd movements. A moved ``cash/``
    cell beside untouched ``scheme/`` rows says the repair changed WHEN the
    book got invested, not what it earned -- a distinction the total cannot make.
    """
    out = {}
    for start, win in (face.get("windows") or {}).items():
        win = win or {}
        for name, rows in (win.get("schemes") or {}).items():
            for mult, row in (rows or {}).items():
                row = row or {}
                for col in _CASH_SCHEME_SCALARS:
                    out[("scheme/%s/%s/%s" % (start, name, mult), col)] = row.get(col)
        for col in _CASH_MECH_SCALARS:
            out[("cash/" + start, col)] = (win.get("cash_mechanism") or {}).get(col)
        ans = win.get("answers") or {}
        for col in _CASH_ANSWER_SCALARS:
            out[("answers/" + start, col)] = ans.get(col)
        for name, val in (ans.get("maxdd_moves_with_cash") or {}).items():
            out[("answers/" + start, "maxdd_move:" + name)] = val
    return out


def _cash_arm_dates(face, keys=None):
    """(E125) the claim layer: the first invested bar, panel edges, multiplier set.

    ``first_invested_bar`` is a date claim, not a number: the price repair can
    move the first month-end whose live set is non-empty, and that is the whole
    cash window. A face that silently grew or lost a multiplier is a different
    experiment, so the multiplier set rides here too.
    """
    out = {}
    for start, win in (face.get("windows") or {}).items():
        win = win or {}
        mech = win.get("cash_mechanism") or {}
        mults = sorted({m for rows in (win.get("schemes") or {}).values()
                        for m in (rows or {})})
        out["cash/" + start] = {
            "first_invested_bar": mech.get("first_invested_bar"),
            "panel_first": mech.get("panel_first"),
            "panel_last": mech.get("panel_last"),
            "multipliers": ",".join(mults),
        }
    return out


def _cash_arrows(face):
    """(E125) the published ARROWS per window: the signs a reader consumes.

    The cash attribution's sign says whether the repo leg helped or hurt; the
    ladder-minus-wide gap says which book leaned on it more; the maxdd arrow
    says whether the repo leg cushioned the drawdown. A sign can flip under a
    sub-floor delta, so all four are carried (E94 family).
    """
    out = {}
    for start, win in (face.get("windows") or {}).items():
        win = win or {}
        ans = win.get("answers") or {}
        lad = ans.get("ladder_cash_attributable_bp")
        wid = ans.get("wide_cash_attributable_bp")
        out[str(start)] = {
            "ladder_cash_sign": _pair_sign(lad),
            "wide_cash_sign": _pair_sign(wid),
            "cash_gap_sign": _pair_sign(
                (lad - wid) if (lad is not None and wid is not None) else None),
            "ladder_maxdd_sign": _pair_sign(
                (ans.get("maxdd_moves_with_cash") or {}).get("ladder5")),
        }
    return out


def _ladder_exposure(base_ladder, report):
    """(E125) does the screen reach the ladder's own five names?

    Every twin in this family publishes a ``ladder`` row beside the wide book.
    If the repair never edits a ladder name, that row is a CONTROL, not evidence
    the repair is harmless -- and a reader who sees "ladder cells: 0 moved"
    without this block would read the opposite. The candidates the screen
    declines to touch (gapped prints) ride here too: a ladder name that is
    neutralised tomorrow would move rows that are all zeros today.
    """
    lad = set(base_ladder)
    entries = [n for n in ((report or {}).get("names") or []) if isinstance(n, dict)]
    touched = {n.get("name") for n in entries if n.get("action") == "neutralise"}
    cand = {n.get("name"): n.get("action") for n in entries if n.get("name") in lad}
    return {
        "ladder_names": sorted(lad),
        "names_neutralised": len(touched),
        "ladder_names_neutralised": sorted(touched & lad),
        "ladder_names_with_untouched_candidates": sorted(cand),
        "untouched_candidate_actions": {k: cand[k] for k in sorted(cand)},
        "ladder_row_is_a_control": not (touched & lad),
        "reading": ("no ladder name is neutralised on this panel, so every ladder "
                    "row in this face is a control arm rather than a measurement "
                    "of the repair; a ladder name that starts being neutralised "
                    "would move rows that read zero today"
                    if not (touched & lad) else
                    "the repair reaches ladder names (%s), so this ladder row is "
                    "a measurement, not a control"
                    % ", ".join(sorted(touched & lad))),
    }


def run_cashdragscreened(outdir, mode="neutralise_int", starts=("2020-01-01",),
                         pick_n=9999, exclude=("sh511",),
                         rate_mults=(0.0, 1.0, 3.0), resume=True):
    """E125: re-derive the E40 cash-leg drag face on the screened arm.

    Same machinery as E112-E124: one load, both arms burned off it, per-arm
    checkpoints, the shared ``_burnin_pair_rows`` join, a same-arm control that
    must read zero, and a cutoff control against the newest published raw face.

    The question is narrower than "did the numbers move": the cash leg is the
    un-invested weight, so its size is set by WHEN the book first trades, which
    eligibility -- and therefore the repaired prints -- decide. So the twin
    publishes the mechanism cells beside the earned cells: a repair that shifts
    the first invested bar without moving the attribution is a different finding
    from one that moves both.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]
    tag = cutoff.replace("-", "")
    kw = {"starts": starts, "pick_n": pick_n, "exclude": exclude,
          "rate_mults": rate_mults}

    def cached(label, thunk):
        p = os.path.join(outdir or ".", "CASHLeg-arm-%s-%s.json" % (label, tag))
        if resume and os.path.isfile(p):
            try:
                with open(p, "r", encoding="utf-8") as fh:
                    return json.load(fh)
            except Exception:
                pass
        face = thunk()
        if outdir:
            write_json(outdir, "CASHLeg-arm-%s-%s.json" % (label, tag), face)
        return face

    screened, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)

    raw_arm = cached("raw", lambda: run_cashdrag(None, raw=raw, **kw))
    scr_arm = cached(mode, lambda: run_cashdrag(None, raw=screened, **kw))

    keys = sorted({k[0] for k in _cash_arm_cells(raw_arm)})
    pair = _burnin_pair_rows(raw_arm, scr_arm, keys,
                             cells_fn=_cash_arm_cells,
                             dates_fn=_cash_arm_dates)
    control = _burnin_pair_rows(raw_arm, raw_arm, keys,
                                cells_fn=_cash_arm_cells,
                                dates_fn=_cash_arm_dates)["summary"]

    # cutoff control: newest published raw cashdrag face vs today's raw arm.
    # The raw face lands in results/e40_cashleg_drag as CASHLeg-<yyyymmdd>.json
    # (E159 pit: searching only the twin's own directory returns null, and null
    # reads as "no older face exists").
    cutoff_control = None
    search_dirs = [d for d in (os.path.join(ROOT, "results", "e40_cashleg_drag"),
                               outdir) if d and os.path.isdir(d)]
    olds = []
    for d in search_dirs:
        olds.extend(os.path.join(d, p) for p in os.listdir(d)
                    if p.startswith("CASHLeg-") and p.endswith(".json")
                    and "-arm-" not in p)
    for path in sorted(olds, key=os.path.basename, reverse=True):
        p = os.path.basename(path)
        if p[len("CASHLeg-"):-len(".json")] == tag:
            continue
        try:
            with open(path, "r", encoding="utf-8") as fh:
                old_face = json.load(fh)
        except Exception:
            continue
        old_keys = sorted({k[0] for k in _cash_arm_cells(old_face)})
        old_pair = _burnin_pair_rows(old_face, raw_arm, old_keys,
                                     cells_fn=_cash_arm_cells,
                                     dates_fn=_cash_arm_dates)
        cutoff_control = {
            "old_face": p,
            "old_cutoff": old_face.get("evidence_cutoff"),
            "comparison": "old raw arm vs today raw arm (arm held fixed)",
            "summary": old_pair["summary"],
            "moved": old_pair["moved"],
        }
        break

    s = pair["summary"]
    survives = _twin_survives(s, control)

    arr_raw, arr_scr = _cash_arrows(raw_arm), _cash_arrows(scr_arm)
    arrow_moved = [{"start": k, "column": c, "raw": arr_raw[k][c],
                    "screened": (arr_scr.get(k) or {}).get(c)}
                   for k in sorted(arr_raw)
                   for c in _CASH_ARROW_COLUMNS
                   if arr_scr.get(k, {}).get(c) != arr_raw[k][c]]
    survives_arrows = not arrow_moved

    scheme_moved = [r for r in pair["moved"] if r["start"].startswith("scheme/")]
    mech_moved = [r for r in pair["moved"] if r["start"].startswith("cash/")]
    answer_moved = [r for r in pair["moved"] if r["start"].startswith("answers/")]
    other_moved = [r for r in pair["moved"] if r not in scheme_moved
                   and r not in mech_moved and r not in answer_moved]

    mech_raw = {st: (w.get("cash_mechanism") or {})
                for st, w in (raw_arm.get("windows") or {}).items()}
    mech_scr = {st: (w.get("cash_mechanism") or {})
                for st, w in (scr_arm.get("windows") or {}).items()}
    first_bar = {st: {"raw": (mech_raw.get(st) or {}).get("first_invested_bar"),
                      "screened": (mech_scr.get(st) or {}).get("first_invested_bar")}
                 for st in sorted(set(mech_raw) | set(mech_scr))}

    ladder_exp = _ladder_exposure(base.LADDER, report)

    return {
        "study": "e125_cashdrag_screened_twin",
        "evidence_cutoff": cutoff,
        "spec": {
            "screen_mode": mode,
            "starts": list(starts), "pick_n": pick_n,
            "exclude_prefixes": list(exclude),
            "rate_mults": list(rate_mults),
            "arms": {"raw": "e27.load_universe() as shipped",
                     "screened": "panel_screen.screen_universe(mode=%s)" % mode},
            "seam": ("run_cashdrag grew a raw= parameter this round: before it "
                     "loaded the shipped universe itself, so a twin could not "
                     "burn both arms off one load"),
            "join": ("_cash_arm_cells harvests the per-book per-multiplier rows, "
                     "the cash-mechanism columns and the derived attributions; "
                     "_cash_arm_dates carries the first invested bar, the panel "
                     "edges and the multiplier set, because a date or a symbol "
                     "list has no delta"),
        },
        "screen_report": report,
        "ladder_exposure": ladder_exp,
        "arrows": {"raw": arr_raw, "screened": arr_scr},
        "first_invested_bar": first_bar,
        "pair": pair,
        "control": control,
        "cutoff_control": cutoff_control,
        "answers": {
            "numbers_survive_the_repair": bool(survives),
            "arrows_survive_the_repair": bool(survives_arrows),
            "cells_compared": s["cells_compared"],
            "cells_moved": s["cells_moved"],
            "max_abs_delta": s["max_abs_delta_pp"],
            "delta_units": ("each delta is in the units of its column: bp for the "
                            "return/cost columns, percent for shares and drawdowns, "
                            "count for bars and indices, a price level for the "
                            "curve endpoints -- the summary max is a screen over "
                            "mixed units, not a quantity"),
            "worst_cell": s["worst"],
            "scheme_cells_moved": len(scheme_moved),
            "mechanism_cells_moved": len(mech_moved),
            "answer_cells_moved": len(answer_moved),
            "other_cells_moved": len(other_moved),
            "moved_attribution_complete": (
                len(scheme_moved) + len(mech_moved) + len(answer_moved)
                + len(other_moved) == s["cells_moved"]),
            "arrow_claims_moved": len(arrow_moved),
            "ladder_row_is_a_control": ladder_exp["ladder_row_is_a_control"],
            "ladder_names_neutralised":
                ladder_exp["ladder_names_neutralised"],
            "first_invested_bar_moved": sorted(
                st for st, v in first_bar.items()
                if v["raw"] != v["screened"]),
            "control_cells_moved": control["cells_moved"],
            "control_ordering_moved": control["gate_dates_moved"],
            "cutoff_control": ({"old_face": cutoff_control["old_face"],
                                "cells_moved":
                                    cutoff_control["summary"]["cells_moved"],
                                "max_abs_delta":
                                    cutoff_control["summary"]["max_abs_delta_pp"]}
                               if cutoff_control else None),
            "reading": (
                ("the cash-leg attribution survives the repair: %d of %d cells "
                 "move, every scheme row holds, the first invested bar does not "
                 "shift and all %d arrow claims stand"
                 % (s["cells_moved"], s["cells_compared"],
                    len(arr_raw) * len(_CASH_ARROW_COLUMNS)))
                if (survives and survives_arrows) else
                ("the repair reaches the cash leg: %d of %d cells move "
                 "(%d scheme / %d mechanism / %d answer / %d other), %d of %d "
                 "arrow claims move and the first invested bar shifts on %s; "
                 "%d cell(s) exist on one arm only"
                 % (s["cells_moved"], s["cells_compared"], len(scheme_moved),
                    len(mech_moved), len(answer_moved), len(other_moved),
                    len(arrow_moved), len(arr_raw) * len(_CASH_ARROW_COLUMNS),
                    (", ".join(sorted(st for st, v in first_bar.items()
                                      if v["raw"] != v["screened"])) or "no window"),
                    s["only_in_raw"] + s["only_in_screened"]))),
        },
        "honest": [
            "descriptive census only: no gate, no verdict on the strategy, no "
            "prereg, no trial count, no ledger booking",
            "the repo leg is the un-invested weight of the same engine, not a "
            "discretionary allocation; a multiplier is a counterfactual rate "
            "that never existed",
            "the screened arm repairs prints inside the panel it is handed; it "
            "does not add or remove bars, so an unchanged ``cash_bars`` cell is "
            "a property of the repair, not evidence the panel is clean",
            "a multiplier row that moves while its ``ann_vs_x0_bp`` holds says "
            "the two runs share the same rate exposure, not that the level is "
            "stable -- the level is quoted with its cutoff",
        ],
    }


# ---------------------------- leg: E46 is the era edge front-loaded?
#
# E45 found the newest era's whole edge earned before the eligibility gate would
# let a cold book hold anything (2024-01..2025-01), with the live span negative.
# That is one era observed once. This leg asks the same question of every era and
# without any gate argument: split each era's slice of the same warm curve into
# halves and see whether the spread lives in one half or is spread through the
# era. A sign flip inside an era means the era's single number is an average of
# two different markets; a flat split means the number is a property of the era.

def _split_curve(curve, parts):
    """``parts`` contiguous chunks of a curve, the last one taking the remainder."""
    n = len(curve)
    if parts < 1 or n < parts * 2:
        return []
    step = n // parts
    return [curve[i * step:(i + 1) * step] for i in range(parts - 1)] + \
           [curve[(parts - 1) * step:]]


def _livespan_setup(exclude=("sh511",), pick_n=9999, cost_mult=1.0, raw=None):
    """Warm pair (ladder vs wide book) on the full calendar, computed once.

    Shared by run_livespan (one cut per call) and run_cutcurve (parts 2..12
    over the same curves), so a cut sweep pays for the simulation once per
    cost level instead of once per cut.

    ``raw`` lets a caller hand in an already-loaded (optionally screened) panel
    so a twin can be burned beside the raw arm off ONE load (E113); the default
    path still loads the shipped universe.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    raw_all = raw if raw is not None else e27.load_universe()
    if exclude:
        raw_all = {s: v for s, v in raw_all.items()
                   if not s.startswith(tuple(exclude))}
    cal = base.load_panel()[0]
    cutoff = cal[-1]
    all_syms = sorted(set(base.LADDER) | set(raw_all))
    prices, amounts = {}, {}
    for s in all_syms:
        c, a = raw_all.get(s, ({}, {}))
        prices[s] = [c.get(d) for d in cal]
        amounts[s] = [a.get(d) for d in cal]
    universe = [s for s in all_syms if s in raw_all]
    wide_name = "wide_top%d" % pick_n
    curves = {}
    for name, univ, n in (("ladder5", list(base.LADDER), None), (wide_name, universe, pick_n)):
        curve, _aux, _hold = e27.simulate(cal, prices, amounts, univ,
                                          base.load_cash_series(cal), n, cost_mult, {})
        curves[name] = curve
    return {"cutoff": cutoff, "curves": curves, "universe": universe,
            "wide_name": wide_name}


def _livespan_rows(curves, eras, parts, wide_name):
    """Per-era part rows for one cut (the E46 split body)."""
    rows = {}
    for era_name, lo, hi in eras:
        lad = [pt for pt in curves["ladder5"]
               if (lo is None or pt[0] >= lo) and (hi is None or pt[0] <= hi)]
        wid = [pt for pt in curves[wide_name]
               if (lo is None or pt[0] >= lo) and (hi is None or pt[0] <= hi)]
        if len(lad) < 2 * parts or len(wid) != len(lad):
            rows[era_name] = {"bars": len(lad), "skipped": "too few bars to split"}
            continue
        chunks = []
        for k, (lc, wc) in enumerate(zip(_split_curve(lad, parts),
                                         _split_curve(wid, parts))):
            lf, wf = _curve_faces(lc), _curve_faces(wc)
            chunks.append({"part": k + 1, "from": (lf or {}).get("from"),
                           "to": (lf or {}).get("to"), "bars": len(lc),
                           "ladder": lf, "wide": wf, "spread_bp": _spread_bp(lf, wf)})
        whole = _spread_bp(_curve_faces(lad), _curve_faces(wid))
        spreads = [c["spread_bp"] for c in chunks if c["spread_bp"] is not None]
        rows[era_name] = {
            "from": lad[0][0], "to": lad[-1][0], "bars": len(lad),
            "era_spread_bp": whole, "parts": chunks,
            "part_spreads_bp": spreads,
            "sign_flips_inside_era": (len(spreads) > 1
                                      and min(spreads) < 0 < max(spreads)),
            "widest_part": (max(chunks, key=lambda c: c["spread_bp"] or -1e9)["part"]
                            if spreads else None),
            "part_band_bp": (round(max(spreads) - min(spreads), 1) if spreads else None),
        }
    return rows


def run_livespan(outdir, eras=ERAS, pick_n=9999, exclude=("sh511",), parts=2,
                 cost_mult=1.0, raw=None):
    """E46: split every era in `parts` chunks and read where its spread is earned.

    ``raw`` is the same screened-twin seam E113 uses on the cut sweep; every
    existing face keeps the default load.
    """
    import e24_ladder_weighting as base

    setup = _livespan_setup(exclude=exclude, pick_n=pick_n, cost_mult=cost_mult,
                            raw=raw)
    cutoff = setup["cutoff"]
    curves = setup["curves"]
    universe = setup["universe"]
    wide_name = setup["wide_name"]
    rows = _livespan_rows(curves, eras, parts, wide_name)
    flipped = [k for k, v in rows.items() if v.get("sign_flips_inside_era")]
    return {
        "study": "e46_live_span_split",
        "evidence_cutoff": cutoff,
        "spec": {"pick_n": pick_n, "exclude_prefixes": list(exclude),
                 "cost_mult": cost_mult, "cost_bp_per_side": base.COST_BP_SIDE,
                 "parts": parts,
                 "curve": "one warm pair on the full calendar, sliced per era then split",
                 "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
                 "universe_members": len(universe)},
        "eras": rows,
        "answers": {
            "eras_split": len([v for v in rows.values() if v.get("parts")]),
            "eras_with_internal_sign_flip": flipped,
            "era_count_with_internal_sign_flip": len(flipped),
            "widest_part_by_era": {k: v.get("widest_part") for k, v in rows.items()
                                   if v.get("widest_part") is not None},
            "part_band_bp_by_era": {k: v.get("part_band_bp") for k, v in rows.items()
                                    if v.get("part_band_bp") is not None},
        },
        "honest": [
            "the split is by bar count, not by calendar year, so the halves are equal in "
            "sessions and unequal in spans only by trading density",
            "an internal sign flip does not say which half is the future; it says the era's "
            "single number is an average of two different markets and must be quoted as such",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }


def _cut_summary(rows):
    """Cut-level roll-up of _livespan_rows: who flips, how wide, which parts are dead.

    Pure function so the sweep's arithmetic is testable without a panel.
    """
    flips = sorted(k for k, v in rows.items() if v.get("sign_flips_inside_era"))
    bands = {k: v.get("part_band_bp") for k, v in rows.items()
             if v.get("part_band_bp") is not None}
    dead = {}
    for k, v in rows.items():
        spreads = [s for s in (v.get("part_spreads_bp") or []) if s is not None]
        n_dead = sum(1 for s in spreads if abs(s) < 0.05)
        if n_dead:
            dead[k] = n_dead
    vals = sorted(bands.values())
    med = None
    if vals:
        n = len(vals)
        med = round(vals[n // 2] if n % 2 else (vals[n // 2 - 1] + vals[n // 2]) / 2.0, 1)
    return {"eras_flipping": flips,
            "flip_count": len(flips),
            "bands_bp": bands,
            "band_mean_bp": round(sum(vals) / len(vals), 1) if vals else None,
            "band_median_bp": med,
            "band_widest_era": max(bands, key=lambda k: bands[k]) if bands else None,
            "zero_spread_parts_by_era": dead}


def _widest_window(row):
    """'from..to' of an era's widest part, or None when the part is missing."""
    wid = row.get("widest_part")
    for p in (row.get("parts") or []):
        if p.get("part") == wid:
            return "%s..%s" % (p.get("from"), p.get("to"))
    return None


def run_cutcurve(outdir, eras=ERAS, pick_n=9999, exclude=("sh511",),
                 costs=(1.0, 3.0), parts_range=range(2, 13), raw=None):
    """E58: one face over the whole cut axis (parts 2..12 at each cost level).

    The eleven cuts exist as eleven single faces, so any claim about the band
    is a claim about which cut it was cut at. This leg replays the same warm
    pair once per cost level and slices it at every cut, so band-vs-cut,
    flip-vs-cut and the widest part's window are readable side by side.

    ``raw`` is the E113 screened-twin seam: hand in a repaired universe and the
    identical sweep runs on it without touching the default path.
    """
    import e24_ladder_weighting as base

    grid = {}
    cutoffs = set()
    for cost in costs:
        setup = _livespan_setup(exclude=exclude, pick_n=pick_n, cost_mult=cost,
                                raw=raw)
        cutoffs.add(setup["cutoff"])
        per_cut = {}
        for parts in parts_range:
            rows = _livespan_rows(setup["curves"], eras, parts, setup["wide_name"])
            per_cut[str(parts)] = {
                "summary": _cut_summary(rows),
                "eras": {k: {"era_spread_bp": v.get("era_spread_bp"),
                             "part_band_bp": v.get("part_band_bp"),
                             "widest_part": v.get("widest_part"),
                             "widest_window": _widest_window(v),
                             "part_spreads_bp": v.get("part_spreads_bp")}
                         for k, v in rows.items()},
            }
        grid["x%g" % cost] = per_cut

    era_names = [n for n, _lo, _hi in eras]
    levels = {}
    drift = {}
    for key, cuts in grid.items():
        levels[key] = {e: sorted({c["eras"].get(e, {}).get("era_spread_bp")
                                  for c in cuts.values()}) for e in era_names}
        drift[key] = {}
        for e in era_names:
            vals = [c["eras"].get(e, {}).get("era_spread_bp") for c in cuts.values()]
            vals = [v for v in vals if v is not None]
            drift[key][e] = round(max(vals) - min(vals), 1) if vals else None

    series = {key: {f: {p: cuts[p]["summary"][f] for p in cuts}
                    for f in ("flip_count", "band_mean_bp", "band_median_bp",
                              "band_widest_era")}
              for key, cuts in grid.items()}
    return {
        "study": "e58_parts_cut_curve",
        "evidence_cutoff": sorted(cutoffs)[-1],
        "spec": {"pick_n": pick_n, "exclude_prefixes": list(exclude),
                 "cost_mult": list(costs), "cost_bp_per_side": base.COST_BP_SIDE,
                 "parts_swept": [min(parts_range), max(parts_range)],
                 "curve": "one warm pair per cost level, sliced at every cut",
                 "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras]},
        "cuts": grid,
        "answers": {
            "era_level_by_cost": levels,
            "era_level_drift_bp": drift,
            "series_by_cost": series,
            "cuts_swept": len(list(parts_range)),
        },
        "honest": [
            "the cuts are bar-count splits of one warm curve, not separate books: the "
            "simulation is run once per cost level, so no cut can differ by engine state",
            "a band is max(part spread) - min(part spread); the sweep shows how that range "
            "moves with the cut, it does not convert a band into a risk or an error bar",
            "widest_window names the window at that cut and can move when the cut moves, "
            "so a window quoted without its cut is not reproducible",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }


def _cutcurve_arm_cells(face, starts=None):
    """(E113) -> {(cost/cut, column): value} for every cell the cut sweep publishes.

    The sweep's published cells are the per-cut summary (flip count, band mean
    and median) and, per era, the level it reads plus the band and part index
    the level was cut from. ``part_spreads_bp`` is deliberately not harvested:
    it is the raw ladder of eleven numbers, and joining it would report a cut
    as moved eleven times for one reason.
    """
    out = {}
    for cost_key, cuts in (face.get("cuts") or {}).items():
        for cut_str, cut in (cuts or {}).items():
            key = "%s/c%s" % (cost_key, cut_str)
            cut = cut or {}
            summ = cut.get("summary") or {}
            for col in ("flip_count", "band_mean_bp", "band_median_bp"):
                out[(key, col)] = summ.get(col)
            for era, row in (cut.get("eras") or {}).items():
                row = row or {}
                out[(key, "era_spread_bp@" + era)] = row.get("era_spread_bp")
                out[(key, "part_band_bp@" + era)] = row.get("part_band_bp")
                out[(key, "widest_part@" + era)] = row.get("widest_part")
    return out


def _cutcurve_widest_windows(face, starts=None):
    """(E113) -> {(cost/cut): {"window@<era>": "from..to"}} for the date join.

    A widest window is a pointer, not a number: it either reproduces on the
    screened arm or the arm changed which stretch of history carries the era.
    """
    out = {}
    for cost_key, cuts in (face.get("cuts") or {}).items():
        for cut_str, cut in (cuts or {}).items():
            key = "%s/c%s" % (cost_key, cut_str)
            out[key] = {"window@" + era: (row or {}).get("widest_window")
                        for era, row in ((cut or {}).get("eras") or {}).items()}
    return out


def run_cutcurvescreen(outdir, pick_n=9999, exclude=("sh511",), mode="neutralise_int",
                       costs=(1.0, 3.0), parts_range=range(2, 13), resume=True):
    """E113: re-derive the cut sweep on the screened arm, beside the raw face.

    E97's ranking puts run_cutcurve second (1,139 numbers) and E112 priced the
    first row: a repair of the panel moves some numbers but need not move the
    conclusion. The cut sweep's conclusion is narrower than the burn-in's --
    every era's level is read off one warm curve and quoted per cut, and the
    load-bearing claim is *which window is the widest part* at each cut. So the
    question here is whether the widest-window reading and the flip count are
    properties of the cut axis (arm-free) or of the panel's prints.

    Both arms burn off ONE load through ``raw=`` (the E113 seam on
    ``run_cutcurve`` -> ``_livespan_setup``), each checkpoints so a killed pass
    resumes, and the pair is joined by the same ``_burnin_pair_rows`` E112 used
    with a cutcurve harvest instead of a second join. A same-arm control is
    computed in-round: if it does not read zero, the join machinery moved the
    numbers and the face must not be read.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]
    tag = cutoff.replace("-", "")

    def cached(label, thunk):
        p = os.path.join(outdir or ".", "CUTCURVE-arm-%s-%s.json" % (label, tag))
        if resume and os.path.isfile(p):
            try:
                with open(p, "r", encoding="utf-8") as fh:
                    return json.load(fh)
            except Exception:
                pass
        face = thunk()
        if outdir:
            write_json(outdir, "CUTCURVE-arm-%s-%s.json" % (label, tag), face)
        return face

    raw_excl = {s: v for s, v in raw.items()
                if not s.startswith(tuple(exclude))} if exclude else dict(raw)
    screened, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)
    screened_excl = {s: v for s, v in screened.items()
                     if not s.startswith(tuple(exclude))} if exclude else dict(screened)

    raw_arm = cached("raw", lambda: run_cutcurve(
        None, pick_n=pick_n, exclude=exclude, costs=costs,
        parts_range=parts_range, raw=raw_excl))
    scr_arm = cached(mode, lambda: run_cutcurve(
        None, pick_n=pick_n, exclude=exclude, costs=costs,
        parts_range=parts_range, raw=screened_excl))

    keys = sorted({k[0] for k in _cutcurve_arm_cells(raw_arm)})
    pair = _burnin_pair_rows(raw_arm, scr_arm, keys,
                             cells_fn=_cutcurve_arm_cells,
                             dates_fn=_cutcurve_widest_windows)
    control = _burnin_pair_rows(raw_arm, raw_arm, keys,
                                cells_fn=_cutcurve_arm_cells,
                                dates_fn=_cutcurve_widest_windows)["summary"]

    # cutoff control: the newest previously published raw sweep vs today's raw
    # arm at the same arm. Two arms at one cutoff isolate the repair; two
    # cutoffs on one arm isolate the panel refresh.
    cutoff_control = None
    # the published raw sweeps live in results/e46_live_span; this face is
    # written beside the burn-in twins, so both directories are searched.
    search_dirs = [d for d in (outdir, os.path.join(ROOT, "results", "e46_live_span"))
                   if d and os.path.isdir(d)]
    olds = []
    for d in search_dirs:
        olds.extend(os.path.join(d, p) for p in os.listdir(d)
                    if p.startswith("CUTCURVE-") and p.endswith(".json")
                    and not p.startswith("CUTCURVE-arm-")
                    and not p.startswith("CUTCURVESCREEN-"))
    for path in sorted(olds, key=os.path.basename, reverse=True):
        p = os.path.basename(path)
        if p[len("CUTCURVE-"):-len(".json")] == tag:
            continue
        try:
            with open(path, "r", encoding="utf-8") as fh:
                old_face = json.load(fh)
        except Exception:
            continue
        old_pair = _burnin_pair_rows(old_face, raw_arm, keys,
                                     cells_fn=_cutcurve_arm_cells,
                                     dates_fn=_cutcurve_widest_windows)
        cutoff_control = {
            "old_face": p,
            "old_cutoff": old_face.get("evidence_cutoff"),
            "comparison": "old raw arm vs today raw arm (arm held fixed)",
            "summary": old_pair["summary"],
            "moved": old_pair["moved"],
            "windows_moved": old_pair["gate_dates_moved"],
        }
        break

    s = pair["summary"]
    window_moves = pair["gate_dates_moved"]
    level_cols = tuple("era_spread_bp@" + e for e in
                       sorted({k[1].split("@", 1)[1] for k in
                               _cutcurve_arm_cells(raw_arm) if "@" in k[1]}))
    level_moved = [r for r in pair["moved"] if r["column"] in level_cols]
    shape_moved = [r for r in pair["moved"] if r["column"] not in level_cols]
    survives = (len(window_moves) == 0
                and s["only_in_raw"] == 0 and s["only_in_screened"] == 0
                and control["cells_moved"] == 0
                and control["max_abs_delta_pp"] == 0.0)
    return {
        "study": "e113_cutcurve_screened_twin",
        "evidence_cutoff": cutoff,
        "spec": {
            "pick_n": pick_n, "exclude_prefixes": list(exclude),
            "screen_mode": mode, "cost_mult": list(costs),
            "parts_swept": [min(parts_range), max(parts_range)],
            "arms": {"raw": "e27.load_universe() as shipped",
                     "screened": "panel_screen.screen_universe(mode=%s)" % mode},
            "join": ("_cutcurve_arm_cells harvests the per-cut summary and the "
                     "per-era level/band/part index; a cell present on one side "
                     "only is reported, a cell moved is reported with its pointer"),
            "dates": ("_cutcurve_widest_windows joins the widest window string per "
                      "(cost, cut, era): a window either reproduces or it does not"),
            "control": ("the same arm joined against itself; every cell must read "
                        "delta 0.0 or the join machinery moved the numbers"),
        },
        "screen_report": report,
        "pair": pair,
        "control": control,
        "cutoff_control": cutoff_control,
        "answers": {
            "conclusion_survives_the_repair": bool(survives),
            "cells_compared": s["cells_compared"],
            "cells_moved": s["cells_moved"],
            "max_abs_delta_pp": s["max_abs_delta_pp"],
            "worst_cell": s["worst"],
            "level_cells_moved": len(level_moved),
            "shape_cells_moved": len(shape_moved),
            "widest_windows_moved": len(window_moves),
            "control_cells_moved": control["cells_moved"],
            "cutoff_control": ({"old_face": cutoff_control["old_face"],
                                "cells_moved": cutoff_control["summary"]["cells_moved"],
                                "max_abs_delta_pp":
                                    cutoff_control["summary"]["max_abs_delta_pp"],
                                "windows_moved": len(cutoff_control["windows_moved"])}
                               if cutoff_control else None),
            "reading": (
                ("the cut-sweep reading survives the repair: every widest window "
                 "reproduces and %d of %d level cells move, worst %.2f pp"
                 % (len(level_moved), len(level_cols),
                    s["max_abs_delta_pp"]))
                if survives else
                ("the repair reaches the cut sweep: %d widest windows move "
                 "between the arms, so a window quoted without its arm is not "
                 "reproducible" % len(window_moves))),
        },
        "honest": [
            "descriptive census only: no gate, no verdict on the strategy, no "
            "prereg, no trial count, no ledger booking",
            "the screened arm repairs prints inside the panel it is handed; it "
            "does not add or remove bars, so unchanged flip counts are a property "
            "of the repair, not evidence the panel is clean",
            "level cells are expected to move and do not decide the verdict; the "
            "verdict is the widest-window join plus the same-arm control",
            "cutcurve shares _livespan_setup with livespan, so this ticket covers "
            "the sweep only; run_livespan (E97 row 3) keeps its own ticket",
        ],
    }


def _livespan_arm_cells(face, starts=None):
    """(E114) -> {(era, column): value} for every number a split face publishes.

    Only the cells a conclusion is built on are harvested: the era's level and
    dispersion, which part was widest, whether the era flips inside itself, and
    the per-part book returns the split is read with.
    """
    out = {}
    for era, row in (face.get("eras") or {}).items():
        row = row or {}
        out[(era, "bars")] = row.get("bars")
        out[(era, "era_spread_bp")] = row.get("era_spread_bp")
        out[(era, "part_band_bp")] = row.get("part_band_bp")
        out[(era, "widest_part")] = row.get("widest_part")
        out[(era, "sign_flips")] = (1 if row.get("sign_flips_inside_era") else 0)
        for k, s in enumerate(row.get("part_spreads_bp") or [], 1):
            out[(era, "part%d_spread_bp" % k)] = s
        for part in (row.get("parts") or []):
            n = part.get("part")
            out[(era, "part%s_ladder_ann_pct" % n)] = (
                (part.get("ladder") or {}).get("ann_return_pct"))
            out[(era, "part%s_wide_ann_pct" % n)] = (
                (part.get("wide") or {}).get("ann_return_pct"))
    return out


def _livespan_dates(face, starts=None):
    """(E114) -> {era: {"from": .., "to": ..}}: an era's edges either reproduce or not."""
    return {era: {"from": (row or {}).get("from"), "to": (row or {}).get("to")}
            for era, row in (face.get("eras") or {}).items()}


def run_livespanscreen(outdir, pick_n=9999, exclude=("sh511",), parts=2,
                       cost_mult=1.0, mode="neutralise_int", resume=True):
    """E114: re-derive the one-cut era split on the screened arm, beside the raw.

    E97 row 3 (471 numbers, feeding e46 + livespan). The split answers where an
    era's ladder-vs-wide spread is earned; the load-bearing readings are the
    era's level, the part that carries it, and whether the era flips sign inside
    itself. E113 showed the same face family can hold several stability classes
    at once, so the harvest here separates level, dispersion and pointer columns
    and reports moved counts per group.

    Both arms burn off ONE load through the ``raw=`` seam, each checkpoints, and
    the pair is joined by the same ``_burnin_pair_rows`` machinery (identity,
    coverage, cutoff controls).
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]
    tag = cutoff.replace("-", "")

    def cached(label, thunk):
        p = os.path.join(outdir or ".", "LIVESPAN-arm-%s-%s.json" % (label, tag))
        if resume and os.path.isfile(p):
            try:
                with open(p, "r", encoding="utf-8") as fh:
                    return json.load(fh)
            except Exception:
                pass
        face = thunk()
        if outdir:
            write_json(outdir, "LIVESPAN-arm-%s-%s.json" % (label, tag), face)
        return face

    raw_excl = {s: v for s, v in raw.items()
                if not s.startswith(tuple(exclude))} if exclude else dict(raw)
    screened, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)
    screened_excl = {s: v for s, v in screened.items()
                     if not s.startswith(tuple(exclude))} if exclude else dict(screened)

    raw_arm = cached("raw", lambda: run_livespan(
        None, pick_n=pick_n, exclude=exclude, parts=parts, cost_mult=cost_mult,
        raw=raw_excl))
    scr_arm = cached(mode, lambda: run_livespan(
        None, pick_n=pick_n, exclude=exclude, parts=parts, cost_mult=cost_mult,
        raw=screened_excl))

    keys = sorted({k[0] for k in _livespan_arm_cells(raw_arm)})
    pair = _burnin_pair_rows(raw_arm, scr_arm, keys,
                             cells_fn=_livespan_arm_cells,
                             dates_fn=_livespan_dates)
    control = _burnin_pair_rows(raw_arm, raw_arm, keys,
                                cells_fn=_livespan_arm_cells,
                                dates_fn=_livespan_dates)["summary"]

    cutoff_control = None
    search_dirs = [d for d in (outdir, os.path.join(ROOT, "results", "e46_live_span"))
                   if d and os.path.isdir(d)]
    olds = []
    for d in search_dirs:
        olds.extend(os.path.join(d, p) for p in os.listdir(d)
                    if p.startswith("LIVESPAN-") and p.endswith(".json")
                    and not p.startswith("LIVESPAN-arm-")
                    and not p.startswith("LIVESPANSCREEN-"))
    want = "" if (cost_mult == 1.0 and parts == 2) else "-x%g-p%d" % (cost_mult, parts)
    for path in sorted(olds, key=os.path.basename, reverse=True):
        p = os.path.basename(path)
        if p[len("LIVESPAN-"):-len(".json")] == tag + want:
            continue
        try:
            with open(path, "r", encoding="utf-8") as fh:
                old_face = json.load(fh)
        except Exception:
            continue
        old_pair = _burnin_pair_rows(old_face, raw_arm, keys,
                                     cells_fn=_livespan_arm_cells,
                                     dates_fn=_livespan_dates)
        cutoff_control = {
            "old_face": p,
            "old_cutoff": old_face.get("evidence_cutoff"),
            "comparison": "old raw arm vs today raw arm (arm held fixed)",
            "summary": old_pair["summary"],
            "moved": old_pair["moved"],
        }
        break

    s = pair["summary"]
    level_cols = ("era_spread_bp",)
    level_moved = [r for r in pair["moved"] if r["column"] in level_cols]
    flip_moved = [r for r in pair["moved"] if r["column"] in ("widest_part", "sign_flips")]
    dispersion_moved = [r for r in pair["moved"]
                        if r["column"].startswith(("part_band_bp", "part1_spread_bp",
                                                   "part2_spread_bp"))]
    survives = (len(pair["gate_dates_moved"]) == 0
                and s["only_in_raw"] == 0 and s["only_in_screened"] == 0
                and control["cells_moved"] == 0
                and control["max_abs_delta_pp"] == 0.0)
    return {
        "study": "e114_livespan_screened_twin",
        "evidence_cutoff": cutoff,
        "spec": {
            "pick_n": pick_n, "exclude_prefixes": list(exclude), "parts": parts,
            "cost_mult": cost_mult, "screen_mode": mode,
            "arms": {"raw": "e27.load_universe() as shipped",
                     "screened": "panel_screen.screen_universe(mode=%s)" % mode},
            "join": ("_livespan_arm_cells harvests the era level, its dispersion, "
                     "the widest part, the flip flag and the per-part book returns; "
                     "_livespan_dates joins each era's edges"),
            "control": ("the same arm joined against itself; every cell must read "
                        "delta 0.0 or the join machinery moved the numbers"),
        },
        "screen_report": report,
        "pair": pair,
        "control": control,
        "cutoff_control": cutoff_control,
        "answers": {
            "conclusion_survives_the_repair": bool(survives),
            "cells_compared": s["cells_compared"],
            "cells_moved": s["cells_moved"],
            "max_abs_delta_pp": s["max_abs_delta_pp"],
            "worst_cell": s["worst"],
            "level_cells_moved": len(level_moved),
            "flip_or_widest_cells_moved": len(flip_moved),
            "dispersion_cells_moved": len(dispersion_moved),
            "era_edge_pairs_moved": len(pair["gate_dates_moved"]),
            "control_cells_moved": control["cells_moved"],
            "cutoff_control": ({"old_face": cutoff_control["old_face"],
                                "cells_moved": cutoff_control["summary"]["cells_moved"],
                                "max_abs_delta_pp":
                                    cutoff_control["summary"]["max_abs_delta_pp"],
                                "era_edges_moved":
                                    len(cutoff_control["summary"] and
                                        [r for r in cutoff_control["moved"]
                                         if r["column"] in ("from", "to")])}
                               if cutoff_control else None),
            "reading": (
                ("the split reading survives the repair: no era edge moves and "
                 "%d of %d level cells move, worst %.2f pp"
                 % (len(level_moved), len(keys) and s["cells_compared"],
                    s["max_abs_delta_pp"]))
                if survives else
                ("the repair reaches the split: %d era edges move between the arms"
                 % len(pair["gate_dates_moved"]))),
        },
        "honest": [
            "descriptive census only: no gate, no verdict on the strategy, no "
            "prereg, no trial count, no ledger booking",
            "the split is by bar count inside an era, so an era with few bars is "
            "skipped by construction and shows up as a missing cell, not a zero",
            "one cut per ticket: parts/cost are published on the face and the raw "
            "twin is only comparable to a published face with the same pair",
        ],
    }


# ------------------------------------------- leg: mid-month vs month-end churn

def _decision_sets(cal, prices, amounts, universe, pick_n, rebal_idxs, rank_cache):
    """[(decision_idx, holdings)] using the engine's own rank call.

    The P&L is never re-implemented here: this helper only asks the same
    function the engine asks, so the recorded book cannot drift from the
    book that produced the curve.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    out = []
    for i in sorted(rebal_idxs):
        if pick_n is None:
            live = [s for s in universe if s in prices and base.elig(prices[s], i)]
        else:
            live = e27._rank(i, universe, prices, amounts, rank_cache)[:pick_n]
        if live:
            out.append((i, sorted(live)))
    return out


def _era_of(date, eras=ERAS):
    """Era of a decision date. Bounds are truncated to YYYY-MM before comparing:
    a bare month is a string PREFIX of its own first day, so '2024-01' <
    '2024-01-01' and every era would silently lose its first month."""
    month = date[:7]
    for name, lo, hi in eras:
        lo_m = lo[:7] if lo else None
        hi_m = hi[:7] if hi else None
        if (lo_m is None or month >= lo_m) and (hi_m is None or month <= hi_m):
            return name
    return None


def _churn_stats(cal, prices, decisions, eras=ERAS, with_names=False):
    """Per-transition membership churn and the entrant-minus-exit sleeve.

    ``with_names`` adds the swapped tickers to each row so a caller can join a
    transition to an event list (E82 churn-gap amplification); the default drops
    them to keep the published face small.

    churn_alpha_bp measures what the swap itself bought: the mean forward
    return (decision to next decision) of the names brought in minus the mean
    forward return of the names dropped. It is a name-level read of the same
    window the book actually held, not a portfolio return.
    """
    rows = []
    for k in range(1, len(decisions)):
        i0, prev = decisions[k - 1]
        i1, cur = decisions[k]
        pset, cset = set(prev), set(cur)
        ent = [s for s in cur if s not in pset]
        ext = [s for s in prev if s not in cset]

        def fwd(s):
            series = prices.get(s)
            if not series:
                return None
            p0, p1 = series[i0], series[i1]
            if p0 is None or p1 is None or p0 <= 0:
                return None
            return p1 / p0 - 1.0

        fe = [x for x in (fwd(s) for s in ent) if x is not None]
        fx = [x for x in (fwd(s) for s in ext) if x is not None]
        union = cset | pset
        row = {
            "date": cal[i0], "next": cal[i1], "era": _era_of(cal[i0], eras),
            "members": len(cur), "entrants": len(ent), "exits": len(ext),
            "entrant_share_pct": round(100.0 * len(ent) / len(cur), 2) if cur else None,
            "membership_churn_pct": (round(100.0 * len(union - (cset & pset)) / len(union), 2)
                                     if union else None),
            "entrant_fwd_pct": round(100 * sum(fe) / len(fe), 3) if fe else None,
            "exit_fwd_pct": round(100 * sum(fx) / len(fx), 3) if fx else None,
            "churn_alpha_bp": (round(1e4 * (sum(fe) / len(fe) - sum(fx) / len(fx)), 1)
                               if fe and fx else None),
        }
        if with_names:
            row["entrant_names"] = sorted(ent)
            row["exit_names"] = sorted(ext)
        rows.append(row)

    agg = {}
    for name, _lo, _hi in eras:
        sub = [r for r in rows if r["era"] == name and r["churn_alpha_bp"] is not None]
        if not sub:
            continue
        alphas = sorted(r["churn_alpha_bp"] for r in sub)
        agg[name] = {
            "transitions": len(sub),
            "entrant_share_pct_mean": round(sum(r["entrant_share_pct"] for r in sub) / len(sub), 2),
            "membership_churn_pct_mean": round(sum(r["membership_churn_pct"] for r in sub) / len(sub), 2),
            "churn_alpha_bp_mean": round(sum(alphas) / len(alphas), 1),
            "churn_alpha_bp_median": round(alphas[len(alphas) // 2], 1),
            "negative_churn_share_pct": round(100.0 * sum(1 for a in alphas if a < 0) / len(alphas), 1),
        }
    return rows, agg


def run_midmonth(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",),
                 mid_day=15, costs=(0.0, 1.0, 3.0), raw=None, full_churn=False):
    """E44: explain the mid-month calendar's weakness at name level.

    ``raw`` lets a caller supply a repaired universe (E80 feeds the split
    screen through here, the same opt-in hook ``run_midsweep`` got in E78);
    the default still reads the untouched loader.

    E43's robustness grid put mid15 at the bottom of every cost column. Two
    candidate mechanisms are separated here on one identical universe and one
    identical rank cache: (a) the mid-month book simply turns over more, so
    fees eat the difference; (b) it turns over the same amount but swaps into
    worse names inside each held window. The churn sleeve answers (b) directly
    and turnover-per-year answers (a).
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    raw_all = raw if raw is not None else e27.load_universe()
    if exclude:
        raw_all = {s: v for s, v in raw_all.items()
                   if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cal = [d for d in cal_full if d >= start]
    cutoff = cal[-1]
    years = len(cal) / 252.0
    all_syms = sorted(set(base.LADDER) | set(raw_all))
    prices, amounts = {}, {}
    for s in all_syms:
        c, a = raw_all.get(s, ({}, {}))
        prices[s] = [c.get(d) for d in cal]
        amounts[s] = [a.get(d) for d in cal]
    universe = [s for s in all_syms if s in raw_all]
    cash = base.load_cash_series(cal)
    rank_cache = {}
    wide_name = "wide_top%d" % pick_n

    calendars = [("me", sorted(set(base.month_end_indices(cal)))),
                 ("mid%d" % mid_day, _mid_month_indices(cal, mid_day))]

    books = {}
    for label, idxs in calendars:
        decisions = _decision_sets(cal, prices, amounts, universe, pick_n,
                                   idxs, rank_cache)
        churn_rows, churn_agg = _churn_stats(cal, prices, decisions,
                                             with_names=full_churn)
        arms = {}
        for cm in costs:
            curve, aux, _hold = e27.simulate(cal, prices, amounts, universe, cash,
                                             pick_n, cm, rank_cache, set(idxs))
            eras = {}
            for name, lo, hi in ERAS:
                sub = _slice_curve(curve, lo, hi)
                if len(sub) < 2:
                    eras[name] = {"bars": len(sub), "skipped": "too few bars"}
                    continue
                prof = risk_profile(_rebase(sub), len(sub) / 252.0)
                eras[name] = {"bars": len(sub),
                              "ann_return_pct": prof["ann_return_pct"],
                              "max_drawdown_pct": prof["max_drawdown_pct"],
                              "monthly_win_rate_pct": prof["monthly_win_rate_pct"]}
            arms["x%g" % cm] = {
                "rebalances": aux["rebalances"],
                "turnover_per_year": round(aux["turnover_total"] / years, 3) if years else None,
                "full_window_ann_pct": risk_profile(curve, years)["ann_return_pct"],
                "eras": eras,
            }
        books[label] = {
            "decision_days": len(idxs),
            "arms": arms,
            "churn": churn_agg,
            "churn_transitions": len(churn_rows),
            "recent_transitions": churn_rows[-6:],
        }
        if full_churn:
            books[label]["churn_rows"] = churn_rows

    me, mid = books["me"], books["mid%d" % mid_day]
    eras_out = {}
    for name, _lo, _hi in ERAS:
        row = {}
        for label, book in (("me", me), ("mid", mid)):
            churn = book["churn"].get(name, {})
            row[label] = {
                "x0_ann_pct": book["arms"]["x0"]["eras"].get(name, {}).get("ann_return_pct"),
                "x1_ann_pct": book["arms"]["x1"]["eras"].get(name, {}).get("ann_return_pct"),
                "x3_ann_pct": book["arms"]["x3"]["eras"].get(name, {}).get("ann_return_pct"),
                "churn_alpha_bp_mean": churn.get("churn_alpha_bp_mean"),
                "negative_churn_share_pct": churn.get("negative_churn_share_pct"),
                "entrant_share_pct_mean": churn.get("entrant_share_pct_mean"),
            }
        for cm in ("x0", "x1", "x3"):
            a, b = row["me"][cm + "_ann_pct"], row["mid"][cm + "_ann_pct"]
            row["gap_%s_bp" % cm] = (round((b - a) * 100, 1)
                                    if a is not None and b is not None else None)
        ca, cb = row["me"]["churn_alpha_bp_mean"], row["mid"]["churn_alpha_bp_mean"]
        row["churn_alpha_gap_bp"] = (round(cb - ca, 1)
                                     if ca is not None and cb is not None else None)
        eras_out[name] = row

    # (a) turnover mechanism vs (b) membership mechanism, same units (bp/yr)
    turn_gap = (mid["arms"]["x1"]["turnover_per_year"] or 0) - (me["arms"]["x1"]["turnover_per_year"] or 0)
    fee_per_turn_bp = 2 * base.COST_BP_SIDE  # one round turn on the swapped half
    fee_gap_bp = 100.0 * turn_gap * base.COST_BP_SIDE / 2.0  # bp/yr, half-turn convention
    newest = eras_out.get("2024_now", {})
    return {
        "study": "e44_midmonth_churn",
        "evidence_cutoff": cutoff,
        "spec": {"pick_n": pick_n, "exclude_prefixes": list(exclude),
                 "cost_mult_list": list(costs), "cost_bp_per_side": base.COST_BP_SIDE,
                 "start": start, "mid_month_day": mid_day,
                 "calendars": [c[0] for c in calendars],
                 "universe_members": len(universe)},
        "books": books,
        "eras": eras_out,
        "answers": {
            "turnover_per_year_me": me["arms"]["x1"]["turnover_per_year"],
            "turnover_per_year_mid": mid["arms"]["x1"]["turnover_per_year"],
            "turnover_gap_per_year": round(turn_gap, 3),
            "fee_gap_bp_per_year_implied": round(fee_gap_bp, 1),
            "full_window_gap_x1_bp": round(
                (mid["arms"]["x1"]["full_window_ann_pct"]
                 - me["arms"]["x1"]["full_window_ann_pct"]) * 100, 1),
            "newest_era_gap_x1_bp": newest.get("gap_x1_bp"),
            "newest_era_churn_alpha_gap_bp": newest.get("churn_alpha_gap_bp"),
            "newest_era_me_negative_churn_share_pct":
                eras_out.get("2024_now", {}).get("me", {}).get("negative_churn_share_pct"),
            "newest_era_mid_negative_churn_share_pct":
                eras_out.get("2024_now", {}).get("mid", {}).get("negative_churn_share_pct"),
        },
        "honest": [
            "the churn sleeve is an equal-weight mean over the swapped names, not a portfolio "
            "return: it says whether the names taken in beat the names given up inside that "
            "window, not how much money the book made",
            "both calendars share one calendar, one universe and one rank cache, so the only "
            "moving part is the set of decision sessions",
            "mid-month is a single fixed date (day %d), not a sweep: it prices a wrong-calendar "
            "cost, it does not search for a better one" % mid_day,
            "the fee_gap figure is an order-of-magnitude conversion of the turnover difference "
            "into bp/yr, not a reconciliation of the measured gap",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }


# --------------------------------- leg: name the mid-month swaps (E57 detail)

CHASE_BUCKETS = ("other_drops_next", "other_still_holds", "disjoint")

# E60: the off-book bucket is re-read inside the entrant's own liquidity, so the
# amount window is a published parameter of the leg and not a hidden constant.
OFFBOOK_LIQ_WINDOW = 60


def _next_decision_idx(decisions, bar_idx):
    """Index of the first decision taken strictly after ``bar_idx``, or None.

    Strictly-after matters: the two calendars can decide on the same session, and
    the question here is what the other book does *next*, not what it did at the
    same instant.
    """
    for j, (i, _hold) in enumerate(decisions):
        if i > bar_idx:
            return j
    return None


def _classify_entrants(entrants, next_hold, drop_next):
    """Bucket one decision's entrants against the other calendar's next book.

    other_drops_next -- the other calendar sheds the name at its very next
        rebalance, so this book bought what the other was about to give up
    other_still_holds      -- the other calendar still holds it, so this book is
        early on a name rather than wrong about it
    disjoint    -- the name is in neither the other book's next holdings
        nor its next drop set: the two calendars read different slices
    """
    nxt = set(next_hold or ())
    drop = set(drop_next or ())
    out = {k: [] for k in CHASE_BUCKETS}
    for s in entrants:
        if s in drop:
            out["other_drops_next"].append(s)
        elif s in nxt:
            out["other_still_holds"].append(s)
        else:
            out["disjoint"].append(s)
    return out


def _chase_rows(cal, prices, decisions, other, eras=ERAS, amounts=None,
                liq_window=OFFBOOK_LIQ_WINDOW):
    """Per-transition entrants with their forward return and their bucket.

    ``other`` is the same-calendar decision list of the other rebalance timing.
    The bucketing reads that book's next two decisions, which is the only
    counterfactual available without re-pricing a portfolio.

    ``amounts`` is optional: when the caller passes the panel's own amount
    series each entrant also carries the trailing traded amount it had at the
    decision bar, which is what E60 needs to ask whether a bucket is a liquidity
    slice. Without it the emitted rows are exactly the E57 rows.
    """
    rows = []
    for k in range(1, len(decisions)):
        i0, prev = decisions[k - 1]
        i1, cur = decisions[k]
        pset = set(prev)
        ent = [s for s in cur if s not in pset]
        ext = [s for s in prev if s not in set(cur)]
        j = _next_decision_idx(other, i0)
        next_hold = other[j][1] if j is not None else None
        drop_next = None
        if j is not None and j + 1 < len(other):
            drop_next = sorted(set(other[j][1]) - set(other[j + 1][1]))
        buckets = _classify_entrants(ent, next_hold, drop_next)

        def fwd(s):
            series = prices.get(s)
            if not series:
                return None
            p0, p1 = series[i0], series[i1]
            if p0 is None or p1 is None or p0 <= 0:
                return None
            return p1 / p0 - 1.0

        bucket_of = {}
        for b, syms in buckets.items():
            for s in syms:
                bucket_of[s] = b
        entrants = []
        for s in ent:
            r = fwd(s)
            entry = {"symbol": s, "bucket": bucket_of.get(s),
                     "fwd_pct": None if r is None else round(100 * r, 3)}
            if amounts is not None:
                entry["liq_amount"] = _trailing_amount(amounts.get(s), i0, liq_window)
            entrants.append(entry)
        exits = [{"symbol": s, "fwd_pct": (None if fwd(s) is None
                                           else round(100 * fwd(s), 3))} for s in ext]
        rows.append({
            "date": cal[i0], "next": cal[i1], "era": _era_of(cal[i0], eras),
            "members": len(cur), "entrants": entrants, "exits": exits,
            "other_next": (cal[other[j][0]] if j is not None else None),
            "other_drop_next_size": len(drop_next) if drop_next is not None else None,
        })
    return rows


def _chase_era(rows, eras=ERAS):
    """Per-era bucket shares and the return of each bucket, plus named swaps."""
    out = {}
    for name, _lo, _hi in eras:
        sub = [r for r in rows if r["era"] == name]
        if not sub:
            continue
        flat = [(r["date"], e) for r in sub for e in r["entrants"]]
        per_bucket = {}
        for b in CHASE_BUCKETS:
            vals = [e["fwd_pct"] for _d, e in flat
                    if e["bucket"] == b and e["fwd_pct"] is not None]
            per_bucket[b] = {
                "entrants": sum(1 for _d, e in flat if e["bucket"] == b),
                "share_pct": (round(100.0 * sum(1 for _d, e in flat if e["bucket"] == b)
                                    / len(flat), 2) if flat else None),
                "priced": len(vals),
                "fwd_pct_mean": round(sum(vals) / len(vals), 3) if vals else None,
                "negative_share_pct": (round(100.0 * sum(1 for v in vals if v < 0) / len(vals), 1)
                                       if vals else None),
            }
        priced = [(d, e) for d, e in flat if e["fwd_pct"] is not None]
        priced.sort(key=lambda x: (-x[1]["fwd_pct"], x[0], x[1]["symbol"]))
        named = lambda seq: [{"date": d, "symbol": e["symbol"], "bucket": e["bucket"],
                              "fwd_pct": e["fwd_pct"]} for d, e in seq]
        uniq = set(e["symbol"] for _d, e in flat)
        out[name] = {
            "transitions": len(sub),
            "entrant_slots": len(flat),
            "unique_entrants": len(uniq),
            "repeat_entrant_share_pct": (round(100.0 * (len(flat) - len(uniq)) / len(flat), 1)
                                         if flat else None),
            "buckets": per_bucket,
            "top10_entrants": named(priced[:10]),
            "bottom10_entrants": named(priced[-10:]),
        }
    return out


def run_chase(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",), mid_day=15,
              raw=None):
    """E57: name the mid-month swaps and test the chase reading.

    r1132 showed the calendars turn over the same amount and that the mid-month
    book's swaps lose -123.7bp while the month-end book's swaps earn +95.6bp.
    Counts cannot say whether those entrants are names the month-end book sheds
    at its next rebalance (a chase into what is being given up), names it keeps
    anyway (being early), or a different slice of the universe. This leg emits
    the symbol lists themselves for both calendars and buckets every entrant
    against the other calendar's next book.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    raw_all = e27.load_universe() if raw is None else raw
    if exclude:
        raw_all = {s: v for s, v in raw_all.items()
                   if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cal = [d for d in cal_full if d >= start]
    cutoff = cal[-1]
    all_syms = sorted(set(base.LADDER) | set(raw_all))
    prices, amounts = {}, {}
    for s in all_syms:
        c, a = raw_all.get(s, ({}, {}))
        prices[s] = [c.get(d) for d in cal]
        amounts[s] = [a.get(d) for d in cal]
    universe = [s for s in all_syms if s in raw_all]
    rank_cache = {}

    calendars = [("me", sorted(set(base.month_end_indices(cal)))),
                 ("mid%d" % mid_day, _mid_month_indices(cal, mid_day))]
    decisions = {}
    for label, idxs in calendars:
        decisions[label] = _decision_sets(cal, prices, amounts, universe, pick_n,
                                          idxs, rank_cache)
    mid_label = "mid%d" % mid_day
    rows_me = _chase_rows(cal, prices, decisions["me"], decisions[mid_label])
    rows_mid = _chase_rows(cal, prices, decisions[mid_label], decisions["me"])
    era_me = _chase_era(rows_me)
    era_mid = _chase_era(rows_mid)
    newest = "2024_now"
    return {
        "study": "e57_midmonth_chase_names",
        "evidence_cutoff": cutoff,
        "spec": {"pick_n": pick_n, "exclude_prefixes": list(exclude), "start": start,
                 "mid_month_day": mid_day, "calendars": [c[0] for c in calendars],
                 "universe_members": len(universe),
                 "bucket_definition": {
                     "other_drops_next": "entrant is in the other calendar's drop set at its next rebalance",
                     "other_still_holds": "entrant is still held by the other calendar at its next rebalance",
                     "disjoint": "entrant is in neither the other book's next holdings nor its next drop set"}},
        "decision_days": {"me": len(decisions["me"]), mid_label: len(decisions[mid_label])},
        "eras": {"me": era_me, mid_label: era_mid},
        "recent_transitions": {mid_label: rows_mid[-3:], "me": rows_me[-2:]},
        "answers": {
            "newest_era_mid_bucket_share_pct": {
                b: era_mid.get(newest, {}).get("buckets", {}).get(b, {}).get("share_pct")
                for b in CHASE_BUCKETS},
            "newest_era_mid_bucket_fwd_pct": {
                b: era_mid.get(newest, {}).get("buckets", {}).get(b, {}).get("fwd_pct_mean")
                for b in CHASE_BUCKETS},
            "newest_era_me_bucket_share_pct": {
                b: era_me.get(newest, {}).get("buckets", {}).get(b, {}).get("share_pct")
                for b in CHASE_BUCKETS},
            "newest_era_me_bucket_fwd_pct": {
                b: era_me.get(newest, {}).get("buckets", {}).get(b, {}).get("fwd_pct_mean")
                for b in CHASE_BUCKETS},
            "newest_era_mid_unique_entrants": era_mid.get(newest, {}).get("unique_entrants"),
            "newest_era_me_unique_entrants": era_me.get(newest, {}).get("unique_entrants"),
            "newest_era_mid_repeat_entrant_share_pct":
                era_mid.get(newest, {}).get("repeat_entrant_share_pct"),
            "newest_era_me_repeat_entrant_share_pct":
                era_me.get(newest, {}).get("repeat_entrant_share_pct"),
        },
        "honest": [
            "bucket membership is decided on the other calendar's book, not on a "
            "re-priced counterfactual: it says what the other book did with the name, "
            "not what the money would have done",
            "fwd_pct is the raw decision-to-decision return of the name, before any "
            "weighting, cost or cash leg",
            "one mid-month date (day %d) against one month-end date: the calendars are "
            "fixed, not swept" % mid_day,
            "the last transition of each calendar has no full forward window if the "
            "panel ends mid-window; those rows carry null returns rather than zeros",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }


# --------------------------------------------- leg: E60 off-book liquidity
LIQ_TERCILES = ("thin", "mid", "thick")
# a within-tercile calendar gap smaller than this is not separating evidence
OFFBOOK_LIQ_FLOOR_PCT = 0.10


def _trailing_amount(series, i0, window=OFFBOOK_LIQ_WINDOW):
    """Mean traded amount over the ``window`` sessions ending at the decision bar.

    The decision bar itself is inside the window: the book is filled on that
    session, so the trailing amount is the longest history an observer could have
    had when the name was bought. Missing bars are skipped rather than read as
    zero turnover -- a suspended session is not a dry one -- and a window with no
    traded value at all stays None, because "no liquidity reading" and "thin" are
    different buckets.
    """
    if not series or i0 is None:
        return None
    lo = max(0, i0 - window + 1)
    vals = [float(v) for v in series[lo:i0 + 1] if v is not None]
    if not vals:
        return None
    return sum(vals) / len(vals)


def _liq_tercile_thresholds(values):
    """One pair of cuts for the whole sweep, at the thirds of the pooled values.

    Pooling is the point: terciles computed per calendar would put the same name
    in different buckets under the two books, and the two readings would then not
    be comparable -- comparing them is the only thing this leg exists to do.
    """
    vals = sorted(float(v) for v in values if v is not None)
    if len(vals) < 3:
        return None

    def q(p):
        pos = p * (len(vals) - 1)
        lo = int(pos)
        hi = min(lo + 1, len(vals) - 1)
        return vals[lo] + (vals[hi] - vals[lo]) * (pos - lo)

    return [round(q(1.0 / 3.0), 1), round(q(2.0 / 3.0), 1)]


def _liq_tercile(value, cuts):
    """thin / mid / thick for one trailing amount, or None without a reading."""
    if value is None or not cuts:
        return None
    if value <= cuts[0]:
        return "thin"
    if value <= cuts[1]:
        return "mid"
    return "thick"


def _attach_terciles(rows, cuts):
    """Write each entrant's own tercile onto its row; return how many got one."""
    attached = 0
    for r in rows:
        for e in r["entrants"]:
            e["tercile"] = _liq_tercile(e.get("liq_amount"), cuts)
            if e["tercile"] is not None:
                attached += 1
    return attached


def _liq_cell(entries):
    """One (calendar x bucket x tercile) cell: count, priced mean, median, tail."""
    priced = [e["fwd_pct"] for e in entries if e.get("fwd_pct") is not None]
    liq = [e["liq_amount"] for e in entries if e.get("liq_amount") is not None]
    return {
        "entrants": len(entries),
        "priced": len(priced),
        "fwd_pct_mean": (round(sum(priced) / len(priced), 3) if priced else None),
        "fwd_pct_median": (None if not priced else round(_median_of(priced), 3)),
        "negative_share_pct": (None if not priced else
                               round(100.0 * sum(1 for v in priced if v < 0)
                                     / len(priced), 1)),
        "liq_amount_median": (None if not liq else round(_median_of(liq), 1)),
    }


def _liq_bucket_cells(rows, eras=ERAS):
    """Per era and per chase bucket: the pooled cell plus one cell per tercile."""
    out = {}
    for name, _lo, _hi in eras:
        sub = [r for r in rows if r["era"] == name]
        if not sub:
            continue
        flat = [e for r in sub for e in r["entrants"]]
        per = {}
        for b in CHASE_BUCKETS:
            inb = [e for e in flat if e["bucket"] == b]
            cell = {"all": _liq_cell(inb)}
            for t in LIQ_TERCILES:
                cell[t] = _liq_cell([e for e in inb if e.get("tercile") == t])
            cell["share_pct"] = (round(100.0 * len(inb) / len(flat), 2)
                                 if flat else None)
            per[b] = cell
        out[name] = {"transitions": len(sub), "entrant_slots": len(flat),
                     "buckets": per}
    return out


def _offbook_liq_verdict(me_cells, mid_cells, floor=OFFBOOK_LIQ_FLOOR_PCT,
                         field="fwd_pct_mean"):
    """Is the off-book bucket a liquidity story, a timing story, or neither?

    ``me_cells`` / ``mid_cells`` are the per-tercile cells of ONE bucket inside
    ONE era. Two magnitudes decide it and both are published:

      * the tercile GAP -- month-end minus mid-month inside each tercile. It is
        the timing reading, and it only counts as surviving if it holds inside
        every measured tercile, in one direction, above the floor.
      * the LIQUIDITY gradient -- thick minus thin inside a calendar. It is the
        composition reading: if thin names simply earn less, a bucket that
        happens to be thin will look bad without any calendar being wrong.

    A bucket whose gap dies inside the terciles is a liquidity slice; one whose
    gap holds everywhere is a timing reading; one that shows both is published as
    both rather than resolved by whichever number reads nicer. ``field`` is why
    the caller can run the same classifier on the mean and on the median: a
    verdict that only exists under one aggregator is not a verdict.
    """
    def v(cells, t):
        return ((cells or {}).get(t) or {}).get(field)

    if not me_cells or not mid_cells:
        return {"classification": "unmeasured", "tercile_gaps_pct": {},
                "liq_gradients_pct": {}, "floor_pct": floor, "field": field}
    gradients = {}
    for label, cells in (("me", me_cells), ("mid", mid_cells)):
        thick, thin = v(cells, "thick"), v(cells, "thin")
        gradients[label] = (None if thick is None or thin is None
                            else round(thick - thin, 3))
    gaps = {}
    for t in LIQ_TERCILES:
        a, b = v(me_cells, t), v(mid_cells, t)
        gaps[t] = None if a is None or b is None else round(a - b, 3)
    measured = [g for g in gaps.values() if g is not None]
    out = {"tercile_gaps_pct": gaps, "liq_gradients_pct": gradients,
           "terciles_measured": len(measured), "floor_pct": floor, "field": field}
    if len(measured) < 2:
        out["classification"] = "no_separating_reading"
        return out
    same_sign = (all(g > 0 for g in measured) or all(g < 0 for g in measured))
    above_floor = all(abs(g) >= floor for g in measured)
    gap_mag = max(abs(g) for g in measured)
    grads = [g for g in gradients.values() if g is not None]
    grad_mag = max(abs(g) for g in grads) if grads else None
    out["gap_magnitude_pct"] = round(gap_mag, 3)
    out["liq_gradient_magnitude_pct"] = (None if grad_mag is None
                                         else round(grad_mag, 3))
    grad_dominates = (grad_mag is not None and grad_mag >= gap_mag
                      and grad_mag >= floor)
    if same_sign and above_floor:
        out["classification"] = ("both_liquidity_and_timing" if grad_dominates
                                 else "timing_survives_inside_every_tercile")
    elif not same_sign and above_floor:
        out["classification"] = "gap_changes_sign_across_terciles"
    elif grad_dominates:
        out["classification"] = "liquidity_gradient_dominates"
    else:
        out["classification"] = "no_separating_reading"
    return out


def _chase_panel(start="2020-01-01", pick_n=9999, exclude=("sh511",), mid_day=15,
                 raw=None):
    """The E57 chase leg's inputs, shared by the legs that extend it.

    Nothing is re-priced here: prices and amounts are the panel's own series and
    the books come from ``_decision_sets``, which calls the engine's own rank.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    raw_all = e27.load_universe() if raw is None else raw
    if exclude:
        raw_all = {s: v for s, v in raw_all.items()
                   if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cal = [d for d in cal_full if d >= start]
    all_syms = sorted(set(base.LADDER) | set(raw_all))
    prices, amounts = {}, {}
    for s in all_syms:
        c, a = raw_all.get(s, ({}, {}))
        prices[s] = [c.get(d) for d in cal]
        amounts[s] = [a.get(d) for d in cal]
    universe = [s for s in all_syms if s in raw_all]
    rank_cache = {}
    calendars = [("me", sorted(set(base.month_end_indices(cal)))),
                 ("mid%d" % mid_day, _mid_month_indices(cal, mid_day))]
    decisions = {}
    for label, idxs in calendars:
        decisions[label] = _decision_sets(cal, prices, amounts, universe, pick_n,
                                          idxs, rank_cache)
    return cal, prices, amounts, universe, decisions, "mid%d" % mid_day


def run_offbookliq(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",),
                   mid_day=15, liq_window=OFFBOOK_LIQ_WINDOW, raw=None):
    """E60: is the off-book bucket a liquidity story?

    E57 (r1134) put the whole 2024_now mid-month gap in the disjoint bucket:
    entrants the other calendar neither holds nor is about to drop earned +0.67%
    per swap there against +2.30% for the rest. Two readings fit that number --
    the disjoint slice is drawn from thin names that simply move less, or the two
    calendars are reading different moments of the same names. This leg separates
    them without re-pricing anything: every entrant is bucketed by its own
    trailing traded amount at the decision bar and the per-swap reading is
    republished inside each liquidity tercile for both calendars.

    A gap that holds inside every tercile is about timing; one that dies inside
    them is about which names the bucket happens to hold.
    """
    cal, prices, amounts, universe, decisions, mid_label = _chase_panel(
        start=start, pick_n=pick_n, exclude=exclude, mid_day=mid_day, raw=raw)
    cutoff = cal[-1]
    rows_me = _chase_rows(cal, prices, decisions["me"], decisions[mid_label],
                          amounts=amounts, liq_window=liq_window)
    rows_mid = _chase_rows(cal, prices, decisions[mid_label], decisions["me"],
                           amounts=amounts, liq_window=liq_window)
    pooled = [e["liq_amount"] for r in (rows_me + rows_mid)
              for e in r["entrants"] if e.get("liq_amount") is not None]
    cuts = _liq_tercile_thresholds(pooled)
    attached = {"me": _attach_terciles(rows_me, cuts),
                mid_label: _attach_terciles(rows_mid, cuts)}
    cells = {"me": _liq_bucket_cells(rows_me), mid_label: _liq_bucket_cells(rows_mid)}
    newest = "2024_now"
    disjoint = {}
    for label in ("me", mid_label):
        disjoint[label] = (((cells[label].get(newest) or {}).get("buckets") or {})
                           .get("disjoint") or {})
    verdict = _offbook_liq_verdict(disjoint["me"], disjoint[mid_label])
    verdict_median = _offbook_liq_verdict(disjoint["me"], disjoint[mid_label],
                                          field="fwd_pct_median")
    # the same disjoint read in every era the panel covers: one era's thick-name
    # run is not a calendar property, and only the era table can show that
    era_gaps, era_verdicts = {}, {}
    for era in (cells["me"] or {}):
        me_b = (((cells["me"][era] or {}).get("buckets") or {}).get("disjoint") or {})
        md_b = ((((cells[mid_label].get(era) or {}).get("buckets") or {})
                 .get("disjoint")) or {})
        if not me_b or not md_b:
            continue
        mean_v = _offbook_liq_verdict(me_b, md_b)
        med_v = _offbook_liq_verdict(me_b, md_b, field="fwd_pct_median")
        era_gaps[era] = {"mean": mean_v["tercile_gaps_pct"],
                         "median": med_v["tercile_gaps_pct"],
                         "disjoint_fwd_pct": {
                             "me": (me_b.get("all") or {}).get("fwd_pct_mean"),
                             mid_label: (md_b.get("all") or {}).get("fwd_pct_mean")},
                         "entrants": {"me": (me_b.get("all") or {}).get("entrants"),
                                      mid_label: (md_b.get("all") or {}).get("entrants")}}
        era_verdicts[era] = {"mean": mean_v["classification"],
                             "median": med_v["classification"]}

    def fwd_by(cells_side, field, terciles=LIQ_TERCILES):
        return {t: ((cells_side.get(t) or {}).get(field)) for t in terciles}

    return {
        "study": "e60_offbook_liquidity_terciles",
        "evidence_cutoff": cutoff,
        "spec": {
            "pick_n": pick_n, "exclude_prefixes": list(exclude), "start": start,
            "mid_month_day": mid_day, "liq_window_sessions": liq_window,
            "universe_members": len(universe),
            "tercile_thresholds_amount": cuts,
            "tercile_unit": "panel amount, 60-session mean ending at the decision bar",
            "bucket_definition": {
                "other_drops_next": "entrant is in the other calendar's drop set at its next rebalance",
                "other_still_holds": "entrant is still held by the other calendar at its next rebalance",
                "disjoint": "entrant is in neither the other book's next holdings nor its next drop set"},
            "floor_pct": OFFBOOK_LIQ_FLOOR_PCT,
        },
        "decision_days": {"me": len(decisions["me"]), mid_label: len(decisions[mid_label])},
        "entrants_bucketed": attached,
        "calendars": cells,
        "answers": {
            "newest_era": newest,
            "newest_era_disjoint_all_fwd_pct": {
                label: (disjoint[label].get("all") or {}).get("fwd_pct_mean")
                for label in ("me", mid_label)},
            "newest_era_disjoint_fwd_pct_by_tercile": {
                label: fwd_by(disjoint[label], "fwd_pct_mean")
                for label in ("me", mid_label)},
            "newest_era_disjoint_tercile_share_pct": {
                label: {t: (None if not (disjoint[label].get("all") or {}).get("entrants")
                            else round(100.0 * (disjoint[label].get(t) or {}).get("entrants", 0)
                                       / disjoint[label]["all"]["entrants"], 1))
                        for t in LIQ_TERCILES}
                for label in ("me", mid_label)},
            "newest_era_disjoint_tercile_gap_me_minus_mid_pct": verdict["tercile_gaps_pct"],
            "newest_era_disjoint_liq_gradient_thick_minus_thin_pct":
                verdict["liq_gradients_pct"],
            "verdict": verdict["classification"],
            "verdict_detail": verdict,
            "verdict_median_based": verdict_median["classification"],
            "verdict_median_detail": verdict_median,
            "verdict_stable_across_aggregators":
                verdict["classification"] == verdict_median["classification"],
            "era_tercile_gap_me_minus_mid_pct": era_gaps,
            "era_verdicts": era_verdicts,
        },
        "honest": [
            "the terciles are cut on the pooled entrant distribution of both "
            "calendars, so one name keeps one bucket whichever book bought it",
            "the amount is the panel's own traded value, not a percentile of the "
            "era: a tercile is a within-slice rank, not an absolute liquidity bar",
            "fwd_pct is the raw decision-to-decision return of the name, before any "
            "weighting, cost or cash leg",
            "one mid-month date (day %d) against one month-end date: the calendars "
            "are fixed, not swept" % mid_day,
            "the last transition of each calendar has no full forward window if the "
            "panel ends mid-window; those rows carry null returns rather than zeros",
            "the verdict is run twice, on the cell means and on the cell medians, "
            "and published as stable only when the two agree: a tercile mean is "
            "tail-sensitive and one thick-name winner can move it",
            "descriptive census only: no gate, no verdict on a strategy, no prereg, "
            "no trial count",
        ],
    }


def _chase_arm_cells(face, starts=None):
    """(E115) -> {(key, column): value} for every cell the chase leg publishes.

    The chase leg's load-bearing reading is the bucket mix of each calendar:
    what share of entrants lands in the other book's drop set and what those
    entrants then earned. Both are harvested per era, because a bucket share is
    only interpretable inside the era it was computed on. ``top10_entrants`` and
    ``recent_transitions`` are deliberately not harvested: they are name lists,
    and joining them would report one swap as a dozen moved numbers.
    """
    out = {}
    for cal_label, eras in (face.get("eras") or {}).items():
        for era, row in (eras or {}).items():
            row = row or {}
            base_key = "era/%s/%s" % (cal_label, era)
            for col in ("transitions", "entrant_slots", "unique_entrants",
                        "repeat_entrant_share_pct"):
                out[(base_key, col)] = row.get(col)
            for b, bd in (row.get("buckets") or {}).items():
                bd = bd or {}
                for col in ("entrants", "share_pct", "priced", "fwd_pct_mean",
                            "negative_share_pct"):
                    out[("%s/%s" % (base_key, b), col)] = bd.get(col)
    for k, v in (face.get("answers") or {}).items():
        if isinstance(v, dict):
            for sub, sv in v.items():
                if isinstance(sv, (int, float)) or sv is None:
                    out[("answers/" + k, sub)] = sv
        elif isinstance(v, (int, float)) or v is None:
            out[("answers", k)] = v
    for k, v in (face.get("decision_days") or {}).items():
        out[("decision_days", k)] = v
    out[("spec", "universe_members")] = (face.get("spec") or {}).get("universe_members")
    return out


# ---------------------------------- leg: E214 off-book era stability (E60 span)
OFFBOOK_ERA_START = "2017-01-01"
# an era counts as a replication only when its thick bucket holds enough slots
OFFBOOK_ERA_MIN_PRICED = 20


def _offbook_liq_era_stability(era_gaps, thick_priced=None,
                              min_priced=OFFBOOK_ERA_MIN_PRICED, field="mean"):
    """Does the liquidity gradient point the same way in every era?

    E60 measured one era's thick column and called the effect unstable because a
    single earlier era read the opposite sign. One reverse and one forward is not
    a flip, it is two points -- so this leg runs the same tercile split on every
    era the panel covers and asks the only question two readings cannot answer:
    how many measured eras agree, and how large is the worst disagreement.

    ``era_gaps`` is E60's own ``era_tercile_gap_me_minus_mid_pct`` map. Each era
    contributes one reading per tercile; a tercile gap is signed (month-end minus
    mid-month), so "stable" means every counted era keeps that sign in the thick
    bucket. An era whose thick cell holds fewer than ``min_priced`` priced
    entrants on either side is reported but not counted: a two-name cell can
    carry any sign.
    """
    rows, excluded = {}, {}
    for era, block in (era_gaps or {}).items():
        gaps = ((block or {}).get(field) or {})
        thick, thin = gaps.get("thick"), gaps.get("thin")
        if thick is None and thin is None:
            continue
        n = (thick_priced or {}).get(era)
        if n is not None and n < min_priced:
            excluded[era] = {"thick_priced_slots": n, "thick_gap_pct": thick}
            continue
        rows[era] = {"thick_gap_pct": thick, "thin_gap_pct": thin,
                     "thick_priced_slots": n}
    signs = [r["thick_gap_pct"] for r in rows.values()
             if r["thick_gap_pct"] is not None]
    measured = len(signs)
    out = {"measured_eras": measured, "min_priced": min_priced, "field": field,
           "per_era": rows, "excluded_eras": excluded}
    if measured < 2:
        out["classification"] = "insufficient_eras"
        return out
    pos = sum(1 for s in signs if s > 0)
    neg = sum(1 for s in signs if s < 0)
    out["positive_thick_gap_eras"] = pos
    out["negative_thick_gap_eras"] = neg
    out["thick_gap_min_pct"] = round(min(signs), 3)
    out["thick_gap_max_pct"] = round(max(signs), 3)
    out["thick_gap_spread_pct"] = round(max(signs) - min(signs), 3)
    if pos == 0 or neg == 0:
        out["classification"] = "thick_gap_sign_stable_across_eras"
    else:
        out["classification"] = "thick_gap_sign_flips_across_eras"
    return out


def run_offbookera(outdir, start=OFFBOOK_ERA_START, pick_n=9999,
                   exclude=("sh511",), mid_day=15, liq_window=OFFBOOK_LIQ_WINDOW,
                   raw=None):
    """E214: the E60 tercile split widened to every era the panel covers.

    E60 published the era table for a 2020-start window (two eras). This leg is
    the same computation carried back to 2017 so the thick-name effect gets a
    third replication, then publishes the cross-era verdict E60 could not state:
    how many eras agree on the sign of the thick-bucket calendar gap.
    """
    face = run_offbookliq(outdir, start=start, pick_n=pick_n, exclude=exclude,
                          mid_day=mid_day, liq_window=liq_window, raw=raw)
    gaps = face["answers"]["era_tercile_gap_me_minus_mid_pct"]
    # the gate uses the thinner of the two sides: a gap printed against an empty
    # calendar cell is arithmetic, not a replication
    thick_priced = {}
    for era in gaps:
        counts = []
        for label in ("me", "mid%d" % mid_day):
            cell = (((face["calendars"].get(label) or {}).get(era) or {})
                    .get("buckets") or {}).get("disjoint") or {}
            counts.append(((cell.get("thick") or {}).get("priced")))
        counts = [c for c in counts if c is not None]
        thick_priced[era] = min(counts) if counts else None
    by_mean = _offbook_liq_era_stability(gaps, thick_priced=thick_priced,
                                        field="mean")
    by_median = _offbook_liq_era_stability(gaps, thick_priced=thick_priced,
                                          field="median")
    face["study"] = "e214_offbook_liquidity_era_stability"
    face["answers"]["era_stability_mean"] = by_mean
    face["answers"]["era_stability_median"] = by_median
    face["answers"]["era_stability_stable_across_aggregators"] = (
        by_mean["classification"] == by_median["classification"])
    face["honest"].append(
        "the span is widened to %s so the era table carries every era the panel "
        "covers after the 60-session liquidity window exists; the tercile cuts are "
        "re-cut on the wider pooled distribution, so the per-era gaps here are not "
        "the E60 face's numbers and must not be joined to them" % start)
    return face


def run_chasescreen(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",),
                    mid_day=15, mode="neutralise_int", resume=True):
    """E115: re-derive the chase leg on the screened arm, beside the raw face.

    E97 ranks run_burnin / run_cutcurve / run_livespan / run_chase; E112-E114
    closed the first three. The chase leg is the fourth (377 published numbers,
    one runner) and it asks a narrower question than the burn-in: do the
    *entrants* move, and does a repaired print change which names the mid-month
    book is chasing? Its bucket shares are still a digital count (how many
    entrants fall in the other book's drop set), so a repair that reorders the
    decision sets can move them without any return changing.

    Same machinery as E112-E114 on purpose: one load, both arms burned off it,
    checkpoints so a killed pass resumes, the same ``_burnin_pair_rows`` join
    with a chase harvest, and a same-arm control that must read zero.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]
    tag = cutoff.replace("-", "")

    def cached(label, thunk):
        p = os.path.join(outdir or ".", "CHASE-arm-%s-%s.json" % (label, tag))
        if resume and os.path.isfile(p):
            try:
                with open(p, "r", encoding="utf-8") as fh:
                    return json.load(fh)
            except Exception:
                pass
        face = thunk()
        if outdir:
            write_json(outdir, "CHASE-arm-%s-%s.json" % (label, tag), face)
        return face

    screened, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)

    raw_arm = cached("raw", lambda: run_chase(None, start=start, pick_n=pick_n,
                                              exclude=exclude, mid_day=mid_day,
                                              raw=raw))
    scr_arm = cached(mode, lambda: run_chase(None, start=start, pick_n=pick_n,
                                             exclude=exclude, mid_day=mid_day,
                                             raw=screened))

    keys = sorted({k[0] for k in _chase_arm_cells(raw_arm)})
    # the chase leg publishes no date pointers, so the date join is empty by
    # construction rather than borrowing the burn-in's window columns.
    no_dates = lambda face, ks: {}
    pair = _burnin_pair_rows(raw_arm, scr_arm, keys, cells_fn=_chase_arm_cells,
                             dates_fn=no_dates)
    control = _burnin_pair_rows(raw_arm, raw_arm, keys, cells_fn=_chase_arm_cells,
                                dates_fn=no_dates)["summary"]

    # cutoff control: the newest previously published raw chase face vs today's
    # raw arm. Same arm, two cutoffs -> isolates the panel refresh, not the
    # repair. The published faces live in results/e44_midmonth.
    cutoff_control = None
    search_dirs = [d for d in (outdir, os.path.join(ROOT, "results", "e44_midmonth"))
                   if d and os.path.isdir(d)]
    olds = []
    for d in search_dirs:
        olds.extend(os.path.join(d, p) for p in os.listdir(d)
                    if p.startswith("CHASE-") and p.endswith(".json")
                    and not p.startswith("CHASE-arm-")
                    and not p.startswith("CHASESCREEN-"))
    for path in sorted(olds, key=os.path.basename, reverse=True):
        p = os.path.basename(path)
        if p[len("CHASE-"):-len(".json")] == tag:
            continue
        try:
            with open(path, "r", encoding="utf-8") as fh:
                old_face = json.load(fh)
        except Exception:
            continue
        old_pair = _burnin_pair_rows(old_face, raw_arm, keys,
                                     cells_fn=_chase_arm_cells, dates_fn=no_dates)
        cutoff_control = {
            "old_face": p,
            "old_cutoff": old_face.get("evidence_cutoff"),
            "comparison": "old raw arm vs today raw arm (arm held fixed)",
            "summary": old_pair["summary"],
            "moved": old_pair["moved"],
        }
        break

    s = pair["summary"]
    share_cols = ("share_pct", "entrants", "priced")
    share_moved = [r for r in pair["moved"] if r["column"] in share_cols]
    return_moved = [r for r in pair["moved"] if r["column"] not in share_cols]
    survives = _twin_survives(s, control)
    return {
        "study": "e115_chase_screened_twin",
        "evidence_cutoff": cutoff,
        "spec": {
            "pick_n": pick_n, "exclude_prefixes": list(exclude), "start": start,
            "mid_month_day": mid_day, "screen_mode": mode,
            "arms": {"raw": "e27.load_universe() as shipped",
                     "screened": "panel_screen.screen_universe(mode=%s)" % mode},
            "join": ("_chase_arm_cells harvests per-era bucket shares, bucket "
                     "forward returns, entrant counts and the calendar's own "
                     "decision/unique counts; name lists are not joined"),
            "control": ("the same arm joined against itself; every cell must read "
                        "delta 0.0 or the join machinery moved the numbers"),
        },
        "screen_report": report,
        "pair": pair,
        "control": control,
        "cutoff_control": cutoff_control,
        "answers": {
            "counts_survive_the_repair": bool(survives),
            "cells_compared": s["cells_compared"],
            "cells_moved": s["cells_moved"],
            "max_abs_delta_pp": s["max_abs_delta_pp"],
            "worst_cell": s["worst"],
            "share_cells_moved": len(share_moved),
            "return_cells_moved": len(return_moved),
            "control_cells_moved": control["cells_moved"],
            "cutoff_control": ({"old_face": cutoff_control["old_face"],
                                "cells_moved": cutoff_control["summary"]["cells_moved"],
                                "max_abs_delta_pp":
                                    cutoff_control["summary"]["max_abs_delta_pp"]}
                               if cutoff_control else None),
            "reading": (
                ("the chase counts survive the repair: %d of %d cells move, %d of "
                 "them share/count cells, worst %.2f pp"
                 % (s["cells_moved"], s["cells_compared"], len(share_moved),
                    s["max_abs_delta_pp"]))
                if survives else
                ("the repair reaches the chase leg: %d of %d cells move (%d share/"
                 "count, %d return) and %d cell(s) exist on one arm only"
                 % (s["cells_moved"], s["cells_compared"], len(share_moved),
                    len(return_moved), s["only_in_raw"] + s["only_in_screened"]))),
        },
        "honest": [
            "descriptive census only: no gate, no verdict on the strategy, no "
            "prereg, no trial count, no ledger booking",
            "the screened arm repairs prints inside the panel it is handed; it "
            "does not add or remove bars, so an unchanged entrant count is a "
            "property of the repair, not evidence the panel is clean",
            "bucket membership is decided on the other calendar's book, so a "
            "share that moves between arms means the repair reordered a decision "
            "set -- it says nothing about what the money would have earned",
            "one mid-month date against one month-end date: the calendars are "
            "fixed, not swept, exactly as in the raw leg",
            "E97 counts 377 published numbers for this runner; %d are joined here "
            "because the per-transition rows and the top10/bottom10 name lists are "
            "not: a symbol list is a pointer, and joining it would report one "
            "swap as a dozen moved numbers" % s["cells_compared"],
        ],
    }


# --------------------------------- leg: sweep the off-cycle calendar (E59)

MID_SWEEP_DAYS = (5, 10, 15, 20, 25)


def _calendar_offsets(cal, idxs, me_idxs):
    """Sessions from each decision to the next month-end decision.

    An off-cycle book is not "one date", it is a distance from the boundary the
    month-end book trades on. Recording that distance lets a gap be read against
    the calendar offset instead of against one chosen day.
    """
    offs = []
    for i in idxs:
        nxt = next((j for j in me_idxs if j >= i), None)
        if nxt is not None:
            offs.append(nxt - i)
    if not offs:
        return {"decisions": 0, "mean_sessions_to_month_end": None,
                "min_sessions": None, "max_sessions": None}
    return {"decisions": len(offs),
            "mean_sessions_to_month_end": round(sum(offs) / float(len(offs)), 2),
            "min_sessions": min(offs), "max_sessions": max(offs)}


def _sweep_gaps(books, cost="x1", eras=ERAS):
    """Gap versus the month-end book, per sweep day, at one cost level."""
    me_arm = books.get("me", {}).get("arms", {}).get(cost, {})
    me_full = me_arm.get("full_window_ann_pct")
    me_eras = me_arm.get("eras", {})
    out = {}
    for label in sorted(books):
        if label == "me":
            continue
        arm = books[label].get("arms", {}).get(cost, {})
        full = arm.get("full_window_ann_pct")
        row_eras = {}
        for name, _lo, _hi in eras:
            a = me_eras.get(name, {}).get("ann_return_pct")
            b = arm.get("eras", {}).get(name, {}).get("ann_return_pct")
            row_eras[name] = {"ann_pct": b,
                              "gap_bp": round((b - a) * 100, 1)
                              if a is not None and b is not None else None}
        out[label] = {
            "offset": books[label].get("offset", {}),
            "turnover_per_year": arm.get("turnover_per_year"),
            "cost_per_year_bp": arm.get("cost_per_year_bp"),
            "full_window_ann_pct": full,
            "full_window_gap_bp": round((full - me_full) * 100, 1)
            if full is not None and me_full is not None else None,
            "eras": row_eras,
        }
    return out


def _cost_face(gaps, lo_tag, hi_tag, eras=ERAS):
    """E63: does the off-cycle gap survive when the fee is switched off?

    A gap that is unchanged between cost levels is a price-path effect -- the
    off-cycle book holds different names over the same months. A gap that moves
    with the fee is the trading cost of the date. Both faces of every sweep day
    are reported; nothing here decides which reading is right.
    """
    out = {}
    for label in sorted(gaps.get(hi_tag, {})):
        a = gaps.get(lo_tag, {}).get(label, {})
        b = gaps.get(hi_tag, {}).get(label, {})
        fa, fb = a.get("full_window_gap_bp"), b.get("full_window_gap_bp")
        row = {"full_window_gap_bp": {lo_tag: fa, hi_tag: fb},
               "full_window_shift_bp": round(fb - fa, 1)
               if fa is not None and fb is not None else None,
               "turnover_per_year": {lo_tag: a.get("turnover_per_year"),
                                     hi_tag: b.get("turnover_per_year")},
               "cost_per_year_bp": {lo_tag: a.get("cost_per_year_bp"),
                                    hi_tag: b.get("cost_per_year_bp")},
               "eras": {}}
        for name, _lo, _hi in eras:
            ea = a.get("eras", {}).get(name, {}).get("gap_bp")
            eb = b.get("eras", {}).get(name, {}).get("gap_bp")
            row["eras"][name] = {lo_tag: ea, hi_tag: eb,
                                 "shift_bp": round(eb - ea, 1)
                                 if ea is not None and eb is not None else None}
        out[label] = row
    return out


def _weekly_indices(cal):
    """First trading session of each ISO week.

    The weekly rule is the densest calendar already in the price panel, so it
    is the natural place to ask whether a month-end book is anything more than
    a re-timed weekly book. Weeks are ISO (Monday-anchored), so the label does
    not drift with the year boundary.
    """
    out, seen = [], set()
    for i, d in enumerate(cal):
        key = datetime.strptime(d, "%Y-%m-%d").isocalendar()[:2]
        if key in seen:
            continue
        seen.add(key)
        out.append(i)
    return out


def _nearest_weekly_to_month_end(week_idxs, me_idxs):
    """The weekly session closest to each month-end decision, deduped.

    This is the weekly grid read at monthly cadence: same names, same cost,
    only traded once a month on the weekly date nearest the boundary. If it
    reproduces the month-end book the calendar is a re-timing; if it loses,
    the boundary date itself carries the information.
    """
    if not week_idxs or not me_idxs:
        return []
    wk = sorted(set(week_idxs))
    out = set()
    for me in sorted(set(me_idxs)):
        out.add(min(wk, key=lambda w: (abs(w - me), w)))
    return sorted(out)


def run_midsweep(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",),
                 days=MID_SWEEP_DAYS, costs=(1.0,), lags=(), weekly=False,
                 raw=None):
    """E59: is the off-cycle penalty day 15's, or any off-cycle date's?

    E44 priced one mid-month date against month-end and E57 showed the two
    calendars buy the same kind of name, so the remaining question is whether
    the gap is a property of the 15th or a property of trading away from the
    month boundary. Five dates are burned here on ONE universe, ONE rank cache
    and ONE cost level: if the gap tracks the distance to month-end the effect
    belongs to the boundary; if it is flat across all five, the boundary is
    simply the right date.

    ``raw`` lets a caller supply a repaired universe (E78 feeds the split
    screen through here); the default still reads the untouched loader.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    raw_all = raw if raw is not None else e27.load_universe()
    if exclude:
        raw_all = {s: v for s, v in raw_all.items()
                   if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cal = [d for d in cal_full if d >= start]
    cutoff = cal[-1]
    years = len(cal) / 252.0
    all_syms = sorted(set(base.LADDER) | set(raw_all))
    prices, amounts = {}, {}
    for s in all_syms:
        c, a = raw_all.get(s, ({}, {}))
        prices[s] = [c.get(d) for d in cal]
        amounts[s] = [a.get(d) for d in cal]
    universe = [s for s in all_syms if s in raw_all]
    cash = base.load_cash_series(cal)
    rank_cache = {}
    me_idxs = sorted(set(base.month_end_indices(cal)))

    calendars = [("me", me_idxs)]
    for d in days:
        calendars.append(("mid%d" % d, _mid_month_indices(cal, d)))
    for k in lags:
        calendars.append(("me_lag%d" % k, _shift_indices(me_idxs, k, len(cal))))
    if weekly:
        wk_idxs = _weekly_indices(cal)
        calendars.append(("week", wk_idxs))
        calendars.append(("week_near_me", _nearest_weekly_to_month_end(wk_idxs, me_idxs)))

    books = {}
    for label, idxs in calendars:
        arms = {}
        for cm in costs:
            curve, aux, _hold = e27.simulate(cal, prices, amounts, universe, cash,
                                            pick_n, cm, rank_cache, set(idxs))
            era_rows = {}
            for name, lo, hi in ERAS:
                sub = _slice_curve(curve, lo, hi)
                if len(sub) < 2:
                    era_rows[name] = {"bars": len(sub), "skipped": "too few bars"}
                    continue
                prof = risk_profile(_rebase(sub), len(sub) / 252.0)
                era_rows[name] = {"bars": len(sub),
                                  "ann_return_pct": prof["ann_return_pct"],
                                  "max_drawdown_pct": prof["max_drawdown_pct"]}
            arms["x%g" % cm] = {
                "rebalances": aux["rebalances"],
                "turnover_per_year": round(aux["turnover_total"] / years, 3) if years else None,
                "cost_per_year_bp": round(aux["cost_paid_frac"] / years * 1e4, 1)
                if years else None,
                "full_window_ann_pct": risk_profile(curve, years)["ann_return_pct"],
                "eras": era_rows,
            }
        books[label] = {"decision_days": len(idxs),
                        "offset": _calendar_offsets(cal, idxs, me_idxs),
                        "arms": arms}

    gaps = {("x%g" % cm): _sweep_gaps(books, "x%g" % cm) for cm in costs}
    newest = "2024_now"
    newest_gap = {lab: gaps[("x%g" % costs[0])][lab]["eras"].get(newest, {}).get("gap_bp")
                  for lab in gaps[("x%g" % costs[0])]}
    # does the gap track the calendar offset, or is it flat across off-cycle days?
    pts = [(gaps[("x%g" % costs[0])][lab]["offset"]["mean_sessions_to_month_end"], v)
           for lab, v in newest_gap.items() if v is not None]
    spread = (max(v for _o, v in pts) - min(v for _o, v in pts)) if len(pts) > 1 else None
    cost_face = (_cost_face(gaps, "x%g" % costs[0], "x%g" % costs[-1])
                 if len(costs) > 1 else None)
    face = {
        "study": "e59_midday_sweep",
        "evidence_cutoff": cutoff,
        "spec": {"pick_n": pick_n, "exclude_prefixes": list(exclude), "start": start,
                 "cost_bp_per_side": base.COST_BP_SIDE, "cost_mult_list": list(costs),
                 "sweep_days": list(days), "delay_lags": list(lags),
                 "calendars": [c[0] for c in calendars],
                 "universe_members": len(universe)},
        "books": {lab: {"decision_days": b["decision_days"], "offset": b["offset"],
                        "arms": b["arms"]} for lab, b in books.items()},
        "gaps": gaps,
        "cost_face": cost_face,
        "answers": {
            "baseline_calendar": "me",
            "sweep_days": list(days),
            "delay_lags": list(lags),
            "cost_levels": list(costs),
            "full_window_gap_bp": {lab: g["full_window_gap_bp"]
                                   for lab, g in gaps[("x%g" % costs[0])].items()},
            "newest_era_gap_bp": newest_gap,
            "newest_era_gap_spread_bp": round(spread, 1) if spread is not None else None,
            "offset_sessions": {lab: g["offset"]["mean_sessions_to_month_end"]
                                for lab, g in gaps[("x%g" % costs[0])].items()},
            "cost_gap_shift_bp": ({lab: v["full_window_shift_bp"]
                                   for lab, v in cost_face.items()}
                                  if cost_face else None),
        },
        "honest": [
            ("one cost level by default: the sweep is about the calendar axis, and the "
             "cost signature of these cuts has been the same -8..-13bp since thirds")
            if len(costs) == 1 else
            ("two cost levels: x%g switches the engine fee off entirely, so a gap that "
             "survives x%g is a price-path effect and not the cost of trading on that "
             "date; the x%g column is the same sweep with the fee switched back on"
             % (costs[0], costs[0], costs[-1])),
            "the five days are fixed dates, not a fitted optimum: no date here is "
            "searched for and none may be read as a recommendation",
            "both calendars share one universe and one rank cache, so the only moving "
            "part is the set of decision sessions",
            "gap spread across days is a range statistic over five points, not a test",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }
    if weekly:
        wk = sorted(set(_weekly_indices(cal)))
        mes = sorted(set(me_idxs))
        face["answers"]["week_overlap"] = {
            "weekly_days": len(wk),
            "me_days": len(mes),
            "exact_coincidence": len(set(wk) & set(mes)),
            "within_1_session": len([i for i in wk
                                     if any(abs(i - j) <= 1 for j in mes)]),
            "within_2_sessions": len([i for i in wk
                                      if any(abs(i - j) <= 2 for j in mes)]),
            "within_5_sessions": len([i for i in wk
                                      if any(abs(i - j) <= 5 for j in mes)]),
        }
        face["honest"].append(
            "the weekly calendar is the ISO first-session grid (Monday-anchored); a "
            "month-end decision and a weekly decision almost never land on the same "
            "session, so 'overlap' here means proximity, not the same trade")
    return face


# ------------------------- leg: is a 0.0bp era gap a cash-only slice? (E64)

def _burnin_share(era_idxs, first_idx):
    """Share of an era slice that sits before the first invested decision.

    The engine only buys when ``_rank`` returns names, so every bar before that
    decision earns the repo rate on a 100% cash book and every calendar prints
    the same number there. A 0.0bp gap is therefore evidence about the calendar
    only once this share is small.
    """
    n = len(era_idxs)
    if not n:
        return None
    if first_idx is None:
        return 100.0
    before = len([i for i in era_idxs if i < first_idx])
    return round(before / float(n) * 100.0, 1)


def _burnin_class(gap_bp, pre_pct):
    """Name who owns an era gap: the calendar, or the burn-in cash block."""
    if gap_bp is None or pre_pct is None:
        return "unmeasured"
    if pre_pct >= 99.9:
        return ("degenerate_cash_slice" if gap_bp == 0.0
                else "all_cash_slice_with_nonzero_gap")
    if gap_bp == 0.0:
        return "exact_zero_with_invested_bars"
    return "informative"


def run_midsweepburnin(outdir=None, faces=None, days=MID_SWEEP_DAYS, exclude=("sh511",)):
    """E64: publish the burn-in block beside the era gaps E59 already prints.

    E59 read the 2017_2020 column as identical for every off-cycle day at start
    2020 and as -26..+1bp at start 2013. An exact 0.0bp on every calendar is
    what an all-cash slice prints -- the engine holds nothing until eligibility
    clears -- so this leg reports, per face and era, the first decision the
    engine would have invested on and the share of the slice before it.

    Nothing is re-simulated: the first invested decision comes from the same
    eligibility+liquidity rule ``e27.simulate`` itself calls, so the reported
    boundary is the engine's, not a lookalike.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    outdir = outdir or os.path.join(ROOT, "results", "e44_midmonth")
    if faces is None:
        src = [os.path.join(outdir, n) for n in sorted(os.listdir(outdir))
               if n.startswith("MIDSWEEP-") and n.endswith(".json")
               and "burnin" not in n]
    else:
        src = list(faces)
    rows, cutoff = [], None
    answers = {"faces_read": 0, "cells": 0, "degenerate": [],
               "informative": 0, "unmeasured": 0, "other": 0,
               "first_invested": {}}
    for path in src:
        with open(path, encoding="utf-8") as fh:
            face = json.load(fh)
        if face.get("study") != "e59_midday_sweep":
            continue
        spec = face.get("spec") or {}
        start = spec.get("start") or "2020-01-01"
        ex = spec.get("exclude_prefixes") or list(exclude)
        days_here = spec.get("sweep_days") or list(days)
        cost_keys = sorted(face.get("gaps") or {})
        if not cost_keys:
            continue
        ck = cost_keys[0]
        raw_all = e27.load_universe()
        if ex:
            raw_all = {s: v for s, v in raw_all.items()
                       if not s.startswith(tuple(ex))}
        cal = [d for d in base.load_panel()[0] if d >= start]
        if len(cal) < 3:
            continue
        cutoff = cal[-1] if cutoff is None else max(cutoff, cal[-1])
        all_syms = sorted(set(base.LADDER) | set(raw_all))
        prices, amounts = {}, {}
        for s in all_syms:
            c, a = raw_all.get(s, ({}, {}))
            prices[s] = [c.get(d) for d in cal]
            amounts[s] = [a.get(d) for d in cal]
        universe = [s for s in all_syms if s in raw_all]
        me_idxs = sorted(set(base.month_end_indices(cal)))
        calendars = [("me", me_idxs)]
        for d in days_here:
            calendars.append(("mid%d" % int(d), _mid_month_indices(cal, int(d))))
        cache = {}
        answers["faces_read"] += 1
        fname = os.path.basename(path)
        for label, idxs in calendars:
            first = None
            for idx in sorted(idxs):
                if idx + 1 >= len(cal):
                    continue
                if e27._rank(idx, universe, prices, amounts, cache):
                    first = idx
                    break
            answers["first_invested"].setdefault(fname, {})[label] = {
                "idx": first,
                "bar": cal[first] if first is not None else None,
                "decision_bars_before_first_invested":
                    len([i for i in idxs if first is not None and i < first]),
            }
            for name, lo, hi in ERAS:
                era_idxs = [i for i, d in enumerate(cal)
                            if (lo is None or d >= lo) and (hi is None or d <= hi)]
                if not era_idxs:
                    continue
                pre = _burnin_share(era_idxs, first)
                gap = ((((face.get("gaps") or {}).get(ck) or {}).get(label) or {})
                       .get("eras", {}).get(name, {}).get("gap_bp"))
                klass = _burnin_class(gap, pre)
                answers["cells"] += 1
                if klass == "degenerate_cash_slice":
                    answers["degenerate"].append(
                        {"face": fname, "calendar": label, "era": name})
                elif klass == "informative":
                    answers["informative"] += 1
                elif klass == "unmeasured":
                    answers["unmeasured"] += 1
                else:
                    answers["other"] += 1
                rows.append({
                    "face": fname, "start": start, "calendar": label, "era": name,
                    "era_bars": len(era_idxs), "gap_bp": gap,
                    "pre_invested_share_pct": pre,
                    "first_invested_bar": cal[first] if first is not None else None,
                    "class": klass,
                })
    return {
        "study": "e64_midsweep_burnin",
        "evidence_cutoff": cutoff,
        "spec": {"faces_read": [os.path.basename(p) for p in src],
                 "sweep_days": list(days),
                 "cost_key": "lowest cost key of each source face's gaps",
                 "first_invested_rule": ("first decision index on which "
                                         "e27._rank returns at least one name -- "
                                         "the same condition e27.simulate buys on")},
        "cells": rows,
        "answers": answers,
        "honest": [
            "nothing is re-simulated here: the face only reads gaps that E59 "
            "already published and derives the burn-in boundary from the "
            "engine's own eligibility rule",
            "an era whose pre-invested share is 100% prints a gap that belongs "
            "to the cash block, not to the calendar -- degenerate_cash_slice "
            "says so in words",
            "an exact 0.0bp on a slice that IS invested is a different reading "
            "(exact_zero_with_invested_bars) and is left standing as such",
            "descriptive census only: no gate, no verdict, no prereg, no trial count",
        ],
    }


# --------------------------------- leg: delay the month-end decision (E65)

def run_entrydelay(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",),
                   lags=(1, 3, 5, 10), costs=(1.0,), raw=None):
    """E65: is the off-cycle penalty the calendar, or simply being late?

    E59/E63 showed every off-cycle date loses 60-90bp and that the fee cannot
    explain it, so the remaining candidate is lateness itself. This leg holds
    the spec, universe and rank cache fixed and only moves the month-end
    decision forward by 1/3/5/10 sessions. The lag moves the DECISION session
    as well as the entry, so the delayed book is re-ranked on the delayed date:
    this prices "decided and bought k sessions later", not "the same names
    bought later".
    ``raw`` (E119) is the screened-twin seam: this leg delegates to
    ``run_midsweep``, so a repaired universe has to be threaded through both
    layers -- handed in here and passed down one level unchanged.
    """
    face = run_midsweep(outdir, start=start, pick_n=pick_n, exclude=exclude,
                        days=(), costs=costs, lags=tuple(lags), raw=raw)
    rows = {}
    for k in lags:
        lab = "me_lag%d" % k
        arm = face["gaps"].get("x%g" % costs[0], {}).get(lab)
        if arm is None:
            continue
        rows[lab] = {"full_window_gap_bp": arm.get("full_window_gap_bp"),
                     "turnover_per_year": arm.get("turnover_per_year"),
                     "eras": {name: v.get("gap_bp")
                              for name, v in (arm.get("eras") or {}).items()}}
    face["study"] = "e65_entrydelay_ladder"
    face["answers"]["delay_rows"] = rows
    face["answers"]["delay_gap_bp"] = {lab: r["full_window_gap_bp"]
                                       for lab, r in rows.items()}
    face["honest"].append(
        "the lag moves the decision session as well as the entry, so the delayed "
        "book is re-ranked on the delayed date; an entry-only lag would need an "
        "execution-lag hook the engine does not have")
    return face


# --------------------------------- leg: decide EARLY instead (E66)

def _early_label(k):
    """Row label for a k-session EARLY decision (positive k = earlier)."""
    return "me_m%d" % k


def _lag_label(k):
    """Row label for a k-session LATE decision (positive k = later)."""
    return "me_lag%d" % k


def _read_delay_face(outdir, kind, cutoff, start):
    """Read a burned delay ladder (ENTRYDELAY/NEIGHBORHOOD) for cutoff+start."""
    tag = "" if start == "2020-01-01" else "-s%s" % start.replace("-", "")
    p = os.path.join(outdir or os.path.join(ROOT, "results", "e44_midmonth"),
                     "%s-%s%s.json" % (kind, cutoff.replace("-", ""), tag))
    if not os.path.exists(p):
        return None, p
    with open(p, encoding="utf-8") as fh:
        return json.load(fh), p


def _read_late_face(outdir, cutoff, start):
    """Read the E65 late ladder for the same cutoff+start, if it was burned."""
    return _read_delay_face(outdir, "ENTRYDELAY", cutoff, start)


def _read_early_face(outdir, cutoff, start):
    """Read the E66 early ladder for the same cutoff+start, if it was burned."""
    return _read_delay_face(outdir, "EARLYDELAY", cutoff, start)


def _delay_face_any(outdir, kind, cutoff, start):
    """Read a delay ladder face, falling back to the newest older burn.

    A neighbourhood leg burned on a newer panel cutoff has no exact-cutoff
    bounds, and refusing the bracket would throw away a burned face over one
    extra bar. The fallback is explicit: it returns the cutoff it actually
    used so the caller can disclose the mismatch instead of hiding it.
    """
    face, p = _read_delay_face(outdir, kind, cutoff, start)
    if face is not None:
        return face, p, cutoff
    import glob
    import re
    tag = "" if start == "2020-01-01" else "-s%s" % start.replace("-", "")
    pat = os.path.join(os.path.dirname(p), "%s-*%s.json" % (kind, tag))
    best = None
    rx = re.compile(r"^%s-(\d{8})%s\.json$" % (kind, re.escape(tag)))
    for c in glob.glob(pat):
        m = rx.match(os.path.basename(c))
        if not m:
            continue
        if best is None or m.group(1) > best[0]:
            best = (m.group(1), c)
    if best is None:
        return None, p, None
    with open(best[1], encoding="utf-8") as fh:
        return json.load(fh), best[1], best[0]


def _bracket_shape(vals, tol=2.0):
    """Is a three-point ladder [k1, k2, k3] a spike, a ramp, or flat?

    vals are gaps in bp at increasing distance from the boundary on ONE side.
    A spike means the middle point comes back to ~zero while both ends pay; a
    ramp means the middle sits between the ends (monotone), i.e. the first
    session already pays something and later sessions pay more.
    """
    if len(vals) != 3 or any(v is None for v in vals):
        return "incomplete"
    a, b, c = vals
    if abs(a) <= tol and abs(b) <= tol and abs(c) <= tol:
        return "flat"
    if abs(b) <= tol and abs(a) > 2 * tol and abs(c) > 2 * tol:
        return "spike"
    if a - tol <= b <= c + tol or a + tol >= b >= c - tol:
        return "ramp"
    return "non_monotone"


def run_earlydelay(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",),
                   early=(1, 3, 5, 10), costs=(1.0,), raw=None):
    """E66: price the other side of the month-end boundary.

    E65 held the spec fixed and moved the month-end decision LATER by
    1/3/5/10 sessions, reading a cliff in the newest era. This leg moves the
    same decision EARLIER by the same amounts on the same universe and rank
    cache. Early is not late with a minus sign: a name that is already
    published at the earlier date is a different candidate set, so the two
    sides together say whether the month boundary is a deadline (only late
    pays) or a point (both sides pay).
    """
    face = run_midsweep(outdir, start=start, pick_n=pick_n, exclude=exclude,
                        days=(), costs=costs, lags=tuple(-k for k in early),
                        raw=raw)
    lvl = "x%g" % costs[0]
    gaps = face["gaps"].get(lvl, {})
    rows = {}
    for k in early:
        arm = gaps.get(_lag_label(-k))
        if arm is None:
            continue
        rows[_early_label(k)] = {"full_window_gap_bp": arm.get("full_window_gap_bp"),
                                 "turnover_per_year": arm.get("turnover_per_year"),
                                 "eras": {name: v.get("gap_bp")
                                          for name, v in (arm.get("eras") or {}).items()}}
    late_face, late_path = _read_late_face(outdir, face["evidence_cutoff"], start)
    late_rows = (late_face or {}).get("answers", {}).get("delay_rows") or {}
    asym = {}
    for k in early:
        e_row = rows.get(_early_label(k))
        l_row = late_rows.get(_lag_label(k))
        if not e_row or not l_row:
            continue
        e_era = e_row["eras"].get("2024_now")
        l_era = l_row["eras"].get("2024_now")
        asym[_early_label(k)] = {
            "full_window_early_minus_late_bp":
                None if (e_row["full_window_gap_bp"] is None
                         or l_row["full_window_gap_bp"] is None)
                else round(e_row["full_window_gap_bp"] - l_row["full_window_gap_bp"], 1),
            "newest_era_early_minus_late_bp":
                None if (e_era is None or l_era is None) else round(e_era - l_era, 1),
        }
    face["study"] = "e66_earlydelay_ladder"
    face["answers"]["early_rows"] = rows
    face["answers"]["early_gap_bp"] = {lab: r["full_window_gap_bp"]
                                       for lab, r in rows.items()}
    face["answers"]["early_newest_era_gap_bp"] = {
        lab: r["eras"].get("2024_now") for lab, r in rows.items()}
    face["answers"]["late_rows_source"] = (os.path.relpath(late_path, ROOT)
                                           if late_face else None)
    face["answers"]["asymmetry_bp"] = asym
    face["honest"].append(
        "the early lag also moves the decision session, so the book is re-ranked on "
        "the earlier date on names that had already published then; the late column "
        "is read from the E65 face at the same cutoff+start (%s), not re-burned"
        % (face["answers"]["late_rows_source"] or "absent"))
    face["honest"].append(
        "an early decision is not the same book one session sooner: it can only buy "
        "what is already eligible, so a flat/or positive early side means the "
        "boundary is a publication deadline, not a price path")
    return face


# --------------------------------- leg: EARLY ladder, screened twin (E116)

def _earlydelay_arm_cells(face, starts=None):
    """(E116) -> {(key, column): value} for every cell the early-delay leg publishes.

    The easy mistake here is to harvest only ``answers.early_rows``: those rows
    are a *copy* of the ladder arms, and the arms themselves live one level
    down in ``gaps[x1][me_mK]`` beside the month-end book they are compared
    against. Both levels are harvested, because a repair that moves a book's
    own annual return and a repair that moves the gap are different findings.
    ``late_rows_source`` and the honest lines are pointers to another face, not
    measurements, so they are not joined.
    """
    out = {}
    lvl = (face.get("spec") or {}).get("cost_mult_list") or [1.0]
    lvl = "x%g" % lvl[0]

    for lab, book in (face.get("books") or {}).items():
        book = book or {}
        key = "book/%s/%s" % (lab, lvl)
        out[(key, "decision_days")] = book.get("decision_days")
        out[(key, "mean_sessions_to_month_end")] = (
            (book.get("offset") or {}).get("mean_sessions_to_month_end"))
        arm = (book.get("arms") or {}).get(lvl) or {}
        for col in ("full_window_ann_pct", "turnover_per_year",
                    "cost_per_year_bp"):
            out[(key, col)] = arm.get(col)
        for era, ed in (arm.get("eras") or {}).items():
            out[("book/%s/%s/era/%s" % (lab, lvl, era), "ann_return_pct")] = (
                (ed or {}).get("ann_return_pct"))

    for lab, gap in ((face.get("gaps") or {}).get(lvl) or {}).items():
        gap = gap or {}
        key = "gap/" + lab
        for col in ("full_window_gap_bp", "turnover_per_year", "cost_per_year_bp"):
            out[(key, col)] = gap.get(col)
        for era, ed in (gap.get("eras") or {}).items():
            out[("gap/%s/era/%s" % (lab, era), "gap_bp")] = (ed or {}).get("gap_bp")

    ans = face.get("answers") or {}
    for lab, row in (ans.get("early_rows") or {}).items():
        row = row or {}
        key = "early/" + lab
        for col in ("full_window_gap_bp", "turnover_per_year"):
            out[(key, col)] = row.get(col)
        for era, ev in (row.get("eras") or {}).items():
            out[("early/%s/era/%s" % (lab, era), "gap_bp")] = ev
    for lab, row in (ans.get("asymmetry_bp") or {}).items():
        row = row or {}
        for col in ("full_window_early_minus_late_bp",
                    "newest_era_early_minus_late_bp"):
            out[("asym/" + lab, col)] = row.get(col)
    for col in ("early_gap_bp", "early_newest_era_gap_bp"):
        for lab, v in (ans.get(col) or {}).items():
            out[("answers/" + col, lab)] = v
    out[("spec", "universe_members")] = (face.get("spec") or {}).get("universe_members")
    return out


def run_earlydelayscreen(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",),
                         early=(1, 3, 5, 10), costs=(1.0,), mode="neutralise_int",
                         resume=True):
    """E116: re-derive the EARLY ladder on the screened arm, beside the raw face.

    E97 row 5 after the burn-in/cut-curve/livespan/chase twins. The early side
    is the one place where a repaired print can also reorder *eligibility*: the
    early decision ranks names that had already published by that earlier date,
    so an arm that changes a print can change which name is picked, not just
    what it earned. That is why the book columns (each calendar's own annual
    return and turnover) are harvested beside the gap columns -- a gap that
    holds while both books move is a different reading from a gap that holds
    because neither book moved.

    Same machinery as E112-E115 on purpose: one load, both arms burned off it,
    checkpoints so a killed pass resumes, the shared ``_burnin_pair_rows`` join,
    and a same-arm control that must read zero everywhere.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]
    tag = cutoff.replace("-", "")

    def cached(label, thunk):
        p = os.path.join(outdir or ".", "EARLYDLY-arm-%s-%s.json" % (label, tag))
        if resume and os.path.isfile(p):
            try:
                with open(p, "r", encoding="utf-8") as fh:
                    return json.load(fh)
            except Exception:
                pass
        face = thunk()
        if outdir:
            write_json(outdir, "EARLYDLY-arm-%s-%s.json" % (label, tag), face)
        return face

    screened, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)

    kw = dict(start=start, pick_n=pick_n, exclude=exclude, early=early, costs=costs)
    raw_arm = cached("raw", lambda: run_earlydelay(None, raw=raw, **kw))
    scr_arm = cached(mode, lambda: run_earlydelay(None, raw=screened, **kw))

    keys = sorted({k[0] for k in _earlydelay_arm_cells(raw_arm)})
    no_dates = lambda face, ks: {}
    pair = _burnin_pair_rows(raw_arm, scr_arm, keys, cells_fn=_earlydelay_arm_cells,
                             dates_fn=no_dates)
    control = _burnin_pair_rows(raw_arm, raw_arm, keys, cells_fn=_earlydelay_arm_cells,
                                dates_fn=no_dates)["summary"]

    # cutoff control: newest previously published raw early face vs today's raw
    # arm -- same arm, two cutoffs, so it isolates the panel refresh.
    cutoff_control = None
    search_dirs = [d for d in (outdir, os.path.join(ROOT, "results", "e44_midmonth"))
                   if d and os.path.isdir(d)]
    olds = []
    for d in search_dirs:
        olds.extend(os.path.join(d, p) for p in os.listdir(d)
                    if p.startswith("EARLYDELAY-") and p.endswith(".json")
                    and not p.startswith("EARLYDELAYSCREEN-"))
    for path in sorted(olds, key=os.path.basename, reverse=True):
        p = os.path.basename(path)
        if p[len("EARLYDELAY-"):-len(".json")] == tag:
            continue
        try:
            with open(path, "r", encoding="utf-8") as fh:
                old_face = json.load(fh)
        except Exception:
            continue
        old_pair = _burnin_pair_rows(old_face, raw_arm, keys,
                                     cells_fn=_earlydelay_arm_cells,
                                     dates_fn=no_dates)
        cutoff_control = {
            "old_face": p,
            "old_cutoff": old_face.get("evidence_cutoff"),
            "comparison": "old raw arm vs today raw arm (arm held fixed)",
            "summary": old_pair["summary"],
            "moved": old_pair["moved"],
        }
        break

    s = pair["summary"]
    book_cols = ("full_window_ann_pct", "ann_return_pct", "turnover_per_year",
                 "cost_per_year_bp")
    gap_cols = ("full_window_gap_bp", "gap_bp",
                "full_window_early_minus_late_bp", "newest_era_early_minus_late_bp")
    book_moved = [r for r in pair["moved"] if r["column"] in book_cols]
    gap_moved = [r for r in pair["moved"] if r["column"] in gap_cols]
    other_moved = [r for r in pair["moved"]
                   if r["column"] not in book_cols and r["column"] not in gap_cols]
    survives = _twin_survives(s, control)
    # the sharpest single reading: does the newest-era early gap keep its sign
    # and its magnitude on the repaired arm?
    newest = {}
    # a null on both sides is not a defect of the join: with start=2020-01-01 the
    # pre2017 era has no bars at all, so every pre2017 cell is structurally empty
    # in BOTH arms. Counted and named here so it cannot be read as a one-sided cell.
    _nulls = pair["null_on_either_side"]
    _pre2017 = [r for r in _nulls if "/era/pre2017" in (r.get("start") or "")]
    raw_newest = (raw_arm.get("answers") or {}).get("early_newest_era_gap_bp") or {}
    scr_newest = (scr_arm.get("answers") or {}).get("early_newest_era_gap_bp") or {}
    for lab in sorted(raw_newest):
        va, vb = raw_newest.get(lab), scr_newest.get(lab)
        newest[lab] = {"raw": va, "screened": vb,
                       "delta": (None if va is None or vb is None else round(vb - va, 4)),
                       "same_sign": (None if va is None or vb is None
                                     else (va >= 0) == (vb >= 0))}
    return {
        "study": "e116_earlydelay_screened_twin",
        "evidence_cutoff": cutoff,
        "spec": {
            "pick_n": pick_n, "exclude_prefixes": list(exclude), "start": start,
            "early_sessions": list(early), "cost_mult_list": list(costs),
            "screen_mode": mode,
            "arms": {"raw": "e27.load_universe() as shipped",
                     "screened": "panel_screen.screen_universe(mode=%s)" % mode},
            "join": ("_earlydelay_arm_cells harvests each calendar's own annual "
                     "return + turnover, the gap rows, and the E66 early/asymmetry "
                     "answers; the late-face pointer and the honest lines are not "
                     "joined because they are references, not measurements"),
            "control": ("the same arm joined against itself; every cell must read "
                        "delta 0.0 or the join machinery moved the numbers"),
        },
        "screen_report": report,
        "pair": pair,
        "control": control,
        "cutoff_control": cutoff_control,
        "answers": {
            "counts_survive_the_repair": bool(survives),
            "cells_compared": s["cells_compared"],
            "cells_moved": s["cells_moved"],
            "max_abs_delta": s["max_abs_delta_pp"],
            "delta_units": ("each delta is in the units of its column: bp for gaps, "
                            "percent per year for annualised returns, turns/yr for "
                            "turnover -- the summary max is a max over mixed units "
                            "and is a screen, not a quantity"),
            "worst_cell": s["worst"],
            "book_cells_moved": len(book_moved),
            "gap_cells_moved": len(gap_moved),
            "other_cells_moved": len(other_moved),
            "control_cells_moved": control["cells_moved"],
            "null_cells": {
                "total": len(_nulls),
                "pre2017_no_bars": len(_pre2017),
                "other": len(_nulls) - len(_pre2017),
                "note": ("a cell null on BOTH arms is not one-sided: at "
                         "start=%s the pre2017 era carries no bars, so those cells "
                         "are empty by construction in both arms" % start),
            },
            "cutoff_control": ({"old_face": cutoff_control["old_face"],
                                "cells_moved": cutoff_control["summary"]["cells_moved"],
                                "max_abs_delta": cutoff_control["summary"]["max_abs_delta_pp"]}
                               if cutoff_control else None),
            "newest_era_early_gap": newest,
            "reading": (
                ("the early ladder survives the repair: %d of %d cells move, "
                 "%d book / %d gap" %
                 (s["cells_moved"], s["cells_compared"], len(book_moved),
                  len(gap_moved)))
                if survives else
                ("the repair reaches the early ladder: %d of %d cells move "
                 "(%d book, %d gap, %d other) and %d cell(s) exist on one arm only"
                 % (s["cells_moved"], s["cells_compared"], len(book_moved),
                    len(gap_moved), len(other_moved),
                    s["only_in_raw"] + s["only_in_screened"]))),
        },
        "honest": [
            "descriptive census only: no gate, no verdict on the strategy, no "
            "prereg, no trial count, no ledger booking",
            "the screened arm repairs prints inside the panel it is handed; it "
            "does not add or remove bars, so an unchanged universe_members count "
            "is a property of the repair, not evidence the panel is clean",
            "the early decision re-ranks on a date when fewer names have published, "
            "so a repair can change the picked set; a stable gap with both books "
            "moving is not the same finding as a stable gap with neither moving",
            "the late column of the asymmetry block is read from the E65 face on "
            "disk at the same cutoff+start, in both arms identically, so it cannot "
            "contribute a delta and is disclosed only for context",
            "E97 counts the published numbers of this runner; the join covers the "
            "book/gap/early/asymmetry cells, not the pointer fields",
        ],
    }


# --------------------------------- leg: the month-end NEIGHBOURHOOD (E67)

def run_neighborhood(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",),
                     costs=(1.0,), neighbors=(2,), raw=None):
    """E67: is the one-session penalty a spike on one session, or a ramp?

    E65 (late) and E66 (early) each priced 1/3/5/10 sessions off the boundary
    and both read a cost at every magnitude, which leaves the shape between
    one and three unresolved. This leg burns only the missing k-session arms
    (early k = `me_mK`, late k = `me_pK`) on the same universe and rank cache,
    then brackets each against the nearest already-burned magnitudes on the
    E65/E66 faces to say whether the penalty is a point kick or a ramp.

    ``raw`` (E120) is the screened-twin seam: the leg delegates to
    ``run_midsweep``, so a repaired universe is handed down one level unchanged.
    """
    neighbors = tuple(int(k) for k in neighbors)
    lags = tuple(sorted({-k for k in neighbors} | {k for k in neighbors}))
    face = run_midsweep(outdir, start=start, pick_n=pick_n, exclude=exclude,
                        days=(), costs=costs, lags=lags, raw=raw)
    lvl = "x%g" % costs[0]
    gaps = face["gaps"].get(lvl, {})
    rows = {}
    for k in neighbors:
        for lab, arm_lab in ((_early_label(k), _lag_label(-k)),
                             ("me_p%d" % k, _lag_label(k))):
            arm = gaps.get(arm_lab)
            if arm is None:
                continue
            rows[lab] = {"source_row": arm_lab,
                         "full_window_gap_bp": arm.get("full_window_gap_bp"),
                         "turnover_per_year": arm.get("turnover_per_year"),
                         "eras": {name: v.get("gap_bp")
                                  for name, v in (arm.get("eras") or {}).items()}}
    early_face, early_path, early_cut = _delay_face_any(
        outdir, "EARLYDELAY", face["evidence_cutoff"], start)
    late_face, late_path, late_cut = _delay_face_any(
        outdir, "ENTRYDELAY", face["evidence_cutoff"], start)
    early_rows = ((early_face or {}).get("answers", {}).get("early_rows") or {})
    late_rows = ((late_face or {}).get("answers", {}).get("delay_rows") or {})

    def _pick(rowset, lab, field, era=None):
        row = rowset.get(lab)
        if not row:
            return None
        if era:
            return (row.get("eras") or {}).get(era)
        return row.get(field)

    def _value(side, k, rowset, era=None):
        # this leg's own rows first, then the E65/E66 faces at the same cutoff+start
        lab = "me_m%d" % k if side == "early" else "me_p%d" % k
        if lab in rows:
            row = rows[lab]
            return (row.get("eras") or {}).get(era) if era else row["full_window_gap_bp"]
        src = "me_m%d" % k if side == "early" else _lag_label(k)
        return _pick(rowset, src, "full_window_gap_bp", era)

    brackets = {}
    for side, rowset in (("early", early_rows), ("late", late_rows)):
        side_src = os.path.relpath(early_path if side == "early" else late_path, ROOT) \
            if (early_face if side == "early" else late_face) else None
        for k in neighbors:
            seq = (k - 1, k, k + 1)
            brackets["%s_k%d" % (side, k)] = {
                "labels": ["me_m%d" % s if side == "early" else "me_p%d" % s
                           for s in seq],
                "full_window_bp": [_value(side, s, rowset) for s in seq],
                "newest_era_bp": [_value(side, s, rowset, "2024_now") for s in seq],
                "full_window_shape": _bracket_shape(
                    [_value(side, s, rowset) for s in seq]),
                "newest_era_shape": _bracket_shape(
                    [_value(side, s, rowset, "2024_now") for s in seq]),
                "neighbor_rows_source": side_src,
            }

    face["study"] = "e67_monthend_neighborhood"
    face["answers"]["neighbor_rows"] = rows
    face["answers"]["neighbor_gap_bp"] = {lab: r["full_window_gap_bp"]
                                          for lab, r in rows.items()}
    face["answers"]["neighbor_newest_era_gap_bp"] = {
        lab: r["eras"].get("2024_now") for lab, r in rows.items()}
    face["answers"]["brackets"] = brackets
    face["answers"]["bound_rows_cutoff"] = {"early": early_cut, "late": late_cut}
    face["answers"]["bound_rows_source"] = {
        "early": os.path.relpath(early_path, ROOT) if early_face else None,
        "late": os.path.relpath(late_path, ROOT) if late_face else None}
    face["honest"].append(
        "the bracket bounds are read from the E65/E66 faces (%s / %s), not re-burned; "
        "only the k-session arms here are new" % (
            ("%s @%s" % (os.path.relpath(early_path, ROOT), early_cut)) if early_face
            else "early absent",
            ("%s @%s" % (os.path.relpath(late_path, ROOT), late_cut)) if late_face
            else "late absent"))
    if (early_face and early_cut != face["evidence_cutoff"]) or (
            late_face and late_cut != face["evidence_cutoff"]):
        face["honest"].append(
            "the bracket faces were burned on an older panel cutoff (%s/%s) than this "
            "leg (%s), so the bracket mixes one extra bar of data and is a shape "
            "reading, not a same-cutoff comparison"
            % (early_cut, late_cut, face["evidence_cutoff"]))
    face["honest"].append(
        "shape labels come from a +/-2bp tolerance on three points: they describe the "
        "ladder, they are not a test and no arm here is a recommendation")
    return face


# ----------------------------------- E120 neighborhood screened twin

def _neighborhood_arm_cells(face, starts=None):
    """(E120) -> {(key, column): value} for every cell the neighborhood leg publishes.

    The published reading of this runner is a three-point bracket, so the
    harvest keeps the three positions APART: the centre (the k the leg burns)
    and its two shoulders are separate cells. A join that averaged them would
    be unable to say whether a repair bends the shape or shifts the level,
    which is the whole question this twin exists to answer.
    """
    out = {}
    lvl = "x%g" % (((face.get("spec") or {}).get("cost_mult_list") or [1.0])[0])

    for lab, book in (face.get("books") or {}).items():
        book = book or {}
        key = "book/%s/%s" % (lab, lvl)
        out[(key, "decision_days")] = book.get("decision_days")
        out[(key, "mean_sessions_to_month_end")] = (
            (book.get("offset") or {}).get("mean_sessions_to_month_end"))
        arm = (book.get("arms") or {}).get(lvl) or {}
        for col in ("full_window_ann_pct", "turnover_per_year", "cost_per_year_bp"):
            out[(key, col)] = arm.get(col)
        for era, ed in (arm.get("eras") or {}).items():
            out[("book/%s/%s/era/%s" % (lab, lvl, era), "ann_return_pct")] = (
                (ed or {}).get("ann_return_pct"))

    for lab, gap in ((face.get("gaps") or {}).get(lvl) or {}).items():
        gap = gap or {}
        key = "gap/" + lab
        for col in ("full_window_gap_bp", "turnover_per_year", "cost_per_year_bp"):
            out[(key, col)] = gap.get(col)
        for era, ed in (gap.get("eras") or {}).items():
            out[("gap/%s/era/%s" % (lab, era), "gap_bp")] = (ed or {}).get("gap_bp")

    ans = face.get("answers") or {}
    for lab, row in (ans.get("neighbor_rows") or {}).items():
        row = row or {}
        key = "neighbor/" + lab
        for col in ("full_window_gap_bp", "turnover_per_year"):
            out[(key, col)] = row.get(col)
        for era, ev in (row.get("eras") or {}).items():
            out[("neighbor/%s/era/%s" % (lab, era), "gap_bp")] = ev
    for col in ("neighbor_gap_bp", "neighbor_newest_era_gap_bp"):
        for lab, v in (ans.get(col) or {}).items():
            out[("answers/%s/%s" % (col, lab), "gap_bp")] = v
    for name, br in (ans.get("brackets") or {}).items():
        br = br or {}
        for col in ("full_window_bp", "newest_era_bp"):
            for idx, v in enumerate(br.get(col) or []):
                out[("bracket/%s/%s/%d" % (name, col, idx), "gap_bp")] = v
    out[("spec", "universe_members")] = (face.get("spec") or {}).get("universe_members")
    return out


def _arm_rank(label):
    """(E120) sessions away from the month boundary, read off an arm label.

    ``me`` is 0 (the boundary itself), ``me_mK`` is K sessions early and
    ``me_lagK`` / ``me_pK`` is K sessions late (the E67 leg republishes the late
    arm under ``me_pK`` while its source row keeps the ``me_lagK`` name). An
    unrecognised label returns None so it is published as 'other' rather than
    silently counted as a shoulder.
    """
    lab = str(label or "")
    if lab == "me":
        return 0
    for pre in ("me_m", "me_lag", "me_p"):
        if lab.startswith(pre):
            rest = lab[len(pre):]
            # the early arms live in the gaps layer as me_lag-K (signed), while
            # the published neighbour rows rename them me_mK: both must classify
            # to the same magnitude or half the bracket lands in 'other'.
            try:
                return int(rest)
            except ValueError:
                return None
    return None


def _neighborhood_cell_role(start, centre=2):
    """(E120) which part of the bracket does a moved cell belong to?

    The seed for this leg says the split IS the deliverable: a repair can move
    the CENTRE while leaving both shoulders alone, or the reverse. So a moved
    cell is named by its position and never only counted in a total.
    """
    s = str(start or "")
    if s.startswith("bracket/"):
        return "centre" if s.endswith("/1") else "shoulder"
    arm = None
    if s.startswith("neighbor/") or s.startswith("gap/"):
        parts = s.split("/")
        arm = parts[1] if len(parts) > 1 else None
    elif s.startswith("answers/"):
        arm = s.rsplit("/", 1)[-1]
    if arm is not None:
        k = _arm_rank(arm)
        if k is None:
            return "other"
        if k == 0:
            return "baseline"
        # magnitude: the early arms are stored as me_lag-K (negative offset) while
        # the published copy names them me_mK, and both sit K sessions off the
        # boundary -- a role computed on the sign would split the same arm in two.
        return "centre" if abs(k) == int(centre) else "shoulder"
    if s.startswith("book/"):
        return "book"
    return "other"


def _neighborhood_shift_verdict(centre_moved, shoulder_moved):
    """(E120) did the repair bend the bracket's shape or shift its level?"""
    if centre_moved and not shoulder_moved:
        return ("centre moved, shoulders held: the repair bends the shape, "
                "not the level")
    if centre_moved and shoulder_moved:
        return ("centre and shoulders moved together: the repair shifts the "
                "level as well")
    if shoulder_moved:
        return ("shoulders moved with the centre held: the bracket is not a "
                "ladder on this panel")
    return "nothing moved: the bracket survives the repair"


def run_neighborhoodscreen(outdir, start="2020-01-01", pick_n=9999,
                           exclude=("sh511",), neighbors=(1, 2, 3), centre=2,
                           costs=(1.0,), mode="neutralise_int", resume=True):
    """E120: re-derive the month-boundary bracket on the screened arm.

    E97 ranks this runner second on the uncovered list (139 published numbers,
    one mode). Two things make the twin necessary rather than a copy:

      * the published leg burns only the k arms it was asked for and then
        brackets them against the E65/E66 faces ON DISK, so its shoulders are
        frozen -- no repair can move them and a same-spec twin would publish a
        guaranteed zero shoulder count;
      * the published reading is a SHAPE ("spike on one session" vs "ramp"), so
        the twin has to keep the three rung positions apart and say whether the
        repair bent the shape or merely shifted the level.

    So this leg burns the shoulders itself (neighbors default 1/2/3) on both
    arms and composes the bracket from its own rows, then publishes the
    centre/shoulder split of the moved cells.

    Same machinery as E112-E119 otherwise: one load, both arms burned off it,
    per-arm checkpoints, the shared ``_burnin_pair_rows`` join, a same-arm
    control that must read zero, and a cutoff control against the newest
    previously published raw neighborhood face.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    neighbours = tuple(int(k) for k in neighbors)
    if int(centre) not in neighbours:
        raise ValueError("centre=%r must be one of neighbors=%r"
                         % (centre, neighbours))

    raw = e27.load_universe()
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]
    tag = cutoff.replace("-", "")

    def cached(label, thunk):
        p = os.path.join(outdir or ".", "NEIGHBOR-arm-%s-%s.json" % (label, tag))
        if resume and os.path.isfile(p):
            try:
                with open(p, "r", encoding="utf-8") as fh:
                    return json.load(fh)
            except Exception:
                pass
        face = thunk()
        if outdir:
            write_json(outdir, "NEIGHBOR-arm-%s-%s.json" % (label, tag), face)
        return face

    screened, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)

    kw = dict(start=start, pick_n=pick_n, exclude=exclude,
              neighbors=neighbours, costs=costs)
    raw_arm = cached("raw", lambda: run_neighborhood(None, raw=raw, **kw))
    scr_arm = cached(mode, lambda: run_neighborhood(None, raw=screened, **kw))

    keys = sorted({k[0] for k in _neighborhood_arm_cells(raw_arm)})
    no_dates = lambda face, ks: {}
    pair = _burnin_pair_rows(raw_arm, scr_arm, keys,
                             cells_fn=_neighborhood_arm_cells, dates_fn=no_dates)
    control = _burnin_pair_rows(raw_arm, raw_arm, keys,
                                cells_fn=_neighborhood_arm_cells,
                                dates_fn=no_dates)["summary"]

    # cutoff control: newest published raw neighborhood face vs today's raw arm.
    # Same arm, two cutoffs, so it sizes the panel refresh beside the repair.
    # Only the k arms the older face actually burned are shared, so the one-sided
    # counts of that join are structural (new shoulder arms), not a defect.
    cutoff_control = None
    search_dirs = [d for d in (outdir, os.path.join(ROOT, "results", "e44_midmonth"))
                   if d and os.path.isdir(d)]
    olds = []
    for d in search_dirs:
        olds.extend(os.path.join(d, p) for p in os.listdir(d)
                    if p.startswith("NEIGHBORHOOD-") and p.endswith(".json")
                    and not p.startswith("NEIGHBORHOODSCREEN-")
                    and not p.startswith("NEIGHBOR-arm-"))
    for path in sorted(olds, key=os.path.basename, reverse=True):
        p = os.path.basename(path)
        if p[len("NEIGHBORHOOD-"):-len(".json")] == tag:
            continue
        try:
            with open(path, "r", encoding="utf-8") as fh:
                old_face = json.load(fh)
        except Exception:
            continue
        old_pair = _burnin_pair_rows(old_face, raw_arm, keys,
                                     cells_fn=_neighborhood_arm_cells,
                                     dates_fn=no_dates)
        cutoff_control = {
            "old_face": p,
            "old_cutoff": old_face.get("evidence_cutoff"),
            "comparison": "old raw arm vs today raw arm (arm held fixed)",
            "summary": old_pair["summary"],
            "moved": old_pair["moved"],
            "one_sided_is_structural": True,
        }
        break

    s = pair["summary"]
    by_role = {}
    for r in pair["moved"]:
        by_role.setdefault(_neighborhood_cell_role(r["start"], centre), []).append(r)
    roles = {role: {"cells_moved": len(rs),
                    "max_abs_delta": round(max(abs(x["delta"]) for x in rs), 4)}
             for role, rs in sorted(by_role.items())}
    centre_moved = len(by_role.get("centre") or [])
    shoulder_moved = len(by_role.get("shoulder") or [])
    survives = _twin_survives(s, control)

    # the bracket itself, composed from THIS leg's own rows on each arm -- no
    # frozen faces, so a shoulder delta is a measurement rather than an artefact
    # of not re-burning it.
    def _bracket_rows(face, side, era=None):
        ans = face.get("answers") or {}
        d = ((ans.get("neighbor_newest_era_gap_bp") if era
              else ans.get("neighbor_gap_bp")) or {})
        labs = [("me_m%d" % k if side == "early" else "me_p%d" % k)
                for k in (centre - 1, centre, centre + 1)]
        return labs, [d.get(x) for x in labs]

    brackets = {}
    for side in ("early", "late"):
        for wname, era in (("full_window", None), ("newest_era", "2024_now")):
            per_arm = {}
            for label, face in (("raw", raw_arm), ("screened", scr_arm)):
                labs, vals = _bracket_rows(face, side, era)
                per_arm[label] = {
                    "labels": labs,
                    "gap_bp": [None if v is None else round(v, 3) for v in vals],
                    "shape": _bracket_shape(vals),
                }
            brackets["%s_%s" % (side, wname)] = {
                "raw": per_arm["raw"],
                "screened": per_arm["screened"],
                "shape_survives": per_arm["raw"]["shape"] == per_arm["screened"]["shape"],
            }

    return {
        "study": "e120_neighborhood_screened_twin",
        "evidence_cutoff": cutoff,
        "spec": {
            "pick_n": pick_n, "exclude_prefixes": list(exclude), "start": start,
            "neighbor_sessions": list(neighbours), "centre_sessions": int(centre),
            "cost_mult_list": list(costs), "screen_mode": mode,
            "arms": {"raw": "e27.load_universe() as shipped",
                     "screened": "panel_screen.screen_universe(mode=%s)" % mode},
            "seam": ("run_neighborhood delegates to run_midsweep, so raw= is "
                     "threaded through both layers"),
            "shoulders": ("the twin burns neighbours 1..%d itself; the published "
                          "E67 leg instead reads its k-1 / k+1 bounds from the "
                          "E65/E66 faces on disk, where no repair can move them"
                          % max(neighbours)),
            "join": ("_neighborhood_arm_cells keeps the three bracket positions "
                     "apart and _neighborhood_cell_role names each moved cell "
                     "centre / shoulder / book / answers, so the split is the "
                     "published reading rather than a total"),
            "control": ("the same arm joined against itself; every cell must read "
                        "delta 0.0 or the join machinery moved the numbers"),
        },
        "screen_report": report,
        "pair": pair,
        "control": control,
        "cutoff_control": cutoff_control,
        "brackets": brackets,
        "answers": {
            "counts_survive_the_repair": bool(survives),
            "cells_compared": s["cells_compared"],
            "cells_moved": s["cells_moved"],
            "max_abs_delta": s["max_abs_delta_pp"],
            "delta_units": ("each delta is in the units of its column: bp for "
                            "gaps, percent per year for annualised returns, "
                            "turns/yr for turnover, sessions for offsets -- the "
                            "summary max is a max over mixed units and is a "
                            "screen, not a quantity"),
            "worst_cell": s["worst"],
            "moved_by_role": roles,
            "centre_cells_moved": centre_moved,
            "shoulder_cells_moved": shoulder_moved,
            "shift_verdict": _neighborhood_shift_verdict(centre_moved,
                                                         shoulder_moved),
            "control_cells_moved": control["cells_moved"],
            "bracket_shapes": {k: {"raw": v["raw"]["shape"],
                                   "screened": v["screened"]["shape"],
                                   "shape_survives": v["shape_survives"]}
                               for k, v in brackets.items()},
            "cutoff_control": ({"old_face": cutoff_control["old_face"],
                                "old_cutoff": cutoff_control["old_cutoff"],
                                "cells_moved":
                                    cutoff_control["summary"]["cells_moved"],
                                "max_abs_delta":
                                    cutoff_control["summary"]["max_abs_delta_pp"]}
                               if cutoff_control else None),
            "reading": (
                ("the bracket survives the repair: %d of %d cells move "
                 "(%d centre / %d shoulder)"
                 % (s["cells_moved"], s["cells_compared"], centre_moved,
                    shoulder_moved))
                if survives else
                ("the repair reaches the bracket: %d of %d cells move "
                 "(%d centre, %d shoulder, %d other) and %d cell(s) exist on "
                 "one arm only"
                 % (s["cells_moved"], s["cells_compared"], centre_moved,
                    shoulder_moved,
                    s["cells_moved"] - centre_moved - shoulder_moved,
                    s["only_in_raw"] + s["only_in_screened"]))),
        },
        "honest": [
            "descriptive census only: no gate, no verdict on the strategy, no "
            "prereg, no trial count, no ledger booking",
            "the shoulders are re-burned rather than read off the E65/E66 faces, "
            "because a frozen bound cannot move under a repair: the split here "
            "is a measurement on both arms, and it is NOT comparable cell by "
            "cell with the published E67 face",
            "the screened arm repairs prints inside the panel it is handed; it "
            "does not add or remove bars, so an unchanged universe_members count "
            "is a property of the repair, not evidence the panel is clean",
            "bracket shapes come from a +/-2bp tolerance on three points and are "
            "a description of one centre and its two neighbours, not a fitted "
            "curve and not a recommendation",
            "the cutoff control joins an older raw face whose neighbour set is "
            "narrower, so its one-sided count is structural and only the shared "
            "cells carry the refresh reading",
            "E97 counts the published numbers of this runner; the join covers the "
            "book/gap/neighbor/answers/bracket cells, not the pointer fields",
            "the published routine emits a bracket for EVERY burned magnitude, so "
            "its k=1 and k=3 brackets reach k=0 and k=4, which this leg does not "
            "burn: those four cells read null on both arms by construction, and "
            "only the centre bracket is complete",
        ],
    }


# ------------------------------ E121 rebalance-calendar screened twin

def _rebalday_arm_cells(face, starts=None):
    """(E121) -> {(key, column): value} for every number the rebalday leg publishes.

    This runner's published reading is a table of calendars x books, so the
    harvest keeps two kinds of number in separate namespaces: what each calendar
    EARNED (ann_return_pct / drawdown / win rate) and WHEN the book TRADED
    (decision-session counts, rebalances, turnover). ``_rebalday_cell_role``
    then names which kind a moved cell belongs to, because "the repair moved the
    trade calendar" and "the repair moved every calendar's return" are different
    findings that a single moved-cell total would blend.
    """
    out = {}
    for start, w in (face.get("windows") or {}).items():
        w = w or {}
        for vname, row in (w.get("variants") or {}).items():
            row = row or {}
            out[("calendar/%s/%s" % (start, vname), "rebalances")] = row.get("rebalances")
            out[("spread/%s/%s" % (start, vname), "vs_ladder_spread_bp")] = row.get(
                "vs_ladder_spread_bp")
            for scheme, cell in row.items():
                if not isinstance(cell, dict):
                    continue
                base = "book/%s/%s/%s" % (start, vname, scheme)
                for col in ("ann_return_pct", "max_drawdown_pct",
                            "monthly_win_rate_pct", "turnover_per_year",
                            "rebalances"):
                    out[(base, col)] = cell.get(col)
        for col, v in (w.get("answers") or {}).items():
            # spread_all_positive is a verdict, not a level: subtracting two
            # booleans would book a "delta" with no units.
            if isinstance(v, bool) or not isinstance(v, (int, float)):
                continue
            out[("answers/%s" % start, col)] = v
        out[("window/%s" % start, "bars")] = w.get("bars")
        out[("window/%s" % start, "years")] = w.get("years")
    return out


_RETURN_COLUMNS = ("ann_return_pct", "max_drawdown_pct", "monthly_win_rate_pct")
_SPREAD_COLUMNS = ("vs_ladder_spread_bp", "spread_range_bp", "spread_min_bp",
                   "spread_max_bp", "spread_at_month_end_bp")
_CALENDAR_COLUMNS = ("rebalances", "turnover_per_year")


def _rebalday_cell_role(start, column):
    """(E121) does a moved cell say WHEN the book traded or WHAT it earned?

    ``calendar`` = the decision/trade schedule itself (rebalance counts and
    turnover). ``returns`` = what a calendar earned. ``spread`` = the ladder-vs-
    wide difference, which is a ratio of two books. ``frame`` = the window's own
    bars/years and the universe count, which move only if the panel changed
    length. Anything unrecognised is published as ``other`` rather than folded
    into a named role.
    """
    col = str(column or "")
    s = str(start or "")
    if col in _CALENDAR_COLUMNS:
        return "calendar"
    if col in _RETURN_COLUMNS or col in ("ladder_ann_range_bp", "wide_ann_range_bp"):
        return "returns"
    if col in _SPREAD_COLUMNS:
        return "spread"
    if col in ("bars", "years", "universe_members"):
        return "frame"
    return "other"


def _rebalday_shift_verdict(returns_moved, calendar_moved):
    """(E121) did the repair change WHEN the book traded or WHAT it earned?"""
    if calendar_moved and not returns_moved:
        return ("the repair changes WHEN the book traded, not WHAT it earned: "
                "the moved cells are decision/rebalance cells while every "
                "calendar's own return holds")
    if calendar_moved and returns_moved:
        return ("the repair moves the trade calendar and the returns measured "
                "on it together, so no calendar row here can be quoted apart "
                "from the repair")
    if returns_moved:
        return ("the repair moves the returns while the trade calendar is "
                "untouched: the calendars disagree by the same schedule, what "
                "moved is the level")
    return "nothing moved: the rebalance-calendar face survives the repair"


def _rebalday_older_raw(outdir, tag):
    """(E121) the newest PUBLISHED raw rebalday face other than ``tag``.

    The runner's published face is written by the ``rebalday`` CLI mode to
    ``results/e41_rebal_day/SHIFT-<cutoff>.json`` -- NOT into this leg's own
    directory and NOT under a REBALDAY- name. Looking in the obvious place
    returns None, and a None cutoff control reads exactly like "no older face
    exists", so the path is kept in one function the selftest can point at a
    temp dir.
    """
    search_dirs = [d for d in (outdir, os.path.join(ROOT, "results", "e41_rebal_day"))
                   if d and os.path.isdir(d)]
    olds = []
    for d in search_dirs:
        olds.extend(os.path.join(d, p) for p in os.listdir(d)
                    if p.startswith("SHIFT-") and p.endswith(".json"))
    for path in sorted(olds, key=os.path.basename, reverse=True):
        if os.path.basename(path)[len("SHIFT-"):-len(".json")] == tag:
            continue
        try:
            with open(path, "r", encoding="utf-8") as fh:
                return path, json.load(fh)
        except Exception:
            continue
    return None, None


def run_rebaldayscreen(outdir, starts=("2020-01-01", "2018-01-01"), pick_n=9999,
                       exclude=("sh511",), mode="neutralise_int", resume=True):
    """E121: re-derive the rebalance-calendar face on the screened arm.

    E97 ranks this runner third on the uncovered list (132 numbers, one mode).
    What makes the twin worth burning rather than copying is that this leg holds
    the axis every other twin moves: it prices the CALENDAR itself. So the
    reading here is a split, not a total -- a moved rebalance count means the
    repair changed when the book traded, while a moved ann_return means it
    changed what the book earned on that schedule, and a spread that holds
    because neither book moved is a different finding from one that holds
    because both moved together.

    Same machinery as E112-E120: one load, both arms burned off it, per-arm
    checkpoints, the shared ``_burnin_pair_rows`` join, a same-arm control that
    must read zero, and a cutoff control against the newest published raw
    rebalday face so the panel refresh is sized beside the repair.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]
    tag = cutoff.replace("-", "")

    def cached(label, thunk):
        p = os.path.join(outdir or ".", "REBALDAY-arm-%s-%s.json" % (label, tag))
        if resume and os.path.isfile(p):
            try:
                with open(p, "r", encoding="utf-8") as fh:
                    return json.load(fh)
            except Exception:
                pass
        face = thunk()
        if outdir:
            write_json(outdir, "REBALDAY-arm-%s-%s.json" % (label, tag), face)
        return face

    screened, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)

    kw = dict(starts=tuple(starts), pick_n=pick_n, exclude=exclude)
    raw_arm = cached("raw", lambda: run_rebalday(None, raw=raw, **kw))
    scr_arm = cached(mode, lambda: run_rebalday(None, raw=screened, **kw))

    keys = sorted({k[0] for k in _rebalday_arm_cells(raw_arm)})
    no_dates = lambda face, ks: {}
    pair = _burnin_pair_rows(raw_arm, scr_arm, keys,
                            cells_fn=_rebalday_arm_cells, dates_fn=no_dates)
    control = _burnin_pair_rows(raw_arm, raw_arm, keys,
                                cells_fn=_rebalday_arm_cells,
                                dates_fn=no_dates)["summary"]

    # cutoff control: the runner's own PUBLISHED raw face is
    # results/e41_rebal_day/SHIFT-<cutoff>.json (the rebalday CLI writes it
    # there), so that is where an older raw arm can be found -- joining the
    # twin's own arm caches would compare today against today and read zero by
    # construction.
    cutoff_control = None
    path, old_face = _rebalday_older_raw(outdir, tag)
    if old_face is not None:
        old_pair = _burnin_pair_rows(old_face, raw_arm, keys,
                                     cells_fn=_rebalday_arm_cells,
                                     dates_fn=no_dates)
        cutoff_control = {
            "old_face": os.path.relpath(path, ROOT),
            "old_cutoff": old_face.get("evidence_cutoff"),
            "comparison": "old raw arm vs today raw arm (arm held fixed)",
            "summary": old_pair["summary"],
            "moved": old_pair["moved"],
            "one_sided_is_structural": True,
        }

    s = pair["summary"]
    by_role = {}
    for r in pair["moved"]:
        by_role.setdefault(_rebalday_cell_role(r["start"], r["column"]),
                           []).append(r)
    roles = {role: {"cells_moved": len(rs),
                    "max_abs_delta": round(max(abs(x["delta"]) for x in rs), 4)}
             for role, rs in sorted(by_role.items())}
    returns_moved = len(by_role.get("returns") or [])
    calendar_moved = len(by_role.get("calendar") or [])
    survives = _twin_survives(s, control)

    # the calendar table itself, side by side, so the role counts can be read
    # against the rows they came from instead of being taken on trust
    calendar_view = {}
    for start in starts:
        rw = (raw_arm.get("windows") or {}).get(start) or {}
        sw = (scr_arm.get("windows") or {}).get(start) or {}
        rows = {}
        for vname, rrow in (rw.get("variants") or {}).items():
            srow = (sw.get("variants") or {}).get(vname) or {}
            rows[vname] = {
                "raw_rebalances": rrow.get("rebalances"),
                "screened_rebalances": srow.get("rebalances"),
                "raw_spread_bp": rrow.get("vs_ladder_spread_bp"),
                "screened_spread_bp": srow.get("vs_ladder_spread_bp"),
                "raw_ladder_ann_pct": (rrow.get("ladder5") or {}).get("ann_return_pct"),
                "screened_ladder_ann_pct": (srow.get("ladder5") or {}).get(
                    "ann_return_pct"),
            }
        calendar_view[start] = {
            "rows": rows,
            "raw_spread_all_positive": (rw.get("answers") or {}).get(
                "spread_all_positive"),
            "screened_spread_all_positive": (sw.get("answers") or {}).get(
                "spread_all_positive"),
        }

    return {
        "study": "e121_rebalday_screened_twin",
        "evidence_cutoff": cutoff,
        "spec": {
            "pick_n": pick_n, "exclude_prefixes": list(exclude),
            "starts": list(starts), "screen_mode": mode,
            "arms": {"raw": "e27.load_universe() as shipped",
                     "screened": "panel_screen.screen_universe(mode=%s)" % mode},
            "seam": "run_rebalday gained raw= so both arms burn off one load",
            "join": ("_rebalday_arm_cells keeps calendar / returns / spread cells "
                     "in separate namespaces and _rebalday_cell_role names each "
                     "moved cell, so the split is the published reading"),
            "control": ("the same arm joined against itself; every cell must read "
                        "delta 0.0 or the join machinery moved the numbers"),
        },
        "screen_report": report,
        "pair": pair,
        "control": control,
        "cutoff_control": cutoff_control,
        "calendar_view": calendar_view,
        "answers": {
            "counts_survive_the_repair": bool(survives),
            "cells_compared": s["cells_compared"],
            "cells_moved": s["cells_moved"],
            "max_abs_delta": s["max_abs_delta_pp"],
            "delta_units": ("each delta is in the units of its column: bp for "
                            "spreads, percent per year for annualised returns, "
                            "turns/yr for turnover, sessions for offsets -- the "
                            "summary max is a max over mixed units and is a "
                            "screen, not a quantity"),
            "worst_cell": s["worst"],
            "moved_by_role": roles,
            "returns_cells_moved": returns_moved,
            "calendar_cells_moved": calendar_moved,
            "shift_verdict": _rebalday_shift_verdict(returns_moved, calendar_moved),
            "control_cells_moved": control["cells_moved"],
            "cutoff_control": ({"old_face": cutoff_control["old_face"],
                                "old_cutoff": cutoff_control["old_cutoff"],
                                "cells_moved":
                                    cutoff_control["summary"]["cells_moved"],
                                "max_abs_delta":
                                    cutoff_control["summary"]["max_abs_delta_pp"]}
                               if cutoff_control else None),
            "reading": (
                ("the calendar face survives the repair: %d of %d cells move "
                 "(%d calendar / %d returns / %d spread)"
                 % (s["cells_moved"], s["cells_compared"], calendar_moved,
                    returns_moved, len(by_role.get("spread") or [])))
                if survives else
                ("the repair reaches the calendar face: %d of %d cells move "
                 "(%d calendar, %d returns, %d spread, %d other) and %d cell(s) "
                 "exist on one arm only"
                 % (s["cells_moved"], s["cells_compared"], calendar_moved,
                    returns_moved, len(by_role.get("spread") or []),
                    len(by_role.get("other") or []) + len(by_role.get("frame") or []),
                    s["only_in_raw"] + s["only_in_screened"]))),
        },
        "honest": [
            "descriptive census only: no gate, no verdict on the strategy, no "
            "prereg, no trial count, no ledger booking",
            "the split is a classification of moved cells, not a decomposition: "
            "a calendar cell and a return cell can move for one and the same "
            "repair, and the counts say how many cells each role lost, not how "
            "much of a change each role caused",
            "spread_all_positive is published per arm as a verdict and is NOT "
            "joined: subtracting two booleans would book a delta with no units",
            "the screened arm repairs prints inside the panel it is handed; it "
            "does not add or remove bars, so an unchanged universe_members count "
            "is a property of the repair, not evidence the panel is clean",
            "the cutoff control joins an older raw face whose start set may be "
            "narrower, so its one-sided count is structural and only the shared "
            "cells carry the refresh reading",
            "E97 counts the published numbers of this runner; the join covers the "
            "book/calendar/spread/answers/window cells, not the pointer fields",
        ],
    }


# --------------------------------- leg: month-end vs the weekly grid (E69/E70)

def _weekly_cal_rows(face, tag, labels=("week", "week_near_me")):
    """E70: the calendar rows of one cost level, keyed by book label.

    Kept pure so the cost-level wiring is testable without a burn: the fee
    question (does switching the multiplier move the calendar gap) needs the
    same rows at two levels, and reading them out of one dict is the only way
    to be sure the comparison is not two different burns.
    """
    gaps = (face.get("gaps") or {}).get(tag) or {}
    books = face.get("books") or {}
    out = {}
    for lab in labels:
        g = gaps.get(lab) or {}
        out[lab] = {
            "decision_days": (books.get(lab) or {}).get("decision_days"),
            "full_window_gap_bp": g.get("full_window_gap_bp"),
            "turnover_per_year": g.get("turnover_per_year"),
            "cost_per_year_bp": g.get("cost_per_year_bp"),
            "eras": {name: v.get("gap_bp")
                     for name, v in (g.get("eras") or {}).items()},
        }
    return out


def run_weeklyclash(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",),
                    costs=(1.0,)):
    """E69: is month-end a calendar of its own, or a re-timed weekly book?

    E68 put the plateau at the first week off the boundary, which is exactly
    where a weekly rebalance sits. Two readings are priced on one universe,
    one rank cache and one cost level: `week` (the full ISO weekly grid, the
    densest rule in the panel) and `week_near_me` (the SAME weekly grid cut to
    one decision per month, taken at the weekly session nearest the boundary).
    If the monthly-cadence weekly book matches month-end, adopting month-end is
    a re-timing; if it loses, the boundary date carries the information. The
    turnover/cost columns answer the second half of the question directly:
    does the month-end calendar trade more than the weekly one, or less.
    """
    face = run_midsweep(outdir, start=start, pick_n=pick_n, exclude=exclude,
                        days=(), costs=costs, lags=(), weekly=True)
    tags = ["x%g" % c for c in costs]
    lvl = tags[0]
    # E70: every cost level keeps its own row set, so the fee question is answered
    # inside the face instead of by hand-diffing two burns.
    rows_by_cost = {tag: _weekly_cal_rows(face, tag) for tag in tags}
    rows = rows_by_cost[lvl]
    me_turn = face["books"].get("me", {}).get("arms", {}).get(lvl, {}).get(
        "turnover_per_year")
    me_turn_by_cost = {tag: face["books"].get("me", {}).get("arms", {}).get(
        tag, {}).get("turnover_per_year") for tag in tags}

    def _ratio(lab, ref=None, tag=lvl):
        t = rows_by_cost.get(tag, {}).get(lab, {}).get("turnover_per_year")
        m = me_turn if ref is None else ref
        if t is None or not m:
            return None
        return round(t / m, 3)

    cost_face = _cost_face(face["gaps"], tags[0], tags[-1]) if len(tags) > 1 else None

    face["study"] = "e70_monthend_weekly_costface" if cost_face else \
        "e69_monthend_weekly_clash"
    face["answers"]["calendar_rows"] = rows
    if cost_face:
        face["answers"]["calendar_rows_by_cost"] = rows_by_cost
        face["answers"]["cost_face"] = cost_face
        face["answers"]["cost_shift_bp"] = {
            lab: (cost_face.get(lab) or {}).get("full_window_shift_bp")
            for lab in ("week", "week_near_me")}
        face["answers"]["turnover_ratio_vs_me_by_cost"] = {
            tag: {"week": _ratio("week", me_turn_by_cost.get(tag), tag),
                  "week_near_me": _ratio("week_near_me",
                                         me_turn_by_cost.get(tag), tag)}
            for tag in tags}
    face["answers"]["me_turnover_per_year"] = me_turn
    face["answers"]["turnover_ratio_vs_me"] = {"week": _ratio("week"),
                                               "week_near_me": _ratio("week_near_me")}
    face["answers"]["retiming_gap_bp"] = rows["week_near_me"]["full_window_gap_bp"]
    face["answers"]["retiming_gap_bp_newest_era"] = \
        rows["week_near_me"]["eras"].get("2024_now")
    face["honest"].append(
        "the weekly book rebalances ~4.3x more often than month-end, so a return gap "
        "against it mixes calendar with trading frequency; only `week_near_me` holds "
        "frequency fixed and prices the DATE")
    face["honest"].append(
        "`week_near_me` snaps each month-end to the nearest weekly session, so its "
        "decisions sit 1-3 sessions inside the boundary rather than on it -- the "
        "residual offset is the price of being on the weekly grid, not noise")
    return face


# --------------------------- leg: what each calendar actually holds (E71)

def _overlap_stats(base_names, other_names):
    """(E71) name overlap of two held sets, with the entrant/exit split.

    Directional on purpose: entrants are names the OTHER book holds and the
    base book does not, exits the reverse, so a row reads as "what the second
    book does differently", not as a symmetric distance.
    """
    a, b = set(base_names or ()), set(other_names or ())
    inter, union = a & b, a | b
    return {"held_base": len(a), "held_other": len(b), "common": len(inter),
            "entrants": len(b - a), "exits": len(a - b),
            "share_of_base": round(len(inter) / float(len(a)), 4) if a else None,
            "share_of_other": round(len(inter) / float(len(b)), 4) if b else None,
            "jaccard": round(len(inter) / float(len(union)), 4) if union else None}


def _pair_to_grid(targets, grid):
    """(E71) map each decision to the nearest session of another grid."""
    g = sorted(set(grid or ()))
    if not g:
        return {}
    return {t: min(g, key=lambda x: (abs(x - t), x))
            for t in sorted(set(targets or ()))}


def _name_churn_stats(held_sets):
    """(E71) how much a book's own membership moves between its decisions."""
    if not held_sets or len(held_sets) < 2:
        return {"steps": 0, "mean_names_kept_share": None,
                "mean_names_changed": None, "max_names_changed": None}
    kept, changed = [], []
    for prev, cur in zip(held_sets, held_sets[1:]):
        a, b = set(prev or ()), set(cur or ())
        if not a and not b:
            continue
        u = a | b
        kept.append(len(a & b) / float(len(u)) if u else None)
        changed.append(len(a ^ b))
    if not kept:
        return {"steps": 0, "mean_names_kept_share": None,
                "mean_names_changed": None, "max_names_changed": None}
    vals = [k for k in kept if k is not None]
    return {"steps": len(kept),
            "mean_names_kept_share": round(sum(vals) / len(vals), 4) if vals else None,
            "mean_names_changed": round(sum(changed) / float(len(changed)), 2),
            "max_names_changed": max(changed)}


def _stale_hold_stats(idxs, held_sets):
    """(E71) how long a dropped name is still held before the next decision.

    A book can only drop a name when it rebalances, so the sessions a dead name
    lingers is exactly the gap between two decisions. That is the membership
    channel a monthly book carries and a weekly book does not, and a per-date
    name overlap cannot see it.
    """
    if not idxs or len(idxs) != len(held_sets) or len(idxs) < 2:
        return {"exits": 0, "mean_sessions_held_after_exit": None,
                "max_sessions_held_after_exit": None}
    tot, n, worst = 0, 0, 0
    for k in range(1, len(idxs)):
        gone = len(set(held_sets[k - 1]) - set(held_sets[k]))
        gap = idxs[k] - idxs[k - 1]
        tot += gone * gap
        n += gone
        if gone:
            worst = max(worst, gap)
    return {"exits": n,
            "mean_sessions_held_after_exit": round(tot / float(n), 2) if n else None,
            "max_sessions_held_after_exit": worst or None}


def _pair_summary(pairs):
    """(E71) aggregate a list of per-pair overlap rows."""
    if not pairs:
        return {"n_pairs": 0, "same_session_pairs": 0, "mean_share_of_base": None,
                "min_share_of_base": None, "max_share_of_base": None,
                "mean_entrants": None, "mean_exits": None,
                "total_entrants": 0, "total_exits": 0}
    shares = [p.get("share_of_base") for p in pairs
              if p.get("share_of_base") is not None]
    return {"n_pairs": len(pairs),
            "same_session_pairs": len([p for p in pairs if p.get("same_session")]),
            "mean_share_of_base": round(sum(shares) / len(shares), 4) if shares else None,
            "min_share_of_base": min(shares) if shares else None,
            "max_share_of_base": max(shares) if shares else None,
            "mean_entrants": round(sum(p.get("entrants", 0) for p in pairs)
                                   / float(len(pairs)), 2),
            "mean_exits": round(sum(p.get("exits", 0) for p in pairs)
                                / float(len(pairs)), 2),
            "total_entrants": sum(p.get("entrants", 0) for p in pairs),
            "total_exits": sum(p.get("exits", 0) for p in pairs)}


def _tail_guard(counts, flat=0.5):
    """(E71) decide which book decisions are priced on a complete panel bar.

    The panel can be mid-arrival: on the day's unfinished bar only a handful of
    members carry a close, so a decision taken there holds a stub book and reads
    as a name explosion against any other calendar. The test is LOCAL -- a
    decision is dropped when its live count collapses against its neighbours --
    because the live universe legitimately grows through the window and a
    global-median test would throw away the early burn-in instead.
    """
    n = len(counts)
    if not n:
        return []
    out = []
    for i, c in enumerate(counts):
        if c is None:
            out.append(True)
            continue
        ref = max([c] + [counts[j] for j in (i - 1, i + 1)
                         if 0 <= j < n and counts[j] is not None])
        out.append(c >= flat * ref)
    return out


def _membership_reading(share, same_flat=0.95):
    """(E71) label a per-date name overlap: same book or diverging books."""
    if share is None:
        return "insufficient"
    return "same_names" if share >= same_flat else "diverging_names"


def _cum_return(series, i0, i1):
    """(E72) close-to-close return between two session indices, or None.

    An unpriced end (missing bar, zero/negative base) is None, never zero: a
    zero here would silently price a dead name as a flat hold.
    """
    if series is None or i0 is None or i1 is None:
        return None
    if i0 < 0 or i1 < 0 or i0 >= len(series) or i1 >= len(series):
        return None
    a, b = series[i0], series[i1]
    if a is None or b is None or a <= 0:
        return None
    return b / float(a) - 1.0


def _week_hold_positions(wk_idxs, wk_books):
    """(E72) name -> ascending list of weekly decision positions holding it."""
    pos = {}
    for p, names in enumerate(wk_books or ()):
        for s in names:
            pos.setdefault(s, []).append(p)
    return pos


def _last_hold_at_or_before(positions, target_idx, wk_idxs):
    """(E72) last weekly position whose session is <= the target session."""
    best = None
    for p in positions or ():
        if p < len(wk_idxs) and wk_idxs[p] <= target_idx:
            best = p
        else:
            break
    return best


def _stale_hold_events(me_idxs, me_books, wk_idxs, wk_books, ret_fn,
                       book_ret_fn=None):
    """(E72) price every stale exit: sessions held past the weekly drop, and bp.

    A monthly book can only drop an ineligible name at its next decision, so a
    name the weekly book already sold keeps a weight for weeks. Each event is
    charged at the book's equal weight (1/n_held_before) times the name's own
    return over the extra sessions, i.e. the bp a weekly drop would have saved.

    E74 adds the RELATIVE face: when `book_ret_fn` is supplied the same span is
    also charged against the wide book's own return, so an event that simply
    moved with the market nets to ~0 instead of reading as a name effect.
    """
    pos = _week_hold_positions(wk_idxs, wk_books)
    events, unpriced, no_weekly, unpriced_book = [], 0, 0, 0
    for k in range(1, len(me_idxs or ())):
        prev, cur = list(me_books[k - 1]), set(me_books[k])
        exits = [s for s in prev if s not in cur]
        if not exits or not prev:
            continue
        w = 1.0 / float(len(prev))
        for s in exits:
            p = _last_hold_at_or_before(pos.get(s, []), me_idxs[k], wk_idxs)
            if p is None:
                no_weekly += 1
                continue
            extra = me_idxs[k] - wk_idxs[p]
            if extra <= 0:
                continue
            r = ret_fn(s, wk_idxs[p], me_idxs[k])
            if r is None:
                unpriced += 1
                continue
            events.append({"me_session": me_idxs[k],
                           "weekly_session": wk_idxs[p],
                           "name": s,
                           "extra_sessions": extra,
                           "return_pct": round(r * 100.0, 4),
                           "weight_pct": round(w * 100.0, 4),
                           "bp_contrib": round(10000.0 * w * r, 3)})
            if book_ret_fn is not None:
                b = book_ret_fn(wk_idxs[p], me_idxs[k])
                if b is None:
                    unpriced_book += 1
                    continue
                events[-1]["book_return_pct"] = round(b * 100.0, 4)
                events[-1]["excess_return_pct"] = round((r - b) * 100.0, 4)
                events[-1]["relative_bp_contrib"] = round(10000.0 * w * (r - b), 3)
    return events, {"unpriced": unpriced, "never_in_weekly_book": no_weekly,
                    "unpriced_book": unpriced_book}


def _years_between(d0, d1):
    """(E72) calendar years between two ISO dates, or None if unusable."""
    try:
        a = datetime.strptime(d0, "%Y-%m-%d")
        b = datetime.strptime(d1, "%Y-%m-%d")
    except (TypeError, ValueError):
        return None
    days = (b - a).days
    return days / 365.25 if days > 0 else None


def _stale_aggregate(events, years, key="bp_contrib", ret_key="return_pct"):
    """(E72/E74) summarise stale-exit events into total bp and per-event stats.

    E74 re-reads the same events on the relative key (`relative_bp_contrib`), so
    the key and the return column are parameters; events missing that key are
    dropped rather than silently counted as a zero excess.
    """
    rows = [e for e in events if key in e] if key != "bp_contrib" else list(events)
    if not rows:
        return {"events": 0, "total_bp": 0.0, "bp_per_year": None,
                "mean_return_pct": None, "negative_share": None,
                "mean_extra_sessions": None, "max_extra_sessions": None,
                "worst_event": None}
    tot = sum(e[key] for e in rows)
    neg = len([e for e in rows if e[ret_key] < 0])
    worst = min(rows, key=lambda e: e[key])
    return {"events": len(rows),
            "total_bp": round(tot, 3),
            "bp_per_year": round(tot / years, 3) if years else None,
            "mean_return_pct": round(sum(e[ret_key] for e in rows)
                                     / float(len(rows)), 4),
            "negative_share": round(neg / float(len(rows)), 4),
            "mean_extra_sessions": round(sum(e["extra_sessions"] for e in rows)
                                         / float(len(rows)), 2),
            "max_extra_sessions": max(e["extra_sessions"] for e in rows),
            "worst_event": {"date": worst.get("date"),
                            "name": worst["name"],
                            "extra_sessions": worst["extra_sessions"],
                            "return_pct": worst.get(ret_key),
                            "bp_contrib": worst[key]}}


def run_weeknames(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",)):
    """E71: the weekly book's -45bp price-path residual -- timing or names?

    E70 switched the fee off and left a -45bp residual on the full weekly grid
    against month-end. Two channels fit that number: WHEN the book trades, or
    WHAT it holds. Both books here equal-weight the whole live universe, so
    membership can only diverge through the eligibility flow -- names that
    appear or drop out between one decision and the next. This census measures
    both: name overlap at paired sessions (the timing question) and the
    sessions a dropped name is still held (the membership question).
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    raw_all = e27.load_universe()
    if exclude:
        raw_all = {s: v for s, v in raw_all.items()
                   if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cal = [d for d in cal_full if d >= start]
    cutoff = cal[-1]
    all_syms = sorted(set(base.LADDER) | set(raw_all))
    prices, amounts = {}, {}
    for s in all_syms:
        c, a = raw_all.get(s, ({}, {}))
        prices[s] = [c.get(d) for d in cal]
        amounts[s] = [a.get(d) for d in cal]
    universe = [s for s in all_syms if s in raw_all]
    rank_cache = {}
    me_idxs = sorted(set(base.month_end_indices(cal)))
    wk_idxs = sorted(set(_weekly_indices(cal)))
    wnm_idxs = sorted(set(_nearest_weekly_to_month_end(wk_idxs, me_idxs)))

    def held(idx):
        return e27._rank(idx, universe, prices, amounts, rank_cache)[:pick_n]

    # a mid-arrival tail bar holds a stub book; drop those decisions instead of
    # letting one incomplete session read as a name explosion
    raw_me = {i: held(i) for i in me_idxs}
    raw_wk = {i: held(i) for i in wk_idxs}
    keep_me = _tail_guard([len(raw_me[i]) for i in me_idxs])
    keep_wk = _tail_guard([len(raw_wk[i]) for i in wk_idxs])
    me_idxs = [i for i, k in zip(me_idxs, keep_me) if k]
    wk_idxs = [i for i, k in zip(wk_idxs, keep_wk) if k]
    dropped = {"me": keep_me.count(False), "week": keep_wk.count(False)}
    wnm_idxs = sorted(set(i for i in wnm_idxs if i in set(wk_idxs)))
    books = {"me": me_idxs, "week": wk_idxs, "week_near_me": wnm_idxs}

    held_by_book = {lab: [held(i) for i in idxs] for lab, idxs in books.items()}

    nearest = _pair_to_grid(me_idxs, wk_idxs)
    pairs_week, pairs_wnm, seen_partner = [], [], set()
    for me_i in me_idxs:
        wk_i = nearest.get(me_i)
        if wk_i is None:
            continue
        base_names = held_by_book["me"][me_idxs.index(me_i)]
        week_names = held_by_book["week"][wk_idxs.index(wk_i)]
        row = _overlap_stats(base_names, week_names)
        row.update({"date": cal[me_i], "partner_date": cal[wk_i],
                    "session_offset": wk_i - me_i,
                    "same_session": wk_i == me_i})
        pairs_week.append(row)
        if wk_i not in seen_partner:
            seen_partner.add(wk_i)
            row2 = dict(row)
            row2["wnm_index"] = wnm_idxs.index(wk_i) if wk_i in wnm_idxs else None
            pairs_wnm.append(row2)

    def _by_era(pairs):
        out = {}
        for name, lo, hi in ERAS:
            rows = [p for p in pairs if _in_era(p["date"][:7], lo, hi)]
            if rows:
                out[name] = _pair_summary(rows)
        return out

    churn = {lab: _name_churn_stats(held_by_book[lab]) for lab in books}
    stale = {lab: _stale_hold_stats(books[lab], held_by_book[lab]) for lab in books}
    unions = {lab: sorted(set().union(*[set(h) for h in sets]))
              if sets else [] for lab, sets in held_by_book.items()}

    summ_week = _pair_summary(pairs_week)
    summ_wnm = _pair_summary(pairs_wnm)
    face = {
        "study": "e71_monthend_weekly_names",
        "evidence_cutoff": cutoff,
        "spec": {"pick_n": pick_n, "exclude_prefixes": list(exclude),
                 "start": start, "universe_members": len(universe),
                 "dropped_decisions": dropped,
                 "calendars": {lab: len(idxs) for lab, idxs in books.items()}},
        "books": {lab: {"decision_days": len(books[lab]),
                        "union_names_ever_held": len(unions[lab]),
                        "self_churn": churn[lab],
                        "stale_hold": stale[lab]} for lab in books},
        "pairs": {"me_vs_week_nearest": {"summary": summ_week,
                                         "eras": _by_era(pairs_week)},
                  "me_vs_week_near_me": {"summary": summ_wnm,
                                         "eras": _by_era(pairs_wnm)}},
        "exclusive_names": {
            "week_only": len(set(unions["week"]) - set(unions["me"])),
            "me_only": len(set(unions["me"]) - set(unions["week"])),
            "both": len(set(unions["week"]) & set(unions["me"])),
        },
        "answers": {
            "share_me_vs_week_nearest": summ_week["mean_share_of_base"],
            "share_me_vs_week_near_me": summ_wnm["mean_share_of_base"],
            "membership_reading": _membership_reading(summ_week["mean_share_of_base"]),
            "names_changed_per_week_step": churn["week"]["mean_names_changed"],
            "names_changed_per_me_step": churn["me"]["mean_names_changed"],
            "stale_hold_sessions_week": stale["week"]["mean_sessions_held_after_exit"],
            "stale_hold_sessions_near_me":
                stale["week_near_me"]["mean_sessions_held_after_exit"],
            "stale_hold_sessions_me": stale["me"]["mean_sessions_held_after_exit"],
            "mean_entrants_per_pair": summ_week["mean_entrants"],
            "mean_exits_per_pair": summ_week["mean_exits"],
            "same_session_pairs": summ_week["same_session_pairs"],
        },
        "honest": [
            "both books equal-weight the entire live universe (pick_n=%d), so this "
            "census measures the eligibility flow and not a top-N selection rule"
            % pick_n,
            "the overlap rows compare each month-end decision with the nearest weekly "
            "session; where those coincide the overlap is exact by construction and "
            "the coincident pairs are counted separately, not averaged away",
            "stale_hold is truncated at the window ends -- the last exit of the series "
            "has no following decision and is never counted",
            "`week_near_me` reuses the same pairing as the nearest-weekly read, deduped "
            "on the weekly session, because that is exactly how its calendar is built",
            "membership_reading is a 0.95 flat threshold on the mean overlap: a label, "
            "not a test, and no prereg covers it",
            "decisions priced on a mid-arrival bar or on an empty cash book (live count "
            "collapsing against its neighbours) are dropped and counted in "
            "spec.dropped_decisions -- without that guard one unfinished session "
            "reads as a +1200-name entrant wave",
            "an era missing from the pair table was dropped as a cash/stub block, not "
            "censused as perfect agreement: the eligibility burn-in leaves the early "
            "window in cash, the same cash-slice signature E59/E64 print as an exact "
            "0.0bp gap",
            "descriptive census only: no gate, no verdict, no ledger booking, trial 0",
        ],
    }
    return face


def _stale_hold_inputs(start, pick_n, exclude, raw=None):
    """(E72/E74) shared panel, calendars and books for both stale legs.

    Factored out so the absolute (E72) and relative (E74) reads cannot drift
    onto two different panels or two different decision calendars.
    ``raw`` (E118) lets the screened twin hand in an already repaired universe
    so both arms are cut from one load; passing it skips the loader entirely.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    raw_all = raw if raw is not None else e27.load_universe()
    if exclude:
        raw_all = {s: v for s, v in raw_all.items()
                   if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cal = [d for d in cal_full if d >= start]
    cutoff = cal[-1]
    all_syms = sorted(set(base.LADDER) | set(raw_all))
    prices, amounts = {}, {}
    for s in all_syms:
        c, a = raw_all.get(s, ({}, {}))
        prices[s] = [c.get(d) for d in cal]
        amounts[s] = [a.get(d) for d in cal]
    universe = [s for s in all_syms if s in raw_all]
    rank_cache = {}
    me_idxs = sorted(set(base.month_end_indices(cal)))
    wk_idxs = sorted(set(_weekly_indices(cal)))

    def held(idx):
        return e27._rank(idx, universe, prices, amounts, rank_cache)[:pick_n]

    raw_me = {i: held(i) for i in me_idxs}
    raw_wk = {i: held(i) for i in wk_idxs}
    keep_me = _tail_guard([len(raw_me[i]) for i in me_idxs])
    keep_wk = _tail_guard([len(raw_wk[i]) for i in wk_idxs])
    me_idxs = [i for i, k in zip(me_idxs, keep_me) if k]
    wk_idxs = [i for i, k in zip(wk_idxs, keep_wk) if k]
    return {"cal": cal, "cutoff": cutoff, "prices": prices,
            "universe": universe, "me_idxs": me_idxs, "wk_idxs": wk_idxs,
            "dropped": {"me": keep_me.count(False),
                        "week": keep_wk.count(False)},
            "me_books": [raw_me[i] for i in me_idxs],
            "wk_books": [raw_wk[i] for i in wk_idxs]}


def run_stalehold(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",)):
    """E72: what is the stale-hold tail actually worth, in bp?

    E71 found the last membership channel left between the month-end and weekly
    books: a name dropped by the weekly book lingers in the monthly book for the
    rest of the month (20.7 vs 4.9 sessions). This leg prices that tail instead
    of counting it -- for every exit event it compounds the name's own return
    over the sessions the monthly book still holds it after the weekly book has
    sold, charged at the book's equal weight, and reports the total in bp and
    bp/yr against the -45bp residual E70 left on the full weekly grid.
    """
    ds = _stale_hold_inputs(start, pick_n, exclude)
    cal, cutoff, prices = ds["cal"], ds["cutoff"], ds["prices"]
    me_idxs, me_books = ds["me_idxs"], ds["me_books"]
    wk_idxs, wk_books = ds["wk_idxs"], ds["wk_books"]
    universe, dropped = ds["universe"], ds["dropped"]

    events, skipped = _stale_hold_events(
        me_idxs, me_books, wk_idxs, wk_books,
        lambda s, a, b: _cum_return(prices.get(s), a, b))
    for e in events:
        e["date"] = cal[e["me_session"]]
        e["weekly_exit_date"] = cal[e["weekly_session"]]

    years = _years_between(cal[me_idxs[0]], cal[me_idxs[-1]]) if me_idxs else None
    overall = _stale_aggregate(events, years)
    by_era = {}
    for name, lo, hi in ERAS:
        rows = [e for e in events if _in_era(e["date"][:7], lo, hi)]
        era_years = (_years_between(rows[0]["date"], rows[-1]["date"])
                     if len(rows) > 1 else None)
        by_era[name] = _stale_aggregate(rows, era_years)

    # the same tail read as an average drag per calendar year of holding
    sessions_span = (me_idxs[-1] - me_idxs[0]) if len(me_idxs) > 1 else 0
    stable = {
        "events": overall["events"],
        "total_bp": overall["total_bp"],
        "bp_per_year": overall["bp_per_year"],
        "mean_return_pct": overall["mean_return_pct"],
        "negative_share": overall["negative_share"],
        "mean_extra_sessions": overall["mean_extra_sessions"],
        "max_extra_sessions": overall["max_extra_sessions"],
        "worst_event": overall["worst_event"],
    }
    face = {
        "study": "e72_stale_hold_price",
        "evidence_cutoff": cutoff,
        "spec": {"pick_n": pick_n, "exclude_prefixes": list(exclude),
                 "start": start, "universe_members": len(universe),
                 "dropped_decisions": dropped,
                 "calendars": {"me": len(me_idxs), "week": len(wk_idxs)},
                 "sessions_span": sessions_span, "years": years,
                 "charge": "1/n_held_before of the monthly book, name's own return "
                           "from the weekly drop session to the monthly drop session"},
        "tail": stable,
        "by_era": by_era,
        "skipped": skipped,
        "answers": {
            "stale_events": overall["events"],
            "tail_total_bp": overall["total_bp"],
            "tail_bp_per_year": overall["bp_per_year"],
            "tail_mean_return_pct": overall["mean_return_pct"],
            "tail_negative_share": overall["negative_share"],
            "stale_sessions_mean": overall["mean_extra_sessions"],
            "newest_era_tail_bp": by_era.get("2024_now", {}).get("total_bp"),
            "newest_era_tail_bp_per_year":
                by_era.get("2024_now", {}).get("bp_per_year"),
            "residual_to_explain_bp": -45.0,
            "residual_source": "E70 weeklyclash cost face (full weekly grid vs "
                               "month-end, x0/x3 residual, 2020 start)",
        },
        "honest": [
            "the tail is priced as name return x equal weight over the extra "
            "sessions; it is not a re-run of either book's P&L, so it cannot "
            "double-count the calendar gaps E65-E69 already priced",
            "an event needs a priced base at the weekly drop session and a priced "
            "close at the monthly drop session; unpriced ends are counted in "
            "skipped.unpriced instead of being charged as a flat hold",
            "names held by the monthly book that never appear in the weekly book "
            "are counted in skipped.never_in_weekly_book and excluded -- they are "
            "not a stale tail, they are a coverage difference",
            "events are charged once each, at the decision that sees the exit, so "
            "a name that enters and exits repeatedly contributes several events",
            "bp_per_year divides the window total by the calendar span, which "
            "understates a concentrated tail in a short era and overstates a "
            "tail diluted over a long one -- read it beside per-era totals",
            "the -45bp residual is quoted from the E70 face as published; no "
            "attempt is made here to recompute it",
            "descriptive census only: no gate, no verdict, no ledger booking, trial 0",
        ],
    }
    return face


def _wide_session_returns(prices, universe, n_sessions):
    """(E74) equal-weight return of the live universe at every session.

    The reference book for the relative stale tail: for session t it averages
    the close-to-close return of every universe member priced at both t-1 and t.
    A session with no priced member is None, and a None anywhere in a span makes
    the compounded span None -- a gap is disclosed, never filled with zero.
    """
    out = [None] * int(n_sessions)
    for t in range(1, int(n_sessions)):
        vals = []
        for s in universe:
            r = _cum_return(prices.get(s), t - 1, t)
            if r is not None:
                vals.append(r)
        if vals:
            out[t] = sum(vals) / float(len(vals))
    return out


def _compound_between(rets, i0, i1):
    """(E74) compound the wide book from session i0 to i1 (exclusive of i0)."""
    if not rets or i0 is None or i1 is None or i1 <= i0:
        return None
    if i0 < 0 or i1 >= len(rets):
        return None
    acc = 1.0
    for t in range(i0 + 1, i1 + 1):
        if rets[t] is None:
            return None
        acc *= (1.0 + rets[t])
    return acc - 1.0


def _max_session_jump(series, i0, i1):
    """(E74) largest absolute move between two consecutive PRICED closes.

    The panel carries some names unadjusted, so a share split prints as a -90%
    "return" and a stale-tail total can be one corporate action. Missing bars
    are skipped rather than aborting the screen: the split itself often hides a
    suspension gap (a None session sits right beside it), so a None-blind scan
    would miss the very artefact it is looking for. Fewer than two priced closes
    in the span leaves the event unjudged (None), never clean.
    """
    if series is None or i0 is None or i1 is None or i1 <= i0:
        return None
    if i0 < 0 or i1 >= len(series):
        return None
    worst, last, n_priced = 0.0, None, 0
    for t in range(i0, i1 + 1):
        v = series[t]
        if v is None or v <= 0:
            continue
        n_priced += 1
        if last is not None:
            r = v / float(last) - 1.0
            if abs(r) > worst:
                worst = abs(r)
        last = v
    return worst if n_priced >= 2 else None


def _relative_reading(raw_bp, rel_bp, shrink_share=0.25, floor_bp=5.0):
    """(E74) label whether a raw tail collapses once the book is subtracted.

    A label, not a test: 'collapsed' when the relative number is inside
    max(floor_bp, shrink_share * |raw|), 'survives' when it keeps at least half
    the raw magnitude with the same sign, 'partial' otherwise.
    """
    if raw_bp is None or rel_bp is None:
        return "insufficient"
    mag = max(floor_bp, shrink_share * abs(raw_bp))
    if abs(rel_bp) <= mag:
        return "collapsed"
    if (raw_bp > 0) == (rel_bp > 0) and abs(rel_bp) >= 0.5 * abs(raw_bp):
        return "survives"
    return "partial"


def run_staletail(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",),
                  raw=None):
    """E74: is the stale tail a name effect, or the market's own path?

    E72 priced the tail raw and its sign flipped era to era (+282bp/yr pre2017,
    -226bp/yr 2021_2023, +1.6bp/yr 2024_now), which is the signature of beta
    rather than a membership mechanism. This leg re-charges the SAME events
    against the wide book over the identical sessions: an event that merely
    moved with the market nets to ~0, and only a surviving excess is a name
    effect worth naming.

    ``raw`` (E118) is the screened-twin seam: the caller hands in an already
    repaired universe so both arms are cut from one load.
    """
    ds = _stale_hold_inputs(start, pick_n, exclude, raw=raw)
    cal, cutoff, prices = ds["cal"], ds["cutoff"], ds["prices"]
    me_idxs, me_books = ds["me_idxs"], ds["me_books"]
    wk_idxs, wk_books = ds["wk_idxs"], ds["wk_books"]
    universe, dropped = ds["universe"], ds["dropped"]
    rets = _wide_session_returns(prices, universe, len(cal))

    events, skipped = _stale_hold_events(
        me_idxs, me_books, wk_idxs, wk_books,
        lambda s, a, b: _cum_return(prices.get(s), a, b),
        book_ret_fn=lambda a, b: _compound_between(rets, a, b))
    for e in events:
        e["date"] = cal[e["me_session"]]
        e["weekly_exit_date"] = cal[e["weekly_session"]]
        jump = _max_session_jump(prices.get(e["name"]), e["weekly_session"],
                                 e["me_session"])
        e["max_session_jump_pct"] = (round(jump * 100.0, 3)
                                     if jump is not None else None)
        e["artefact"] = jump is not None and jump > ARTEFACT_JUMP
    n_artefact = len([e for e in events if e["artefact"]])

    years = _years_between(cal[me_idxs[0]], cal[me_idxs[-1]]) if me_idxs else None
    raw_all = _stale_aggregate(events, years)
    rel_all = _stale_aggregate(events, years, key="relative_bp_contrib",
                               ret_key="excess_return_pct")
    clean = [e for e in events if not e.get("artefact")]
    raw_clean = _stale_aggregate(clean, years)
    rel_clean = _stale_aggregate(clean, years, key="relative_bp_contrib",
                                 ret_key="excess_return_pct")
    raw_overall, rel_overall = raw_clean, rel_clean
    by_era, by_era_raw = {}, {}
    for name, lo, hi in ERAS:
        rows_all = [e for e in events if _in_era(e["date"][:7], lo, hi)]
        rows = [e for e in rows_all if not e.get("artefact")]
        era_years = (_years_between(rows[0]["date"], rows[-1]["date"])
                     if len(rows) > 1 else None)
        by_era_raw[name] = _stale_aggregate(rows_all, era_years)
        rel = _stale_aggregate(rows, era_years, key="relative_bp_contrib",
                               ret_key="excess_return_pct")
        rel["reading"] = _relative_reading(
            _stale_aggregate(rows, era_years)["bp_per_year"],
            rel["bp_per_year"])
        rel["artefacts_excluded"] = len(rows_all) - len(rows)
        by_era[name] = rel

    sessions_span = (me_idxs[-1] - me_idxs[0]) if len(me_idxs) > 1 else 0
    face = {
        "study": "e74_stale_hold_relative",
        "evidence_cutoff": cutoff,
        "spec": {"pick_n": pick_n, "exclude_prefixes": list(exclude),
                 "start": start, "universe_members": len(universe),
                 "dropped_decisions": dropped,
                 "calendars": {"me": len(me_idxs), "week": len(wk_idxs)},
                 "sessions_span": sessions_span, "years": years,
                 "wide_book": "equal weight of every universe member priced at "
                              "both t-1 and t, compounded over the event span",
                 "charge": "1/n_held_before of the monthly book, name's own "
                           "return minus the wide book's return over the same "
                           "sessions",
                 "artefact_guard": "event excluded from the priced tail when the "
                                   "largest single-session move inside its span "
                                   "exceeds %.0f%% (a corporate action printed on "
                                   "an unadjusted series)" % (100.0 * ARTEFACT_JUMP)},
        "tail": {"raw_all_events": raw_all, "raw_clean": raw_clean,
                 "relative_all_events": rel_all, "relative_clean": rel_clean},
        "artefacts": {"excluded_events": n_artefact,
                      "jump_threshold_pct": round(100.0 * ARTEFACT_JUMP, 2),
                      "events": [{"date": e["date"], "name": e["name"],
                                  "return_pct": e["return_pct"],
                                  "max_session_jump_pct": e["max_session_jump_pct"],
                                  "bp_contrib": e["bp_contrib"]}
                                 for e in events if e["artefact"]]},
        "by_era": by_era,
        "by_era_raw": by_era_raw,
        "skipped": skipped,
        "answers": {
            "stale_events": raw_clean["events"],
            "stale_events_all": raw_all["events"],
            "artefacts_excluded": n_artefact,
            "raw_total_bp": raw_clean["total_bp"],
            "raw_bp_per_year": raw_clean["bp_per_year"],
            "raw_all_events_total_bp": raw_all["total_bp"],
            "raw_all_events_bp_per_year": raw_all["bp_per_year"],
            "relative_total_bp": rel_clean["total_bp"],
            "relative_bp_per_year": rel_clean["bp_per_year"],
            "relative_negative_share": rel_clean["negative_share"],
            "relative_share_of_raw": (
                round(rel_clean["bp_per_year"] / raw_clean["bp_per_year"], 4)
                if raw_clean["bp_per_year"] else None),
            "relative_reading": _relative_reading(raw_clean["bp_per_year"],
                                                  rel_clean["bp_per_year"]),
            "relative_all_events_bp_per_year": rel_all["bp_per_year"],
            "era_relative_reading": {k: v["reading"] for k, v in by_era.items()},
            "era_relative_bp_per_year": {k: v["bp_per_year"]
                                         for k, v in by_era.items()},
            "era_raw_bp_per_year": {k: v["bp_per_year"]
                                    for k, v in by_era_raw.items()},
            "newest_era_relative_bp": by_era.get("2024_now", {}).get("total_bp"),
            "residual_to_explain_bp": -45.0,
            "residual_source": "E70 weeklyclash cost face (full weekly grid vs "
                               "month-end, x0/x3 residual, 2020 start)",
        },
        "honest": [
            "the wide book is the whole live universe equal weight, which is the "
            "same book both calendars hold here (pick_n=%d); the relative face "
            "therefore measures the cross-sectional excess of the exiting names, "
            "not a size or style mismatch" % pick_n,
            "relative bp = name return minus the wide book's compounded return "
            "over the identical sessions, still charged at 1/n of the dropping "
            "book; it is an arithmetic difference, not a hedged P&L",
            "events whose span contains a session with no priced universe member "
            "are counted in skipped.unpriced_book and excluded from the relative "
            "columns only -- the raw columns keep them",
            "reading labels come from a 0.25 shrink share with a 5bp floor and "
            "are published as labels, not as a test; no prereg covers them",
            "an era with a handful of events (pre2017 rests on ~19) gives a "
            "bp/yr that divides a small total by a short span -- read the event "
            "count beside any era rate",
            "the -45bp residual is quoted from the E70 face as published; the "
            "relative tail is reported in its own bp/yr and is never added to it",
            "the artefact guard is a daily-limit screen, not an adjustment: a name "
            "whose series is unadjusted prints a split as a -90% tail, and such an "
            "event is excluded from the priced columns and listed in `artefacts` "
            "with its largest single-session move -- the all-events columns are "
            "kept beside the guarded ones so nothing is silently dropped",
            "descriptive census only: no gate, no verdict, no ledger booking, trial 0",
        ],
    }
    return face


# ------------------------------------------------ E118 stale-tail screened twin

def _staletail_arm_cells(face, starts=None):
    """(E118) -> {(key, column): value} for every number the stale-tail leg prices.

    Three levels, because they answer three different questions: ``tail/*`` is
    the whole tail (all events vs artefact-guarded, raw vs relative), ``era/*``
    is where the published sign flips live, and ``answers/*`` is the headline
    the E74 reading was written from. The artefact guard is what makes this leg
    interesting: it already excludes the prints ``panel_screen`` repairs, so a
    repair that reaches this face should move the *unguarded* columns
    (``raw_all_events``, ``artefacts.excluded_events``) and leave the guarded
    ones alone -- and if it moves the guarded ones too, the guard was never
    catching what it claimed to catch.
    """
    out = {}
    for lab, agg in (face.get("tail") or {}).items():
        agg = agg or {}
        key = "tail/" + lab
        for col in ("events", "total_bp", "bp_per_year", "mean_return_pct",
                    "negative_share", "mean_extra_sessions", "max_extra_sessions"):
            out[(key, col)] = agg.get(col)
    for lab, agg in (face.get("by_era") or {}).items():
        agg = agg or {}
        key = "era/" + lab
        for col in ("events", "total_bp", "bp_per_year", "mean_return_pct",
                    "negative_share", "artefacts_excluded"):
            out[(key, col)] = agg.get(col)
    for lab, agg in (face.get("by_era_raw") or {}).items():
        agg = agg or {}
        key = "era_raw/" + lab
        for col in ("events", "total_bp", "bp_per_year", "negative_share"):
            out[(key, col)] = agg.get(col)
    out[("artefacts", "excluded_events")] = (face.get("artefacts") or {}).get(
        "excluded_events")
    ans = face.get("answers") or {}
    for col in ("stale_events", "stale_events_all", "artefacts_excluded",
                "raw_total_bp", "raw_bp_per_year",
                "raw_all_events_total_bp", "raw_all_events_bp_per_year",
                "relative_total_bp", "relative_bp_per_year",
                "relative_negative_share", "relative_share_of_raw",
                "relative_all_events_bp_per_year", "newest_era_relative_bp"):
        out[("answers", col)] = ans.get(col)
    for lab, v in (ans.get("era_relative_bp_per_year") or {}).items():
        out[("answers/era_relative_bp_per_year", lab)] = v
    for lab, v in (ans.get("era_raw_bp_per_year") or {}).items():
        out[("answers/era_raw_bp_per_year", lab)] = v
    out[("spec", "universe_members")] = (face.get("spec") or {}).get("universe_members")
    return out


def _staletail_top_event(face, starts=None):
    """(E118) the artefact list as a date face: the tail's identity, not its size.

    The E97 census counts numbers; the artefact event list is the one place this
    face names WHICH print it charged. A repair that changes the count without
    changing the names is a different finding from one that swaps them, so the
    top event (largest |bp_contrib|) travels as a string cell that either moves
    or does not.
    """
    evs = (face.get("artefacts") or {}).get("events") or []
    if not evs:
        return {"artefacts": {"top": None, "n": 0}}
    top = max(evs, key=lambda e: abs(e.get("bp_contrib") or 0.0))
    return {"artefacts": {"top": "%s@%s" % (top.get("name"), top.get("date")),
                          "n": len(evs)}}


def run_staletailscreen(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",),
                        mode="neutralise_int", resume=True):
    """E118: re-price the stale tail on the screened arm, beside the raw face.

    E97 row 6 after the burn-in/cut-curve/livespan/chase/early/split twins. This
    is the last of the mid-month E7x family, and the only one whose published
    numbers are already split by an artefact guard: E74 excluded every event
    whose span carried a >30% single-session jump BEFORE pricing it. So the twin
    reads as a test of the guard itself:

      * if the repair only touches the unguarded columns, the guard and the
        screen agree on which prints are impossible, and the priced tail is
        arm-invariant -- that is the result that would let the tail be quoted;
      * if the guarded columns move too, the guard was catching a different set
        of prints than ``panel_screen`` repairs, and neither face is safe to
        quote until the two are reconciled;
      * if the counts move while the rates hold, only the population changed.

    Same machinery as E112-E117 on purpose: one load, both arms burned off it,
    per-arm checkpoints, one ``_burnin_pair_rows`` join, a same-arm control that
    must read zero, and a cutoff control (an older published raw tail face vs
    today's raw arm).
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]
    tag = cutoff.replace("-", "")

    def cached(label, thunk):
        p = os.path.join(outdir or ".", "STALETAIL-arm-%s-%s.json" % (label, tag))
        if resume and os.path.isfile(p):
            try:
                with open(p, "r", encoding="utf-8") as fh:
                    return json.load(fh)
            except Exception:
                pass
        face = thunk()
        if outdir:
            write_json(outdir, "STALETAIL-arm-%s-%s.json" % (label, tag), face)
        return face

    screened, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)

    kw = dict(start=start, pick_n=pick_n, exclude=exclude)
    raw_arm = cached("raw", lambda: run_staletail(None, raw=raw, **kw))
    scr_arm = cached(mode, lambda: run_staletail(None, raw=screened, **kw))

    keys = sorted({k[0] for k in _staletail_arm_cells(raw_arm)})
    pair = _burnin_pair_rows(raw_arm, scr_arm, keys,
                             cells_fn=_staletail_arm_cells,
                             dates_fn=_staletail_top_event)
    control = _burnin_pair_rows(raw_arm, raw_arm, keys,
                                cells_fn=_staletail_arm_cells,
                                dates_fn=_staletail_top_event)["summary"]

    # cutoff control: newest previously published raw tail face vs today's raw
    # arm -- same arm, two cutoffs, so it isolates the panel refresh.
    cutoff_control = None
    search_dirs = [d for d in (outdir, os.path.join(ROOT, "results", "e44_midmonth"))
                   if d and os.path.isdir(d)]
    olds = []
    for d in search_dirs:
        olds.extend(os.path.join(d, p) for p in os.listdir(d)
                    if p.startswith("STALETAIL-") and p.endswith(".json")
                    and not p.startswith("STALETAIL-arm-")
                    and not p.startswith("STALETAILSCREEN-"))
    for path in sorted(olds, key=os.path.basename, reverse=True):
        p = os.path.basename(path)
        if p[len("STALETAIL-"):-len(".json")] == tag:
            continue
        try:
            with open(path, "r", encoding="utf-8") as fh:
                old_face = json.load(fh)
        except Exception:
            continue
        old_pair = _burnin_pair_rows(old_face, raw_arm, keys,
                                     cells_fn=_staletail_arm_cells,
                                     dates_fn=_staletail_top_event)
        cutoff_control = {
            "old_face": p,
            "old_cutoff": old_face.get("evidence_cutoff"),
            "comparison": "old raw arm vs today raw arm (arm held fixed)",
            "summary": old_pair["summary"],
            "moved": old_pair["moved"],
            "gate_dates_moved": old_pair["gate_dates_moved"],
        }
        break

    s = pair["summary"]
    guarded_cols = ("tail/raw_clean", "tail/relative_clean")
    guarded_moved = [r for r in pair["moved"] if r["start"] in guarded_cols]
    unguarded_moved = [r for r in pair["moved"]
                       if r["start"] in ("tail/raw_all_events",
                                         "tail/relative_all_events",
                                         "artefacts", "answers")
                       or r["start"].startswith("era_raw/")]
    other_moved = [r for r in pair["moved"]
                   if r not in guarded_moved and r not in unguarded_moved]
    survives = _twin_survives(s, control)
    raw_sum = {lab: (raw_arm.get("tail") or {}).get(lab, {})
               for lab in ("raw_all_events", "raw_clean",
                           "relative_all_events", "relative_clean")}
    scr_sum = {lab: (scr_arm.get("tail") or {}).get(lab, {})
               for lab in ("raw_all_events", "raw_clean",
                           "relative_all_events", "relative_clean")}
    return {
        "study": "e118_staletail_screened_twin",
        "evidence_cutoff": cutoff,
        "spec": {
            "pick_n": pick_n, "exclude_prefixes": list(exclude), "start": start,
            "screen_mode": mode,
            "arms": {"raw": "e27.load_universe() as shipped",
                     "screened": "panel_screen.screen_universe(mode=%s)" % mode},
            "join": ("_staletail_arm_cells harvests the four tail aggregates, "
                     "each era on both the relative and the raw key, the artefact "
                     "block and the E74 answers; the artefact event LIST travels "
                     "as a date face (its top print) because a count that moves "
                     "without the names moving is a different finding"),
            "control": ("the same arm joined against itself; every cell must read "
                        "delta 0.0 or the join machinery moved the numbers"),
            "guard_vs_repair": ("guarded columns = the tail E74 actually priced "
                                "(events with no >%.0f%% single-session jump inside "
                                "their span); unguarded = the all-events and "
                                "artefact block beside it"
                                % (100.0 * ARTEFACT_JUMP)),
        },
        "screen_report": report,
        "pair": pair,
        "control": control,
        "cutoff_control": cutoff_control,
        "answers": {
            "face_survives_the_repair": bool(survives),
            "cells_compared": s["cells_compared"],
            "cells_moved": s["cells_moved"],
            "guarded_cells_moved": len(guarded_moved),
            "unguarded_cells_moved": len(unguarded_moved),
            "other_cells_moved": len(other_moved),
            "max_abs_delta": s["max_abs_delta_pp"],
            "delta_units": ("counts are events; bp columns are basis points; "
                            "negative_share is a fraction; years is a duration -- "
                            "the summary max is a screen over mixed units, not a "
                            "quantity"),
            "worst_cell": s["worst"],
            "control_cells_moved": control["cells_moved"],
            "artefact_events": {
                "raw": (raw_arm.get("artefacts") or {}).get("excluded_events"),
                "screened": (scr_arm.get("artefacts") or {}).get("excluded_events"),
                "guard_threshold_pct": (raw_arm.get("artefacts") or {}).get(
                    "jump_threshold_pct"),
            },
            "tail_by_arm": {
                lab: {"raw": {k: raw_sum[lab].get(k)
                              for k in ("events", "total_bp", "bp_per_year")},
                      "screened": {k: scr_sum[lab].get(k)
                                   for k in ("events", "total_bp", "bp_per_year")}}
                for lab in raw_sum},
            "gate_dates": pair["gate_dates"],
            "gate_dates_moved": pair["gate_dates_moved"],
            "cutoff_control": ({"old_face": cutoff_control["old_face"],
                                "cells_moved": cutoff_control["summary"]["cells_moved"],
                                "max_abs_delta": cutoff_control["summary"]["max_abs_delta_pp"]}
                               if cutoff_control else None),
            "reading": (
                ("the priced stale tail survives the repair: %d of %d cells move "
                 "(%d guarded / %d unguarded), so the E74 artefact guard and "
                 "panel_screen agree on which prints are impossible"
                 % (s["cells_moved"], s["cells_compared"], len(guarded_moved),
                    len(unguarded_moved)))
                if survives else
                ("the repair reaches the stale tail: %d of %d cells move "
                 "(%d guarded, %d unguarded, %d other) and %d cell(s) exist on "
                 "one arm only"
                 % (s["cells_moved"], s["cells_compared"], len(guarded_moved),
                    len(unguarded_moved), len(other_moved),
                    s["only_in_raw"] + s["only_in_screened"]))),
            "honest_flag": ("guarded columns moving is the finding that matters: "
                            "E74's guard is a >%.0f%% single-session jump test, "
                            "while panel_screen repairs integer-ratio prints -- "
                            "two different populations, and a delta here means the "
                            "tail was quoting a set the screen never touched"
                            % (100.0 * ARTEFACT_JUMP)),
        },
        "honest": [
            "descriptive census only: no gate, no verdict on the strategy, no "
            "prereg, no trial count, no ledger booking",
            "the screened arm repairs prints inside the panel it is handed; it "
            "does not add or remove bars, so an unchanged universe_members count "
            "is a property of the repair, not evidence the panel is clean",
            "the artefact guard is a daily-limit screen, not an adjustment: an "
            "event it excludes is excluded on BOTH arms identically, so this leg "
            "can only show whether the repair reached the prints the guard missed",
            "E74's era bp/yr divides a small total by a short span on the early "
            "eras; those cells move for arithmetic reasons as much as for repair "
            "reasons and are read beside their event counts",
            "E97 counts the published numbers of this runner; the join covers the "
            "tail/era/answers cells and the top artefact print, not the full "
            "event list or the skipped-block counters",
        ],
    }


# ------------------------------------------ E119 entry-delay screened twin

def _entrydelay_arm_cells(face, starts=None):
    """(E119) -> {(key, column): value} for every cell the entry-delay leg publishes.

    This is the first twin whose runner DELEGATES: ``run_entrydelay`` calls
    ``run_midsweep`` and republishes a subset of its rows. So the harvest walks
    both layers on purpose. ``answers.delay_rows`` is the copy the runner
    publishes, and ``gaps[x1][me_lagK]`` is the arm that copy was taken from.

    That split is the whole point of the leg: a repair that moves the copy while
    the source holds (or the reverse) has changed the delegating layer and not
    the measurement, and a join that harvested only one of the two could not
    tell those apart. The books are harvested too, because a gap can hold while
    both books move -- that is a different finding from a gap that holds because
    neither book moved.
    """
    out = {}
    lvl = (face.get("spec") or {}).get("cost_mult_list") or [1.0]
    lvl = "x%g" % lvl[0]

    for lab, book in (face.get("books") or {}).items():
        book = book or {}
        key = "book/%s/%s" % (lab, lvl)
        out[(key, "decision_days")] = book.get("decision_days")
        out[(key, "mean_sessions_to_month_end")] = (
            (book.get("offset") or {}).get("mean_sessions_to_month_end"))
        arm = (book.get("arms") or {}).get(lvl) or {}
        for col in ("full_window_ann_pct", "turnover_per_year", "cost_per_year_bp"):
            out[(key, col)] = arm.get(col)
        for era, ed in (arm.get("eras") or {}).items():
            out[("book/%s/%s/era/%s" % (lab, lvl, era), "ann_return_pct")] = (
                (ed or {}).get("ann_return_pct"))

    for lab, gap in ((face.get("gaps") or {}).get(lvl) or {}).items():
        gap = gap or {}
        key = "gap/" + lab
        for col in ("full_window_gap_bp", "turnover_per_year", "cost_per_year_bp"):
            out[(key, col)] = gap.get(col)
        for era, ed in (gap.get("eras") or {}).items():
            out[("gap/%s/era/%s" % (lab, era), "gap_bp")] = (ed or {}).get("gap_bp")

    ans = face.get("answers") or {}
    for lab, row in (ans.get("delay_rows") or {}).items():
        row = row or {}
        key = "delay/" + lab
        for col in ("full_window_gap_bp", "turnover_per_year"):
            out[(key, col)] = row.get(col)
        for era, ev in (row.get("eras") or {}).items():
            out[("delay/%s/era/%s" % (lab, era), "gap_bp")] = ev
    for col in ("delay_gap_bp", "newest_era_gap_bp"):
        for lab, v in (ans.get(col) or {}).items():
            out[("answers/" + col, lab)] = v
    out[("spec", "universe_members")] = (face.get("spec") or {}).get("universe_members")
    return out


def _lag_ladder_read(face, lags, era=None, lvl=None, tol=2.0):
    """(E119) the ladder itself: does each extra k sessions still cost more?

    The published question of this runner is "is the off-cycle penalty the
    calendar or being late", and the answer is a SHAPE, not a level: if each
    additional k sessions costs more, lateness is priced; if every rung sits at
    the same gap, lateness is free and the off-cycle cost belongs to the date.

    A tolerance keeps a sub-2bp wiggle from being read as a shape. ``era`` picks
    one era's gap column; ``None`` reads the full window.
    """
    lvl = lvl or "x%g" % (((face.get("spec") or {}).get("cost_mult_list")
                           or [1.0])[0])
    gaps = (face.get("gaps") or {}).get(lvl) or {}
    rungs = []
    for k in sorted(lags):
        arm = gaps.get("me_lag%d" % k) or {}
        v = ((arm.get("eras") or {}).get(era) or {}).get("gap_bp") if era \
            else arm.get("full_window_gap_bp")
        rungs.append((k, v))
    vals = [v for _k, v in rungs]
    if any(v is None for v in vals):
        shape = "incomplete"
    elif all(abs(v) <= tol for v in vals):
        shape = "flat"
    elif all(vals[i + 1] <= vals[i] + tol for i in range(len(vals) - 1)):
        shape = "monotone"
    elif all(vals[i + 1] >= vals[i] - tol for i in range(len(vals) - 1)):
        shape = "monotone_relief"
    else:
        shape = "non_monotone"
    return {"era": era, "cost_level": lvl,
            "rungs": [{"lag": k, "gap_bp": v} for k, v in rungs],
            "shape": shape,
            "span_bp": (round(vals[-1] - vals[0], 3)
                        if len(vals) > 1 and all(v is not None for v in vals) else None),
            "tolerance_bp": tol}


def _entrydelay_copy_mismatch(face):
    """(E119) does the published copy equal the arm it was copied from?

    The delegation is the only new machinery this runner has, so it is checked
    as an invariant rather than a finding: on ONE arm, ``delay_rows[me_lagK]``
    and ``gaps[x1][me_lagK]`` must carry the same full-window gap. A mismatch
    is not a repair effect -- it means the twin is joining a layer that rewrites
    its numbers, and no delta from it may be read.
    """
    lvl = "x%g" % (((face.get("spec") or {}).get("cost_mult_list") or [1.0])[0])
    gaps = (face.get("gaps") or {}).get(lvl) or {}
    rows = (face.get("answers") or {}).get("delay_rows") or {}
    out = []
    for lab, row in rows.items():
        src = (gaps.get(lab) or {}).get("full_window_gap_bp")
        cop = (row or {}).get("full_window_gap_bp")
        if src is None or cop is None:
            continue
        if abs(cop - src) > 1e-9:
            out.append({"arm": lab, "copy": cop, "source": src,
                        "delta": round(cop - src, 6)})
    return out


def _delegation_attribution(copy_moved, source_moved):
    """(E119) which LAYER of a delegating runner did the repair move?

    ``run_entrydelay`` republishes rows it took from ``run_midsweep``, so every
    delta on this face has two possible owners. Naming the layer is the reading
    the twin exists to produce: a copy that moved while its source held means
    the delegating layer changed, and that is a defect in this face rather than
    a repair effect. Decided on counts, in that order, so a face that moved both
    cannot be reported as a one-sided defect.
    """
    if copy_moved and source_moved:
        return "both layers moved = the ladder itself changed"
    if copy_moved:
        return "copy moved + source held = the delegating layer changed"
    if source_moved:
        return "source moved + copy held = the copy is stale against its arm"
    return "neither layer moved"


def run_entrydelayscreen(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",),
                         lags=(1, 3, 5, 10), costs=(1.0,), mode="neutralise_int",
                         resume=True):
    """E119: re-derive the ENTRY-delay ladder on the screened arm, beside the raw.

    E97 row 7 after the burn-in/cut-curve/livespan/chase/early/split/stale twins.
    Two things make this one different from its five predecessors:

      * it is the first twin that cannot reuse an existing seam -- the runner
        delegates to ``run_midsweep`` and republishes its lag arms, so the
        repaired universe is threaded through BOTH layers;
      * the published reading is a SHAPE (does each extra k sessions still cost
        more) rather than a set of cells, so the twin publishes the ladder on
        each arm beside the moved-cell count. A repair that changes which name
        is picked on a delayed date can bend the ladder without moving any
        single cell by much.

    Same machinery as E112-E118 otherwise: one load, both arms burned off it,
    per-arm checkpoints, the shared ``_burnin_pair_rows`` join, a same-arm
    control that must read zero, and a cutoff control against the newest
    previously published raw ladder.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]
    tag = cutoff.replace("-", "")

    def cached(label, thunk):
        p = os.path.join(outdir or ".", "ENTRYDLY-arm-%s-%s.json" % (label, tag))
        if resume and os.path.isfile(p):
            try:
                with open(p, "r", encoding="utf-8") as fh:
                    return json.load(fh)
            except Exception:
                pass
        face = thunk()
        if outdir:
            write_json(outdir, "ENTRYDLY-arm-%s-%s.json" % (label, tag), face)
        return face

    screened, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)

    kw = dict(start=start, pick_n=pick_n, exclude=exclude, lags=lags, costs=costs)
    raw_arm = cached("raw", lambda: run_entrydelay(None, raw=raw, **kw))
    scr_arm = cached(mode, lambda: run_entrydelay(None, raw=screened, **kw))

    keys = sorted({k[0] for k in _entrydelay_arm_cells(raw_arm)})
    no_dates = lambda face, ks: {}
    pair = _burnin_pair_rows(raw_arm, scr_arm, keys,
                             cells_fn=_entrydelay_arm_cells, dates_fn=no_dates)
    control = _burnin_pair_rows(raw_arm, raw_arm, keys,
                                cells_fn=_entrydelay_arm_cells,
                                dates_fn=no_dates)["summary"]

    # cutoff control: newest previously published raw ladder vs today's raw arm
    # -- same arm, two cutoffs, so it isolates the panel refresh.
    cutoff_control = None
    search_dirs = [d for d in (outdir, os.path.join(ROOT, "results", "e44_midmonth"))
                   if d and os.path.isdir(d)]
    olds = []
    for d in search_dirs:
        olds.extend(os.path.join(d, p) for p in os.listdir(d)
                    if p.startswith("ENTRYDELAY-") and p.endswith(".json")
                    and not p.startswith("ENTRYDELAYSCREEN-"))
    for path in sorted(olds, key=os.path.basename, reverse=True):
        p = os.path.basename(path)
        if p[len("ENTRYDELAY-"):-len(".json")] == tag:
            continue
        try:
            with open(path, "r", encoding="utf-8") as fh:
                old_face = json.load(fh)
        except Exception:
            continue
        old_pair = _burnin_pair_rows(old_face, raw_arm, keys,
                                     cells_fn=_entrydelay_arm_cells,
                                     dates_fn=no_dates)
        cutoff_control = {
            "old_face": p,
            "old_cutoff": old_face.get("evidence_cutoff"),
            "comparison": "old raw arm vs today raw arm (arm held fixed)",
            "summary": old_pair["summary"],
            "moved": old_pair["moved"],
        }
        break

    s = pair["summary"]
    book_cols = ("full_window_ann_pct", "ann_return_pct", "turnover_per_year",
                 "cost_per_year_bp", "decision_days", "mean_sessions_to_month_end")
    # the copy layer: what this runner republishes
    copy_moved = [r for r in pair["moved"] if r["start"].startswith("delay/")]
    # the delegated layer: the midsweep arm the copy came from
    source_moved = [r for r in pair["moved"] if r["start"].startswith("gap/")]
    book_moved = [r for r in pair["moved"] if r["start"].startswith("book/")]
    answer_moved = [r for r in pair["moved"] if r["start"].startswith("answers/")]
    other_moved = [r for r in pair["moved"]
                   if r not in copy_moved and r not in source_moved
                   and r not in book_moved and r not in answer_moved]
    survives = _twin_survives(s, control)
    copy_mismatch = {"raw": _entrydelay_copy_mismatch(raw_arm),
                     "screened": _entrydelay_copy_mismatch(scr_arm)}
    # the sharpest single reading: the ladder shape on each arm, full window and
    # newest era, plus whether the shape survived the repair.
    newest = "2024_now"
    ladders = {}
    for label, face in (("raw", raw_arm), ("screened", scr_arm)):
        ladders[label] = {
            "full_window": _lag_ladder_read(face, lags),
            "newest_era": _lag_ladder_read(face, lags, era=newest),
        }
    shapes_raw = {k: v["shape"] for k, v in ladders["raw"].items()}
    shapes_scr = {k: v["shape"] for k, v in ladders["screened"].items()}
    # a null on both sides is not a defect of the join: at start=2020-01-01 the
    # pre2017 era carries no bars, so its cells are empty by construction.
    _nulls = pair["null_on_either_side"]
    _pre2017 = [r for r in _nulls if "/era/pre2017" in (r.get("start") or "")]
    return {
        "study": "e119_entrydelay_screened_twin",
        "evidence_cutoff": cutoff,
        "spec": {
            "pick_n": pick_n, "exclude_prefixes": list(exclude), "start": start,
            "delay_sessions": list(lags), "cost_mult_list": list(costs),
            "screen_mode": mode,
            "arms": {"raw": "e27.load_universe() as shipped",
                     "screened": "panel_screen.screen_universe(mode=%s)" % mode},
            "seam": ("run_entrydelay delegates to run_midsweep, so raw= is "
                     "threaded through BOTH layers: the twin hands it to "
                     "run_entrydelay, which passes it down unchanged"),
            "join": ("_entrydelay_arm_cells harvests the book rows, the gaps "
                     "layer (the delegated arms), the delay rows (the copy this "
                     "runner republishes) and the E65 answers; the copy/source "
                     "split is what attributes a moved arm to the repair or to "
                     "the delegating layer"),
            "ladder": ("_lag_ladder_read reads the lag ladder as a SHAPE: "
                       "monotone means each extra k sessions costs more (or, for "
                       "monotone_relief, less); flat means lateness is free on "
                       "that arm; tolerance %.1fbp" % 2.0),
            "control": ("the same arm joined against itself; every cell must read "
                        "delta 0.0 or the join machinery moved the numbers"),
        },
        "screen_report": report,
        "pair": pair,
        "control": control,
        "cutoff_control": cutoff_control,
        "ladders": ladders,
        "copy_invariant": copy_mismatch,
        "answers": {
            "counts_survive_the_repair": bool(survives),
            "cells_compared": s["cells_compared"],
            "cells_moved": s["cells_moved"],
            "max_abs_delta": s["max_abs_delta_pp"],
            "delta_units": ("each delta is in the units of its column: bp for gaps, "
                            "percent per year for annualised returns, turns/yr for "
                            "turnover, sessions for offsets -- the summary max is a "
                            "max over mixed units and is a screen, not a quantity"),
            "worst_cell": s["worst"],
            "copy_cells_moved": len(copy_moved),
            "source_cells_moved": len(source_moved),
            "book_cells_moved": len(book_moved),
            "answer_cells_moved": len(answer_moved),
            "other_cells_moved": len(other_moved),
            "delegation_attribution": _delegation_attribution(copy_moved,
                                                              source_moved),
            "copy_matches_source": {k: (len(v) == 0)
                                    for k, v in copy_mismatch.items()},
            "control_cells_moved": control["cells_moved"],
            "ladder_shape": {"raw": shapes_raw, "screened": shapes_scr,
                             "shape_survives": shapes_raw == shapes_scr},
            "null_cells": {
                "total": len(_nulls),
                "pre2017_no_bars": len(_pre2017),
                "other": len(_nulls) - len(_pre2017),
                "note": ("a cell null on BOTH arms is not one-sided: at "
                         "start=%s the pre2017 era carries no bars, so those "
                         "cells are empty by construction in both arms" % start),
            },
            "cutoff_control": ({"old_face": cutoff_control["old_face"],
                                "cells_moved":
                                    cutoff_control["summary"]["cells_moved"],
                                "max_abs_delta":
                                    cutoff_control["summary"]["max_abs_delta_pp"]}
                               if cutoff_control else None),
            "reading": (
                ("the delay ladder survives the repair: %d of %d cells move "
                 "(%d copy / %d source / %d book)" %
                 (s["cells_moved"], s["cells_compared"], len(copy_moved),
                  len(source_moved), len(book_moved)))
                if survives else
                ("the repair reaches the delay ladder: %d of %d cells move "
                 "(%d copy, %d source, %d book, %d other) and %d cell(s) exist "
                 "on one arm only" %
                 (s["cells_moved"], s["cells_compared"], len(copy_moved),
                  len(source_moved), len(book_moved), len(other_moved),
                  s["only_in_raw"] + s["only_in_screened"]))),
        },
        "honest": [
            "descriptive census only: no gate, no verdict on the strategy, no "
            "prereg, no trial count, no ledger booking",
            "the lag moves the DECISION session as well as the entry, so a "
            "repair that changes which name is picked on a delayed date changes "
            "the ladder by construction; an entry-only lag would need an "
            "execution-lag hook the engine does not have",
            "the screened arm repairs prints inside the panel it is handed; it "
            "does not add or remove bars, so an unchanged universe_members count "
            "is a property of the repair, not evidence the panel is clean",
            "ladder shapes are read at a 2bp tolerance and are a description of "
            "four fixed lags (1/3/5/10 sessions), not a fitted curve",
            "the copy/source invariant is checked on each arm separately before "
            "any delta is read: a face whose published copy disagrees with its "
            "own delegated arm cannot attribute a move to the repair",
            "E97 counts the published numbers of this runner; the join covers the "
            "book/gap/delay/answers cells, not the pointer fields",
        ],
    }


# --------------------------------------------------------------- E75 panel splits

def _panel_inputs(start, exclude, raw=None):
    """(E75) raw closes on the decision calendar -- no book, no rank, nothing dropped.

    The split audit must see every name a census leg could ever charge, so it
    skips the monthly/weekly book machinery and reads the closes directly.
    ``raw`` (E117) lets the screened twin hand in an already repaired universe so
    both arms are cut from one load; passing it skips the loader entirely.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    raw = raw if raw is not None else e27.load_universe()
    if exclude:
        raw = {s: v for s, v in raw.items()
               if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cal = [d for d in cal_full if d >= start]
    prices = {}
    for s in sorted(raw):
        closes = raw[s][0]
        prices[s] = [closes.get(d) for d in cal]
    return cal, prices, sorted(raw), cal[-1]


def _breadth(prices, universe, n_sessions):
    """(E75) priced-member count per session -- the equal-weight book's divisor."""
    out = [0] * int(n_sessions)
    for s in universe:
        for i, v in enumerate(prices.get(s) or []):
            if v is not None and v > 0 and i < len(out):
                out[i] += 1
    return out


def _split_ratio(ret):
    """(E75) implied share ratio of a flagged move and its distance to an integer.

    A 12:1 split prints as -91.7% and 1/(1+r) recovers the 12.0, so a move that
    lands near an integer is a corporate action. One that does not is a
    resumption, a restatement or a misprint -- a different thing to disclose.
    """
    if ret is None or ret <= -1.0:
        return None
    ratio = 1.0 / (1.0 + ret)
    if ratio < 1.0:
        ratio = 1.0 / ratio
    nearest = int(round(ratio))
    if nearest < 1:
        nearest = 1
    resid = abs(ratio / float(nearest) - 1.0)
    return {"ratio": round(ratio, 4), "nearest_int": nearest,
            "resid_pct": round(100.0 * resid, 3),
            "integer_like": nearest >= 2 and resid <= 0.02}


def _split_events(cal, prices, universe, breadth, thresh=ARTEFACT_JUMP):
    """(E75) every panel-wide single-session move past the daily-limit screen.

    Bars are compared against the previous PRICED close (a split frequently sits
    next to a suspension bar, so a None-abort scan misses it -- the E74 lesson),
    and the gap is carried on the event: an adjacent-session move past the limit
    cannot be a real A-share print, while a gapped one can be a resumption.
    """
    events = []
    for s in universe:
        last, last_i = None, None
        for i, v in enumerate(prices.get(s) or []):
            if v is None or v <= 0:
                continue
            if last is not None:
                r = v / float(last) - 1.0
                if abs(r) > thresh:
                    n = breadth[i] if i < len(breadth) else 0
                    events.append({
                        "name": s,
                        "date": cal[i],
                        "prev_date": cal[last_i],
                        "prev_close": round(last, 4),
                        "close": round(v, 4),
                        "ret_pct": round(100.0 * r, 2),
                        "direction": "down" if r < 0 else "up",
                        "gap_sessions": i - last_i,
                        "adjacent": (i - last_i) == 1,
                        "era": _era_of(cal[i]),
                        "breadth": n,
                        "book_impact_bp": (round(10000.0 * abs(r) / n, 2)
                                           if n else None),
                        "implied_ratio": _split_ratio(r),
                    })
            last, last_i = v, i
    return events


def _split_summary(events, years):
    """(E75) book-level cost of the flagged prints: one name in an n-name book."""
    rows = [e for e in events if e.get("book_impact_bp") is not None]
    impacts = [e["book_impact_bp"] for e in rows]
    total = sum(impacts)
    integer_like = [e for e in rows
                    if (e.get("implied_ratio") or {}).get("integer_like")]
    return {
        "events": len(rows),
        "names": len(set(e["name"] for e in rows)),
        "adjacent": len([e for e in rows if e["adjacent"]]),
        "gapped": len([e for e in rows if not e["adjacent"]]),
        "down": len([e for e in rows if e["direction"] == "down"]),
        "up": len([e for e in rows if e["direction"] == "up"]),
        "integer_ratio_events": len(integer_like),
        "non_integer_events": len(rows) - len(integer_like),
        "total_book_bp": round(total, 2),
        "bp_per_year": (round(total / years, 2) if years and years > 0 else None),
        "max_event_bp": (round(max(impacts), 2) if impacts else None),
        "median_event_bp": (round(_quant(impacts, 0.5), 2) if impacts else None),
        "years": years,
    }


def run_panelsplit(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",),
                   top_n=15, raw=None):
    """E75: how many published census numbers sit on unadjusted corporate actions?

    E74 found 19 of 128 stale-tail events were unadjusted splits and that they
    alone flipped an era column's sign. This leg asks the panel-wide version:
    every single-session move past the 30% daily-limit screen, who it belongs to,
    whether it lands on an integer share ratio, and what it costs an equal-weight
    book (one name charges |r|/n).

    ``raw`` (E117) is the screened-twin seam: hand in a repaired universe and the
    census is re-derived over it, which is exactly the question E117 asks -- this
    leg counts the prints that the repair edits.
    """
    cal, prices, universe, cutoff = _panel_inputs(start, exclude, raw=raw)
    breadth = _breadth(prices, universe, len(cal))
    events = _split_events(cal, prices, universe, breadth)
    years = _years_between(cal[0], cal[-1]) if cal else None

    by_era = {}
    for name, lo, hi in ERAS:
        rows = sorted([e for e in events if e.get("era") == name],
                      key=lambda e: e["date"])
        era_years = (_years_between(rows[0]["date"], rows[-1]["date"])
                     if len(rows) > 1 else None)
        by_era[name] = _split_summary(rows, era_years)
    by_year = {}
    for e in events:
        y = e["date"][:4]
        by_year[y] = by_year.get(y, 0) + 1

    ranked = sorted([e for e in events if e.get("book_impact_bp") is not None],
                    key=lambda e: -e["book_impact_bp"])
    live_breadth = [b for b in breadth if b > 0]
    face = {
        "study": "e75_panel_split_audit",
        "evidence_cutoff": cutoff,
        "spec": {"start": start, "exclude_prefixes": list(exclude),
                 "panel_names": len(universe), "sessions": len(cal),
                 "years": years,
                 "screen": "consecutive PRICED closes, missing bars skipped and "
                           "never filled; flag |return| > %.0f%%"
                           % (100.0 * ARTEFACT_JUMP),
                 "charge": "an equal-weight book of n live names absorbs one "
                           "name's move as |r|/n; breadth is the priced-member "
                           "count at that session",
                 "pick_n": "accepted for CLI parity and unused -- this leg "
                           "audits every panel name"},
        "panel": {"events": len(events),
                  "names": len(set(e["name"] for e in events)),
                  "breadth_median": _quant(live_breadth, 0.5),
                  "breadth_min": min(live_breadth) if live_breadth else None,
                  "breadth_max": max(live_breadth) if live_breadth else None},
        "summary": _split_summary(events, years),
        "by_era": by_era,
        "events_per_year": dict(sorted(by_year.items())),
        "top_events": ranked[:top_n],
        "screening": {
            "screened_legs": ["staletail (E74: events inside the stale tail)"],
            "unscreened_rule": "every census leg in this file charges per-name "
                               "returns out of the same e27.load_universe() "
                               "closes, so an unadjusted print enters any "
                               "equal-weight number at weight 1/n; only staletail "
                               "screens for it",
            "selection_channel": "rank/_rank sorts on traded amount, and a split "
                                 "re-prices the share, so the amount leg is "
                                 "distorted on the same date as the return leg"},
        "answers": dict(_split_summary(events, years), **{
            "panel_names": len(universe),
            "top_event": ({"name": ranked[0]["name"], "date": ranked[0]["date"],
                           "ret_pct": ranked[0]["ret_pct"],
                           "book_impact_bp": ranked[0]["book_impact_bp"]}
                          if ranked else None)}),
        "honest": [
            "the screen flags arithmetic impossibilities, not confirmed corporate "
            "actions: an adjacent-session move past 30% cannot be a real A-share "
            "return under the 10%/20% limits, but the panel also carries ETFs and "
            "bonds whose daily limits differ, so a flagged ETF print may be genuine",
            "the integer-ratio fingerprint is inferred from the price ratio alone "
            "with a 2% band and no announcement feed; non-integer events are listed "
            "as unclassified, never as clean",
            "book impact assumes equal weight at 1/n of the live breadth: it sizes "
            "the distortion, it is not a correction to any published number",
            "gapped events (a resumption after suspension) can be real; the "
            "adjacent flag is the hard screen and the gap is published on every row",
            "pick_n is unused here by design -- the audit covers the whole panel so "
            "no book construction can hide a print",
            "descriptive census only: no gate, no verdict, no ledger booking, trial 0",
        ],
    }
    return face


# ------------------------------ leg: E117 the split census' own screened twin
#
# E75 counted the prints; E117 asks whether that count is a panel fact or an arm
# statement. run_panelsplit is the only census leg that already knows about
# splits -- it censused the 135 adjacent impossibilities that ``panel_screen``
# repairs -- so the hazard is that the audit may be reading the very prints it
# repairs. Re-derive it over the repaired universe with the E112-E116 join.

_PANELSPLIT_COUNT_COLUMNS = ("events", "names", "adjacent", "gapped", "down",
                             "up", "integer_ratio_events", "non_integer_events")


def _panelsplit_arm_cells(face, starts=None):
    """(E117) -> {(key, column): value} for every cell the split audit publishes.

    The runner_note's rule is kept here: a repair that changes an EVENT COUNT
    makes a different claim from one that changes what an event EARNED, so both
    classes are harvested into one join but classified separately by the caller
    (``_PANELSPLIT_COUNT_COLUMNS``). The honest/screening lines and the ranked
    ``top_events`` list are pointers, not measurements, so they are not joined.
    """
    out = {}
    for col, val in (face.get("panel") or {}).items():
        out[("panel", col)] = val
    for col, val in (face.get("summary") or {}).items():
        out[("summary", col)] = val
    for era, row in (face.get("by_era") or {}).items():
        for col, val in (row or {}).items():
            out[("era/" + era, col)] = val
    for year, n in (face.get("events_per_year") or {}).items():
        out[("year/%s" % year, "events")] = n
    return out


def _panelsplit_top_event(face, starts=None):
    """(E117) the ranked headline event is an identity: it moves or it does not."""
    top = (face.get("answers") or {}).get("top_event") or {}
    return {"top": {"name": top.get("name"), "date": top.get("date"),
                    "ret_pct": top.get("ret_pct"),
                    "book_impact_bp": top.get("book_impact_bp")}}


def run_panelsplitscreen(outdir, start="2020-01-01", pick_n=9999,
                         exclude=("sh511",), mode="neutralise_int", resume=True):
    """E117: re-derive the split census on the screened arm, beside the raw face.

    E97 leaves this runner as the largest uncovered one after E116, and it is the
    one leg whose SUBJECT is the repair: it censused the adjacent-impossibility
    prints that ``panel_screen`` edits. So the twin is not a formality -- if the
    repair works, this leg's own counts should collapse, and the open question is
    what is left:

      * event counts are the repair's target: a delta there is the repair working
        (or failing), not a stability finding;
      * the bp/year columns are what the unadjusted prints charged, so their
        delta is the size of the distortion E75 published;
      * whatever remains on the repaired arm is the census' irreducible core --
        resumptions after suspension, ETFs whose daily limits are not 10/20%, and
        prints whose implied ratio is not an integer.

    Same machinery as E112-E116: one load, both arms burned off it, per-arm
    checkpoints, one ``_burnin_pair_rows`` join, a same-arm control that must
    read zero, and a cutoff control (an older published raw face vs today's raw).
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]
    tag = cutoff.replace("-", "")

    def cached(label, thunk):
        p = os.path.join(outdir or ".", "PANELSPLIT-arm-%s-%s.json" % (label, tag))
        if resume and os.path.isfile(p):
            try:
                with open(p, "r", encoding="utf-8") as fh:
                    return json.load(fh)
            except Exception:
                pass
        face = thunk()
        if outdir:
            write_json(outdir, "PANELSPLIT-arm-%s-%s.json" % (label, tag), face)
        return face

    screened, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)

    raw_arm = cached("raw", lambda: run_panelsplit(None, start=start,
                                                  pick_n=pick_n,
                                                  exclude=exclude, raw=raw))
    scr_arm = cached(mode, lambda: run_panelsplit(None, start=start,
                                                 pick_n=pick_n,
                                                 exclude=exclude, raw=screened))

    keys = sorted({k[0] for k in _panelsplit_arm_cells(raw_arm)})
    pair = _burnin_pair_rows(raw_arm, scr_arm, keys,
                             cells_fn=_panelsplit_arm_cells,
                             dates_fn=_panelsplit_top_event)
    control = _burnin_pair_rows(raw_arm, raw_arm, keys,
                                cells_fn=_panelsplit_arm_cells,
                                dates_fn=_panelsplit_top_event)["summary"]

    # cutoff control: an older published raw split face vs today's raw arm. Same
    # arm, two cutoffs -> isolates the panel refresh from the repair.
    cutoff_control = None
    search_dirs = [d for d in (outdir, os.path.join(ROOT, "results", "e44_midmonth"))
                   if d and os.path.isdir(d)]
    olds = []
    for d in search_dirs:
        olds.extend(os.path.join(d, p) for p in os.listdir(d)
                    if p.startswith("PANELSPLIT-") and p.endswith(".json")
                    and not p.startswith("PANELSPLIT-arm-")
                    and not p.startswith("PANELSPLITSCREEN-"))
    for path in sorted(olds, key=os.path.basename, reverse=True):
        p = os.path.basename(path)
        if p[len("PANELSPLIT-"):-len(".json")] == tag:
            continue
        try:
            with open(path, "r", encoding="utf-8") as fh:
                old_face = json.load(fh)
        except Exception:
            continue
        old_pair = _burnin_pair_rows(old_face, raw_arm, keys,
                                     cells_fn=_panelsplit_arm_cells,
                                     dates_fn=_panelsplit_top_event)
        cutoff_control = {
            "old_face": p,
            "old_cutoff": old_face.get("evidence_cutoff"),
            "comparison": "old raw arm vs today raw arm (arm held fixed)",
            "summary": old_pair["summary"],
            "moved": old_pair["moved"],
        }
        break

    s = pair["summary"]
    count_moved = [r for r in pair["moved"]
                   if r["column"] in _PANELSPLIT_COUNT_COLUMNS]
    value_moved = [r for r in pair["moved"]
                   if r["column"] not in _PANELSPLIT_COUNT_COLUMNS]
    survives = _twin_survives(s, control)

    raw_sum = raw_arm.get("summary") or {}
    scr_sum = scr_arm.get("summary") or {}
    raw_panel = raw_arm.get("panel") or {}
    scr_panel = scr_arm.get("panel") or {}
    return {
        "study": "e117_panelsplit_screened_twin",
        "evidence_cutoff": cutoff,
        "spec": {
            "pick_n": pick_n, "exclude_prefixes": list(exclude), "start": start,
            "screen_mode": mode,
            "arms": {"raw": "e27.load_universe() as shipped",
                     "screened": "panel_screen.screen_universe(mode=%s)" % mode},
            "join": ("_panelsplit_arm_cells harvests panel/summary/each era/each "
                     "year; count columns and bp-year columns are joined together "
                     "and split apart again in answers, because an event count "
                     "moving and an event's cost moving are different findings"),
            "control": ("the same arm joined against itself; every cell must read "
                        "delta 0.0 or the join machinery moved the numbers"),
        },
        "screen_report": report,
        "pair": pair,
        "control": control,
        "cutoff_control": cutoff_control,
        "answers": {
            "face_survives_the_repair": bool(survives),
            "cells_compared": s["cells_compared"],
            "cells_moved": s["cells_moved"],
            "count_cells_moved": len(count_moved),
            "value_cells_moved": len(value_moved),
            "max_abs_delta": s["max_abs_delta_pp"],
            "delta_units": ("counts are event/name counts; total_book_bp and "
                            "bp_per_year are basis points, years is a duration -- "
                            "the summary max is a screen over mixed units, not a "
                            "quantity"),
            "worst_cell": s["worst"],
            "control_cells_moved": control["cells_moved"],
            "events": {"raw": raw_sum.get("events"),
                       "screened": scr_sum.get("events"),
                       "removed": (None if raw_sum.get("events") is None
                                   or scr_sum.get("events") is None
                                   else raw_sum["events"] - scr_sum["events"])},
            "integer_ratio_events": {
                "raw": raw_sum.get("integer_ratio_events"),
                "screened": scr_sum.get("integer_ratio_events")},
            "book_bp": {"raw": raw_sum.get("total_book_bp"),
                        "screened": scr_sum.get("total_book_bp"),
                        "bp_per_year_raw": raw_sum.get("bp_per_year"),
                        "bp_per_year_screened": scr_sum.get("bp_per_year")},
            "irreducible_core": {
                "screened_events": scr_sum.get("events"),
                "screened_adjacent": scr_sum.get("adjacent"),
                "screened_gapped": scr_sum.get("gapped"),
                "screened_non_integer": scr_sum.get("non_integer_events"),
                "screened_names": scr_sum.get("names"),
                "note": ("what is left after the repair is not 'clean': it is "
                         "resumptions, non-integer prints and instruments whose "
                         "daily limit is not 10/20%, which the screen never "
                         "claimed to fix"),
            },
            "panel_breadth": {"raw_median": raw_panel.get("breadth_median"),
                              "screened_median": scr_panel.get("breadth_median"),
                              "raw_names": raw_panel.get("names"),
                              "screened_names": scr_panel.get("names")},
            "cutoff_control": ({"old_face": cutoff_control["old_face"],
                                "cells_moved": cutoff_control["summary"]["cells_moved"],
                                "max_abs_delta": cutoff_control["summary"]["max_abs_delta_pp"]}
                               if cutoff_control else None),
            "reading": (
                ("the split census reads the same on both arms (%d of %d cells "
                 "move)" % (s["cells_moved"], s["cells_compared"]))
                if survives else
                ("the split census is an arm statement: %d of %d cells move "
                 "(%d count, %d value) and %d cell(s) exist on one arm only"
                 % (s["cells_moved"], s["cells_compared"], len(count_moved),
                    len(value_moved), s["only_in_raw"] + s["only_in_screened"]))),
            "honest_flag": ("event-count cells are EXPECTED to move: the repair "
                            "targets exactly the prints this leg counts, so a "
                            "count delta is the repair working, not instability"),
        },
        "honest": [
            "descriptive census only: no gate, no verdict on the strategy, no "
            "prereg, no trial count, no ledger booking",
            "the repair edits the panel this leg censuses, so counts moving is the "
            "expected outcome and is not evidence about any other face",
            "the screened arm keeps every name (neutralise_int repairs the print, "
            "it does not drop the symbol), so names/breadth cannot move -- that is "
            "a property of the mode, not proof the panel is clean",
            "the screen flags arithmetic impossibilities rather than confirmed "
            "corporate actions; the residual core still contains ETFs, resumptions "
            "and non-integer prints, so 'repaired' never means 'clean'",
            "E97 counts the published numbers of this runner; the join covers the "
            "panel/summary/era/year cells, not the ranked top-event list or the "
            "screening pointers (the headline event identity is compared "
            "separately as a date face)",
        ],
    }


# ------------------------------------------- leg: E76 screen-regrade (opt-in)
#
# E75 sized the problem: 135 adjacent-session prints past the 30% screen on 152
# names, ~216bp/yr of equal-weight book impact -- 4.8x the -45bp residual the
# chain had been chasing. But E75 only *sized* it; every published ladder and
# era-spread number still charges the unadjusted prints. This leg is the other
# half: the same two headline faces replayed from a repaired universe, with the
# unscreened column kept beside them so the correction is measured, not claimed.

LADDER_COLUMNS = ("ann_pct", "vol_pct", "sharpe", "max_drawdown_pct",
                  "worst_month_return_pct", "turnover_per_year",
                  "cost_per_year_bp")
ERA_COLUMNS = ("spread_ann_bp", "ladder_ann_pct", "wide_ann_pct")
ERA_RATIO_COLUMNS = ("max_drawdown_pct", "ann_pct")


def _ladder_window(raw, cal, start):
    """One ladder5 window (the E39 columns) from an already loaded universe."""
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27

    years = len(cal) / 252.0
    prices = {}
    for s in base.LADDER:
        c = raw.get(s, ({}, {}))[0] if s in raw else {}
        if not c:
            c = base.load_panel(s)[1].get(s, {})
        prices[s] = [c.get(d) for d in cal]
    cash = base.load_cash_series(cal)
    curve, aux, _hold = e27.simulate(cal, prices, {}, base.LADDER, cash, None, 1.0, {})
    m = base.metrics(curve, years)
    prof = risk_profile(curve, years)
    return {
        "start": start, "bars": len(cal),
        "ann_pct": m.get("ann_return_pct"),
        "vol_pct": m.get("ann_vol_pct"),
        "sharpe": m.get("sharpe"),
        "max_drawdown_pct": prof["max_drawdown_pct"],
        "worst_month_return_pct": (prof["worst_month"] or {}).get("return_pct"),
        "turnover_per_year": (round(aux["turnover_total"] / years, 4) if years else None),
        "cost_per_year_bp": (round(aux["cost_paid_frac"] / years * 1e4, 2) if years else None),
    }


def _screen_face(raw, cal_full, pick_n, eras, ladder_starts):
    """The two headline faces (ladder windows + era spread) from one universe."""
    ladder = {}
    for start in ladder_starts:
        cal = [d for d in cal_full if d >= start]
        ladder[start] = _ladder_window(raw, cal, start)
    lad, wide, ratio = _era_curves(raw, cal_full, pick_n)
    return {"ladder": ladder, "eras": _era_rows(lad, wide, ratio, eras)}


def _delta_rows(base_label, faces):
    """Column-by-column unscreened vs screened table, one row per cell."""
    rows = []
    base_face = faces[base_label]
    others = [k for k in faces if k != base_label]

    def cell(row, key, u, v):
        row[key] = v
        row["delta_" + key] = (round(v - u, 4)
                               if isinstance(v, (int, float)) and isinstance(u, (int, float))
                               else None)

    for start in sorted(base_face["ladder"]):
        u = base_face["ladder"][start]
        for col in LADDER_COLUMNS:
            row = {"face": "ladder@%s" % start, "column": col,
                   "unscreened": u.get(col)}
            for mode in others:
                cell(row, mode, u.get(col), faces[mode]["ladder"][start].get(col))
            rows.append(row)
    for era in base_face["eras"]:
        u = base_face["eras"][era]
        if "spread_ann_bp" not in u:
            continue
        for col in ERA_COLUMNS:
            row = {"face": "era:%s" % era, "column": col, "unscreened": u.get(col)}
            for mode in others:
                cell(row, mode, u.get(col), faces[mode]["eras"][era].get(col))
            rows.append(row)
        for col in ERA_RATIO_COLUMNS:
            ur = (u.get("ratio_path") or {}).get(col)
            row = {"face": "era:%s" % era, "column": "ratio_" + col,
                   "unscreened": ur}
            for mode in others:
                cell(row, mode, ur,
                     (faces[mode]["eras"][era].get("ratio_path") or {}).get(col))
            rows.append(row)
    return rows


def _member_print_face(closes, cal, thresh=None):
    """(E76) how many adjacent/gapped artefact prints one series carries."""
    import panel_screen
    if not closes:
        return {"adjacent": 0, "gapped": 0, "prints": []}
    events = panel_screen.split_events(closes, cal=cal)
    adj = [e for e in events if e["adjacent"]]
    return {"adjacent": len(adj), "gapped": len(events) - len(adj),
            "prints": [{"date": e["date"], "ret_pct": round(e["ret_pct"], 2),
                        "adjacent": e["adjacent"]} for e in events]}


def run_screenreg(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",),
                  modes=("neutralise_int", "neutralise", "drop"), eras=ERAS,
                  ladder_starts=("2020-01-01", "2018-01-01")):
    """E76: re-derive the ladder + era-spread headline with the split screen on.

    The loader is opt-in (``scripts/panel_screen.py``); this leg is the only
    caller in the census chain, and it publishes the unscreened column beside
    every screened one. A screened number without its unscreened twin would let
    one silent repair move the whole book.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    if exclude:
        raw = {s: v for s, v in raw.items() if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]

    faces = {"unscreened": _screen_face(raw, cal_full, pick_n, eras, ladder_starts)}
    reports = {}
    for mode in modes:
        repaired, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)
        reports[mode] = report
        faces[mode] = _screen_face(repaired, cal_full, pick_n, eras, ladder_starts)

    delta = _delta_rows("unscreened", faces)

    def _biggest(pred):
        rows = [r for r in delta if pred(r)]
        if not rows:
            return None
        best = max(rows, key=lambda r: max(
            abs(r["delta_" + m]) for m in modes if r.get("delta_" + m) is not None))
        out = {"face": best["face"], "column": best["column"],
               "unscreened": best["unscreened"]}
        for m in modes:
            out[m] = best.get(m)
            out["delta_" + m] = best.get("delta_" + m)
        return out

    flipped = sorted(era for era in faces["unscreened"]["eras"]
                     if "spread_ann_bp" in faces["unscreened"]["eras"][era]
                     and any((faces[m]["eras"][era].get("spread_ann_bp") or 0)
                             * (faces["unscreened"]["eras"][era]["spread_ann_bp"] or 0) < 0
                             for m in modes))

    return {
        "study": "e76_panelscreen_regrade",
        "evidence_cutoff": cutoff,
        "spec": {
            "start": start, "pick_n": pick_n, "exclude_prefixes": list(exclude),
            "modes": list(modes), "cost_bp_per_side": base.COST_BP_SIDE,
            "ladder_starts": list(ladder_starts),
            "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
            "loader": "scripts/panel_screen.py (opt-in; every other leg still "
                      "reads e27.load_universe() unmodified)",
            "books": "ladder5 = E39 engine call on the five ladder members; era "
                     "spread = E41 ladder5 vs wide_topN on the full calendar",
        },
        "screen_reports": reports,
        "faces": faces,
        "delta": delta,
        "answers": {
            "ladder_worst_correction": _biggest(
                lambda r: r["face"].startswith("ladder@")),
            "ladder_member_prints": {
                s: _member_print_face(raw.get(s, ({}, {}))[0], cal_full)
                for s in base.LADDER if s in raw},
            "era_worst_correction": _biggest(
                lambda r: r["face"].startswith("era:") and r["column"] == "spread_ann_bp"),
            "eras_whose_spread_changes_sign": flipped,
            "delta_cells": len(delta),
            "non_zero_delta_cells": len([r for r in delta
                                         if any(r.get("delta_" + m) not in (None, 0)
                                                for m in modes)]),
        },
        "honest": [
            "the screen repairs arithmetic impossibility only: a flagged ETF print "
            "may be genuine (ETF daily limits differ from the 10%/20% stock band), "
            "so 'neutralise' is a sensitivity face, not a corrected truth",
            "three columns are published for that reason: neutralise_int repairs only "
            "the prints whose price ratio lands on an integer (a share ratio with no "
            "announcement feed), neutralise repairs every adjacent print, drop removes "
            "the name -- the range between them bounds the correction",
            "a slashed >30% sequence may need more than one event to clear; the "
            "loader applies every adjacent event it finds, and the report lists them",
            "the screened book is not a pre-registration and books no trial: it is "
            "the same descriptive face replayed from a different input",
            "drop mode changes the universe (n and eligibility), so its delta mixes "
            "the correction with a composition change; neutralise isolates it",
            "gapped prints are deliberately not repaired -- a resumption after "
            "suspension can be a real market print, and on this panel both ladder5 "
            "corporate actions sit behind a suspension bar, which is why the ladder "
            "column does not move at all (ladder_member_prints shows each one)",
            "descriptive census only: no gate, no verdict, no ledger booking, trial 0",
        ],
    }


def _screengapera_rows(faces, base="unscreened", adjacent="neutralise"):
    """(E93) One row per era: the published spread under every arm, with the
    delta against BOTH the untouched column and the adjacent-only column.

    The adjacent-only delta is the one the E92 chain needed: it isolates what
    the gap-tolerant repair adds, because the adjacent-only arm already
    carries the default screen. Rows only exist for eras that actually publish
    a spread (a wide leg with no live member cannot)."""
    rows = []
    for era in faces[base]["eras"]:
        u = faces[base]["eras"][era]
        if "spread_ann_bp" not in u:
            continue
        adj = (faces.get(adjacent, {}).get("eras", {}).get(era) or {}).get(
            "spread_ann_bp")
        row = {"era": era, "unscreened_spread_ann_bp": u.get("spread_ann_bp"),
               "adjacent_only_spread_ann_bp": adj}
        for arm in faces:
            if arm in (base, adjacent):
                continue
            v = (faces[arm]["eras"].get(era) or {}).get("spread_ann_bp")
            row[arm + "_spread_ann_bp"] = v
            row["delta_vs_unscreened_" + arm] = (
                round(v - u["spread_ann_bp"], 4)
                if isinstance(v, (int, float)) else None)
            row["delta_vs_adjacent_only_" + arm] = (
                round(v - adj, 4)
                if isinstance(v, (int, float)) and isinstance(adj, (int, float))
                else None)
        rows.append(row)
    return rows


def run_screengapera(outdir, start="2020-01-01", pick_n=9999,
                     exclude=("sh511",), eras=ERAS,
                     ladder_starts=("2020-01-01", "2018-01-01"),
                     gap_limits=(1, 5)):
    """E93: re-derive the era-SPREAD face (the number the chain publishes as
    an edge) with the gap-tolerant screen beside the untouched and the
    adjacent-only columns.

    E92 showed the churn LEVELS move while the churn GAP does not, but the
    churn sleeve is a name-level mean -- this leg reads the ladder-vs-wide era
    spread itself under gap_limit 1 and 5. No arm is overwritten: each arm is
    a separately labelled column, and both the unscreened and the adjacent-only
    spreads are carried into every row so no arm can be silently swapped.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    if exclude:
        raw = {s: v for s, v in raw.items() if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]

    arms = ["unscreened", "neutralise", "neutralise_int"]
    arms += ["neutralise_gap@%d" % g for g in gap_limits]
    faces = {"unscreened": _screen_face(raw, cal_full, pick_n, eras,
                                        ladder_starts)}
    reports = {}
    for mode in ("neutralise", "neutralise_int"):
        repaired, report = panel_screen.screen_universe(raw, mode=mode,
                                                        cal=cal_full)
        reports[mode] = report
        faces[mode] = _screen_face(repaired, cal_full, pick_n, eras,
                                   ladder_starts)
    for g in gap_limits:
        repaired, report = panel_screen.screen_universe(
            raw, mode="neutralise_gap", cal=cal_full, gap_limit=g)
        arm = "neutralise_gap@%d" % g
        reports[arm] = report
        faces[arm] = _screen_face(repaired, cal_full, pick_n, eras,
                                  ladder_starts)

    rows = _screengapera_rows(faces)
    gap_arms = [a for a in arms if a.startswith("neutralise_gap@")]

    def _signs_against(col):
        out = []
        for r in rows:
            u = r[col]
            if not isinstance(u, (int, float)) or u == 0:
                continue
            for a in gap_arms:
                v = r.get(a + "_spread_ann_bp")
                if isinstance(v, (int, float)) and v * u < 0:
                    out.append({"era": r["era"], "arm": a,
                                col: u, "arm_spread_ann_bp": v})
                    break
        return out

    worst = None
    for r in rows:
        for a in gap_arms:
            d = r.get("delta_vs_unscreened_" + a)
            if d is None:
                continue
            if worst is None or abs(d) > abs(worst["delta_vs_unscreened"]):
                worst = {"era": r["era"], "arm": a,
                         "unscreened": r["unscreened_spread_ann_bp"],
                         "arm_spread_ann_bp": r.get(a + "_spread_ann_bp"),
                         "delta_vs_unscreened": d,
                         "delta_vs_adjacent_only":
                             r.get("delta_vs_adjacent_only_" + a)}
    marginal = []
    if len(gap_limits) >= 2:
        lo, hi = "neutralise_gap@%d" % gap_limits[0], \
                 "neutralise_gap@%d" % gap_limits[-1]
        for r in rows:
            a, b = r.get(lo + "_spread_ann_bp"), r.get(hi + "_spread_ann_bp")
            marginal.append({"era": r["era"], "arm_low": lo, "arm_high": hi,
                             "delta": (round(b - a, 4)
                                       if isinstance(a, (int, float))
                                       and isinstance(b, (int, float)) else None)})

    return {
        "study": "e93_screengap_era_spread",
        "evidence_cutoff": cutoff,
        "spec": {
            "start": start, "pick_n": pick_n,
            "exclude_prefixes": list(exclude), "arms": arms,
            "gap_limits_sessions": list(gap_limits),
            "cost_bp_per_side": base.COST_BP_SIDE,
            "ladder_starts": list(ladder_starts),
            "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
            "books": "era spread = E41 ladder5 vs wide_topN on the full "
                     "calendar (same face E76 published); ladder windows "
                     "carried for completeness",
            "loader": "scripts/panel_screen.py (opt-in, integer-ratio gate)",
        },
        "screen_reports": reports,
        "era_rows": rows,
        "ladder_faces": {a: faces[a]["ladder"] for a in arms},
        "answers": {
            "eras_whose_spread_changes_sign_vs_unscreened":
                _signs_against("unscreened_spread_ann_bp"),
            "eras_whose_spread_changes_sign_vs_adjacent_only":
                _signs_against("adjacent_only_spread_ann_bp"),
            "worst_era_correction": worst,
            "gap_limit_marginal": marginal,
            "eras_compared": len(rows),
            "gap_arms": gap_arms,
        },
        "honest": [
            "descriptive census only: no gate, no verdict, no ledger booking, "
            "trial 0 (a re-read of an already published face, not a new claim)",
            "the gap-tolerant arm repairs only prints whose implied ratio lands "
            "on an integer and that sit within gap_limit sessions of the last "
            "priced close; everything else is left alone",
            "the adjacent-only and unscreened arms are re-derived, never "
            "rewritten: SCREENREG/SCREENGAP files on disk are untouched",
            "era spread is a sleeve-level mean of a name-level book, so a "
            "shift here is a composition-and-print effect on the same members, "
            "not a strategy change",
        ],
    }


# ------------------------------------------------------------ E77 wide screen

WIDE_COLUMNS = ("wide_ann_pct", "wide_total_return_pct", "wide_vol_pct",
                "wide_sharpe", "ladder_ann_pct", "vs_ladder_bp_annualised",
                "turnover_per_year", "cost_per_year_bp", "mean_bp", "t")
WIDE_ERA_COLUMNS = ("wide_ann_pct", "ladder_ann_pct", "spread_ann_bp",
                    "ratio_ann_pct", "ratio_max_drawdown_pct")


def _wide_headline(face, pick_n=9999):
    """(E77) the wide-book headline columns out of one e27 universe face."""
    w = (face.get("schemes") or {}).get("top%d" % pick_n) or {}
    lad = (face.get("schemes") or {}).get("ladder5") or {}
    m = w.get("metrics") or {}
    a = w.get("aux") or {}
    rel = w.get("vs_ladder") or {}
    return {
        "wide_ann_pct": m.get("ann_return_pct"),
        "wide_total_return_pct": m.get("total_return_pct"),
        "wide_vol_pct": m.get("ann_vol_pct"),
        "wide_sharpe": m.get("sharpe"),
        "ladder_ann_pct": (lad.get("metrics") or {}).get("ann_return_pct"),
        "vs_ladder_bp_annualised": w.get("vs_ladder_bp_annualised"),
        "turnover_per_year": a.get("turnover_per_year"),
        "cost_per_year_bp": a.get("cost_per_year_bp"),
        "months": rel.get("months"),
        "mean_bp": rel.get("mean_bp"),
        "t": rel.get("t"),
        "universe_size": face.get("universe_size"),
        "bars": face.get("bars"),
    }


def _wide_era_headline(rows):
    """(E77) flatten _era_rows into the wide-book era column set."""
    out = {}
    for era, r in rows.items():
        if "spread_ann_bp" not in r:
            out[era] = {"skipped": r.get("skipped"), "bars": r.get("bars")}
            continue
        ratio = r.get("ratio_path") or {}
        out[era] = {
            "wide_ann_pct": r.get("wide_ann_pct"),
            "ladder_ann_pct": r.get("ladder_ann_pct"),
            "spread_ann_bp": r.get("spread_ann_bp"),
            "ratio_ann_pct": ratio.get("ann_pct"),
            "ratio_max_drawdown_pct": ratio.get("max_drawdown_pct"),
            "from": r.get("from"), "to": r.get("to"), "bars": r.get("bars"),
        }
    return out


def _wide_delta_rows(base_label, faces, modes, starts, costs, eras):
    """(E77) one row per (window|era, cost, column) with every screen beside it."""
    rows = []
    u = faces[base_label]

    def emit(face, column, unscreened, pick):
        row = {"face": face, "column": column, "unscreened": unscreened}
        for m in modes:
            v = pick(faces[m])
            row[m] = v
            row["delta_" + m] = (round(v - unscreened, 4)
                                 if isinstance(v, (int, float))
                                 and isinstance(unscreened, (int, float)) else None)
        rows.append(row)

    for start in starts:
        for cost in costs:
            key = "x%g" % cost
            uw = ((u["windows"].get(start) or {}).get(key) or {})
            for col in WIDE_COLUMNS:
                emit("wide@%s@%s" % (start, key), col, uw.get(col),
                     lambda f, s=start, k=key, c=col:
                     ((f["windows"].get(s) or {}).get(k) or {}).get(c))
    for cost in costs:
        key = "x%g" % cost
        ue = u["eras"].get(key) or {}
        for era in eras:
            ename = era[0]
            urow = ue.get(ename) or {}
            for col in WIDE_ERA_COLUMNS:
                emit("era:%s@%s" % (ename, key), col, urow.get(col),
                     lambda f, k=key, e=ename, c=col:
                     ((f["eras"].get(k) or {}).get(e) or {}).get(c))
    return rows


def run_screenwide(outdir, pick_n=9999, exclude=("sh511",),
                   modes=("neutralise_int", "neutralise", "drop"),
                   starts=("2020-01-01", "2018-01-01"), costs=(1.0, 3.0),
                   eras=ERAS):
    """E77: replay the wide-book headline from the repaired universe.

    E76 showed the era *spread* moves when the split screen is on. This leg asks
    the narrower question the pool asked: do the wide-book columns themselves
    (both start windows, both cost levels, per era) move, and does the
    correction survive costs. The unscreened column sits beside every screened
    one; no published face is rewritten.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    if exclude:
        raw = {s: v for s, v in raw.items() if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]

    universes = {"unscreened": (raw, None)}
    reports = {}
    for mode in modes:
        repaired, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)
        reports[mode] = report
        universes[mode] = (repaired, mode)

    faces, n_runs = {}, 0
    for label, (univ_raw, _mode) in universes.items():
        windows = {}
        for start in starts:
            windows[start] = {}
            for cost in costs:
                face = e27.run(ns=(pick_n,), start=start, cost_mult=cost,
                               exclude=exclude, raw=univ_raw)
                n_runs += 1
                windows[start]["x%g" % cost] = _wide_headline(face, pick_n)
        era_faces = {}
        for cost in costs:
            lad, wide, ratio = _era_curves(univ_raw, cal_full, pick_n, cost_mult=cost)
            n_runs += 2
            era_faces["x%g" % cost] = _wide_era_headline(
                _era_rows(lad, wide, ratio, eras))
        faces[label] = {"windows": windows, "eras": era_faces,
                        "universe_size": len(univ_raw)}

    delta = _wide_delta_rows("unscreened", faces, modes, starts, costs, eras)

    def _biggest(pred):
        rows = [r for r in delta if pred(r)]
        if not rows:
            return None
        best = max(rows, key=lambda r: max(
            abs(r["delta_" + m]) for m in modes if r.get("delta_" + m) is not None))
        out = {"face": best["face"], "column": best["column"],
               "unscreened": best["unscreened"]}
        for m in modes:
            out[m] = best.get(m)
            out["delta_" + m] = best.get("delta_" + m)
        return out

    newest = eras[-1][0]
    era_cells = {}
    for label in faces:
        era_cells[label] = {}
        for cost in costs:
            key = "x%g" % cost
            row = (faces[label]["eras"].get(key) or {}).get(newest) or {}
            era_cells[label][key] = {"wide_ann_pct": row.get("wide_ann_pct"),
                                     "spread_ann_bp": row.get("spread_ann_bp")}

    flipped = sorted(
        era[0] for era in eras
        if any((((faces["unscreened"]["eras"].get("x%g" % cost) or {})
                 .get(era[0]) or {}).get("spread_ann_bp") or 0)
               * (((faces[m]["eras"].get("x%g" % cost) or {})
                   .get(era[0]) or {}).get("spread_ann_bp") or 0) < 0
               for m in modes for cost in costs))

    # does the correction survive the cost multiplier?
    cost_shift = []
    for label in ["unscreened"] + list(modes):
        for start in starts:
            a = (faces[label]["windows"][start].get("x1") or {}).get("wide_ann_pct")
            b = (faces[label]["windows"][start].get("x3") or {}).get("wide_ann_pct")
            cost_shift.append({
                "mode": label, "start": start,
                "x1_ann_pct": a, "x3_ann_pct": b,
                "shift_pct": (round(b - a, 3)
                              if isinstance(a, (int, float))
                              and isinstance(b, (int, float)) else None)})

    return {
        "study": "e77_screened_wide_era",
        "evidence_cutoff": cutoff,
        "spec": {
            "pick_n": pick_n, "exclude_prefixes": list(exclude),
            "modes": list(modes), "starts": list(starts), "costs": list(costs),
            "cost_bp_per_side": base.COST_BP_SIDE,
            "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
            "loader": "scripts/panel_screen.py via e27.run(raw=...) (opt-in)",
            "books": "wide_topN = e27 universe book; ladder5 = the five ladder "
                     "members; the spread/ratio read comes from _era_rows",
            "runs": n_runs,
        },
        "screen_reports": reports,
        "faces": faces,
        "delta": delta,
        "cost_shift": cost_shift,
        "answers": {
            "wide_worst_correction": _biggest(lambda r: r["face"].startswith("wide@")),
            "era_worst_correction": _biggest(
                lambda r: r["face"].startswith("era:") and r["column"] == "spread_ann_bp"),
            "newest_era_cells": era_cells,
            "eras_whose_spread_changes_sign": flipped,
            "delta_cells": len(delta),
            "non_zero_delta_cells": len([r for r in delta
                                         if any(r.get("delta_" + m) not in (None, 0)
                                                for m in modes)]),
            "max_abs_delta_by_column": {
                col: max([abs(r.get("delta_" + m) or 0) for r in delta
                          if r["column"] == col for m in modes] or [0])
                for col in sorted(set(WIDE_COLUMNS) | set(WIDE_ERA_COLUMNS))},
        },
        "honest": [
            "the screen repairs arithmetic impossibility only; a flagged ETF print "
            "may be genuine, so 'neutralise' is a sensitivity face, not a truth",
            "drop mode changes the universe size, so its delta mixes the correction "
            "with a composition change; the two neutralise columns isolate it",
            "gapped prints are never repaired, and both ladder5 corporate actions sit "
            "behind a suspension bar, so the ladder column is expected to be flat",
            "the wide book is a trailing-turnover top-N equal-weight book, not a "
            "cap-weighted index; its ann% is a book return, not a market return",
            "cost x3 is a stress face on the frozen 13.041bp/side, not a fee forecast",
            "descriptive census only: no gate, no verdict, no prereg, no trial booking",
        ],
    }


# --------------------------------------------------- E78 screened weekly residual

WEEK_COLUMNS = ("full_window_gap_bp", "turnover_per_year", "cost_per_year_bp")


def _week_delta_rows(base_label, faces, modes, costs, labels=("week", "week_near_me"),
                     eras=ERAS):
    """(E78) unscreened-vs-screened weekly residual, one row per cell.

    Pure so the residual arithmetic is testable without a burn: the weekly
    calendar and its month-end-near twin are the two books whose gap the
    six-round chain has been pricing, and every screened cell keeps the
    unscreened twin it is a delta against.
    """
    rows = []
    u = faces[base_label]["calendar_rows"]

    def emit(face, column, unscreened, pick):
        row = {"face": face, "column": column, "unscreened": unscreened}
        for m in modes:
            v = pick(faces[m])
            row[m] = v
            row["delta_" + m] = (round(v - unscreened, 4)
                                 if isinstance(v, (int, float))
                                 and isinstance(unscreened, (int, float)) else None)
        rows.append(row)

    for cost in costs:
        tag = "x%g" % cost
        for lab in labels:
            urow = (u.get(tag) or {}).get(lab) or {}
            for col in WEEK_COLUMNS:
                emit("%s@%s" % (lab, tag), col, urow.get(col),
                     lambda f, t=tag, l=lab, c=col:
                     ((f["calendar_rows"].get(t) or {}).get(l) or {}).get(c))
            for era in eras:
                ename = era[0]
                uv = (urow.get("eras") or {}).get(ename)
                emit("era:%s@%s@%s" % (lab, ename, tag), "gap_bp", uv,
                     lambda f, t=tag, l=lab, e=ename:
                     (((f["calendar_rows"].get(t) or {}).get(l) or {})
                      .get("eras") or {}).get(e))
    return rows


def run_screenweek(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",),
                   modes=("neutralise_int", "neutralise", "drop"),
                   costs=(1.0, 3.0), eras=ERAS, labels=("week", "week_near_me")):
    """E78: does the weekly-vs-monthly residual survive the split screen?

    E77 showed the split screen moves the wide book exactly in 2021_2023 and
    2024_now -- the two eras where the weekly-vs-monthly chain (E63/E69/E70)
    priced its residual. That residual is re-derived here from the repaired
    universe at both cost levels, through the same run_midsweep wiring, so the
    only moving part is the input book. Every screened cell keeps its
    unscreened twin and no published WEEKCLASH face is rewritten.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    if exclude:
        raw = {s: v for s, v in raw.items() if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]

    universes = {"unscreened": raw}
    reports = {}
    for mode in modes:
        repaired, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)
        reports[mode] = report
        universes[mode] = repaired

    tags = ["x%g" % c for c in costs]
    faces, n_runs = {}, 0
    for label, univ in universes.items():
        clash = run_midsweep(outdir, start=start, pick_n=pick_n, exclude=exclude,
                             days=(), costs=costs, lags=(), weekly=True, raw=univ)
        n_runs += 1
        rows_by_cost = {tag: _weekly_cal_rows(clash, tag, labels) for tag in tags}
        me_turn = {}
        for tag in tags:
            arms = ((clash.get("books") or {}).get("me") or {}).get("arms") or {}
            me_turn[tag] = (arms.get(tag) or {}).get("turnover_per_year")
        faces[label] = {"calendar_rows": rows_by_cost,
                        "me_turnover_by_cost": me_turn,
                        "universe_size": len(univ),
                        "week_overlap": clash["answers"].get("week_overlap")}

    delta = _week_delta_rows("unscreened", faces, modes, costs, labels, eras)

    def _biggest(pred):
        rows = [r for r in delta if pred(r)
                and any(r.get("delta_" + m) is not None for m in modes)]
        if not rows:
            return None
        best = max(rows, key=lambda r: max(
            abs(r["delta_" + m]) for m in modes
            if r.get("delta_" + m) is not None))
        out = {"face": best["face"], "column": best["column"],
               "unscreened": best["unscreened"]}
        for m in modes:
            out[m] = best.get(m)
            out["delta_" + m] = best.get("delta_" + m)
        return out

    # the residual itself, at every cost level, per mode
    residual = {label: {tag: ((faces[label]["calendar_rows"].get(tag) or {})
                              .get("week_near_me") or {}).get("full_window_gap_bp")
                        for tag in tags} for label in faces}
    full_gap = {label: {tag: ((faces[label]["calendar_rows"].get(tag) or {})
                              .get("week") or {}).get("full_window_gap_bp")
                        for tag in tags} for label in faces}

    surv = {}
    for tag in tags:
        base_bp = residual["unscreened"].get(tag)
        surv[tag] = {}
        for m in modes:
            v = residual[m].get(tag)
            surv[tag][m] = {
                "unscreened_bp": base_bp, "screened_bp": v,
                "delta_bp": (round(v - base_bp, 2)
                             if isinstance(v, (int, float))
                             and isinstance(base_bp, (int, float)) else None),
                "surviving_share_pct": (round(100.0 * v / base_bp, 1)
                                        if isinstance(v, (int, float)) and base_bp
                                        else None)}

    newest = eras[-1][0]
    era_residual = {tag: {label: ((faces[label]["calendar_rows"].get(tag) or {})
                                  .get("week_near_me") or {}).get("eras", {})
                             .get(newest)
                          for label in faces} for tag in tags}

    flipped = sorted(
        era[0] for era in eras
        if any(((((faces["unscreened"]["calendar_rows"].get(tag) or {})
                  .get("week_near_me") or {}).get("eras") or {}).get(era[0]) or 0)
               * ((((faces[m]["calendar_rows"].get(tag) or {})
                    .get("week_near_me") or {}).get("eras") or {}).get(era[0]) or 0) < 0
               for m in modes for tag in tags))

    return {
        "study": "e78_screened_weekclash_residual",
        "evidence_cutoff": cutoff,
        "spec": {
            "start": start, "pick_n": pick_n, "exclude_prefixes": list(exclude),
            "modes": list(modes), "costs": list(costs), "labels": list(labels),
            "cost_bp_per_side": base.COST_BP_SIDE,
            "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
            "loader": "scripts/panel_screen.py via run_midsweep(raw=...) (opt-in)",
            "books": "week = full ISO weekly grid; week_near_me = the same grid cut "
                     "to one decision per month at the weekly session nearest the "
                     "boundary; the gap is each book against month-end",
            "runs": n_runs,
        },
        "screen_reports": reports,
        "faces": faces,
        "delta": delta,
        "answers": {
            "residual_bp_by_cost": residual,
            "full_week_gap_bp_by_cost": full_gap,
            "residual_survival": surv,
            "newest_era_residual_bp": era_residual,
            "worst_correction": _biggest(lambda r: True),
            "residual_worst_correction": _biggest(
                lambda r: r["face"].startswith("week_near_me@")),
            "eras_whose_residual_changes_sign": flipped,
            "delta_cells": len(delta),
            "non_zero_delta_cells": len([r for r in delta
                                         if any(r.get("delta_" + m) not in (None, 0)
                                                for m in modes)]),
        },
        "honest": [
            "the screen repairs arithmetic impossibility only; a flagged ETF print "
            "may be genuine, so 'neutralise' is a sensitivity face, not a truth",
            "drop mode changes the universe size, so its delta mixes the correction "
            "with a composition change; the two neutralise columns isolate it",
            "week_near_me holds the trading frequency fixed against month-end, so it "
            "is the book that prices the DATE; the raw weekly gap mixes calendar "
            "with a ~4.3x higher rebalance rate and is published for context only",
            "turnover columns are the control that the screen moves the return path "
            "and not the traded book",
            "cost x3 is a stress face on the frozen 13.041bp/side, not a fee forecast",
            "gapped prints are never repaired, so a residual carried by a "
            "behind-suspension print would read flat here rather than corrected",
            "descriptive census only: no gate, no verdict, no prereg, no trial booking",
        ],
    }


# ------------------------------------------------------ E80 screened mid-month


def _dig(face, *path):
    """Walk a nested dict, returning None the moment the path breaks."""
    cur = face
    for p in path:
        if not isinstance(cur, dict):
            return None
        cur = cur.get(p)
    return cur


def _mid_delta_rows(base_label, faces, modes, eras, costs=(0.0, 1.0, 3.0),
                    mid_label="mid15"):
    """(E80) unscreened-vs-screened mid-month churn rows, one row per cell.

    Pure so the delta arithmetic is testable without a burn: every screened cell
    keeps the unscreened twin it is a delta against, at the same book, era and
    cost column. ``mid_label`` is the book key the face actually publishes
    (``mid15``), not a nickname -- the arms rows live under it.
    """
    rows = []
    u = faces.get(base_label) or {}
    era_names = [e[0] for e in eras]
    books = (("me", "me"), (mid_label, "mid"))

    def emit(face, column, unscreened, pick):
        row = {"face": face, "column": column, "unscreened": unscreened}
        for m in modes:
            v = pick(faces.get(m) or {})
            row[m] = v
            row["delta_" + m] = (round(v - unscreened, 4)
                                 if isinstance(v, (int, float))
                                 and isinstance(unscreened, (int, float)) else None)
        rows.append(row)

    for tag in ["x%g" % c for c in costs]:
        for key, lab in books:
            for col in ("turnover_per_year", "full_window_ann_pct"):
                emit("%s@%s" % (lab, tag), col,
                     _dig(u, "books", key, "arms", tag, col),
                     lambda f, t=tag, k=key, c=col:
                     _dig(f, "books", k, "arms", t, c))
            for era in era_names:
                emit("era:%s@%s@%s" % (lab, era, tag), "ann_return_pct",
                     _dig(u, "books", key, "arms", tag, "eras", era, "ann_return_pct"),
                     lambda f, t=tag, k=key, e=era:
                     _dig(f, "books", k, "arms", t, "eras", e, "ann_return_pct"))
        for era in era_names:
            key = "gap_%s_bp" % tag
            emit("gap:%s@%s" % (era, tag), "gap_bp", _dig(u, "eras", era, key),
                 lambda f, e=era, c=key: _dig(f, "eras", e, c))

    for era in era_names:
        for lab in ("me", "mid"):
            emit("churn:%s@%s" % (lab, era), "churn_alpha_bp_mean",
                 _dig(u, "eras", era, lab, "churn_alpha_bp_mean"),
                 lambda f, e=era, l=lab:
                 _dig(f, "eras", e, l, "churn_alpha_bp_mean"))
            emit("negchurn:%s@%s" % (lab, era), "negative_churn_share_pct",
                 _dig(u, "eras", era, lab, "negative_churn_share_pct"),
                 lambda f, e=era, l=lab:
                 _dig(f, "eras", e, l, "negative_churn_share_pct"))
        emit("churngap:%s" % era, "churn_alpha_gap_bp",
             _dig(u, "eras", era, "churn_alpha_gap_bp"),
             lambda f, e=era: _dig(f, "eras", e, "churn_alpha_gap_bp"))
    return rows


def _mid_flip_eras(faces, modes, eras, pick):
    """Eras whose unscreened value and a screened value straddle zero."""
    out = []
    u = faces.get("unscreened") or {}
    for era in [e[0] for e in eras]:
        uv = pick(u, era)
        if not isinstance(uv, (int, float)) or uv == 0:
            continue
        for m in modes:
            v = pick(faces.get(m) or {}, era)
            if isinstance(v, (int, float)) and uv * v < 0:
                out.append(era)
                break
    return sorted(out)


def run_midscreen(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",),
                  modes=("neutralise_int", "neutralise", "drop"), mid_day=15,
                  costs=(0.0, 1.0, 3.0), eras=ERAS):
    """E80: does the mid-month membership claim survive the split screen?

    E44 put the 2024_now mid-month gap (-87bp/yr) on membership -- the book turns
    over the same amount but swaps into worse names -- and E77/E78 showed the
    split screen moves exactly that era. The churn rows are re-derived here from
    the repaired universe, with the unscreened column kept beside every screened
    one, so the membership claim is measured rather than assumed. No published
    MIDMONTH face is rewritten.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    if exclude:
        raw = {s: v for s, v in raw.items() if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cutoff = cal_full[-1]

    universes = {"unscreened": raw}
    reports = {}
    for mode in modes:
        repaired, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)
        reports[mode] = report
        universes[mode] = repaired

    faces = {}
    for label, univ in universes.items():
        faces[label] = run_midmonth(outdir, start=start, pick_n=pick_n,
                                    exclude=exclude, mid_day=mid_day,
                                    costs=costs, raw=univ)

    delta = _mid_delta_rows("unscreened", faces, modes, eras, costs,
                            mid_label="mid%d" % mid_day)

    def _biggest(pred):
        rows = [r for r in delta if pred(r)
                and any(r.get("delta_" + m) is not None for m in modes)]
        if not rows:
            return None
        best = max(rows, key=lambda r: max(
            abs(r["delta_" + m]) for m in modes
            if r.get("delta_" + m) is not None))
        out = {"face": best["face"], "column": best["column"],
               "unscreened": best["unscreened"]}
        for m in modes:
            out[m] = best.get(m)
            out["delta_" + m] = best.get("delta_" + m)
        return out

    newest = eras[-1][0]
    gap_by_label = {label: _dig(faces[label], "answers", "newest_era_gap_x1_bp")
                    for label in faces}
    churn_by_label = {label: _dig(faces[label], "eras", newest, "churn_alpha_gap_bp")
                      for label in faces}
    negchurn_by_label = {
        label: {"me": _dig(faces[label], "eras", newest, "me", "negative_churn_share_pct"),
                "mid": _dig(faces[label], "eras", newest, "mid", "negative_churn_share_pct")}
        for label in faces}
    turn_by_label = {label: {"me": _dig(faces[label], "books", "me", "arms", "x1",
                                             "turnover_per_year"),
                             "mid": _dig(faces[label], "books", "mid%d" % mid_day,
                                         "arms", "x1", "turnover_per_year")}
                     for label in faces}

    base_gap = gap_by_label.get("unscreened")
    surv = {}
    for m in modes:
        v = gap_by_label.get(m)
        surv[m] = {
            "unscreened_bp": base_gap, "screened_bp": v,
            "delta_bp": (round(v - base_gap, 1)
                         if isinstance(v, (int, float))
                         and isinstance(base_gap, (int, float)) else None),
            "surviving_share_pct": (round(100.0 * v / base_gap, 1)
                                    if isinstance(v, (int, float)) and base_gap else None)}

    return {
        "study": "e80_screened_midmonth_churn",
        "evidence_cutoff": cutoff,
        "spec": {
            "start": start, "pick_n": pick_n, "exclude_prefixes": list(exclude),
            "modes": list(modes), "costs": list(costs), "mid_month_day": mid_day,
            "cost_bp_per_side": base.COST_BP_SIDE,
            "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
            "loader": "scripts/panel_screen.py via run_midmonth(raw=...) (opt-in)",
            "books": "me = month-end decisions; mid%d = first session on/after the "
                     "%dth of each month; both on one calendar, one rank cache" % (mid_day, mid_day),
            "runs": len(universes),
        },
        "screen_reports": reports,
        "eras": {label: faces[label].get("eras") for label in faces},
        "answers": {label: faces[label].get("answers") for label in faces},
        "delta": delta,
        "results": {
            "newest_era_gap_x1_bp": gap_by_label,
            "gap_survival": surv,
            "newest_era_churn_alpha_gap_bp": churn_by_label,
            "newest_era_negative_churn_share_pct": negchurn_by_label,
            "turnover_per_year_control": turn_by_label,
            "eras_whose_gap_changes_sign": _mid_flip_eras(
                faces, modes, eras, lambda f, e: _dig(f, "eras", e, "gap_x1_bp")),
            "eras_whose_churn_gap_changes_sign": _mid_flip_eras(
                faces, modes, eras, lambda f, e: _dig(f, "eras", e, "churn_alpha_gap_bp")),
            "worst_correction": _biggest(lambda r: True),
            "delta_cells": len(delta),
            "non_zero_delta_cells": len([r for r in delta
                                         if any(r.get("delta_" + m) not in (None, 0)
                                                for m in modes)]),
        },
        "honest": [
            "the screen repairs arithmetic impossibility only; a flagged ETF print may be "
            "genuine, so 'neutralise' is a sensitivity face, not a corrected truth",
            "drop mode changes the universe size, so its delta mixes the correction with a "
            "composition change and its eligibility set differs from the twin",
            "the churn sleeve is an equal-weight mean over the swapped names, not a "
            "portfolio return: it prices whether the names taken in beat the names given "
            "up inside that window",
            "the turnover column is the control that the screen moves the return path and "
            "not the traded book; a screened turnover that differs from its twin means the "
            "screen changed eligibility, not the calendar",
            "gapped prints are never repaired, so a churn carried by a behind-suspension "
            "print reads flat here rather than corrected",
            "descriptive census only: no gate, no verdict, no prereg, no trial booking",
        ],
    }


# ------------------------------- leg: who carries the churn-gap amplification (E82)


def _event_dates(universe, cal):
    """name -> sorted print-event dates, scanned on consecutive priced closes."""
    import panel_screen

    out = {}
    for s, pair in universe.items():
        closes = pair[0] if isinstance(pair, tuple) else pair
        ev = panel_screen.split_events(closes, cal=cal)
        if ev:
            out[s] = sorted({e["date"] for e in ev})
    return out


def _transition_hits(d0, d1, swapped, event_dates):
    """Swapped names whose print event sits inside (d0, d1] -- the priced window.

    Exclusive start, inclusive end: the sleeve prices ``date -> next``, so an
    event on the decision day itself belongs to the previous window.
    """
    hits = []
    for s in swapped:
        for d in event_dates.get(s, ()):
            if d0 < d <= d1:
                hits.append({"name": s, "date": d})
                break
    return hits


def _churn_join(base_rows, mode_rows, event_dates, eras=ERAS):
    """Per-transition delta (mode minus baseline) tagged hit / clean.

    hit  -- at least one swapped name carried a print event inside the window
    clean-- no swapped name did, so a repair cannot be the cause of the move
    """
    m_by = {r["date"]: r for r in mode_rows}
    out = []
    for b in base_rows:
        m = m_by.get(b["date"])
        if m is None:
            continue
        swapped = sorted(set(b.get("entrant_names") or ())
                         | set(b.get("exit_names") or ()))
        hits = _transition_hits(b["date"], b["next"], swapped, event_dates)
        a0, a1 = b.get("churn_alpha_bp"), m.get("churn_alpha_bp")
        out.append({
            "date": b["date"], "next": b["next"], "era": b.get("era"),
            "hit": bool(hits), "hit_names": [h["name"] for h in hits],
            "alpha_base_bp": a0, "alpha_mode_bp": a1,
            "delta_bp": (round(a1 - a0, 1)
                         if isinstance(a0, (int, float))
                         and isinstance(a1, (int, float)) else None),
        })

    agg = {}
    for name, _lo, _hi in eras:
        sub = [r for r in out if r["era"] == name and r["delta_bp"] is not None]
        if not sub:
            continue
        hit = [r["delta_bp"] for r in sub if r["hit"]]
        clean = [r["delta_bp"] for r in sub if not r["hit"]]
        total = sum(r["delta_bp"] for r in sub)
        agg[name] = {
            "transitions": len(sub),
            "hit_transitions": len(hit),
            "hit_share_pct": round(100.0 * len(hit) / len(sub), 1),
            "delta_mean_all_bp": round(total / len(sub), 1),
            "delta_mean_hit_bp": round(sum(hit) / len(hit), 1) if hit else None,
            "delta_mean_clean_bp": round(sum(clean) / len(clean), 1) if clean else None,
            "delta_sum_hit_bp": round(sum(hit), 1) if hit else 0.0,
            "delta_sum_clean_bp": round(sum(clean), 1) if clean else 0.0,
            "hit_share_of_delta_pct": (round(100.0 * sum(hit) / total, 1)
                                       if hit and total else None),
        }
    return out, agg


def _worst_transitions(rows, n=8):
    """The n largest |delta| transitions, kept with their hit tag and window."""
    live = [r for r in rows if r["delta_bp"] is not None]
    live.sort(key=lambda r: -abs(r["delta_bp"]))
    return live[:n]


def run_churngap(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",),
                 modes=("neutralise_int", "neutralise", "drop"), mid_day=15,
                 eras=ERAS):
    """E82: break the churn-gap amplification down per transition.

    E80 left an asymmetry -- the newest-era churn alpha gap widens under
    neutralise (-211 -> -457bp per swap) but collapses under drop (-24bp). If
    the amplification lives on the transitions whose swapped names hold a print
    event, it is a repair effect; if it is spread over clean transitions, it is
    a composition effect of the repaired universe. Both books (month-end and
    mid-month) are joined transition-by-transition against the raw event list;
    no published face is rewritten.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    if exclude:
        raw = {s: v for s, v in raw.items() if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cal = [d for d in cal_full if d >= start]
    cutoff = cal[-1]
    event_dates = _event_dates(raw, cal_full)

    universes = {"unscreened": raw}
    reports = {}
    for mode in modes:
        repaired, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)
        reports[mode] = report
        universes[mode] = repaired

    faces = {}
    for label, univ in universes.items():
        faces[label] = run_midmonth(outdir, start=start, pick_n=pick_n,
                                    exclude=exclude, mid_day=mid_day,
                                    raw=univ, full_churn=True)

    book_labels = ["me", "mid%d" % mid_day]
    joins, summary = {}, {}
    for book in book_labels:
        base_rows = faces["unscreened"]["books"][book]["churn_rows"]
        joins[book] = {}
        summary[book] = {}
        for mode in modes:
            mode_rows = faces[mode]["books"][book]["churn_rows"]
            rows, agg = _churn_join(base_rows, mode_rows, event_dates, eras)
            joins[book][mode] = {"eras": agg,
                                 "worst_transitions": _worst_transitions(rows),
                                 "transitions": len(rows)}
            newest = agg.get(eras[-1][0], {})
            summary[book][mode] = {
                "transitions_joined": len(rows),
                "transitions_with_a_repair": len([r for r in rows if r["hit"]]),
                "newest_era_delta_mean_all_bp": newest.get("delta_mean_all_bp"),
                "newest_era_delta_mean_hit_bp": newest.get("delta_mean_hit_bp"),
                "newest_era_delta_mean_clean_bp": newest.get("delta_mean_clean_bp"),
                "newest_era_hit_share_of_delta_pct": newest.get("hit_share_of_delta_pct"),
            }

    # the amplification itself, re-read on the joined transitions: mode minus
    # baseline for the same book, so the two columns cannot be two different burns
    return {
        "study": "e82_churn_gap_amplification",
        "evidence_cutoff": cutoff,
        "spec": {
            "start": start, "pick_n": pick_n, "exclude_prefixes": list(exclude),
            "modes": list(modes), "mid_month_day": mid_day,
            "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
            "books": book_labels,
            "joins": "churn rows from run_midmonth(full_churn=True) joined by "
                     "decision date against panel_screen.split_events on the raw prints",
            "hit_window": "event date d counts when decision date < d <= next decision date",
            "cost_mult_list": [0.0, 1.0, 3.0],
            "why_this_cost_set": "the churn sleeve is a name-level mean, not a "
                                 "portfolio return, so no cost multiplier can move it; the "
                                 "standard triple is kept so the sleeve lands beside the "
                                 "turnover control of the same burn",
            "universe_members": len(raw),
            "events_indexed": len(event_dates),
            "runs": len(universes),
        },
        "screen_reports": reports,
        "events_by_name": {k: v for k, v in sorted(event_dates.items())},
        "joins": joins,
        "results": summary,
        "honest": [
            "a hit transition says a print event sits inside the priced window; it does "
            "not say the book traded that name on that bar",
            "the churn sleeve is an equal-weight mean over the swapped names, so a single "
            "large print can move one transition's alpha by more than a clean year",
            "drop mode removes names entirely, so its delta mixes repair with composition "
            "and is not comparable cell-for-cell with the neutralise arms",
            "transitions are counted, not weighted: a period with more rebalances "
            "contributes more rows, and the era means are unweighted",
            "the event index comes from the raw prints, so a name that never traded a "
            "suspicious bar is clean by construction and cannot explain anything here",
            "descriptive census only: no gate, no verdict, no prereg, no trial booking",
        ],
    }


# -------------------------------------------------------------- E83 / E84

def _single_print_cell(rows, eras=ERAS, event_dates=None):
    """E83: one era cell re-read with its single most influential swap removed.

    Removing transition i from a cell of n alphas moves the mean to
    ``(n*m - a_i)/(n-1)``, so the biggest collapse is always the transition
    farthest from the mean. A cell that keeps less than half its magnitude
    without one transition is quoting one swap, not a period.
    """
    out = {}
    for name, _lo, _hi in eras:
        sub = [r for r in rows
               if r.get("era") == name
               and isinstance(r.get("churn_alpha_bp"), (int, float))]
        if not sub:
            continue
        vals = [r["churn_alpha_bp"] for r in sub]
        n = len(sub)
        tot = sum(vals)
        m = tot / n
        face = {"transitions": n, "mean_bp": round(m, 1),
                "median_bp": round(sorted(vals)[n // 2], 1),
                "single_swap_removable": n >= 2}
        if n >= 2:
            best = None
            for r, a in zip(sub, vals):
                new = (tot - a) / (n - 1)
                if best is None or abs(new) < abs(best["mean_without_bp"]):
                    best = {"removed_window": [r["date"], r["next"]],
                            "removed_alpha_bp": round(a, 1),
                            "removed_swapped": sorted(set(r.get("entrant_names") or ())
                                                      | set(r.get("exit_names") or ())),
                            "mean_without_bp": round(new, 1)}
            share = (abs(best["mean_without_bp"]) / abs(m)) if m else None
            best["magnitude_remaining_pct"] = (round(100.0 * share, 1)
                                               if share is not None else None)
            best["single_print"] = bool(share is not None and share < 0.5)
            best["sign_flip"] = bool(m * best["mean_without_bp"] < 0)
            if event_dates is not None:
                d0, d1 = best["removed_window"]
                best["removed_carries_a_print"] = bool(
                    _transition_hits(d0, d1, best["removed_swapped"], event_dates))
            face["most_influential_removal"] = best
        out[name] = face
    return out


def _single_print_gap(me_rows, mid_rows, eras=ERAS, event_dates=None):
    """E83: the me-vs-mid churn gap re-read with one transition removed.

    The two books rebalance on different dates (month-end vs mid-month), so
    there is no matched transition to drop -- the date sets are disjoint by
    construction. The gap is therefore perturbed the only way it can be: remove
    the single most influential transition from ONE side and leave the other
    intact. Both sides are tried and the larger collapse is reported together
    with the side it came from.
    """
    out = {}
    for name, _lo, _hi in eras:
        a_rows = [r for r in me_rows
                  if r.get("era") == name
                  and isinstance(r.get("churn_alpha_bp"), (int, float))]
        b_rows = [r for r in mid_rows
                  if r.get("era") == name
                  and isinstance(r.get("churn_alpha_bp"), (int, float))]
        if not a_rows or not b_rows:
            continue
        a_vals = [r["churn_alpha_bp"] for r in a_rows]
        b_vals = [r["churn_alpha_bp"] for r in b_rows]
        ma = sum(a_vals) / len(a_vals)
        mb = sum(b_vals) / len(b_vals)
        gap = mb - ma
        face = {"transitions_me": len(a_vals), "transitions_mid": len(b_vals),
                "gap_bp": round(gap, 1),
                "single_swap_removable": len(a_vals) >= 2 or len(b_vals) >= 2}
        best = None
        if len(a_vals) >= 2:
            for r, a in zip(a_rows, a_vals):
                new = mb - (sum(a_vals) - a) / (len(a_vals) - 1)
                cand = {"removed_side": "me", "removed_window": [r["date"], r["next"]],
                        "removed_alpha_bp": round(a, 1),
                        "removed_swapped": sorted(set(r.get("entrant_names") or ())
                                                  | set(r.get("exit_names") or ())),
                        "gap_without_bp": round(new, 1)}
                if best is None or abs(new) < abs(best["gap_without_bp"]):
                    best = cand
        if len(b_vals) >= 2:
            for r, b in zip(b_rows, b_vals):
                new = (sum(b_vals) - b) / (len(b_vals) - 1) - ma
                cand = {"removed_side": "mid", "removed_window": [r["date"], r["next"]],
                        "removed_alpha_bp": round(b, 1),
                        "removed_swapped": sorted(set(r.get("entrant_names") or ())
                                                  | set(r.get("exit_names") or ())),
                        "gap_without_bp": round(new, 1)}
                if abs(new) < abs(best["gap_without_bp"]):
                    best = cand
        if best is not None:
            share = (abs(best["gap_without_bp"]) / abs(gap)) if gap else None
            best["magnitude_remaining_pct"] = (round(100.0 * share, 1)
                                               if share is not None else None)
            best["single_print"] = bool(share is not None and share < 0.5)
            best["sign_flip"] = bool(gap * best["gap_without_bp"] < 0)
            if event_dates is not None:
                d0, d1 = best["removed_window"]
                best["removed_carries_a_print"] = bool(
                    _transition_hits(d0, d1, best["removed_swapped"], event_dates))
            face["most_influential_removal"] = best
        out[name] = face
    return out


def _mode_universe_diff(reports, modes=("neutralise_int", "neutralise")):
    """E84: which names one screen repairs and the other leaves alone."""
    touched = {}
    for mode in modes:
        touched[mode] = {r["name"]: r for r in reports[mode]["names"]
                         if r.get("action") != "kept-gapped-only"}
    small, big = touched[modes[0]], touched[modes[1]]
    extra = sorted(set(big) - set(small))
    return {
        "modes": list(modes),
        "names_touched": {m: len(touched[m]) for m in modes},
        "names_events": {m: reports[m]["events_neutralised"] for m in modes},
        "names_only_in_%s" % modes[1]: len(extra),
        "extra_names": extra,
        "extra_prints": [
            {"name": n, "events": big[n]["events"],
             "prints": [{"date": p.get("date"), "ret_pct": p.get("ret_pct"),
                         "ratio": p.get("ratio"),
                         "nearest_int": p.get("nearest_int"),
                         "resid_pct": p.get("resid_pct")}
                        for p in big[n].get("prints", ())]}
            for n in extra],
        "note": "the conservative arm repairs a strict subset: every name and every "
                "print it touches is also touched by the full arm",
    }


def _mode_row_diff(rows_a, rows_b):
    """E84: exact transition-by-transition comparison of two screen modes."""
    a = {r["date"]: r.get("churn_alpha_bp") for r in rows_a}
    b = {r["date"]: r.get("churn_alpha_bp") for r in rows_b}
    dates = sorted(set(a) & set(b))
    diffs = []
    for d in dates:
        x, y = a[d], b[d]
        if isinstance(x, (int, float)) and isinstance(y, (int, float)):
            if x != y:
                diffs.append({"date": d, "a_bp": x, "b_bp": y})
        elif x is not y:
            diffs.append({"date": d, "a_bp": x, "b_bp": y})
    return {
        "transitions_compared": len(dates),
        "transitions_differing": len(diffs),
        "date_set_mismatch": len(set(a) ^ set(b)),
        "differing_rows": diffs[:20],
        "bit_identical": not diffs and not (set(a) ^ set(b)),
    }


def _extra_name_relevance(churn_row_sets, extra_names, event_dates):
    """E84: did any transition ever swap one of the names only the wider arm fixes?"""
    extra = set(extra_names)
    ever_swapped = set()
    windows_with_print = 0
    windows_with_swap = 0
    for rows in churn_row_sets:
        for r in rows:
            swapped = set(r.get("entrant_names") or ()) | set(r.get("exit_names") or ())
            if not swapped & extra:
                continue
            windows_with_swap += 1
            ever_swapped |= swapped & extra
            if _transition_hits(r["date"], r["next"], sorted(swapped & extra),
                                event_dates):
                windows_with_print += 1
    return {"extra_names": len(extra),
            "extra_names_ever_swapped": len(ever_swapped),
            "extra_names_ever_swapped_list": sorted(ever_swapped),
            "windows_swapping_an_extra_name": windows_with_swap,
            "windows_where_an_extra_name_carried_a_print": windows_with_print}


def run_singleprint(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",),
                    modes=("neutralise_int", "neutralise", "drop"), mid_day=15,
                    eras=ERAS):
    """E83 + E84: is a published churn cell one swap wide, and is the second arm wasted?

    E82 found the newest-era amplification of the mid-month churn gap is a
    single transition (mid15 2024-01-15 sz159925). E83 turns that from an
    anecdote into a screen over every published churn cell: each book, each
    screen mode, each era, re-read with its single most influential transition
    removed, flagged when less than half the magnitude survives. E84 audits
    ``neutralise_int`` against ``neutralise`` -- the two arms returned identical
    churn rows in E80/E82, and a silently duplicate arm is the shape of an
    accounting error. Both questions are answered from ONE burn, because they
    need the same four universes; the universe-level half of E84 is hermetic and
    costs nothing.

    Drop mode is flagged separately everywhere: it removes names, so a dropped
    name changes the book's composition rather than repairing a bar, and its
    cells are not comparable to the neutralise arms.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    if exclude:
        raw = {s: v for s, v in raw.items() if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cal = [d for d in cal_full if d >= start]
    cutoff = cal[-1]
    event_dates = _event_dates(raw, cal_full)

    universes = {"unscreened": raw}
    reports = {}
    for mode in modes:
        repaired, report = panel_screen.screen_universe(raw, mode=mode,
                                                       cal=cal_full)
        reports[mode] = report
        universes[mode] = repaired

    faces = {}
    for label, univ in universes.items():
        faces[label] = run_midmonth(outdir, start=start, pick_n=pick_n,
                                    exclude=exclude, mid_day=mid_day,
                                    raw=univ, full_churn=True)

    book_labels = ["me", "mid%d" % mid_day]
    cells, gaps = {}, {}
    for book in book_labels:
        cells[book] = {}
        for label in universes:
            cells[book][label] = _single_print_cell(
                faces[label]["books"][book]["churn_rows"], eras, event_dates)
    for label in universes:
        gaps[label] = _single_print_gap(
            faces[label]["books"]["me"]["churn_rows"],
            faces[label]["books"]["mid%d" % mid_day]["churn_rows"], eras,
            event_dates)

    n_cells = sum(len(era_map) for book in cells.values()
                  for era_map in book.values())
    n_gaps = sum(len(v) for v in gaps.values())
    flagged = []
    for book in book_labels:
        for label in universes:
            for era, face in cells[book][label].items():
                rm = face.get("most_influential_removal")
                if rm and rm.get("single_print"):
                    flagged.append({
                        "face": "churn_alpha_bp_mean", "book": book,
                        "universe": label, "era": era,
                        "mean_bp": face["mean_bp"],
                        "without_one_swap_bp": rm["mean_without_bp"],
                        "magnitude_remaining_pct": rm["magnitude_remaining_pct"],
                        "sign_flip": rm["sign_flip"],
                        "removed_window": rm["removed_window"],
                        "removed_carries_a_print": rm.get("removed_carries_a_print"),
                    })
    for label in universes:
        for era, face in gaps[label].items():
            rm = face.get("most_influential_removal")
            if rm and rm.get("single_print"):
                flagged.append({
                    "face": "churn_alpha_gap_bp", "book": "mid%d-me" % mid_day,
                    "universe": label, "era": era,
                    "mean_bp": face["gap_bp"],
                    "without_one_swap_bp": rm["gap_without_bp"],
                    "magnitude_remaining_pct": rm["magnitude_remaining_pct"],
                    "sign_flip": rm["sign_flip"],
                    "removed_side": rm.get("removed_side"),
                    "removed_window": rm["removed_window"],
                    "removed_carries_a_print": rm.get("removed_carries_a_print"),
                })

    # E84: the two neutralise arms, universe half (exact) and cell half (exact)
    universe_diff = _mode_universe_diff(reports)
    row_diffs = {book: _mode_row_diff(
        faces["neutralise_int"]["books"][book]["churn_rows"],
        faces["neutralise"]["books"][book]["churn_rows"]) for book in book_labels}
    all_rows = [faces[label]["books"][b]["churn_rows"]
                for label in universes for b in book_labels]
    relevance = _extra_name_relevance(all_rows,
                                      universe_diff["extra_names"], event_dates)
    era_cell_diffs = {}
    for book in book_labels:
        for era in cells[book]["neutralise_int"]:
            a = cells[book]["neutralise_int"][era].get("mean_bp")
            b = cells[book]["neutralise"].get(era, {}).get("mean_bp")
            if a != b:
                era_cell_diffs["%s:%s" % (book, era)] = {"int_bp": a, "all_bp": b}

    identical = all(d["bit_identical"] for d in row_diffs.values())
    modeeq = {
        "study": "e84_screen_mode_equivalence",
        "evidence_cutoff": cutoff,
        "question": "neutralise_int and neutralise produced identical churn cells in "
                    "E80/E82 -- is the second arm a duplicate burn?",
        "universe_half": universe_diff,
        "churn_row_half": row_diffs,
        "era_cell_diffs": era_cell_diffs,
        "relevance_to_this_book": relevance,
        "verdict": ("identical_on_this_face" if identical else
                    "differs_somewhere"),
        "reading": [
            "the conservative arm touches a strict subset of the names the full arm "
            "repairs, so the universes are NOT the same object",
            "the churn cells are identical here because a repaired bar can only move a "
            "cell through a name the book actually swapped inside that window",
            "so the right statement is 'duplicate for THIS consumer at THIS cutoff', "
            "not 'the modes are the same screen' -- any face that prices per-name "
            "returns over the whole universe (book returns, breadth) must still run the "
            "full arm",
        ],
        "honest": [
            "a zero row difference can also mean both arms failed to repair anything; "
            "the touched-name counts above are the control against that",
            "drop mode is not part of this comparison: it removes names and changes "
            "composition, so it can never be a duplicate of a bar-repair arm",
        ],
    }

    bond = {
        "study": "e83_single_print_screen",
        "evidence_cutoff": cutoff,
        "spec": {"start": start, "pick_n": pick_n,
                 "exclude_prefixes": list(exclude), "modes": list(modes),
                 "mid_month_day": mid_day,
                 "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
                 "books": book_labels,
                 "screen": "each era cell of every book/universe pair, re-read with its "
                           "single most influential transition removed "
                           "(mean_without = (n*m - a_i)/(n-1), pick the smallest "
                           "|mean_without|)",
                 "flag_rule": "single_print when less than 50% of the cell's magnitude "
                              "survives the removal of one transition",
                 "universe_members": len(raw),
                 "events_indexed": len(event_dates),
                 "runs": len(universes)},
        "screen_reports": reports,
        "cells": cells,
        "gaps": gaps,
        "flagged": flagged,
        "flagged_count": len(flagged),
        "cells_examined": n_cells + n_gaps,
        "results": {
            "cells_examined": n_cells + n_gaps,
            "cell_breakdown": {"book_era_cells": n_cells, "gap_era_cells": n_gaps},
            "flagged": len(flagged),
            "flagged_unscreened": len([f for f in flagged
                                       if f["universe"] == "unscreened"]),
            "flagged_neutralise": len([f for f in flagged
                                       if f["universe"].startswith("neutralise")]),
            "flagged_drop": len([f for f in flagged if f["universe"] == "drop"]),
            "flagged_with_a_print": len([f for f in flagged
                                         if f["removed_carries_a_print"]]),
        },
        "mode_equivalence_ref": "MODEEQ-%s.json" % cutoff.replace("-", ""),
        "honest": [
            "the screen removes the single most influential transition; it does not "
            "test whether a second removal matters too, so 'not single print' only "
            "means the cell survives one swap",
            "an era cell with two transitions cannot survive any removal by "
            "arithmetic -- its magnitude_remaining_pct is 0 by construction, so read "
            "the transitions count before the flag",
            "removal is unweighted: transition alphas are an equal-weight mean over "
            "swapped names, so a period with few transitions can be dominated by one "
            "wide window",
            "drop mode is flagged separately and cannot be compared to the neutralise "
            "arms cell-for-cell",
            "descriptive census only: no gate, no verdict, no prereg, no trial booking",
        ],
    }
    return bond, modeeq


def _median_sorted(s):
    """Median of an already-sorted list (mean of the two middles when even)."""
    n = len(s)
    if not n:
        return None
    mid = n // 2
    if n % 2:
        return float(s[mid])
    return 0.5 * (s[mid - 1] + s[mid])


def _robust_stats(vals, trim_pct=10.0):
    """Mean, median and symmetric trimmed mean of one cell's own values.

    Every churn cell in E80/E82/E83 is a MEAN over per-transition numbers, and
    those numbers are heavy-tailed by construction (one swap can own a window).
    A mean that survives as a median is a statement about the typical
    transition; a mean that collapses is a statement about a few.
    """
    clean = [float(v) for v in vals if isinstance(v, (int, float))]
    n = len(clean)
    if not n:
        return {"n": 0, "mean_bp": None, "median_bp": None, "trim10_bp": None,
                "trim_dropped": 0, "median_keep_pct_of_mean": None,
                "trim10_keep_pct_of_mean": None}
    s = sorted(clean)
    k = int(n * trim_pct / 100.0)
    core = s[k:n - k] if n - 2 * k > 0 else s
    mean = sum(clean) / n
    med = _median_sorted(s)
    trim = sum(core) / len(core)

    def keep(x):
        if mean == 0:
            return None
        return round(100.0 * x / mean, 1)

    return {"n": n, "mean_bp": round(mean, 1), "median_bp": round(med, 1),
            "trim10_bp": round(trim, 1),
            "trim_dropped": (2 * k) if core is not s else 0,
            "median_keep_pct_of_mean": keep(med),
            "trim10_keep_pct_of_mean": keep(trim)}


def _concentration(vals, k=3):
    """How much of a cell's signed total the k largest |values| carry."""
    clean = [float(v) for v in vals if isinstance(v, (int, float))]
    if not clean:
        return None
    order = sorted(range(len(clean)), key=lambda i: -abs(clean[i]))[:k]
    top = sum(clean[i] for i in order)
    tot = sum(clean)
    return {"k": len(order), "top_sum_bp": round(top, 1),
            "total_sum_bp": round(tot, 1),
            "top_share_of_total_pct": (round(100.0 * top / tot, 1)
                                       if tot else None)}


def run_robustchurn(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",),
                    modes=("neutralise_int", "neutralise", "drop"), mid_day=15,
                    eras=ERAS):
    """E85: put a robust estimator beside every published churn cell's mean.

    E83 showed one transition can own a cell; that is a magnitude statement
    about the MEAN. This leg asks the complementary question on the same burn:
    does the cell's centre of mass move? Cells are (book, universe|mode, era)
    and each carries mean / median / 10% trimmed mean plus the share of the
    signed total carried by the three largest transitions. No published face is
    rewritten and no predictor is claimed.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    if exclude:
        raw = {s: v for s, v in raw.items() if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cal = [d for d in cal_full if d >= start]
    cutoff = cal[-1]
    event_dates = _event_dates(raw, cal_full)

    universes = {"unscreened": raw}
    reports = {}
    for mode in modes:
        repaired, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)
        reports[mode] = report
        universes[mode] = repaired

    faces = {}
    for label, univ in universes.items():
        faces[label] = run_midmonth(outdir, start=start, pick_n=pick_n,
                                    exclude=exclude, mid_day=mid_day,
                                    raw=univ, full_churn=True)

    books = ["me", "mid%d" % mid_day]
    cells, delta_cells = [], []
    for book in books:
        base_rows = faces["unscreened"]["books"][book]["churn_rows"]
        for label in universes:
            rows = (base_rows if label == "unscreened"
                    else faces[label]["books"][book]["churn_rows"])
            for name, _lo, _hi in eras:
                sub = [r["churn_alpha_bp"] for r in rows if r.get("era") == name]
                st = _robust_stats(sub)
                if not st["n"]:
                    continue
                cells.append({"book": book, "universe": label, "era": name,
                              "face": "churn_alpha_bp", **st,
                              "concentration_top3": _concentration(sub, 3)})
        for mode in modes:
            rows, _agg = _churn_join(base_rows,
                                     faces[mode]["books"][book]["churn_rows"],
                                     event_dates, eras)
            for name, _lo, _hi in eras:
                sub = [r["delta_bp"] for r in rows if r["era"] == name]
                st = _robust_stats(sub)
                if not st["n"]:
                    continue
                delta_cells.append({"book": book, "mode": mode, "era": name,
                                    "face": "delta_bp", **st,
                                    "concentration_top3": _concentration(sub, 3)})

    def _tally(rows):
        live = [c for c in rows if c["median_keep_pct_of_mean"] is not None]
        return {
            "cells": len(live),
            "median_keeps_under_half_pct": len(
                [c for c in live if abs(c["median_keep_pct_of_mean"]) < 50.0]),
            "trim10_keeps_under_half_pct": len(
                [c for c in live
                 if c["trim10_keep_pct_of_mean"] is not None
                 and abs(c["trim10_keep_pct_of_mean"]) < 50.0]),
            "median_flips_sign": len(
                [c for c in live
                 if (c["median_bp"] or 0.0) * (c["mean_bp"] or 0.0) < 0]),
            "top3_over_half_of_total_pct": len(
                [c for c in live
                 if c["concentration_top3"]
                 and c["concentration_top3"]["top_share_of_total_pct"] is not None
                 and abs(c["concentration_top3"]["top_share_of_total_pct"]) > 50.0]),
        }

    return {
        "study": "e85_robust_churn_estimators",
        "evidence_cutoff": cutoff,
        "spec": {
            "start": start, "pick_n": pick_n, "exclude_prefixes": list(exclude),
            "modes": list(modes), "mid_month_day": mid_day,
            "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
            "books": books,
            "estimators": ["mean", "median", "trimmed_mean_10pct"],
            "concentration": "sum of the 3 largest |value| transitions over the "
                             "cell signed total; >50% means three transitions "
                             "carry the cell",
            "universe_members": len(raw),
            "events_indexed": len(event_dates),
            "descriptive_only": "no prereg, no judgement, zero ledger booking",
        },
        "cells": cells,
        "delta_cells": delta_cells,
        "summary": {"levels": _tally(cells), "deltas": _tally(delta_cells)},
        "screen_reports": reports,
    }


# -------------------------------------------------------------- E91

def _top_transitions(rows, k=3):
    """The k largest |churn_alpha_bp| transitions of one cell, by name and date.

    E87 showed the two oldest eras have no centre of mass (top-3 carry 108-149%
    of the signed total). A share is not auditable, so this leg prints the
    window, the swapped names and the two side means that produced the number;
    the newest-era cells ride along as the control.
    """
    live = [r for r in (rows or []) if isinstance(r.get("churn_alpha_bp"), (int, float))]
    if not live:
        return []
    tot = sum(r["churn_alpha_bp"] for r in live)
    order = sorted(range(len(live)), key=lambda i: -abs(live[i]["churn_alpha_bp"]))[:k]
    out = []
    for i in order:
        r = live[i]
        ent, ext = r.get("entrant_fwd_pct"), r.get("exit_fwd_pct")
        side = None
        if isinstance(ent, (int, float)) and isinstance(ext, (int, float)):
            side = "entrants" if ent > ext else "exits"
        out.append({
            "date": r.get("date"), "next": r.get("next"),
            "churn_alpha_bp": r.get("churn_alpha_bp"),
            "share_of_signed_total_pct": (round(100.0 * r["churn_alpha_bp"] / tot, 1)
                                          if tot else None),
            "entrants": r.get("entrants"), "exits": r.get("exits"),
            "entrant_fwd_pct": ent, "exit_fwd_pct": ext,
            "carried_by": side,
            "entrant_names": (r.get("entrant_names") or [])[:10],
            "exit_names": (r.get("exit_names") or [])[:10],
        })
    return out


def run_topnames(outdir, start="2013-01-01", pick_n=9999, exclude=("sh511",),
                 modes=("neutralise_int", "neutralise", "drop"), mid_day=15,
                 eras=ERAS, top_k=3):
    """E91: make every concentrated churn cell auditable by name and date.

    Each (book, universe|mode, era) cell publishes its top-k transitions with
    the decision window, the swapped tickers, both side means and which side
    carried the sign, beside the plain cell mean. Nothing is re-estimated: rows
    are the same ``full_churn`` burn E82/E85/E86/E87 read.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    if exclude:
        raw = {s: v for s, v in raw.items() if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cal = [d for d in cal_full if d >= start]
    cutoff = cal[-1]

    universes = {"unscreened": raw}
    reports = {}
    for mode in modes:
        repaired, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)
        reports[mode] = report
        universes[mode] = repaired

    faces = {}
    for label, univ in universes.items():
        faces[label] = run_midmonth(outdir, start=start, pick_n=pick_n,
                                    exclude=exclude, mid_day=mid_day,
                                    raw=univ, full_churn=True)

    books = ["me", "mid%d" % mid_day]
    cells = []
    for book in books:
        for label in universes:
            rows = faces[label]["books"][book]["churn_rows"]
            for name, _lo, _hi in eras:
                sub = [r for r in rows if r.get("era") == name
                       and isinstance(r.get("churn_alpha_bp"), (int, float))]
                if not sub:
                    continue
                vals = [r["churn_alpha_bp"] for r in sub]
                mean = sum(vals) / len(vals)
                top = _top_transitions(sub, top_k)
                top_sum = sum(t["churn_alpha_bp"] for t in top)
                cells.append({
                    "book": book, "universe": label, "era": name,
                    "transitions": len(sub),
                    "mean_bp": round(mean, 1),
                    "top_k": top,
                    "top_k_share_of_signed_total_pct":
                        (round(100.0 * top_sum / sum(vals), 1) if sum(vals) else None),
                    "top1_is_more_than_half": (abs(top[0]["churn_alpha_bp"])
                                               > abs(mean) * len(sub) * 0.5
                                               if top else None),
                })

    def _tally(rows):
        shar = [c["top_k_share_of_signed_total_pct"] for c in rows
                if c["top_k_share_of_signed_total_pct"] is not None]
        return {
            "cells": len(rows),
            "cells_with_top3_over_half_pct": len([s for s in shar if abs(s) > 50.0]),
            "cells_named": len([c for c in rows if c["top_k"]]),
        }

    return {
        "study": "e91_top_churn_transition_names",
        "evidence_cutoff": cutoff,
        "spec": {
            "start": start, "pick_n": pick_n, "exclude_prefixes": list(exclude),
            "modes": list(modes), "mid_month_day": mid_day, "top_k": top_k,
            "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
            "books": books,
            "names_truncated_to": 10,
            "descriptive_only": "no prereg, no judgement, zero ledger booking",
            "universe_members": len(raw),
        },
        "cells": cells,
        "summary": _tally(cells),
        "screen_reports": reports,
    }


# -------------------------------------------------------------- E86

def _loo_means(vals):
    """Every leave-one-out mean of one cell: ``(n*m - a_i)/(n-1)``.

    E83 reports only ``argmin |mean_without|``; E86 asks what the WHOLE
    removal distribution looks like, so each cell's answer is the spread of
    all n leave-one-out re-reads, not its worst member.
    """
    clean = [float(v) for v in vals if isinstance(v, (int, float))]
    n = len(clean)
    if n < 2:
        return []
    tot = sum(clean)
    return [(tot - a) / (n - 1) for a in clean]


def _breakdown_k(vals, target_frac=0.5):
    """How many transitions must be removed before |mean| falls to target_frac.

    Greedy removal of the transition farthest from the current mean (the same
    "most influential" rule E83 applies once, iterated). k is the count of
    removals, ``share_of_transitions_pct`` its size relative to the cell, and
    ``path_bp`` records the mean after each removal so a reader can see whether
    the collapse is stepwise or one cliff.
    """
    clean = [float(v) for v in vals if isinstance(v, (int, float))]
    n = len(clean)
    if n < 2:
        return {"k": None, "n": n, "share_of_transitions_pct": None,
                "mean_after_bp": None, "path_bp": []}
    m0 = sum(clean) / n
    rest = list(clean)
    k = 0
    path = []
    while len(rest) > 1:
        cur = sum(rest) / len(rest)
        idx = max(range(len(rest)), key=lambda i: abs(rest[i] - cur))
        rest.pop(idx)
        k += 1
        cur = sum(rest) / len(rest)
        path.append(round(cur, 1))
        if abs(cur) <= abs(m0) * target_frac:
            return {"k": k, "n": n,
                    "share_of_transitions_pct": round(100.0 * k / n, 1),
                    "mean_after_bp": round(cur, 1), "path_bp": path}
    return {"k": None, "n": n, "share_of_transitions_pct": None,
            "mean_after_bp": round(rest[0], 1), "path_bp": path}


def _loo_stats(vals):
    """E86: the leave-one-out distribution of one cell plus its breakdown k."""
    clean = [float(v) for v in vals if isinstance(v, (int, float))]
    n = len(clean)
    if n < 2:
        return {"n": n, "loo_available": False, "mean_bp": (round(clean[0], 1)
                                                            if clean else None)}
    m = sum(clean) / n
    s = sorted(_loo_means(clean))

    def q(p):
        i = min(len(s) - 1, max(0, int(round(p * (len(s) - 1)))))
        return round(s[i], 1)

    half = abs(m) * 0.5
    kill = len([x for x in s if abs(x) < half])
    flip = len([x for x in s if x * m < 0])
    return {
        "n": n, "loo_available": True, "mean_bp": round(m, 1),
        "loo_min_bp": round(s[0], 1), "loo_p10_bp": q(0.10),
        "loo_median_bp": q(0.50), "loo_p90_bp": q(0.90),
        "loo_max_bp": round(s[-1], 1),
        "loo_kills_half_count": kill,
        "loo_kills_half_pct": round(100.0 * kill / n, 1),
        "loo_flips_sign_count": flip,
        "loo_flips_sign_pct": round(100.0 * flip / n, 1),
        "breakdown": _breakdown_k(clean),
    }


def run_loodist(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",),
                modes=("neutralise_int", "neutralise", "drop"), mid_day=15,
                eras=ERAS):
    """E86: how wide is a churn cell -- every removal, and the breakdown count.

    E83 asked "does removing ONE transition kill the cell". This leg answers the
    size question that leaves open: over all n removals, how many kill it, how
    wide is the leave-one-out spread, and how many removals (k, greedily) are
    needed before the magnitude halves. A cell that dies on 1 of 27 removals is
    a different object from a cell that dies on 20 of 27, though E83's flag is
    identical for both.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    if exclude:
        raw = {s: v for s, v in raw.items() if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cal = [d for d in cal_full if d >= start]
    cutoff = cal[-1]
    event_dates = _event_dates(raw, cal_full)

    universes = {"unscreened": raw}
    reports = {}
    for mode in modes:
        repaired, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)
        reports[mode] = report
        universes[mode] = repaired

    faces = {}
    for label, univ in universes.items():
        faces[label] = run_midmonth(outdir, start=start, pick_n=pick_n,
                                    exclude=exclude, mid_day=mid_day,
                                    raw=univ, full_churn=True)

    books = ["me", "mid%d" % mid_day]
    cells, gap_cells = [], []
    for book in books:
        base_rows = faces["unscreened"]["books"][book]["churn_rows"]
        for label in universes:
            rows = (base_rows if label == "unscreened"
                    else faces[label]["books"][book]["churn_rows"])
            for name, _lo, _hi in eras:
                sub = [r["churn_alpha_bp"] for r in rows if r.get("era") == name]
                st = _loo_stats(sub)
                if not st["n"]:
                    continue
                cells.append({"book": book, "universe": label, "era": name,
                              "face": "churn_alpha_bp", **st})

    mid_book = "mid%d" % mid_day
    me_rows = faces["unscreened"]["books"]["me"]["churn_rows"]
    mid_rows = faces["unscreened"]["books"][mid_book]["churn_rows"]
    for name, _lo, _hi in eras:
        a = [r["churn_alpha_bp"] for r in me_rows if r.get("era") == name]
        b = [r["churn_alpha_bp"] for r in mid_rows if r.get("era") == name]
        a = [v for v in a if isinstance(v, (int, float))]
        b = [v for v in b if isinstance(v, (int, float))]
        if not a or not b:
            continue
        ma, mb = sum(a) / len(a), sum(b) / len(b)
        gap = mb - ma
        me_loo = [mb - x for x in _loo_means(a)]
        mid_loo = [x - ma for x in _loo_means(b)]
        both = sorted(round(x, 1) for x in me_loo + mid_loo)
        half = abs(gap) * 0.5
        gap_cells.append({
            "book": "%s-me" % mid_book, "universe": "unscreened", "era": name,
            "face": "churn_alpha_gap_bp",
            "n_me": len(a), "n_mid": len(b), "gap_bp": round(gap, 1),
            "loo_both_min_bp": both[0] if both else None,
            "loo_both_median_bp": (both[len(both) // 2] if both else None),
            "loo_both_max_bp": both[-1] if both else None,
            "loo_both_kills_half_count": len([x for x in both if abs(x) < half]),
            "loo_both_flips_sign_count": len([x for x in both if x * gap < 0]),
            "loo_draws": len(both),
        })

    live = [c for c in cells if c.get("loo_available")]
    ks = [c["breakdown"]["k"] for c in live if c["breakdown"]["k"] is not None]
    shares = [c["breakdown"]["share_of_transitions_pct"] for c in live
              if c["breakdown"]["share_of_transitions_pct"] is not None]
    return {
        "study": "e86_loo_distribution",
        "evidence_cutoff": cutoff,
        "spec": {
            "start": start, "pick_n": pick_n, "exclude_prefixes": list(exclude),
            "modes": list(modes), "mid_month_day": mid_day,
            "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
            "books": books,
            "loo": "all n leave-one-out re-reads of each cell, (n*m - a_i)/(n-1)",
            "breakdown": "greedy removal of the transition farthest from the "
                         "current mean, repeated until |mean| <= 50% of the "
                         "original |mean|",
            "descriptive_only": "no prereg, no judgement, zero ledger booking",
        },
        "cells": cells,
        "gap_cells": gap_cells,
        "summary": {
            "level_cells": len(cells),
            "level_cells_with_loo": len(live),
            "cells_dying_on_one_removal": len(
                [c for c in live if c["loo_kills_half_count"] >= 1]),
            "cells_where_one_removal_is_under_10pct_of_removals": len(
                [c for c in live if c["loo_kills_half_pct"] < 10.0]),
            "cells_where_majority_of_removals_kill": len(
                [c for c in live if c["loo_kills_half_pct"] > 50.0]),
            "breakdown_k_median": (sorted(ks)[len(ks) // 2] if ks else None),
            "breakdown_share_pct_median": (sorted(shares)[len(shares) // 2]
                                           if shares else None),
            "gap_cells": len(gap_cells),
        },
        "screen_reports": reports,
    }


# -------------------------------------------------------------- E89

def _sd(vals):
    """Sample standard deviation (ddof=1); None for fewer than two points."""
    import math

    n = len(vals)
    if n < 2:
        return None
    m = sum(vals) / n
    return math.sqrt(sum((x - m) ** 2 for x in vals) / (n - 1))


def _jackknife_mean(vals):
    """Closed-form jackknife standard error of one cell mean.

    For the mean the jackknife reduces to the textbook standard error
    ``sqrt(sum (x_i - m)^2 / (n*(n-1)))``, so a cell's sampling noise is priced
    from the alphas already in memory -- no resampling, no second burn.
    """
    import math

    clean = [float(v) for v in vals if isinstance(v, (int, float))]
    n = len(clean)
    if n < 2:
        return {"n": n, "mean_bp": (round(clean[0], 1) if clean else None),
                "jk_se_bp": None, "jk_lo90_bp": None, "jk_hi90_bp": None,
                "jk_available": False}
    m = sum(clean) / n
    ss = sum((x - m) ** 2 for x in clean)
    se = math.sqrt(ss / (n * (n - 1)))
    return {"n": n, "mean_bp": round(m, 1), "jk_se_bp": round(se, 2),
            "jk_lo90_bp": round(m - 1.6449 * se, 1),
            "jk_hi90_bp": round(m + 1.6449 * se, 1),
            "jk_available": True}


def _boot_mean_ci(vals, draws=2000, seed=20261022):
    """Seeded percentile bootstrap of one cell mean (reproducible by seed).

    A fixed seed plus a stable draw order makes the face bit-reproducible; the
    point estimate stays the plain mean, so the interval is an ADDED column and
    never a replacement for a published number.
    """
    import math
    import random

    clean = [float(v) for v in vals if isinstance(v, (int, float))]
    n = len(clean)
    if n < 2:
        return {"boot_available": False, "draws": 0, "boot_p05_bp": None,
                "boot_p95_bp": None, "boot_ci_straddles_zero": None,
                "boot_signflip_pct": None, "boot_se_bp": None}
    rng = random.Random(seed)
    means = []
    for _ in range(draws):
        means.append(sum(clean[rng.randrange(n)] for _ in range(n)) / n)
    means.sort()
    m = sum(clean) / n

    def q(p):
        i = min(len(means) - 1, max(0, int(round(p * (len(means) - 1)))))
        return round(means[i], 1)

    lo, hi = q(0.05), q(0.95)
    cross = len(means) if m == 0 else len([x for x in means if x * m < 0])
    return {"boot_available": True, "draws": draws, "seed": seed,
            "boot_p05_bp": lo, "boot_p95_bp": hi,
            "boot_ci_straddles_zero": bool(lo <= 0.0 <= hi),
            "boot_signflip_pct": round(100.0 * cross / len(means), 1),
            "boot_se_bp": round(_sd(means), 2)}


def _gap_interval(a, b, draws=2000, seed=20261022):
    """Interval for ``mean(b) - mean(a)`` with the two books resampled apart.

    The books are separate transition populations, so their standard errors add
    in quadrature; the bootstrap draws each side independently from the same
    seed, keeping the whole face reproducible.
    """
    import math
    import random

    ca = [float(v) for v in a if isinstance(v, (int, float))]
    cb = [float(v) for v in b if isinstance(v, (int, float))]
    na, nb = len(ca), len(cb)
    if na < 2 or nb < 2:
        return {"n_me": na, "n_mid": nb, "gap_bp": None,
                "gap_available": False, "jk_available": False,
                "jk_se_bp": None, "jk_lo90_bp": None,
                "jk_hi90_bp": None, "boot_p05_bp": None, "boot_p95_bp": None,
                "boot_ci_straddles_zero": None, "boot_signflip_pct": None}
    ma, mb = sum(ca) / na, sum(cb) / nb
    gap = mb - ma
    sea, seb = _sd(ca) / math.sqrt(na), _sd(cb) / math.sqrt(nb)
    se = math.sqrt(sea * sea + seb * seb)
    rng = random.Random(seed)
    diffs = []
    for _ in range(draws):
        sa = sum(ca[rng.randrange(na)] for _ in range(na)) / na
        sb = sum(cb[rng.randrange(nb)] for _ in range(nb)) / nb
        diffs.append(sb - sa)
    diffs.sort()

    def q(p):
        i = min(len(diffs) - 1, max(0, int(round(p * (len(diffs) - 1)))))
        return round(diffs[i], 1)

    lo, hi = q(0.05), q(0.95)
    cross = len(diffs) if gap == 0 else len([x for x in diffs if x * gap < 0])
    return {"n_me": na, "n_mid": nb, "gap_bp": round(gap, 1),
            "gap_available": True, "jk_available": True,
            "jk_se_bp": round(se, 2),
            "jk_lo90_bp": round(gap - 1.6449 * se, 1),
            "jk_hi90_bp": round(gap + 1.6449 * se, 1),
            "boot_p05_bp": lo, "boot_p95_bp": hi,
            "boot_ci_straddles_zero": bool(lo <= 0.0 <= hi),
            "boot_signflip_pct": round(100.0 * cross / len(diffs), 1),
            "interval_clears_zero": bool(
                (gap - 1.6449 * se) * (gap + 1.6449 * se) > 0)}


def run_churnse(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",),
                modes=("neutralise_int", "neutralise", "drop"), mid_day=15,
                eras=ERAS, draws=2000, seed=20261022):
    """E89: a sampling interval beside every churn cell and churn gap.

    Every published churn number is a point estimate over 25-29 transitions, so
    a reader cannot separate "+318.8bp" from zero. This leg adds, on the same
    burn, a closed-form jackknife standard error and a seeded percentile
    bootstrap (fixed seed recorded in the spec) beside each mean, plus the share
    of resamples whose sign differs from the point estimate. The mean column is
    untouched: the interval is an extra face, never a revision.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    if exclude:
        raw = {s: v for s, v in raw.items() if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cal = [d for d in cal_full if d >= start]
    cutoff = cal[-1]
    event_dates = _event_dates(raw, cal_full)

    universes = {"unscreened": raw}
    reports = {}
    for mode in modes:
        repaired, report = panel_screen.screen_universe(raw, mode=mode, cal=cal_full)
        reports[mode] = report
        universes[mode] = repaired

    faces = {}
    for label, univ in universes.items():
        faces[label] = run_midmonth(outdir, start=start, pick_n=pick_n,
                                    exclude=exclude, mid_day=mid_day,
                                    raw=univ, full_churn=True)

    books = ["me", "mid%d" % mid_day]
    cells, delta_cells = [], []
    for book in books:
        base_rows = faces["unscreened"]["books"][book]["churn_rows"]
        for label in universes:
            rows = (base_rows if label == "unscreened"
                    else faces[label]["books"][book]["churn_rows"])
            for name, _lo, _hi in eras:
                sub = [r["churn_alpha_bp"] for r in rows if r.get("era") == name]
                jk = _jackknife_mean(sub)
                if not jk["n"]:
                    continue
                bt = _boot_mean_ci(sub, draws=draws, seed=seed)
                cells.append({"book": book, "universe": label, "era": name,
                              "face": "churn_alpha_bp", **jk, **bt,
                              "interval_clears_zero": (
                                  None if not jk["jk_available"] or not jk["mean_bp"]
                                  else bool(jk["jk_lo90_bp"] * jk["jk_hi90_bp"] > 0))})
        for mode in modes:
            rows, _agg = _churn_join(base_rows,
                                     faces[mode]["books"][book]["churn_rows"],
                                     event_dates, eras)
            for name, _lo, _hi in eras:
                sub = [r["delta_bp"] for r in rows if r["era"] == name]
                jk = _jackknife_mean(sub)
                if not jk["n"]:
                    continue
                bt = _boot_mean_ci(sub, draws=draws, seed=seed)
                delta_cells.append({"book": book, "mode": mode, "era": name,
                                    "face": "delta_bp", **jk, **bt,
                                    "interval_clears_zero": (
                                        None if not jk["jk_available"]
                                        or not jk["mean_bp"]
                                        else bool(jk["jk_lo90_bp"] * jk["jk_hi90_bp"] > 0))})

    mid_book = "mid%d" % mid_day
    me_rows = faces["unscreened"]["books"]["me"]["churn_rows"]
    mid_rows = faces["unscreened"]["books"][mid_book]["churn_rows"]
    gap_cells = []
    for name, _lo, _hi in eras:
        a = [r["churn_alpha_bp"] for r in me_rows if r.get("era") == name]
        b = [r["churn_alpha_bp"] for r in mid_rows if r.get("era") == name]
        g = _gap_interval(a, b, draws=draws, seed=seed)
        if not g["gap_available"]:
            continue
        gap_cells.append({"book": "%s-me" % mid_book, "universe": "unscreened",
                          "era": name, "face": "churn_alpha_gap_bp", **g})

    def _tally(rows):
        live = [c for c in rows if c.get("jk_available")]
        ses = [c["jk_se_bp"] for c in live if c["jk_se_bp"] is not None]
        return {
            "cells": len(rows),
            "cells_with_interval": len(live),
            "jk_interval_clears_zero": len(
                [c for c in live if c["interval_clears_zero"]]),
            "jk_interval_straddles_zero": len(
                [c for c in live if c["interval_clears_zero"] is False]),
            "boot_interval_clears_zero": len(
                [c for c in live if c["boot_ci_straddles_zero"] is False]),
            "boot_interval_straddles_zero": len(
                [c for c in live if c["boot_ci_straddles_zero"] is True]),
            "jk_se_bp_median": (sorted(ses)[len(ses) // 2] if ses else None),
            "mean_exceeds_own_se": len(
                [c for c in live
                 if c["jk_se_bp"] and (c.get("mean_bp") or c.get("gap_bp"))
                 and abs(c.get("mean_bp") or c.get("gap_bp")) > c["jk_se_bp"]]),
            "signflip_pct_median": (sorted(
                [c["boot_signflip_pct"] for c in live
                 if c["boot_signflip_pct"] is not None])[
                len([c for c in live if c["boot_signflip_pct"] is not None]) // 2]
                if live else None),
        }

    return {
        "study": "e89_churn_sampling_intervals",
        "evidence_cutoff": cutoff,
        "spec": {
            "start": start, "pick_n": pick_n, "exclude_prefixes": list(exclude),
            "modes": list(modes), "mid_month_day": mid_day,
            "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
            "books": books,
            "jackknife": "closed-form SE of a mean, "
                         "sqrt(sum (x_i-mean)^2 / (n*(n-1))); 90% band = "
                         "mean +/- 1.6449*SE",
            "bootstrap": "percentile bootstrap of the mean, %d draws, fixed "
                         "seed %d (reproducible by seed, no panel read)"
                         % (draws, seed),
            "gap_interval": "mid-minus-me, books resampled independently, "
                            "SEs added in quadrature; the two books decide on "
                            "different calendar dates (30 me vs 29 mid15 in "
                            "2021_2023) so nothing pairs date-to-date, but they "
                            "hold the same names over the same era, which makes "
                            "the true difference error SMALLER than this "
                            "quadrature band -- the gap band is conservative",
            "interval_meaning": "sampling noise of the transition sample only: "
                                "cells are monthly decisions on overlapping "
                                "holdings, not iid prints, so no significance "
                                "claim is made and no cell is called positive or "
                                "negative on the strength of its band",
            "descriptive_only": "no prereg, no judgement, zero ledger booking",
        },
        "cells": cells,
        "delta_cells": delta_cells,
        "gap_cells": gap_cells,
        "summary": {"levels": _tally(cells), "deltas": _tally(delta_cells),
                    "gaps": _tally(gap_cells)},
        "screen_reports": reports,
    }


# ------------------------------------------------ E92 gap-tolerant split screen

def _gap_print_census(raw, cal_full, limits=(1, 2, 5)):
    """E92: every gapped print the fixed adjacency rule leaves unrepaired.

    ``panel_screen`` screens a print only when it sits on the next session. E91
    found the 12:1 split that owns a published era gap sitting one *missing bar*
    away from its own previous close, i.e. inside that blind spot. This census
    lists the gapped prints per gap limit (in sessions) and keeps the integer
    share ratios separate from the rest, because only an integer ratio is
    evidence of a corporate action rather than a resumption misprint.
    """
    import panel_screen

    events = []
    for s in sorted(raw):
        pair = raw[s]
        closes = pair[0] if isinstance(pair, tuple) else pair
        for e in panel_screen.split_events(closes, cal=cal_full):
            if e["adjacent"]:
                continue
            im = e.get("implied") or {}
            events.append({
                "name": s, "date": e["date"], "prev_date": e["prev_date"],
                "gap_sessions": e["gap_sessions"],
                "ret_pct": round(e["ret_pct"], 2),
                "ratio": round(im.get("ratio", e["factor"]), 4),
                "nearest_int": im.get("nearest_int"),
                "resid_pct": (round(im["resid_pct"], 3) if im else None),
                "integer_like": bool(im.get("integer_like")),
                "era": _era_of(e["date"]),
            })

    census = {}
    for lim in limits:
        eligible = [e for e in events
                    if e["integer_like"] and e["gap_sessions"] <= lim]
        by_era = {}
        for name, _lo, _hi in ERAS:
            sub = [e for e in eligible if e["era"] == name]
            if sub:
                by_era[name] = len(sub)
        census["gap%d" % lim] = {
            "gap_limit_sessions": lim,
            "gapped_prints_total": len(events),
            "eligible_integer_prints": len(eligible),
            "eligible_names": len(set(e["name"] for e in eligible)),
            "eligible_by_era": by_era,
            "non_integer_gapped": len([e for e in events if not e["integer_like"]
                                       and e["gap_sessions"] <= lim]),
            "largest_eligible": sorted(eligible,
                                       key=lambda e: -abs(e["ret_pct"]))[:10],
        }
    return {"gapped_prints": len(events), "by_gap_limit": census,
            "events": events}


def run_gapsplit(outdir, start="2020-01-01", pick_n=9999, exclude=("sh511",),
                 limits=(1, 2, 5), mid_day=15, eras=ERAS):
    """E92: does the published churn gap survive a gap-tolerant split screen?

    E91 named the defect: sh510150's unadjusted 12:1 split lands behind a missing
    bar, so both screen arms leave it at +9424.4bp and it owns 2021_2023's churn
    gap. Here the screen is widened one session (then two, then five) and the
    churn gap is re-derived on the same burn, so the answer is measured rather
    than argued. The unscreened column is kept; no published face is rewritten.
    """
    import e24_ladder_weighting as base
    import e27_universe_expansion as e27
    import panel_screen

    raw = e27.load_universe()
    if exclude:
        raw = {s: v for s, v in raw.items() if not s.startswith(tuple(exclude))}
    cal_full = base.load_panel()[0]
    cal = [d for d in cal_full if d >= start]
    cutoff = cal[-1]
    event_dates = _event_dates(raw, cal_full)

    universes = {"unscreened": raw}
    reports = {}
    for lim in limits:
        label = "gap%d" % lim
        repaired, report = panel_screen.screen_universe(
            raw, mode="neutralise_gap", cal=cal_full, gap_limit=lim)
        reports[label] = report
        universes[label] = repaired

    faces = {}
    for label, univ in universes.items():
        faces[label] = run_midmonth(None, start=start, pick_n=pick_n,
                                    exclude=exclude,
                                    mid_day=mid_day, raw=univ,
                                    full_churn=True)

    data = {"study": "e92_gap_tolerant_split_screen",
            "evidence_cutoff": cutoff,
            "spec": {
                "start": start, "pick_n": pick_n,
                "exclude_prefixes": list(exclude),
                "gap_limits_sessions": list(limits), "mid_month_day": mid_day,
                "costs_run": [0.0, 1.0, 3.0],
                "screen_modes": ["unscreened", "neutralise_gap"],
                "why_costs": "the churn sleeve is a name-level mean over swapped "
                             "names and no cost multiplier can move it; the standard "
                             "triple is kept because run_midmonth publishes all three "
                             "arms and the era spread is read off the same burn",
                "eras": [{"name": n, "from": lo, "to": hi} for n, lo, hi in eras],
                "books": ["me", "mid%d" % mid_day],
                "universe_members": len(raw),
            },
            "census": _gap_print_census(raw, cal_full, limits),
            "screen_reports": reports,
            "honest": [
                "the gap-tolerant branch repairs only integer-ratio prints inside "
                "the session limit, so a real resumption that happens to land on an "
                "integer ratio would be repaired too -- the ratio test is evidence, "
                "not proof",
                "a wider gap limit buys more repairs and more false positives "
                "together; the sweep is published so the reader can see what each "
                "session costs",
                "churn sleeve is an equal-weight mean over the swapped names, not a "
                "portfolio return",
                "screen reports count repairs, not book impact: a repaired print "
                "still enters the rank cache at its adjusted level",
                "descriptive census only: no gate, no verdict, no prereg, no trial "
                "count",
            ]}

    book_labels = ["me", "mid%d" % mid_day]
    gaps = {}
    for era in [n for n, _lo, _hi in eras]:
        row = {}
        for label in universes:
            me = faces[label]["eras"].get(era, {}).get("me", {})
            mid = faces[label]["eras"].get(era, {}).get("mid", {})
            a, b = me.get("churn_alpha_bp_mean"), mid.get("churn_alpha_bp_mean")
            row[label] = {
                "me_churn_alpha_bp": a, "mid_churn_alpha_bp": b,
                "churn_gap_bp": (round(b - a, 1)
                                 if a is not None and b is not None else None),
            }
        base_gap = (row.get("unscreened") or {}).get("churn_gap_bp")
        for label in universes:
            g = row[label].get("churn_gap_bp")
            row[label]["delta_vs_unscreened_bp"] = (
                round(g - base_gap, 1)
                if isinstance(g, (int, float))
                and isinstance(base_gap, (int, float)) else None)
        gaps[era] = row
    data["churn_gap_by_era"] = gaps

    joins = {}
    for book in book_labels:
        base_rows = faces["unscreened"]["books"][book]["churn_rows"]
        joins[book] = {}
        for lim in limits:
            label = "gap%d" % lim
            rows, agg = _churn_join(base_rows,
                                    faces[label]["books"][book]["churn_rows"],
                                    event_dates, eras)
            moved = [r for r in rows if r.get("hit")
                     and isinstance(r.get("delta_bp"), (int, float))
                     and abs(r["delta_bp"]) > 0.5]
            joins[book][label] = {
                "eras": agg,
                "transitions": len(rows),
                "transitions_moved": len(moved),
                "top_moved": _worst_transitions(rows, n=6),
            }
    data["joins"] = joins
    return data


# ------------------------------------------------------------------- plumbing

# (E111) a face's LEVEL is produced by panel_screen's repair code, so two faces
# are comparable only when that code is the same. E110 burned this lesson: a
# pre-E108 face joined against a post-E108 one and the difference was reported
# as a defect. The cutoff was stamped; the code version was not.
REPAIR_FACTOR_KEY = "repair_factor"


def _stamp_repair_factor(payload):
    """Put the repair-factor id on a face this module is about to write."""
    if isinstance(payload, dict) and not payload.get(REPAIR_FACTOR_KEY):
        try:
            import panel_screen
            payload[REPAIR_FACTOR_KEY] = panel_screen.repair_factor_id()
            payload["repair_factor_src"] = "+".join(panel_screen.REPAIR_FACTOR_SRC)
        except Exception as exc:      # a burn is never failed over its stamp
            payload["repair_factor_error"] = repr(exc)
    return payload


def write_json(outdir, name, payload):
    os.makedirs(outdir, exist_ok=True)
    p = os.path.join(outdir, name)
    payload = _stamp_repair_factor(payload)
    with open(p, "w", encoding="utf-8", newline="\n") as fh:
        json.dump(payload, fh, ensure_ascii=False, indent=1)
        fh.write("\n")
    return p


def selftest():
    ok = tot = 0
    def chk(cond, label):
        nonlocal ok, tot
        tot += 1
        if cond:
            ok += 1
        else:
            print("FAIL %s" % label)

    # risk profile on a known path: 1.0 -> 1.20 -> 0.90 -> 1.30
    curve = [("2020-01-02", 1.0), ("2020-02-03", 1.10), ("2020-02-28", 1.20),
             ("2020-03-31", 0.90), ("2020-04-30", 1.30)]
    prof = risk_profile(curve, 0.5)
    chk(prof["max_drawdown_pct"] == -25.0, "max dd 1.20 -> 0.90 is -25%")
    chk(prof["worst_month"]["month"] == "2020-03", "worst month is the -25% month")
    chk(prof["best_month"]["month"] == "2020-04", "best month is the +44% month")
    chk(prof["longest_underwater_sessions"] == 1, "one session underwater before the new high")
    chk(prof["negative_months"] == 1, "March is the only negative month on the mark set")

    # classification table
    cal = ["2026-09-%02d" % d for d in range(1, 22)]
    dead = [{"date": "2026-09-01", "close": 1.0, "volume": 0.0, "amount": 0.0},
            {"date": "2026-09-02", "close": 1.0, "volume": 0.0, "amount": 0.0}]
    chk(classify_stale("sh999999.csv", dead, cal, cal[-1])["class"] == "DEAD_LISTING",
        "zero-turnover tail reads dead")
    live = [{"date": "2026-09-%02d" % d, "close": 1.0, "volume": 1000.0, "amount": 2000.0}
            for d in (1, 2, 3, 4)]
    chk(classify_stale("sh512390.csv", live, cal, cal[-1])["class"] == "SOURCE_SIDE_GAP",
        "traded tail before the bulk date reads source-side gap")
    at_bulk = [{"date": "2026-09-%02d" % d, "close": 1.0, "volume": 1000.0, "amount": 2000.0}
               for d in (20, 21, 22)]
    chk(classify_stale("sh500000.csv", at_bulk, cal, cal[-1])["class"] == "REFRESH_FAILURE",
        "tail ending on the bulk date reads refresh failure")
    chk(classify_stale("510880_t73.csv", live, cal, cal[-1])["class"] == "PINNED_SLOT_COPY",
        "tagged filename reads pinned copy")

    # month-end collapse keeps the last mark of each month
    me = _month_ends([("2020-01-02", 1.0), ("2020-01-31", 2.0), ("2020-02-03", 3.0)])
    chk(me == [("2020-01-31", 2.0), ("2020-02-03", 3.0)], "month-end collapse")

    # pair leg: a ratio curve carries the spread's own drawdown, not the legs'
    lad = [("2020-01-02", 1.0), ("2020-02-03", 0.80), ("2020-03-31", 1.0)]
    wide = [("2020-01-02", 1.0), ("2020-02-03", 0.72), ("2020-03-31", 1.0)]
    lm = dict(lad)
    ratio = [(d, v / lm[d]) for d, v in wide if d in lm and lm[d] > 0]
    chk(risk_profile(lad, 0.25)["max_drawdown_pct"] == -20.0, "ladder leg dd -20%")
    chk(risk_profile(wide, 0.25)["max_drawdown_pct"] == -28.0, "wide leg dd -28%")
    chk(risk_profile(ratio, 0.25)["max_drawdown_pct"] == -10.0,
        "ratio curve dd is the spread (-10%), not either leg")

    # cash-leg scaling: None stays the zero-cash convention, x0 empties the series
    chk(_scale_cash(None, 2.0) is None, "no cash panel stays no cash panel")
    sc = _scale_cash({"series": {"2020-01-02": 0.001}}, 3.0)
    chk(abs(sc["series"]["2020-01-02"] - 0.003) < 1e-15, "multiplier scales daily returns")
    chk(_scale_cash({"series": {"2020-01-02": 0.001}}, 0.0)["series"] == {},
        "x0 empties the series so the engine reads 0.0")
    chk(_scale_cash({"series": {}}, 1.0)["series"] == {}, "empty series survives scaling")

    # cash attribution arithmetic on a synthetic table
    rows = {"x0": {"ann_return_pct": -0.43}, "x1": {"ann_return_pct": 0.12}}
    chk(round((rows["x1"]["ann_return_pct"] - rows["x0"]["ann_return_pct"]) * 100, 2) == 55.0,
        "attribution is the ann column difference in bp")

    # size tilt legs: month marks, the 2/5+3/5 identity, and the spread in bp
    mr = _month_rets([("2020-01-31", 1.0), ("2020-02-28", 1.1), ("2020-03-31", 1.21)])
    chk(len(mr) == 2 and abs(mr[0][1] - 0.10) < 1e-12 and mr[1][0] == "2020-03",
        "month returns come off month-end marks")
    chk(abs((0.4 * 0.01 + 0.6 * 0.03) - 0.022) < 1e-12,
        "equal-weight ladder month decomposes into 2/5 large + 3/5 small")
    chk(abs((0.03 - 0.01) * 1e4 - 200.0) < 1e-9,
        "tilt spread is the large-vs-small monthly gap in bp")
    mom = _moments([0.01, 0.03, 0.05])
    chk(abs(mom["mean"] - 0.03) < 1e-12 and abs(mom["sd"] - 0.02) < 1e-9,
        "sample moments use the n-1 denominator")
    mem_raw = {"shX": ({"2020-01-31": 1.0, "2020-02-28": 1.2, "2020-03-31": 0.9}, {})}
    mem = _member_monthly(["2020-01-31", "2020-02-28", "2020-03-31"], "shX", mem_raw)
    chk(abs(mem["2020-02"] - 0.2) < 1e-12 and abs(mem["2020-03"] + 0.25) < 1e-12,
        "member monthly returns read their own month-end closes")

    # rebalance-day shift: clamping, dedupe, and the mid-month pick
    chk(_shift_indices([0, 5, 9], -1, 10) == [0, 4, 8], "shift -1 clamps at index 0")
    chk(_shift_indices([8, 9], 1, 10) == [9], "shift +1 clamps and dedupes at the last bar")
    chk(_shift_indices([3], 0, 10) == [3], "zero shift is the identity")
    cal_mid = ["2020-01-02", "2020-01-15", "2020-01-31",
               "2020-02-03", "2020-02-14", "2020-02-28"]
    chk(_mid_month_indices(cal_mid, 15) == [1, 5],
        "mid-month picks the first session on/after the 15th, once per month")
    chk(_mid_month_indices(cal_mid, 1) == [0, 3],
        "mid-month day 1 reads as the first session of each month")
    chk(_shift_indices(_mid_month_indices(cal_mid, 15), -1, len(cal_mid)) == [0, 4],
        "shifting the mid-month set moves every decision one session earlier")

    # E42: era slicing, OLS recovery, and the additive spread identity
    chk(_in_era("2016-12", None, "2016-12-31") and not _in_era("2017-01", None, "2016-12-31"),
        "era upper bound is inclusive on its month")
    chk(_in_era("2017-01", "2017-01-01", "2020-12-31") and not _in_era("2021-01", "2017-01-01", "2020-12-31"),
        "era lower bound is inclusive and the next year is out")
    chk(_in_era("2024-03", "2024-01-01", None), "open-ended era has no upper bound")
    xs = [-0.02, -0.01, 0.0, 0.01, 0.02]
    ys = [0.02 + 2.0 * x for x in xs]
    b, a, r2 = _ols(ys, xs)
    chk(abs(b - 2.0) < 1e-12 and abs(a - 0.02) < 1e-12 and abs(r2 - 1.0) < 1e-12,
        "OLS recovers beta/alpha/R2 on an exact linear series")
    chk(_ols([0.1, 0.2], [0.1, 0.2]) == (None, None, None), "fewer than 3 points is undetermined")
    chk(_ols([0.1, 0.1, 0.1], [0.01, 0.02, 0.03]) == (None, None, None),
        "a flat y has no slope to estimate")
    raw = 95.0
    neutral, size_part = 120.0, -25.0
    chk(abs((neutral + size_part) - raw) < 1e-12,
        "additive identity: raw spread = size-neutral intercept + size component")

    # E43: four-member skin is a strict subset, and the tilt builder drops only the
    # months a leg cannot be priced on
    chk(set(TILT4_SMALL) < set(TILT_SMALL) and len(TILT4_SMALL) == 2,
        "four-member small leg is a two-name subset of the five-member skin")
    chk(abs((2 / 4.0) - 0.5) < 1e-12 and abs((2 / 4.0 + 2 / 4.0) - 1.0) < 1e-12,
        "four-member skin weights 0.5/0.5 so the identity still closes")
    f_mem = {"L1": {"m1": 0.01, "m2": 0.01}, "L2": {"m1": 0.01},
             "S1": {"m1": 0.03, "m2": 0.05}, "S2": {"m1": 0.03}}
    f_brk = {"L1": set(), "L2": set(), "S1": set(), "S2": {"m2"}}
    used, tilts, drops = _tilt_series(f_mem, f_brk, ["m1", "m2", "m3"],
                                      ("L1", "L2"), ("S1", "S2"))
    chk(used == ["m1", "m2"], "tilt builder keeps only months both legs can price")
    chk(abs(tilts["m1"] - 0.02) < 1e-12, "two-name legs average before the spread")
    chk(abs(tilts["m2"] - 0.04) < 1e-12,
        "a broken member drops out of the leg mean, it does not drop the month")
    chk(len(drops) == 1 and drops[0]["month"] == "m3"
        and "S1" in drops[0]["members_missing"],
        "an unpriced month is disclosed, never silently averaged")
    comp = _compose_counts(["sh510300", "sh510500", "sh512880"], TILT_LARGE, TILT_SMALL)
    chk(comp["n"] == 3 and comp["ladder_small_names"] == 1
        and comp["ladder_large_names"] == 1 and comp["other_weight_pct"] == round(100 / 3.0, 4),
        "composition counts split holdings into ladder small / ladder large / other")
    chk(_compose_counts([], TILT_LARGE, TILT_SMALL) == {"n": 0},
        "an empty book has no composition to report")

    # E44: every leave-one-out skin drops exactly one member and keeps both legs alive
    lg5, sm5 = _skin_sets(None)
    chk(lg5 == TILT_LARGE and sm5 == TILT_SMALL,
        "the full skin is the untouched five-member set")
    lg4, sm4 = _skin_sets("sh588000")
    chk(lg4 == TILT_LARGE and sm4 == TILT4_SMALL,
        "dropping STAR reproduces the E43 four-member skin exactly")
    lg1, sm1 = _skin_sets("sh510050")
    chk(len(lg1) == 1 and sm1 == TILT_SMALL,
        "dropping a large-cap leaves a one-name large leg, not an empty one")
    chk(all(_skin_sets(d)[0] and _skin_sets(d)[1] for d in (TILT_LARGE + TILT_SMALL)),
        "no single-member drop empties either size leg")

    # E44 burn-in: the gate is window-relative, and the arrival index is the
    # first bar whose trailing window is fully priced (a gap restarts the run)
    chk(_first_eligible_idx([None] * 10, 3) is None,
        "a series with no priced closes never becomes eligible")
    chk(_first_eligible_idx([1.0] * 300, 250) == 249,
        "a fully priced series clears the 250-bar gate on its 250th bar")
    gap = [1.0] * 249 + [None] + [1.0] * 250
    chk(_first_eligible_idx(gap, 250) == 499,
        "a single missing close restarts the burn-in inside the window")
    chk(_first_eligible_idx([None] * 100 + [1.0] * 250, 250) == 349,
        "eligibility is window-relative: the first 100 sessions are dead for everyone")
    # annual chaining off month-end marks
    chk(_annual_rets([("2020-12-31", 1.0), ("2021-12-31", 1.10),
                      ("2022-12-31", 0.99)]) == {"2021": 10.0, "2022": -10.0},
        "annual returns chain each year off the prior year-end mark")
    chk(_annual_rets([("2021-06-30", 2.0)]) == {}, 
        "a single year has no prior close to chain from")

    # E45 warm vs cold: dead-block counting, slice faces, spread arithmetic
    cur = [("2020-01-02", 1.0), ("2020-01-03", 1.1), ("2020-02-03", 1.2)]
    chk(_bars_before(cur, "2020-02-03") == 2, "bars before a date excludes the date itself")
    chk(_bars_before(cur, None) == 0, "an unknown first-invested date counts no dead bars")
    chk(_bars_before(cur, "2019-01-01") == 0, "a date before the curve counts nothing")
    chk(_curve_faces(cur[:2]) is None, "a slice under 3 bars has no annualised face")
    face = _curve_faces(cur)
    chk(face["bars"] == 3 and face["from"] == "2020-01-02" and face["ann_return_pct"] > 0,
        "a 3-bar slice reports from/to/bars/ann")
    chk(_curve_faces(cur)["ann_return_pct"] == _curve_faces(cur)["ann_return_pct"],
        "the face is deterministic on the same slice")
    chk(_spread_bp({"ann_return_pct": 1.0}, {"ann_return_pct": 2.5}) == 150.0,
        "spread is the wide-minus-ladder ann gap in bp")
    chk(_spread_bp(None, {"ann_return_pct": 2.5}) is None,
        "a missing leg has no spread")
    csh = {"series": {"2020-01-02": 0.001, "2020-01-03": 0.001, "2020-02-03": 0.001}}
    ccal = [d for d, _v in cur]
    chk(abs(_cash_accrual_pct(csh, ccal, "2020-02-03") - 0.2) < 1e-9,
        "cash accrual compounds the daily repo returns before the first invested bar")
    chk(_cash_accrual_pct(None, ccal, "2020-02-03") == 0.0,
        "no cash panel accrues nothing")
    chk(_cash_accrual_pct(csh, ccal, None) == 0.0,
        "a book with no first-invested bar accrues nothing")

    # E46 era splitting: contiguous halves that keep the whole slice
    spl = _split_curve([("d%d" % i, 1.0 + i) for i in range(10)], 2)
    chk([len(s) for s in spl] == [5, 5], "two parts of ten bars split five and five")
    chk(spl[0][0][0] == "d0" and spl[-1][-1][0] == "d9",
        "the split keeps the first and last bar of the slice")
    chk(_split_curve([("d%d" % i, 1.0) for i in range(3)], 2) == [],
        "a slice too short to split is refused, not half-split")

    # E58 cut roll-up: flip set, band stats and dead parts are read per cut
    fake = {"A": {"part_spreads_bp": [10.0, -20.0, 0.0], "part_band_bp": 30.0,
                  "sign_flips_inside_era": True, "widest_part": 1,
                  "parts": [{"part": 1, "from": "2020-01-01", "to": "2020-02-01"},
                            {"part": 2, "from": "2020-02-02", "to": "2020-03-01"}]},
            "B": {"part_spreads_bp": [5.0, 7.0], "part_band_bp": 2.0,
                  "sign_flips_inside_era": False, "widest_part": 2,
                  "parts": [{"part": 1, "from": "2020-01-01", "to": "2020-02-01"},
                            {"part": 2, "from": "2020-02-02", "to": "2020-03-01"}]}}
    cup = _cut_summary(fake)
    chk(cup["flip_count"] == 1 and cup["eras_flipping"] == ["A"],
        "cut summary names exactly the eras that flip")
    chk(cup["bands_bp"] == {"A": 30.0, "B": 2.0} and cup["band_widest_era"] == "A",
        "cut summary keeps the per-era band and the widest era")
    chk(cup["band_mean_bp"] == 16.0 and cup["band_median_bp"] == 16.0,
        "band mean and median agree on a two-era cut")
    chk(cup["zero_spread_parts_by_era"] == {"A": 1},
        "a part with spread exactly 0 is counted as a dead band slot")
    chk(_widest_window(fake["A"]) == "2020-01-01..2020-02-01",
        "the widest part is reported with the window of that cut")
    chk(_widest_window({"widest_part": 9, "parts": []}) is None,
        "a missing widest part reports no window instead of guessing one")

    # E44 churn sleeve: identical books swap nothing
    ccal = ["2020-01-%02d" % d for d in (2, 3, 6, 7)]
    cpx = {"a": [1.0, 1.0, 1.0, 1.0], "b": [1.0, 1.0, 1.0, 1.0]}
    same = [(1, ["a", "b"]), (3, ["a", "b"])]
    rows, agg = _churn_stats(ccal, cpx, same)
    chk(len(rows) == 1 and rows[0]["entrants"] == 0 and rows[0]["churn_alpha_bp"] is None,
        "identical consecutive books produce no churn and no churn alpha")
    chk(agg == {}, "a book that never swaps contributes no era aggregate")

    # one-in one-out with known forward returns: alpha == entrant minus exit
    swap = [(1, ["a"]), (3, ["b"])]
    cpx2 = {"a": [1.0, 1.0, 2.0, 1.1], "b": [1.0, 1.0, 2.0, 0.9]}
    rows2, agg2 = _churn_stats(ccal, cpx2, swap)
    chk(rows2[0]["entrants"] == 1 and rows2[0]["exits"] == 1,
        "a full swap reports one entrant and one exit")
    chk(abs(rows2[0]["churn_alpha_bp"] - (-2000.0)) < 1e-9,
        "churn alpha is entrant forward return minus exit forward return in bp "
        "(-10%% entrant vs +10%% exit -> -2000bp)")

    # E57: the other calendar's next book decides the bucket, and the "next"
    # decision is strictly after the one being classified
    dec = [(0, ["a"]), (5, ["a", "b"]), (9, ["b", "c"])]
    chk(_next_decision_idx(dec, 0) == 1, "next decision skips a same-session twin")
    chk(_next_decision_idx(dec, 5) == 2 and _next_decision_idx(dec, 9) is None,
        "next decision is strictly after the bar index")
    bk = _classify_entrants(["a", "b", "c", "d"], next_hold=["a", "b"], drop_next=["b"])
    chk(bk["other_drops_next"] == ["b"], "a name the other book sheds is chase")
    chk(bk["other_still_holds"] == ["a"], "a name the other book keeps is being early")
    chk(bk["disjoint"] == ["c", "d"], "names in neither book are a different slice")
    chk(_classify_entrants(["a"], None, None)["disjoint"] == ["a"],
        "a missing other book buckets everything as disjoint, not as a silent pass")

    # E59 sweep: the offset is measured to the NEXT month-end decision, and a
    # missing arm reports None rather than a silent zero gap
    scal = ["2020-01-%02d" % d for d in range(1, 11)]
    chk(_calendar_offsets(scal, [3, 6], [4, 7])["mean_sessions_to_month_end"] == 1.0,
        "a decision one session before month-end has offset 1")
    chk(_calendar_offsets(scal, [3], [])["mean_sessions_to_month_end"] is None,
        "no month-end decision leaves the offset unknown, not zero")
    sbook = {"me": {"arms": {"x1": {"full_window_ann_pct": 5.0,
                                    "eras": {"A": {"ann_return_pct": 4.0}}}}},
             "mid10": {"offset": {"mean_sessions_to_month_end": 6.0},
                       "arms": {"x1": {"full_window_ann_pct": 4.0,
                                       "turnover_per_year": 0.6,
                                       "eras": {"A": {"ann_return_pct": 3.5}}}}}}
    sg = _sweep_gaps(sbook, "x1", eras=(("A", "a", "b"),))
    chk(sg["mid10"]["full_window_gap_bp"] == -100.0,
        "sweep gap is the off-cycle minus month-end ann in bp")
    chk(sg["mid10"]["eras"]["A"]["gap_bp"] == -50.0,
        "sweep era gap carries the same sign convention")
    chk(_sweep_gaps(sbook, "x3", eras=(("A", "a", "b"),))["mid10"]["full_window_gap_bp"] is None,
        "a cost level with no arm reports no gap instead of a zero")

    # E63 cost face: the shift is the fee signature of a sweep day, and a
    # missing arm reports None instead of a silent zero shift
    cg = {"x0": {"mid10": {"full_window_gap_bp": -60.0, "turnover_per_year": 0.58,
                           "eras": {"A": {"gap_bp": -70.0}}}},
          "x3": {"mid10": {"full_window_gap_bp": -68.0, "turnover_per_year": 0.58,
                           "eras": {"A": {"gap_bp": -66.0}}}}}
    face = _cost_face(cg, "x0", "x3", eras=(("A", "a", "b"),))
    chk(face["mid10"]["full_window_shift_bp"] == -8.0,
        "cost shift is x3 minus x0 on the same sweep day")
    chk(face["mid10"]["eras"]["A"]["shift_bp"] == 4.0,
        "era shift is signed per era, not folded into the full window")
    chk(face["mid10"]["turnover_per_year"]["x0"] == 0.58,
        "the cost face carries turnover beside the gap it is pricing")
    cg_missing = {"x0": {"mid10": {"full_window_gap_bp": -60.0, "eras": {}}},
                  "x3": {"mid10": {"full_window_gap_bp": None, "eras": {}}}}
    chk(_cost_face(cg_missing, "x0", "x3", eras=(("A", "a", "b"),))
        ["mid10"]["full_window_shift_bp"] is None,
        "an unpriced cost arm leaves the shift unknown, not zero")

    # E65 delay ladder: a +k lag moves every decision k sessions later, and the
    # tail clamps into the last bar instead of inventing future sessions
    chk(_shift_indices([3, 6], 1, 10) == [4, 7],
        "a one-session lag moves each decision exactly one session later")
    chk(_shift_indices([8, 9], 3, 10) == [9],
        "a lag past the calendar end clamps to the last bar and dedupes")

    # era attribution follows the decision date, not the next date
    chk(_era_of("2023-12-29") == "2021_2023" and _era_of("2024-01-02") == "2024_now",
        "era boundaries key on the decision date")

    # E66 early ladder: the two sides of the boundary must never share a label,
    # and a negative shift stays inside the calendar
    chk(_early_label(3) == "me_m3" and _lag_label(3) == "me_lag3"
        and _early_label(3) != _lag_label(3),
        "early and late rows carry distinct labels at the same magnitude")
    chk(_lag_label(-1) == "me_lag-1" and _shift_indices([0, 5, 9], -1, 10) == [0, 4, 8],
        "an early lag is the negative shift and clamps at the first bar")

    # E69 weekly clash: the weekly grid is one decision per ISO week, and the
    # monthly-cadence reading snaps each month-end to the nearest weekly session
    _wk_cal = ["2024-01-01", "2024-01-02", "2024-01-03", "2024-01-04", "2024-01-05",
               "2024-01-08", "2024-01-09", "2024-01-10"]
    chk(_weekly_indices(_wk_cal) == [0, 5],
        "the weekly grid keeps one decision per ISO week")
    chk(_nearest_weekly_to_month_end([0, 5, 10], [3, 8]) == [5, 10]
        and _nearest_weekly_to_month_end([0, 5, 10], [4, 6]) == [5],
        "month-ends snap to the nearest weekly session, deduped")
    chk(_nearest_weekly_to_month_end([], [3]) == [] and
        _nearest_weekly_to_month_end([0], []) == [],
        "an empty grid returns no decisions instead of raising")

    # E70 cost face on the weekly clash: the same rows at two cost levels, read
    # out of ONE face, and a fee-only gap must move while a price-path gap does not
    _synth = {"gaps": {"x0": {"week": {"full_window_gap_bp": -40.0,
                                      "turnover_per_year": 0.70,
                                      "cost_per_year_bp": 0.0,
                                      "eras": {"2024_now": {"gap_bp": -50.0}}},
                              "week_near_me": {"full_window_gap_bp": -8.0,
                                               "turnover_per_year": 0.50,
                                               "cost_per_year_bp": 0.0,
                                               "eras": {"2024_now": {"gap_bp": -9.0}}}},
                       "x3": {"week": {"full_window_gap_bp": -55.0,
                                      "turnover_per_year": 0.70,
                                      "cost_per_year_bp": 30.0,
                                      "eras": {"2024_now": {"gap_bp": -50.0}}},
                              "week_near_me": {"full_window_gap_bp": -8.0,
                                               "turnover_per_year": 0.50,
                                               "cost_per_year_bp": 30.0,
                                               "eras": {"2024_now": {"gap_bp": -9.0}}}}},
              "books": {"week": {"decision_days": 349},
                        "week_near_me": {"decision_days": 82}}}
    _rows0 = _weekly_cal_rows(_synth, "x0")
    _rows3 = _weekly_cal_rows(_synth, "x3")
